INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36161, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6223e701-db4d-4fad-8ad6-90e467be2509') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36161, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「現象を」の〈を〉。見る対象を示す目的語として自然。"}, {"text": "が", "is_correct": false, "explanation": "「現象が、私は…見た」は文として続かず不自然。"}, {"text": "で", "is_correct": false, "explanation": "〈で〉は手段や場所を示すが、「現象で見た」は意味が通らない。"}, {"text": "の", "is_correct": false, "explanation": "〈の〉は連体修飾だが、「現象の、私は…」では文が続かない。"}], "correct_answer": "を", "explanations": {"を": "「現象を」の〈を〉。見る対象を示す目的語として自然。", "が": "「現象が、私は…見た」は文として続かず不自然。", "で": "〈で〉は手段や場所を示すが、「現象で見た」は意味が通らない。", "の": "〈の〉は連体修飾だが、「現象の、私は…」では文が続かない。"}, "error_tags": {"が": "主語", "で": "手段・場所", "の": "連体修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6223e701-db4d-4fad-8ad6-90e467be2509') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36161, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "人が外から観察できる、実際に起こっている事柄や様子。", "primary_collocate": null, "pronunciation": "げんしょう", "ipa": "ɡeɴɕoː", "syllable_count": 4, "sentences": [{"text": "研究者は、夜空で起きた現象を望遠鏡で観察し、その記録を残した。", "target_word": "現象", "complexity_tier": "T3", "furigana": "研究者[けんきゅうしゃ]は、夜空[よぞら]で起[お]きた現象[げんしょう]を望遠鏡[ぼうえんきょう]で観察[かんさつ]し、その記録[きろく]を残[のこ]した。", "sentence_source": "generated"}, {"text": "夜になると空が緑色に光る現象が、北の町で何度も観察された。", "target_word": "現象", "complexity_tier": "T3", "furigana": "夜[よる]になると空[そら]が緑色[みどりいろ]に光[ひか]る現象[げんしょう]が、北[きた]の町[まち]で何度[なんど]も観察[かんさつ]された。", "sentence_source": "generated"}, {"text": "科学者たちは、この不思議な現象の原因を調べている。", "target_word": "現象", "complexity_tier": "T3", "furigana": "科学者[かがくしゃ]たちは、この不思議[ふしぎ]な現象[げんしょう]の原因[げんいん]を調[しら]べている。", "sentence_source": "generated"}, {"text": "雨が降る前にカエルが鳴くという現象は、昔から知られている。", "target_word": "現象", "complexity_tier": "T3", "furigana": "雨[あめ]が降[ふ]る前[まえ]にカエルが鳴[な]くという現象[げんしょう]は、昔[むかし]から知[し]られている。", "sentence_source": "generated"}, {"text": "氷が水に変わる現象は、温度が上がるために起こる。", "target_word": "現象", "complexity_tier": "T3", "furigana": "氷[こおり]が水[みず]に変[か]わる現象[げんしょう]は、温度[おんど]が上[あ]がるために起[お]こる。", "sentence_source": "generated"}, {"text": "日食は、月が太陽をかくす現象であり、数年に一度しか見られない。", "target_word": "現象", "complexity_tier": "T3", "furigana": "日食[にっしょく]は、月[つき]が太陽[たいよう]をかくす現象[げんしょう]であり、数年[すうねん]に一度[いちど]しか見[み]られない。", "sentence_source": "generated"}, {"text": "同じ実験をしても、毎回違う現象が見られたので、先生は首をかしげた。", "target_word": "現象", "complexity_tier": "T3", "furigana": "同[おな]じ実験[じっけん]をしても、毎回[まいかい]違[ちが]う現象[げんしょう]が見[み]られたので、先生[せんせい]は首[くび]をかしげた。", "sentence_source": "generated"}, {"text": "海の水が赤く変わる現象を、私は写真で初めて見た。", "target_word": "現象", "complexity_tier": "T3", "furigana": "海[うみ]の水[みず]が赤[あか]く変[か]わる現象[げんしょう]を、私[わたし]は写真[しゃしん]で初[はじ]めて見[み]た。", "sentence_source": "generated"}, {"text": "観測データを見ると、この現象は夏にだけ起こることが分かる。", "target_word": "現象", "complexity_tier": "T3", "furigana": "観測[かんそく]データを見[み]ると、この現象[げんしょう]は夏[なつ]にだけ起[お]こることが分[わ]かる。", "sentence_source": "generated"}, {"text": "目に見える現象だけでなく、その裏にある仕組みも考えなければならない。", "target_word": "現象", "complexity_tier": "T3", "furigana": "目[め]に見[み]える現象[げんしょう]だけでなく、その裏[うら]にある仕組[しく]みも考[かんが]えなければならない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "現象", "label": "基本形"}], "register": "formal", "sense_fingerprint": "観察や測定でとらえられる、実際に起こっている出来事・様子（科学的・観察的な意味）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 5 above tier T2: contains vocabulary far above tier T2: かくす (Zipf 1.98)']::text[], 'c1e5117e-6210-437d-8c4a-90abcde11eb5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36161, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "現象", "is_correct": true, "explanation": "『起きた現象を観察』の語。観察の対象となる出来事を指し、文に合う。"}, {"text": "食器", "is_correct": false, "explanation": "『起きた食器を観察』は成り立たず、観察の対象にならない。"}, {"text": "家具", "is_correct": false, "explanation": "『起きた家具を観察』は意味をなさず、この文に入らない。"}, {"text": "指輪", "is_correct": false, "explanation": "『起きた指輪を観察』は不自然で、観察される出来事を表さない。"}], "explanations": {"現象": "『起きた現象を観察』の語。観察の対象となる出来事を指し、文に合う。", "食器": "『起きた食器を観察』は成り立たず、観察の対象にならない。", "家具": "『起きた家具を観察』は意味をなさず、この文に入らない。", "指輪": "『起きた指輪を観察』は不自然で、観察される出来事を表さない。"}, "sentence_index": 0, "correct_answer": "現象"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "警察は昨日、現象を逮捕した。", "explanation": "ここは〈犯人〉の意味。現象は起きる出来事で、人として逮捕する対象にはならない。"}, {"text": "警察が現象に到着した。", "explanation": "ここは〈現場〉の意味。現象は場所ではないので、人や車が到着する対象にはならない。"}, {"text": "毎朝、現象を量る。", "explanation": "ここは〈体重〉の意味。現象は量れるものではなく、測定の対象にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6223e701-db4d-4fad-8ad6-90e467be2509') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36161, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "現象", "is_correct": true, "explanation": "「違う現象が見られた」の語。観察された出来事を指し、文に合う。"}, {"text": "咳払い", "is_correct": false, "explanation": "「違う咳払いが見られた」は実験の観察結果として成り立たない。"}, {"text": "梯子", "is_correct": false, "explanation": "「違う梯子が見られた」は実験の文脈に合わない。"}, {"text": "石鹸", "is_correct": false, "explanation": "「違う石鹸が見られた」は意味が通らない。"}], "explanations": {"現象": "「違う現象が見られた」の語。観察された出来事を指し、文に合う。", "咳払い": "「違う咳払いが見られた」は実験の観察結果として成り立たない。", "梯子": "「違う梯子が見られた」は実験の文脈に合わない。", "石鹸": "「違う石鹸が見られた」は意味が通らない。"}, "sentence_index": 6, "correct_answer": "現象"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この現象を、夕飯に食べた。", "explanation": "ここは〈料理〉の意味。現象は食べ物ではないので、食べる対象にはならない。"}, {"text": "夏の終わりに、現象を畑に植えた。", "explanation": "ここは〈作物〉の意味。現象は植えて育てる対象にはならない。"}, {"text": "明日の現象に合格したい。", "explanation": "ここは〈試験〉の意味。現象は合否を受ける対象ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6223e701-db4d-4fad-8ad6-90e467be2509') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36161, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "その現象を、町の人々は驚いた。", "corrected_sentence": "その現象に、町の人々は驚いた。", "error_description": "「驚く」は「に」で驚きの対象を示す。「を」は他動詞に付く助詞なので誤り。正しくは「現象に」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6223e701-db4d-4fad-8ad6-90e467be2509') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36161, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夏の夜に、その現象が見られるた。", "corrected_sentence": "夏の夜に、その現象が見られた。", "error_description": "「見られる」の過去形は「見られた」。「見られるた」は過去の語尾を誤っている活用の誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6223e701-db4d-4fad-8ad6-90e467be2509') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36162, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「結果を分析し」で、分析の目的語を示す。直前に分析が来るので正しい。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示す助詞で、分析の対象を示す位置には使えないので合わない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は相手や到達点を示すので、分析の対象を表す文脈には合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示す助詞で、分析の対象を示す位置には合わない。"}], "correct_answer": "を", "explanations": {"を": "「結果を分析し」で、分析の目的語を示す。直前に分析が来るので正しい。", "が": "「が」は主語を示す助詞で、分析の対象を示す位置には使えないので合わない。", "に": "「に」は相手や到達点を示すので、分析の対象を表す文脈には合わない。", "へ": "「へ」は方向を示す助詞で、分析の対象を示す位置には合わない。"}, "error_tags": {"が": "主語を示す", "に": "相手・到達を示す", "へ": "方向を示す"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "総合", "is_correct": true, "explanation": "分析は部分に分けて調べることで、その対義語は全体をまとめる「総合」。辞書でも対義語として挙げられる。"}, {"text": "推測", "is_correct": false, "explanation": "推測は手がかりから推し量ることで、分けて調べる分析の対義語ではない。"}, {"text": "放置", "is_correct": false, "explanation": "放置はそのままにしておくことで、分析とは対になる関係ではない。"}, {"text": "記憶", "is_correct": false, "explanation": "記憶は覚えておくことで、分析と対義の関係にはない。"}], "correct_answer": "総合", "explanations": {"総合": "分析は部分に分けて調べることで、その対義語は全体をまとめる「総合」。辞書でも対義語として挙げられる。", "推測": "推測は手がかりから推し量ることで、分けて調べる分析の対義語ではない。", "放置": "放置はそのままにしておくことで、分析とは対になる関係ではない。", "記憶": "記憶は覚えておくことで、分析と対義の関係にはない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aad67c8f-e9b3-403f-a0ec-20e528ef9731') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36162, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「研究所で分析」で、分析を行う場所を示す。直前に分析が来るので正しい。"}, {"text": "を", "is_correct": false, "explanation": "「研究所を分析」だと研究所そのものを調べる意味になり、ここでは不自然なので合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、分析を行う場所を表す位置には合わない。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示すので、「研究所が分析してもらった」は主語と「てもらう」の関係が合わず不自然。"}], "correct_answer": "で", "explanations": {"で": "「研究所で分析」で、分析を行う場所を示す。直前に分析が来るので正しい。", "を": "「研究所を分析」だと研究所そのものを調べる意味になり、ここでは不自然なので合わない。", "へ": "「へ」は方向を示すので、分析を行う場所を表す位置には合わない。", "が": "「が」は主語を示すので、「研究所が分析してもらった」は主語と「てもらう」の関係が合わず不自然。"}, "error_tags": {"を": "対象を示す", "へ": "方向を示す", "が": "主語を示す"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "総合", "is_correct": true, "explanation": "分析の対義語は全体をまとめる「総合」。辞書でも対義語として挙げられる。"}, {"text": "直感", "is_correct": false, "explanation": "直感は考えずに感じ取ることで、分析の対義語ではない。"}, {"text": "統計", "is_correct": false, "explanation": "統計は数を集めて扱うことで、分析と対になる関係ではない。"}, {"text": "作成", "is_correct": false, "explanation": "作成は新しく作ることで、分析の対義語とは言えない。"}], "correct_answer": "総合", "explanations": {"総合": "分析の対義語は全体をまとめる「総合」。辞書でも対義語として挙げられる。", "直感": "直感は考えずに感じ取ることで、分析の対義語ではない。", "統計": "統計は数を集めて扱うことで、分析と対になる関係ではない。", "作成": "作成は新しく作ることで、分析の対義語とは言えない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aad67c8f-e9b3-403f-a0ec-20e528ef9731') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36162, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "あることをくわしく調べて、わかるようにすること。", "primary_collocate": null, "pronunciation": "ぶんせき", "ipa": "bɯnseki", "syllable_count": 4, "sentences": [{"text": "医者は血液を分析して、病気の原因を調べました。", "target_word": "分析", "complexity_tier": "T3", "furigana": "医者[いしゃ]は血液[けつえき]を分析[ぶんせき]して、病気[びょうき]の原因[げんいん]を調[しら]べました。", "sentence_source": "generated"}, {"text": "先生はテストの結果を分析し、生徒に説明しました。", "target_word": "分析", "complexity_tier": "T3", "furigana": "先生[せんせい]はテストの結果[けっか]を分析[ぶんせき]し、生徒[せいと]に説明[せつめい]しました。", "sentence_source": "generated"}, {"text": "売り上げのデータを分析すると、冬によく売れる商品がわかります。", "target_word": "分析", "complexity_tier": "T3", "furigana": "売[う]り上[あ]げのデータを分析[ぶんせき]すると、冬[ふゆ]によく売[う]れる商品[しょうひん]がわかります。", "sentence_source": "generated"}, {"text": "この会社は客の声を分析して、新しい商品を作りました。", "target_word": "分析", "complexity_tier": "T3", "furigana": "この会社[かいしゃ]は客[きゃく]の声[こえ]を分析[ぶんせき]して、新[あたら]しい商品[しょうひん]を作[つく]りました。", "sentence_source": "generated"}, {"text": "彼は事故の原因を分析するために、現場を何度も訪れた。", "target_word": "分析", "complexity_tier": "T3", "furigana": "彼[かれ]は事故[じこ]の原因[げんいん]を分析[ぶんせき]するために、現場[げんば]を何度[なんど]も訪[おとず]れた。", "sentence_source": "generated"}, {"text": "分析が終わるまで、結果は発表できません。", "target_word": "分析", "complexity_tier": "T3", "furigana": "分析[ぶんせき]が終[お]わるまで、結果[けっか]は発表[はっぴょう]できません。", "sentence_source": "generated"}, {"text": "専門家の分析によると、来年は景気がよくなるそうです。", "target_word": "分析", "complexity_tier": "T3", "furigana": "専門家[せんもんか]の分析[ぶんせき]によると、来年[らいねん]は景気[けいき]がよくなるそうです。", "sentence_source": "generated"}, {"text": "水の中に何が入っているか、研究所で分析してもらった。", "target_word": "分析", "complexity_tier": "T3", "furigana": "水[みず]の中[なか]に何[なに]が入[はい]っているか、研究所[けんきゅうじょ]で分析[ぶんせき]してもらった。", "sentence_source": "generated"}, {"text": "試合の映像を分析したので、次は勝てると思います。", "target_word": "分析", "complexity_tier": "T3", "furigana": "試合[しあい]の映像[えいぞう]を分析[ぶんせき]したので、次[つぎ]は勝[か]てると思[おも]います。", "sentence_source": "generated"}, {"text": "失敗の分析をしっかりしないと、同じ間違いをくり返します。", "target_word": "分析", "complexity_tier": "T3", "furigana": "失敗[しっぱい]の分析[ぶんせき]をしっかりしないと、同[おな]じ間違[まちが]いをくり返[かえ]します。", "sentence_source": "generated"}], "morphological_forms": [{"form": "分析", "label": "基本形"}, {"form": "分析する", "label": "する動詞"}, {"form": "分析した", "label": "過去形"}, {"form": "分析して", "label": "て形"}], "register": "neutral", "sense_fingerprint": "物事を細かく調べて、原因や中身を明らかにすること(する動詞化できる名詞)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94f9763a-fbdb-4942-b840-f5e9ecdfccc6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36162, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "分析", "is_correct": true, "explanation": "「血液を分析して」で、血液の中身を細かく調べる意味になり、病気の原因を調べたという文に合う。"}, {"text": "手術", "is_correct": false, "explanation": "手術は体の悪い部分を治す行為で、血液を目的語にして「手術して調べた」とは言わないので合わない。"}, {"text": "処方", "is_correct": false, "explanation": "処方は薬を出すことで、血液を対象にすると意味が通らないので合わない。"}, {"text": "注射", "is_correct": false, "explanation": "注射は体内に薬などを入れる行為で、血液を対象に調べる文脈とは合わない。"}], "explanations": {"分析": "「血液を分析して」で、血液の中身を細かく調べる意味になり、病気の原因を調べたという文に合う。", "手術": "手術は体の悪い部分を治す行為で、血液を目的語にして「手術して調べた」とは言わないので合わない。", "処方": "処方は薬を出すことで、血液を対象にすると意味が通らないので合わない。", "注射": "注射は体内に薬などを入れる行為で、血液を対象に調べる文脈とは合わない。"}, "sentence_index": 0, "correct_answer": "分析"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は本を色ごとに分析して、棚に並べた。", "explanation": "ここは〈分類〉の意味。色で分けて並べるだけなら分類であり、中身を詳しく調べる分析とは言わないので合わない。"}, {"text": "古い家を分析して、取り壊した。", "explanation": "ここは〈解体〉の意味。建物を壊す行為は分析の意味に含まれないので合わない。"}, {"text": "夏休み、庭のアサガオを一時間分析して、ノートに絵をかいた。", "explanation": "ここは〈観察〉の意味。ただ見て記録するなら観察であり、分析は細かく調べて中身を明らかにすることなので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aad67c8f-e9b3-403f-a0ec-20e528ef9731') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36162, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "分析", "is_correct": true, "explanation": "「専門家の分析」は、専門家が調べて出した判断を指し、景気の予想という文に合う。"}, {"text": "採点", "is_correct": false, "explanation": "採点は答案に点をつけることで、専門家の判断という文脈には合わない。"}, {"text": "翻訳", "is_correct": false, "explanation": "翻訳は言語を別の言語に置き換えることで、景気の予想とは関係がない。"}, {"text": "清掃", "is_correct": false, "explanation": "清掃は掃除をすることで、専門家の判断という文とは意味がつながらない。"}], "explanations": {"分析": "「専門家の分析」は、専門家が調べて出した判断を指し、景気の予想という文に合う。", "採点": "採点は答案に点をつけることで、専門家の判断という文脈には合わない。", "翻訳": "翻訳は言語を別の言語に置き換えることで、景気の予想とは関係がない。", "清掃": "清掃は掃除をすることで、専門家の判断という文とは意味がつながらない。"}, "sentence_index": 6, "correct_answer": "分析"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "空港で、かばんを分析して、危険な物がないか調べた。", "explanation": "ここは〈検査〉の意味。中身を確かめて危険物を見つけるのは検査であり、原因を明らかにする分析とは言わないので合わない。"}, {"text": "彼は壁を分析して、白いペンキで塗った。", "explanation": "ここは〈塗装〉の意味。壁にペンキを塗るのは塗装であり、中身を詳しく調べる分析の意味には含まれないので合わない。"}, {"text": "先生はカエルを分析して、心臓を取り出した。", "explanation": "ここは〈解剖〉の意味。体を切り開いて中の器官を取り出すのは解剖であり、分析の意味には含まれないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aad67c8f-e9b3-403f-a0ec-20e528ef9731') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
