INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36162, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "先生は売り上げを分析しから、新しい商品を選んだ。", "corrected_sentence": "先生は売り上げを分析してから、新しい商品を選んだ。", "error_description": "「分析する」の後に「てから」を続けて「分析してから」とする。「分析しから」は活用の誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aad67c8f-e9b3-403f-a0ec-20e528ef9731') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
