INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36164, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「作品を批評し合う」で、批評する対象を表す。"}, {"text": "に", "is_correct": false, "explanation": "「作品に批評し合う」は対象の示し方として不自然。"}, {"text": "と", "is_correct": false, "explanation": "「作品と批評し合う」は「作品を相手に」の意味になり不適切。"}, {"text": "の", "is_correct": false, "explanation": "「作品の批評し合う」は文として成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「作品を批評し合う」で、批評する対象を表す。", "に": "「作品に批評し合う」は対象の示し方として不自然。", "と": "「作品と批評し合う」は「作品を相手に」の意味になり不適切。", "の": "「作品の批評し合う」は文として成り立たない。"}, "error_tags": {"に": "target_of_action", "と": "comitative", "の": "possessive"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2197b1bc-1dbc-4d2e-8a3d-935419e745a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36164, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "何かについて、いいところや悪いところを考えること。", "primary_collocate": null, "pronunciation": "ひひょう", "ipa": "çihjoː", "syllable_count": 3, "sentences": [{"text": "友だちの絵を批評した。", "target_word": "批評", "complexity_tier": "T2", "furigana": "友[とも]だちの絵[え]を批評[ひひょう]した。", "sentence_source": "generated"}, {"text": "先生に批評してもらった。", "target_word": "批評", "complexity_tier": "T2", "furigana": "先生[せんせい]に批評[ひひょう]してもらった。", "sentence_source": "generated"}, {"text": "人の批評ばかりするのは、よくない。", "target_word": "批評", "complexity_tier": "T3", "furigana": "人[ひと]の批評[ひひょう]ばかりするのは、よくない。", "sentence_source": "generated"}, {"text": "彼は料理の批評が好きだ。", "target_word": "批評", "complexity_tier": "T2", "furigana": "彼[かれ]は料理[りょうり]の批評[ひひょう]が好[す]きだ。", "sentence_source": "generated"}, {"text": "批評を聞いて、考えが変わった。", "target_word": "批評", "complexity_tier": "T3", "furigana": "批評[ひひょう]を聞[き]いて、考[かんが]えが変[か]わった。", "sentence_source": "generated"}, {"text": "本の感想と批評は、少し違う。", "target_word": "批評", "complexity_tier": "T3", "furigana": "本[ほん]の感想[かんそう]と批評[ひひょう]は、少[すこ]し違[ちが]う。", "sentence_source": "generated"}, {"text": "彼女の批評はやさしくて、わかりやすい。", "target_word": "批評", "complexity_tier": "T3", "furigana": "彼女[かのじょ]の批評[ひひょう]はやさしくて、わかりやすい。", "sentence_source": "generated"}, {"text": "みんなで作品を批評し合う時間があった。", "target_word": "批評", "complexity_tier": "T3", "furigana": "みんなで作品[さくひん]を批評[ひひょう]し合[あ]う時間[じかん]があった。", "sentence_source": "generated"}, {"text": "悪いところだけでなく、いいところも批評する。", "target_word": "批評", "complexity_tier": "T3", "furigana": "悪[わる]いところだけでなく、いいところも批評[ひひょう]する。", "sentence_source": "generated"}, {"text": "批評の仕方によって、相手の気持ちは変わる。", "target_word": "批評", "complexity_tier": "T4", "furigana": "批評[ひひょう]の仕方[しかた]によって、相手[あいて]の気持[きも]ちは変[か]わる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "批評する", "label": "活用"}, {"form": "批評される", "label": "活用"}, {"form": "批評家", "label": "派生"}, {"form": "批評的", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | いいところや悪いところを考えて述べること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47a9a169-f8ce-40f2-ac03-946696cdfb23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36164, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "批評", "is_correct": true, "explanation": "見出し語そのもの（ひひょう）。"}, {"text": "非常", "is_correct": false, "explanation": "ひじょう。2拍目の「ひょ」が「じょ」に変わる。"}, {"text": "肥料", "is_correct": false, "explanation": "ひりょう。2拍目の「ひょ」が「りょ」に変わる。"}, {"text": "卑怯", "is_correct": false, "explanation": "ひきょう。2拍目の「ひょ」が「きょ」に変わる。"}, {"text": "指標", "is_correct": false, "explanation": "しひょう。1拍目の「ひ」が「し」に変わる。"}], "explanations": {"批評": "見出し語そのもの（ひひょう）。", "非常": "ひじょう。2拍目の「ひょ」が「じょ」に変わる。", "肥料": "ひりょう。2拍目の「ひょ」が「りょ」に変わる。", "卑怯": "ひきょう。2拍目の「ひょ」が「きょ」に変わる。", "指標": "しひょう。1拍目の「ひ」が「し」に変わる。"}, "sentence_index": null, "correct_answer": "批評"}, "level_3": {"options": [{"text": "批評", "is_correct": true, "explanation": "「友だちの絵を批評した」で意味が合う。"}, {"text": "散歩", "is_correct": false, "explanation": "形は合うが、絵を散歩するのは意味が合わない。"}, {"text": "運転", "is_correct": false, "explanation": "形は合うが、絵を運転するのは意味が合わない。"}, {"text": "出発", "is_correct": false, "explanation": "形は合うが、絵を出発するのは意味が合わない。"}], "explanations": {"批評": "「友だちの絵を批評した」で意味が合う。", "散歩": "形は合うが、絵を散歩するのは意味が合わない。", "運転": "形は合うが、絵を運転するのは意味が合わない。", "出発": "形は合うが、絵を出発するのは意味が合わない。"}, "sentence_index": 0, "correct_answer": "批評"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は毎朝、批評を飲んでから学校へ行く。", "explanation": "批評は意見を述べることで、飲み物ではないので「飲む」とは使えない。"}, {"text": "駅の前に大きな批評が建っている。", "explanation": "批評は考えや意見で、建物のように建つものではない。"}, {"text": "このかばんは批評が入っていて、とても軽い。", "explanation": "批評は抽象的なことで、かばんに入れる物ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2197b1bc-1dbc-4d2e-8a3d-935419e745a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36164, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "批評", "is_correct": true, "explanation": "見出し語そのもの（ひひょう）。"}, {"text": "飛行", "is_correct": false, "explanation": "ひこう。2拍目の「ひょ」が「こ」に変わる。"}, {"text": "疲労", "is_correct": false, "explanation": "ひろう。2拍目の「ひょ」が「ろ」に変わる。"}, {"text": "悲壮", "is_correct": false, "explanation": "ひそう。2拍目の「ひょ」が「そ」に変わる。"}, {"text": "悲報", "is_correct": false, "explanation": "ひほう。2拍目の「ひょ」が「ほ」に変わる。"}], "explanations": {"批評": "見出し語そのもの（ひひょう）。", "飛行": "ひこう。2拍目の「ひょ」が「こ」に変わる。", "疲労": "ひろう。2拍目の「ひょ」が「ろ」に変わる。", "悲壮": "ひそう。2拍目の「ひょ」が「そ」に変わる。", "悲報": "ひほう。2拍目の「ひょ」が「ほ」に変わる。"}, "sentence_index": null, "correct_answer": "批評"}, "level_3": {"options": [{"text": "批評", "is_correct": true, "explanation": "「彼女の批評はやさしくて、わかりやすい」で意味が合う。"}, {"text": "財布", "is_correct": false, "explanation": "形は合うが、財布がやさしくてわかりやすいのは意味が合わない。"}, {"text": "電車", "is_correct": false, "explanation": "形は合うが、電車がやさしくてわかりやすいのは意味が合わない。"}, {"text": "季節", "is_correct": false, "explanation": "形は合うが、季節がやさしくてわかりやすいのは意味が合わない。"}], "explanations": {"批評": "「彼女の批評はやさしくて、わかりやすい」で意味が合う。", "財布": "形は合うが、財布がやさしくてわかりやすいのは意味が合わない。", "電車": "形は合うが、電車がやさしくてわかりやすいのは意味が合わない。", "季節": "形は合うが、季節がやさしくてわかりやすいのは意味が合わない。"}, "sentence_index": 6, "correct_answer": "批評"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "批評の車によって、相手の気持ちは変わる。", "explanation": "批評は乗り物ではないので「批評の車」という使い方は誤り。"}, {"text": "この道は批評が長くて、歩くのに三十分かかる。", "explanation": "批評は距離や長さを表さず、道の説明に使えない。"}, {"text": "毎日、庭で批評に水をやっている。", "explanation": "批評は植物ではなく、水をやる対象にならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2197b1bc-1dbc-4d2e-8a3d-935419e745a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_