INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36165, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「批評をくれた」で、くれる物を表す目的語になる。"}, {"text": "に", "is_correct": false, "explanation": "「批評にくれた」は文として成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「批評でくれた」は文として成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "「批評からくれた」は文として成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「批評をくれた」で、くれる物を表す目的語になる。", "に": "「批評にくれた」は文として成り立たない。", "で": "「批評でくれた」は文として成り立たない。", "から": "「批評からくれた」は文として成り立たない。"}, "error_tags": {"に": "target_of_action", "で": "means", "から": "source"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2197b1bc-1dbc-4d2e-8a3d-935419e745a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36165, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「批評に力を入れる」で、力を注ぐ対象を表す。"}, {"text": "を", "is_correct": false, "explanation": "後ろに「力を」があり、「を」が二つ続いて不自然。"}, {"text": "と", "is_correct": false, "explanation": "「批評と力を入れる」は文として成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「批評の力を入れている」は文として成り立たない。"}], "correct_answer": "に", "explanations": {"に": "「批評に力を入れる」で、力を注ぐ対象を表す。", "を": "後ろに「力を」があり、「を」が二つ続いて不自然。", "と": "「批評と力を入れる」は文として成り立たない。", "の": "「批評の力を入れている」は文として成り立たない。"}, "error_tags": {"を": "double_object", "と": "comitative", "の": "possessive"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2197b1bc-1dbc-4d2e-8a3d-935419e745a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36165, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事の価値や問題点を評価し、意見を述べること。", "primary_collocate": null, "pronunciation": "ひひょう", "ipa": "çihjoː", "syllable_count": 3, "sentences": [{"text": "建築を単なる機能の集合体ではなく、記号が織りなすテキストとして読み解く態度が、ポスト構造主義に基づく批評の核心です。", "target_word": "批評", "complexity_tier": "T6", "furigana": "建築[けんちく]を単[たん]なる機能[きのう]の集合体[しゅうごうたい]ではなく、記号[きごう]が織[お]りなすテキストとして読[よ]み解[と]く態度[たいど]が、ポスト構造主義[こうぞうしゅぎ]に基[もと]づく批評[ひひょう]の核心[かくしん]です。", "sentence_source": "mined"}, {"text": "先生は私の作文に批評をくれた。", "target_word": "批評", "complexity_tier": "T2", "furigana": "先生[せんせい]は私[わたし]の作文[さくぶん]に批評[ひひょう]をくれた。", "sentence_source": "generated"}, {"text": "映画の批評を読んでから、見に行った。", "target_word": "批評", "complexity_tier": "T3", "furigana": "映画[えいが]の批評[ひひょう]を読[よ]んでから、見[み]に行[い]った。", "sentence_source": "generated"}, {"text": "彼は鋭い批評で有名だ。", "target_word": "批評", "complexity_tier": "T2", "furigana": "彼[かれ]は鋭[するど]い批評[ひひょう]で有名[ゆうめい]だ。", "sentence_source": "generated"}, {"text": "作品への批評が、新聞に載った。", "target_word": "批評", "complexity_tier": "T3", "furigana": "作品[さくひん]への批評[ひひょう]が、新聞[しんぶん]に載[の]った。", "sentence_source": "generated"}, {"text": "友だちの批評は、いつも的確です。", "target_word": "批評", "complexity_tier": "T2", "furigana": "友[とも]だちの批評[ひひょう]は、いつも的確[てきかく]です。", "sentence_source": "generated"}, {"text": "厳しい批評を受けて、彼は書き直した。", "target_word": "批評", "complexity_tier": "T3", "furigana": "厳[きび]しい批評[ひひょう]を受[う]けて、彼[かれ]は書[か]き直[なお]した。", "sentence_source": "generated"}, {"text": "この雑誌は、音楽の批評に力を入れている。", "target_word": "批評", "complexity_tier": "T3", "furigana": "この雑誌[ざっし]は、音楽[おんがく]の批評[ひひょう]に力[ちから]を入[い]れている。", "sentence_source": "generated"}, {"text": "社会に対する批評を込めた小説が話題になった。", "target_word": "批評", "complexity_tier": "T4", "furigana": "社会[しゃかい]に対[たい]する批評[ひひょう]を込[こ]めた小説[しょうせつ]が話題[わだい]になった。", "sentence_source": "generated"}, {"text": "批評されるのが怖くて、作品を見せられない。", "target_word": "批評される", "complexity_tier": "T4", "furigana": "批評[ひひょう]されるのが怖[こわ]くて、作品[さくひん]を見[み]せられない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "批評する", "label": "活用"}, {"form": "批評される", "label": "活用"}, {"form": "批評家", "label": "派生"}, {"form": "批評的", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 物事の価値や問題点を評価し述べること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47a9a169-f8ce-40f2-ac03-946696cdfb23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36165, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "批評", "is_correct": true, "explanation": "見出し語そのもの（ひひょう）。"}, {"text": "非常", "is_correct": false, "explanation": "ひじょう。2拍目の「ひょ」が「じょ」に変わる。"}, {"text": "肥料", "is_correct": false, "explanation": "ひりょう。2拍目の「ひょ」が「りょ」に変わる。"}, {"text": "卑怯", "is_correct": false, "explanation": "ひきょう。2拍目の「ひょ」が「きょ」に変わる。"}, {"text": "指標", "is_correct": false, "explanation": "しひょう。1拍目の「ひ」が「し」に変わる。"}], "explanations": {"批評": "見出し語そのもの（ひひょう）。", "非常": "ひじょう。2拍目の「ひょ」が「じょ」に変わる。", "肥料": "ひりょう。2拍目の「ひょ」が「りょ」に変わる。", "卑怯": "ひきょう。2拍目の「ひょ」が「きょ」に変わる。", "指標": "しひょう。1拍目の「ひ」が「し」に変わる。"}, "sentence_index": null, "correct_answer": "批評"}, "level_3": {"options": [{"text": "批評", "is_correct": true, "explanation": "「ポスト構造主義に基づく批評の核心」で意味が合う。"}, {"text": "料理", "is_correct": false, "explanation": "形は合うが、構造主義に基づく料理では意味が合わない。"}, {"text": "天気", "is_correct": false, "explanation": "形は合うが、構造主義に基づく天気では意味が合わない。"}, {"text": "財布", "is_correct": false, "explanation": "形は合うが、構造主義に基づく財布では意味が合わない。"}], "explanations": {"批評": "「ポスト構造主義に基づく批評の核心」で意味が合う。", "料理": "形は合うが、構造主義に基づく料理では意味が合わない。", "天気": "形は合うが、構造主義に基づく天気では意味が合わない。", "財布": "形は合うが、構造主義に基づく財布では意味が合わない。"}, "sentence_index": 0, "correct_answer": "批評"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "私は毎朝、パンと批評を食べてから学校へ行く。", "explanation": "批評は意見を述べることで、食べ物ではないので「食べる」とは使えない。"}, {"text": "公園で批評と一緒にサッカーをした。", "explanation": "批評は人ではないので、一緒に遊ぶ相手にならない。"}, {"text": "この批評は重くて、一人では持ち上がらない。", "explanation": "批評は抽象的な意見で、物理的な重さはない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2197b1bc-1dbc-4d2e-8a3d-935419e745a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors =