INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36165, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "批評", "is_correct": true, "explanation": "見出し語そのもの（ひひょう）。"}, {"text": "飛行", "is_correct": false, "explanation": "ひこう。2拍目の「ひょ」が「こ」に変わる。"}, {"text": "疲労", "is_correct": false, "explanation": "ひろう。2拍目の「ひょ」が「ろ」に変わる。"}, {"text": "悲壮", "is_correct": false, "explanation": "ひそう。2拍目の「ひょ」が「そ」に変わる。"}, {"text": "悲報", "is_correct": false, "explanation": "ひほう。2拍目の「ひょ」が「ほ」に変わる。"}], "explanations": {"批評": "見出し語そのもの（ひひょう）。", "飛行": "ひこう。2拍目の「ひょ」が「こ」に変わる。", "疲労": "ひろう。2拍目の「ひょ」が「ろ」に変わる。", "悲壮": "ひそう。2拍目の「ひょ」が「そ」に変わる。", "悲報": "ひほう。2拍目の「ひょ」が「ほ」に変わる。"}, "sentence_index": null, "correct_answer": "批評"}, "level_3": {"options": [{"text": "批評", "is_correct": true, "explanation": "「厳しい批評を受けて書き直した」で意味が合う。"}, {"text": "旅行", "is_correct": false, "explanation": "形は合うが、厳しい旅行を受けて書き直すのは意味が合わない。"}, {"text": "食事", "is_correct": false, "explanation": "形は合うが、厳しい食事を受けて書き直すのは意味が合わない。"}, {"text": "散歩", "is_correct": false, "explanation": "形は合うが、厳しい散歩を受けて書き直すのは意味が合わない。"}], "explanations": {"批評": "「厳しい批評を受けて書き直した」で意味が合う。", "旅行": "形は合うが、厳しい旅行を受けて書き直すのは意味が合わない。", "食事": "形は合うが、厳しい食事を受けて書き直すのは意味が合わない。", "散歩": "形は合うが、厳しい散歩を受けて書き直すのは意味が合わない。"}, "sentence_index": 6, "correct_answer": "批評"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "毎晩十時に批評して、朝七時に起きる。", "explanation": "批評は寝る意味ではないので誤り。"}, {"text": "駅まで批評して歩いたら、十分で着いた。", "explanation": "批評は移動の動作ではなく、「歩く」手段として使えない。"}, {"text": "寒いので、上着を批評して出かけた。", "explanation": "批評は服を着る意味ではないので誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2197b1bc-1dbc-4d2e-8a3d-935419e745a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
