INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36167, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "複数の要素が組み合わさって一つのまとまりを作ること。また、その組み合わせ方や構造。", "primary_collocate": null, "pronunciation": "こうせい", "ipa": "koːseː", "syllable_count": 4, "sentences": [{"text": "熟練したソムリエは、グラス内で感じる香りの構成を、味覚と嗅覚の両方から読み解く。", "target_word": "構成", "complexity_tier": "T5", "furigana": "熟練[じゅくれん]したソムリエは、グラス内[ない]で感[かん]じる香[か]りの構成[こうせい]を、味覚[みかく]と嗅覚[きゅうかく]の両方[りょうほう]から読[よ]み解[と]く。", "sentence_source": "generated"}, {"text": "このチームは経験者と新人の構成がよく、バランスがとれている。", "target_word": "構成", "complexity_tier": "T3", "furigana": "このチームは経験者[けいけんしゃ]と新人[しんじん]の構成[こうせい]がよく、バランスがとれている。", "sentence_source": "generated"}, {"text": "委員会は五人の委員で構成されている。", "target_word": "構成", "complexity_tier": "T3", "furigana": "委員会[いいんかい]は五人[ごにん]の委員[いいん]で構成[こうせい]されている。", "sentence_source": "generated"}, {"text": "論文の構成を考えてから、書き始めた。", "target_word": "構成", "complexity_tier": "T3", "furigana": "論文[ろんぶん]の構成[こうせい]を考[かんが]えてから、書[か]き始[はじ]めた。", "sentence_source": "generated"}, {"text": "水は水素と酸素から構成されている。", "target_word": "構成", "complexity_tier": "T3", "furigana": "水[みず]は水素[すいそ]と酸素[さんそ]から構成[こうせい]されている。", "sentence_source": "generated"}, {"text": "話の構成が悪く、何が言いたいのかわからなかった。", "target_word": "構成", "complexity_tier": "T3", "furigana": "話[はなし]の構成[こうせい]が悪[わる]く、何[なに]が言[い]いたいのかわからなかった。", "sentence_source": "generated"}, {"text": "この曲は、四つの楽章で構成されている。", "target_word": "構成", "complexity_tier": "T3", "furigana": "この曲[きょく]は、四[よっ]つの楽章[がくしょう]で構成[こうせい]されている。", "sentence_source": "generated"}, {"text": "映画の構成が巧みで、最後まで目が離せなかった。", "target_word": "構成", "complexity_tier": "T4", "furigana": "映画[えいが]の構成[こうせい]が巧[たく]みで、最後[さいご]まで目[め]が離[はな]せなかった。", "sentence_source": "generated"}, {"text": "クラスの男女の構成を調べたら、女子のほうが多かった。", "target_word": "構成", "complexity_tier": "T3", "furigana": "クラスの男女[だんじょ]の構成[こうせい]を調[しら]べたら、女子[じょし]のほうが多[おお]かった。", "sentence_source": "generated"}, {"text": "彼は番組の構成を担当し、話の順番を決めている。", "target_word": "構成", "complexity_tier": "T4", "furigana": "彼[かれ]は番組[ばんぐみ]の構成[こうせい]を担当[たんとう]し、話[はなし]の順番[じゅんばん]を決[き]めている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "構成する", "label": "dictionary form (suru verb)"}, {"form": "構成される", "label": "passive"}, {"form": "構成した", "label": "past"}], "register": "neutral", "sense_fingerprint": "要素を組み合わせて全体を作ること、またその組み合わせ方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T2: 5 words above tier T2 (max 3): 熟練 (Zipf 3.62), ソムリエ (Zipf 3.22), 味覚 (Zipf 3.61), 嗅覚 (Zipf 3.32), 読み解く (Zipf 3.08)']::text[], '32b69eeb-98c8-40d8-b5f5-d42b8a81ba55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36167, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "構成", "is_correct": true, "explanation": "「香りの構成」は香りを作る要素の組み合わせを指し、読み解く対象として自然。"}, {"text": "採用", "is_correct": false, "explanation": "採り入れる意味。「香りの採用を読み解く」では意味がつながらない。"}, {"text": "延期", "is_correct": false, "explanation": "予定を延ばす意味で、香りを味覚で読み解く文脈には合わない。"}, {"text": "宣伝", "is_correct": false, "explanation": "広く知らせる意味で、香りを読み解く文とは意味がつながらない。"}], "explanations": {"構成": "「香りの構成」は香りを作る要素の組み合わせを指し、読み解く対象として自然。", "採用": "採り入れる意味。「香りの採用を読み解く」では意味がつながらない。", "延期": "予定を延ばす意味で、香りを味覚で読み解く文脈には合わない。", "宣伝": "広く知らせる意味で、香りを読み解く文とは意味がつながらない。"}, "sentence_index": 0, "correct_answer": "構成"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "その文を英語に構成した。", "explanation": "ここは〈翻訳〉（別の言語に置き換える）の意味。構成は要素の組み合わせを指すので、言語を移す文には合わない。"}, {"text": "二つの物質を構成して、新しい薬を作った。", "explanation": "ここは〈合成〉（人工的に化合させる）の意味。構成は既にある要素がまとまっている状態を指すので、新しい物質を作る文には合わない。"}, {"text": "信頼関係を構成するには、長い時間がかかる。", "explanation": "ここは〈構築〉（時間をかけて積み上げる）の意味。構成は部品の組み合わせを指すので、関係を築く文には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ea9fa82-6a8e-445f-8c7b-21bcfdb23706') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36167, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "構成", "is_correct": true, "explanation": "「構成されている」の語幹。曲が複数の楽章から成ることを表し、空所に入る。"}, {"text": "延期", "is_correct": false, "explanation": "予定を延ばす意味。曲の楽章の作りを表す文とは合わない。"}, {"text": "献上", "is_correct": false, "explanation": "目上の人に差し出す意味。曲の楽章の作りを表す文とは意味がつながらない。"}, {"text": "清掃", "is_correct": false, "explanation": "掃除する意味。曲の構造を述べる文には入らない。"}], "explanations": {"構成": "「構成されている」の語幹。曲が複数の楽章から成ることを表し、空所に入る。", "延期": "予定を延ばす意味。曲の楽章の作りを表す文とは合わない。", "献上": "目上の人に差し出す意味。曲の楽章の作りを表す文とは意味がつながらない。", "清掃": "掃除する意味。曲の構造を述べる文には入らない。"}, "sentence_index": 6, "correct_answer": "構成"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "その構成が、遅刻の理由として先生に認められた。", "explanation": "ここは〈理由〉（原因となる事情）の意味。構成は要素の組み合わせを指すので、遅刻の原因を表す文には合わない。"}, {"text": "料理の構成を一つずつ量ってから、作り始めた。", "explanation": "ここは〈分量〉（材料の量）の意味。構成は要素の組み合わせを指すので、量って測る文には合わない。"}, {"text": "この受付の構成は三千円だった。", "explanation": "ここは〈値段〉（代金）の意味。構成は組み合わせ方を指すので、金額を示す文には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ea9fa82-6a8e-445f-8c7b-21bcfdb23706') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36167, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "このモデルは四つの部品で構成れている。", "corrected_sentence": "このモデルは四つの部品で構成されている。", "error_description": "「構成する」の受身は「構成される」。「構成れている」は活用が誤っていて、「構成されている」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ea9fa82-6a8e-445f-8c7b-21bcfdb23706') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36167, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "その報告書は三つの部分に構成されています。", "corrected_sentence": "その報告書は三つの部分で構成されています。", "error_description": "「構成される」は構成要素を「で」で示す。「に」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ea9fa82-6a8e-445f-8c7b-21bcfdb23706') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
