INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36170, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "ものが、前よりもっとすごいものや、新しいものに変わること。", "primary_collocate": null, "pronunciation": "しんか", "ipa": "ɕiŋka", "syllable_count": 3, "sentences": [{"text": "ゲームのキャラクターが進化して、強い姿に変わりました。", "target_word": "進化", "complexity_tier": "T3", "furigana": "ゲームのキャラクターが進化[しんか]して、強[つよ]い姿[すがた]に変[か]わりました。", "sentence_source": "generated"}, {"text": "この自転車は去年のものより進化していて、とても軽い。", "target_word": "進化", "complexity_tier": "T3", "furigana": "この自転車[じてんしゃ]は去年[きょねん]のものより進化[しんか]していて、とても軽[かる]い。", "sentence_source": "generated"}, {"text": "新しいスマートフォンは、前の機種から大きく進化した。", "target_word": "進化", "complexity_tier": "T3", "furigana": "新[あたら]しいスマートフォンは、前[まえ]の機種[きしゅ]から大[おお]きく進化[しんか]した。", "sentence_source": "generated"}, {"text": "弟が使っている動画編集ソフトは、アップデートで驚くほど進化した。", "target_word": "進化", "complexity_tier": "T3", "furigana": "弟[おとうと]が使っている動画編集[どうがへんしゅう]ソフトは、アップデートで驚くほど進化[しんか]した。", "sentence_source": "generated"}, {"text": "ポケモンが進化する場面を見て、子どもたちは大喜びした。", "target_word": "進化", "complexity_tier": "T3", "furigana": "ポケモンが進化[しんか]する場面[ばめん]を見[み]て、子[こ]どもたちは大喜[おおよろこ]びした。", "sentence_source": "generated"}, {"text": "このアプリは、使いやすく進化して人気が出ました。", "target_word": "進化", "complexity_tier": "T3", "furigana": "このアプリは、使[つか]いやすく進化[しんか]して人気[にんき]が出[で]ました。", "sentence_source": "generated"}, {"text": "古い掃除機が進化して、自分で動くロボットになった。", "target_word": "進化", "complexity_tier": "T3", "furigana": "古[ふる]い掃除機[そうじき]が進化[しんか]して、自分[じぶん]で動[うご]くロボットになった。", "sentence_source": "generated"}, {"text": "去年買い替えた炊飯器は、調理モードがずいぶん進化した。", "target_word": "進化", "complexity_tier": "T3", "furigana": "去年[きょねん]買い替[かいか]えた炊飯器[すいはんき]は、調理[ちょうり]モードがずいぶん進化[しんか]した。", "sentence_source": "generated"}, {"text": "進化した電気自動車は、音も静かで、走りもなめらかだ。", "target_word": "進化", "complexity_tier": "T3", "furigana": "進化[しんか]した電気自動車[でんきじどうしゃ]は、音[おと]も静[しず]かで、走[はし]りもなめらかだ。", "sentence_source": "generated"}, {"text": "今年の新しいモデルは去年より進化していて、燃費もずいぶん良くなった。", "target_word": "進化", "complexity_tier": "T3", "furigana": "今年[ことし]の新しいモデルは去年[きょねん]より進化[しんか]していて、燃費[ねんぴ]もずいぶん良く[よく]なった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "進化", "label": "基本形"}, {"form": "進化する", "label": "動詞形（する）"}, {"form": "進化した", "label": "過去形"}, {"form": "進化して", "label": "て形"}], "register": "neutral", "sense_fingerprint": "道具・機械・キャラクター・能力などが、前よりすごいものや新しいものに変わること（日常的でやさしい意味）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b09cdd42-7420-4776-b53c-9df05b93ebf1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36170, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "進化", "is_correct": true, "explanation": "キャラクターが強い姿に変わることを表し、「して」に続けて文の意味に合う。"}, {"text": "洗濯", "is_correct": false, "explanation": "衣類を洗う意味で、キャラクターの変化には合わない。"}, {"text": "渋滞", "is_correct": false, "explanation": "車などの流れが止まる意味で、姿の変化を表さない。"}, {"text": "睡眠", "is_correct": false, "explanation": "眠る意味で、強い姿に変わる文には合わない。"}], "explanations": {"進化": "キャラクターが強い姿に変わることを表し、「して」に続けて文の意味に合う。", "洗濯": "衣類を洗う意味で、キャラクターの変化には合わない。", "渋滞": "車などの流れが止まる意味で、姿の変化を表さない。", "睡眠": "眠る意味で、強い姿に変わる文には合わない。"}, "sentence_index": 0, "correct_answer": "進化"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "会社は来月から、勤務時間を進化することにした。", "explanation": "ここは〈変更〉の意味。決まりや予定を変える場合は変更を使い、進化は勤務時間には使わない。"}, {"text": "長く寝込んだあと、体力がずいぶん進化した。", "explanation": "ここは〈回復〉の意味。弱った体力が元に戻ることには回復を使い、進化は合わない。"}, {"text": "壊れた時計を店で進化させてもらった。", "explanation": "ここは〈修理〉の意味。壊れた物を直すのは修理で、進化は新しく高度にすることなので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e62be08b-44dc-4a57-a5de-3543ebd23134') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36170, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "進化", "is_correct": true, "explanation": "古い掃除機が新しい姿に変わる意味で、「して」に続けて自然に成り立つ。"}, {"text": "停電", "is_correct": false, "explanation": "電気が止まることで、ロボットになる変化とは合わない。"}, {"text": "旅行", "is_correct": false, "explanation": "移動する意味で、機械が姿を変える文には合わない。"}, {"text": "欠席", "is_correct": false, "explanation": "出席しない意味で、機械の変化を表さないため合わない。"}], "explanations": {"進化": "古い掃除機が新しい姿に変わる意味で、「して」に続けて自然に成り立つ。", "停電": "電気が止まることで、ロボットになる変化とは合わない。", "旅行": "移動する意味で、機械が姿を変える文には合わない。", "欠席": "出席しない意味で、機械の変化を表さないため合わない。"}, "sentence_index": 6, "correct_answer": "進化"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "チームは、長く続いた問題をついに進化した。", "explanation": "ここは〈解決〉の意味。問題を片付けて終わらせる場合は解決を使い、進化は問題には使わない。"}, {"text": "雨のため、試合を来週に進化した。", "explanation": "ここは〈延期〉の意味。予定を後ろにずらすのは延期で、進化は予定には使わない。"}, {"text": "この本を英語に進化した。", "explanation": "ここは〈翻訳〉の意味。別の言語に移すのは翻訳で、進化は言語の変換には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e62be08b-44dc-4a57-a5de-3543ebd23134') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36170, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "古いゲームが進化しで、新しい遊び方ができるようになった。", "corrected_sentence": "古いゲームが進化して、新しい遊び方ができるようになった。", "error_description": "「進化しで」は活用の誤り。て形は「進化して」で、「しで」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e62be08b-44dc-4a57-a5de-3543ebd23134') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36170, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "会社は、このロボットをさらに進化した。", "corrected_sentence": "会社は、このロボットをさらに進化させた。", "error_description": "「ロボットを」と目的語を取るには、他動詞の「進化させた」が必要。「進化した」は自動詞なので、「を」と合わず不自然になる。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e62be08b-44dc-4a57-a5de-3543ebd23134') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36171, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "退化", "is_correct": true, "explanation": "類語辞典で進化の対義語に挙がる。劣った状態へ戻る意味で、高度になる進化と対になる。"}, {"text": "変化", "is_correct": false, "explanation": "状態が変わること全般を指し、進化の反対語ではない。"}, {"text": "成熟", "is_correct": false, "explanation": "熟して完成に近づく意味で、進化の対義語ではない。"}, {"text": "完成", "is_correct": false, "explanation": "仕上がる意味で、進化と対になる関係にはならない。"}], "correct_answer": "退化", "explanations": {"退化": "類語辞典で進化の対義語に挙がる。劣った状態へ戻る意味で、高度になる進化と対になる。", "変化": "状態が変わること全般を指し、進化の反対語ではない。", "成熟": "熟して完成に近づく意味で、進化の対義語ではない。", "完成": "仕上がる意味で、進化と対になる関係にはならない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e62be08b-44dc-4a57-a5de-3543ebd23134') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36171, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "退化", "is_correct": true, "explanation": "類語辞典で進化の対義語に挙がる。劣った状態へ戻る意味で、高度になる進化と対になる。"}, {"text": "発展", "is_correct": false, "explanation": "進みよくなる方向の語で、進化と同じ向きなので対義語ではない。"}, {"text": "改良", "is_correct": false, "explanation": "悪い点を直して良くする意味で、進化の対義語ではない。"}, {"text": "成長", "is_correct": false, "explanation": "大きく育つ意味で、進化の反対語ではない。"}], "correct_answer": "退化", "explanations": {"退化": "類語辞典で進化の対義語に挙がる。劣った状態へ戻る意味で、高度になる進化と対になる。", "発展": "進みよくなる方向の語で、進化と同じ向きなので対義語ではない。", "改良": "悪い点を直して良くする意味で、進化の対義語ではない。", "成長": "大きく育つ意味で、進化の反対語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e62be08b-44dc-4a57-a5de-3543ebd23134') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36171, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事が長い時間をかけて、より複雑で高度な状態に変わっていくこと。", "primary_collocate": null, "pronunciation": "しんか", "ipa": "ɕiŋka", "syllable_count": 3, "sentences": [{"text": "誰が、どこで、何を、なぜ、どのように書くか、その技法が進化します。", "target_word": "進化", "complexity_tier": "T3", "furigana": "誰[だれ]が、どこで、何[なに]を、なぜ、どのように書[か]くか、その技法[ぎほう]が進化[しんか]します。", "sentence_source": "mined"}, {"text": "生物は長い時間をかけて、少しずつ進化してきました。", "target_word": "進化", "complexity_tier": "T3", "furigana": "生物[せいぶつ]は長[なが]い時間[じかん]をかけて、少[すこ]しずつ進化[しんか]してきました。", "sentence_source": "generated"}, {"text": "携帯電話は二十年ほどで大きく進化し、今ではカメラも地図も入っている。", "target_word": "進化", "complexity_tier": "T3", "furigana": "携帯電話[けいたいでんわ]は二十年[にじゅうねん]ほどで大[おお]きく進化[しんか]し、今[いま]ではカメラも地図[ちず]も入[はい]っている。", "sentence_source": "generated"}, {"text": "恐竜の一部は進化して、今の鳥になったと考えられています。", "target_word": "進化", "complexity_tier": "T3", "furigana": "恐竜[きょうりゅう]の一部[いちぶ]は進化[しんか]して、今[いま]の鳥[とり]になったと考[かんが]えられています。", "sentence_source": "generated"}, {"text": "人工知能の技術が進化したおかげで、翻訳はずっと正確になった。", "target_word": "進化", "complexity_tier": "T3", "furigana": "人工知能[じんこうちのう]の技術[ぎじゅつ]が進化[しんか]したおかげで、翻訳[ほんやく]はずっと正確[せいかく]になった。", "sentence_source": "generated"}, {"text": "都市の交通システムは、百年かけて複雑に進化した。", "target_word": "進化", "complexity_tier": "T3", "furigana": "都市[とし]の交通[こうつう]システムは、百年[ひゃくねん]かけて複雑[ふくざつ]に進化[しんか]した。", "sentence_source": "generated"}, {"text": "進化の過程で、人間は道具を使う能力を身につけた。", "target_word": "進化", "complexity_tier": "T3", "furigana": "進化[しんか]の過程[かてい]で、人間[にんげん]は道具[どうぐ]を使[つか]う能力[のうりょく]を身[み]につけた。", "sentence_source": "generated"}, {"text": "この会社のロボットは毎年進化していて、去年よりずっと器用に動く。", "target_word": "進化", "complexity_tier": "T3", "furigana": "この会社[かいしゃ]のロボットは毎年[まいとし]進化[しんか]していて、去年[きょねん]よりずっと器用[きよう]に動[うご]く。", "sentence_source": "generated"}, {"text": "魚から陸の動物へと進化するには、何百万年も必要だった。", "target_word": "進化", "complexity_tier": "T3", "furigana": "魚[さかな]から陸[りく]の動物[どうぶつ]へと進化[しんか]するには、何百万年[なんひゃくまんねん]も必要[ひつよう]だった。", "sentence_source": "generated"}, {"text": "料理の技術が進化したので、家でも店の味に近いものが作れる。", "target_word": "進化", "complexity_tier": "T3", "furigana": "料理[りょうり]の技術[ぎじゅつ]が進化[しんか]したので、家[いえ]でも店[みせ]の味[あじ]に近[ちか]いものが作[つく]れる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "進化", "label": "基本形"}, {"form": "進化する", "label": "動詞形（する）"}, {"form": "進化した", "label": "過去形"}, {"form": "進化して", "label": "て形"}], "register": "neutral", "sense_fingerprint": "生物・技術・仕組みなどが長い時間をかけて、複雑で高度な状態へ少しずつ変化していく過程", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b09cdd42-7420-4776-b53c-9df05b93ebf1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36171, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "進化", "is_correct": true, "explanation": "技法が複雑で高度な状態に変わることを表し、「その技法が」の述語として合う。"}, {"text": "消費", "is_correct": false, "explanation": "物を使い減らす意味で、技法が変わることは表さないため合わない。"}, {"text": "販売", "is_correct": false, "explanation": "商品を売る意味で、技法の変化を表せないため合わない。"}, {"text": "沈黙", "is_correct": false, "explanation": "声を出さないことで、技法の変化を表す文にはならない。"}], "explanations": {"進化": "技法が複雑で高度な状態に変わることを表し、「その技法が」の述語として合う。", "消費": "物を使い減らす意味で、技法が変わることは表さないため合わない。", "販売": "商品を売る意味で、技法の変化を表せないため合わない。", "沈黙": "声を出さないことで、技法の変化を表す文にはならない。"}, "sentence_index": 0, "correct_answer": "進化"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "その子は、数年で体が大きく進化した。", "explanation": "ここは〈成長〉の意味。人の体が大きくなるのは成長で、進化は種や仕組みが高度に変わる時に使う。"}, {"text": "天気が急に進化して、雨が降り出した。", "explanation": "ここは〈変化〉の意味。天気は変わるだけで高度になるわけではないので、進化は合わない。"}, {"text": "果物が十分に進化して、甘くなった。", "explanation": "ここは〈成熟〉の意味。果物が熟して食べごろになる変化は成熟で、進化は使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e62be08b-44dc-4a57-a5de-3543ebd23134') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36171, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "進化", "is_correct": true, "explanation": "能力を身につける過程という意味で、「の過程で」に続き文の意味に合う。"}, {"text": "停電", "is_correct": false, "explanation": "電気が止まることで、能力を身につける過程には合わない。"}, {"text": "渋滞", "is_correct": false, "explanation": "車の流れが止まる意味で、能力を身につける過程とは関係しない。"}, {"text": "洗濯", "is_correct": false, "explanation": "洗濯の過程では意味が通らず、能力を身につける過程とは結びつかない。"}], "explanations": {"進化": "能力を身につける過程という意味で、「の過程で」に続き文の意味に合う。", "停電": "電気が止まることで、能力を身につける過程には合わない。", "渋滞": "車の流れが止まる意味で、能力を身につける過程とは関係しない。", "洗濯": "洗濯の過程では意味が通らず、能力を身につける過程とは結びつかない。"}, "sentence_index": 6, "correct_answer": "進化"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "壊れた橋を進化して、通れるようにした。", "explanation": "ここは〈修復〉の意味。壊れた物を直すのは修復で、進化は高度になる変化なので合わない。"}, {"text": "町は人口が減って進化した。", "explanation": "ここは〈衰退〉の意味。勢いが弱まる変化には衰退を使い、進化は使わない。"}, {"text": "患者の体調は少しずつ進化した。", "explanation": "ここは〈回復〉の意味。病気や不調から元の状態に戻ることは回復で、進化は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e62be08b-44dc-4a57-a5de-3543ebd23134') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36171, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "進化を途中で、この鳥は翼を大きく発達させた。", "corrected_sentence": "進化の途中で、この鳥は翼を大きく発達させた。", "error_description": "誤りは「進化を」の「を」。「途中」は「〜の途中」と続けるので、進化に付くのは「の」が正しい。「を」では名詞「途中」につながらない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e62be08b-44dc-4a57-a5de-3543ebd23134') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36171, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "人類の進化が仕組みを、研究者が調べている。", "corrected_sentence": "人類の進化の仕組みを、研究者が調べている。", "error_description": "誤りは「進化が」の「が」。「仕組み」に続けるので「の」が正しい。「が」では進化が主語になり、仕組みが続かない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e62be08b-44dc-4a57-a5de-3543ebd23134') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36172, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "手段を示す。コンピューターを使って調べものをする文になる。"}, {"text": "が", "is_correct": false, "explanation": "主語を示すが、コンピューターが調べものをする文としては不自然で合わない。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示すが、「調べものをする」の前に目的語を置く形にはならないので合わない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示すが、「調べものをする」の手段にはならないので合わない。"}], "correct_answer": "で", "explanations": {"で": "手段を示す。コンピューターを使って調べものをする文になる。", "が": "主語を示すが、コンピューターが調べものをする文としては不自然で合わない。", "を": "目的語を示すが、「調べものをする」の前に目的語を置く形にはならないので合わない。", "へ": "方向を示すが、「調べものをする」の手段にはならないので合わない。"}, "error_tags": {"が": "主語", "を": "目的語", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19836b82-001c-42e6-ba97-1d1bf9ed206d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36172, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「買う」の目的語を示す。新しいコンピューターを買うという文になる。"}, {"text": "が", "is_correct": false, "explanation": "主語を示すが、「買う」の目的語にはならないので合わない。"}, {"text": "に", "is_correct": false, "explanation": "対象や方向を示すが、「買う」の目的語にはならないので合わない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示すが、「買う」の目的語にはならないので合わない。"}], "correct_answer": "を", "explanations": {"を": "「買う」の目的語を示す。新しいコンピューターを買うという文になる。", "が": "主語を示すが、「買う」の目的語にはならないので合わない。", "に": "対象や方向を示すが、「買う」の目的語にはならないので合わない。", "へ": "方向を示すが、「買う」の目的語にはならないので合わない。"}, "error_tags": {"が": "主語", "に": "対象・方向", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19836b82-001c-42e6-ba97-1d1bf9ed206d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36172, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "計算や情報の整理をする機械です。", "primary_collocate": null, "pronunciation": "こんぴゅーたー", "ipa": "kombjuːtaː", "syllable_count": 6, "sentences": [{"text": "父は、会社でコンピューターを使っています。", "target_word": "コンピューター", "complexity_tier": "T2", "furigana": "父[ちち]は、会社[かいしゃ]でコンピューターを使[つか]っています。", "sentence_source": "generated"}, {"text": "コンピューターで、宿題の調べものをしました。", "target_word": "コンピューター", "complexity_tier": "T2", "furigana": "コンピューターで、宿題[しゅくだい]の調[しら]べものをしました。", "sentence_source": "generated"}, {"text": "このコンピューターは、とても速いです。", "target_word": "コンピューター", "complexity_tier": "T2", "furigana": "このコンピューターは、とても速[はや]いです。", "sentence_source": "generated"}, {"text": "コンピューターが動かなくなって、困りました。", "target_word": "コンピューター", "complexity_tier": "T3", "furigana": "コンピューターが動[うご]かなくなって、困[こま]りました。", "sentence_source": "generated"}, {"text": "学校には、コンピューターが三十台あります。", "target_word": "コンピューター", "complexity_tier": "T3", "furigana": "学校[がっこう]には、コンピューターが三十台[さんじゅうだい]あります。", "sentence_source": "generated"}, {"text": "弟は、コンピューターでゲームをするのが好きです。", "target_word": "コンピューター", "complexity_tier": "T3", "furigana": "弟[おとうと]は、コンピューターでゲームをするのが好[す]きです。", "sentence_source": "generated"}, {"text": "コンピューターを使えば、計算がすぐ終わります。", "target_word": "コンピューター", "complexity_tier": "T3", "furigana": "コンピューターを使[つか]えば、計算[けいさん]がすぐ終[お]わります。", "sentence_source": "generated"}, {"text": "新しいコンピューターを、電気屋で買いました。", "target_word": "コンピューター", "complexity_tier": "T3", "furigana": "新[あたら]しいコンピューターを、電気屋[でんきや]で買[か]いました。", "sentence_source": "generated"}, {"text": "使わないときは、コンピューターの電源を切ります。", "target_word": "コンピューター", "complexity_tier": "T3", "furigana": "使[つか]わないときは、コンピューターの電源[でんげん]を切[き]ります。", "sentence_source": "generated"}, {"text": "姉はコンピューターで、レポートを書いています。", "target_word": "コンピューター", "complexity_tier": "T3", "furigana": "姉[あね]はコンピューターで、レポートを書[か]いています。", "sentence_source": "generated"}], "morphological_forms": [{"form": "コンピューター", "label": "基本形"}], "register": "標準（丁寧体）", "sense_fingerprint": "計算や調べもの、情報の整理に使う機械", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a823ebd7-d8b4-4527-9bc5-56dd45c51f93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36172, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "コンピューター", "is_correct": true, "explanation": "会社で使う機械として文が成り立つ語。"}, {"text": "ヨーグルト", "is_correct": false, "explanation": "食べ物の名前で、会社で使うものとして文が成り立たないので合わない。"}, {"text": "シャンプー", "is_correct": false, "explanation": "洗髪料の名前で、会社で使うものとして文が成り立たないので合わない。"}, {"text": "ギター", "is_correct": false, "explanation": "楽器の名前で、会社で使う文脈には合わないので合わない。"}], "explanations": {"コンピューター": "会社で使う機械として文が成り立つ語。", "ヨーグルト": "食べ物の名前で、会社で使うものとして文が成り立たないので合わない。", "シャンプー": "洗髪料の名前で、会社で使うものとして文が成り立たないので合わない。", "ギター": "楽器の名前で、会社で使う文脈には合わないので合わない。"}, "sentence_index": 0, "correct_answer": "コンピューター"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "雨が降ってきたので、コンピューターを傘の代わりにさして帰りました。", "explanation": "ここは〈雨具〉の用途。コンピューターは雨をよける道具ではないので合わない。"}, {"text": "お腹がすいたので、コンピューターで野菜を洗って料理しました。", "explanation": "ここは〈洗剤・水〉の役目。コンピューターは野菜を洗う道具ではないので合わない。"}, {"text": "新しい家を建てるために、コンピューターでレンガを積みました。", "explanation": "ここは〈建築材料〉の場面。コンピューターはレンガのような材料ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19836b82-001c-42e6-ba97-1d1bf9ed206d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36172, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "コンピューター", "is_correct": true, "explanation": "計算を速くする道具として文が成り立つ語。"}, {"text": "ハンカチ", "is_correct": false, "explanation": "持ち物の名前で、計算を速くする道具にはならないので合わない。"}, {"text": "バナナ", "is_correct": false, "explanation": "食べ物の名前で、計算を速くする道具にはならないので合わない。"}, {"text": "傘", "is_correct": false, "explanation": "雨具の名前で、計算を速くする道具にはならないので合わない。"}], "explanations": {"コンピューター": "計算を速くする道具として文が成り立つ語。", "ハンカチ": "持ち物の名前で、計算を速くする道具にはならないので合わない。", "バナナ": "食べ物の名前で、計算を速くする道具にはならないので合わない。", "傘": "雨具の名前で、計算を速くする道具にはならないので合わない。"}, "sentence_index": 6, "correct_answer": "コンピューター"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "朝ごはんに、コンピューターで卵をゆでました。", "explanation": "ここは〈調理器具〉の場面。コンピューターは卵をゆでる機器ではないので合わない。"}, {"text": "寒い日は、コンピューターで部屋を暖めました。", "explanation": "ここは〈暖房〉の場面。コンピューターは部屋を暖める機器ではないので合わない。"}, {"text": "姉の部屋の壁は、コンピューターでできています。", "explanation": "ここは〈建築材料〉の場面。コンピューターは壁の材料ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19836b82-001c-42e6-ba97-1d1bf9ed206d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36172, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "友だちは、家でコンピューターで使って宿題をします。", "corrected_sentence": "友だちは、家でコンピューターを使って宿題をします。", "error_description": "『使う』は『〜を使う』の形をとるので、『で』は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19836b82-001c-42e6-ba97-1d1bf9ed206d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
