INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36173, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "対象や位置を示す。コンピューターに入ったウイルスという文になる。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示すが、「入る」は『に』で場所を示すので合わない。"}, {"text": "で", "is_correct": false, "explanation": "場所や手段を示すが、「入る」の場所を示す形にはならないので合わない。"}, {"text": "と", "is_correct": false, "explanation": "相手や並列を示すが、「入る」の場所にはならないので合わない。"}], "correct_answer": "に", "explanations": {"に": "対象や位置を示す。コンピューターに入ったウイルスという文になる。", "を": "目的語を示すが、「入る」は『に』で場所を示すので合わない。", "で": "場所や手段を示すが、「入る」の場所を示す形にはならないので合わない。", "と": "相手や並列を示すが、「入る」の場所にはならないので合わない。"}, "error_tags": {"を": "目的語", "で": "場所・手段", "と": "相手・並列"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19836b82-001c-42e6-ba97-1d1bf9ed206d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36173, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "データを処理し、計算や情報の保存・表示を行う電子機器。", "primary_collocate": null, "pronunciation": "こんぴゅーたー", "ipa": "kombjuːtaː", "syllable_count": 6, "sentences": [{"text": "コンピューターは、大量のデータを短時間で処理できます。", "target_word": "コンピューター", "complexity_tier": "T4", "furigana": "コンピューターは、大量[たいりょう]のデータを短時間[たんじかん]で処理[しょり]できます。", "sentence_source": "generated"}, {"text": "このコンピューターは、記憶容量が大きいので写真を多く保存できます。", "target_word": "コンピューター", "complexity_tier": "T4", "furigana": "このコンピューターは、記憶容量[きおくようりょう]が大[おお]きいので写真[しゃしん]を多[おお]く保存[ほぞん]できます。", "sentence_source": "generated"}, {"text": "病院では、コンピューターで患者の情報を管理しています。", "target_word": "コンピューター", "complexity_tier": "T4", "furigana": "病院[びょういん]では、コンピューターで患者[かんじゃ]の情報[じょうほう]を管理[かんり]しています。", "sentence_source": "generated"}, {"text": "古いコンピューターは、最新のソフトが動かないことがあります。", "target_word": "コンピューター", "complexity_tier": "T4", "furigana": "古[ふる]いコンピューターは、最新[さいしん]のソフトが動[うご]かないことがあります。", "sentence_source": "generated"}, {"text": "コンピューターの画面に、計算の結果が表示されました。", "target_word": "コンピューター", "complexity_tier": "T3", "furigana": "コンピューターの画面[がめん]に、計算[けいさん]の結果[けっか]が表示[ひょうじ]されました。", "sentence_source": "generated"}, {"text": "工場のコンピューターが、機械の動きを制御しています。", "target_word": "コンピューター", "complexity_tier": "T4", "furigana": "工場[こうじょう]のコンピューターが、機械[きかい]の動[うご]きを制御[せいぎょ]しています。", "sentence_source": "generated"}, {"text": "彼は、コンピューターの仕組みを研究する学者です。", "target_word": "コンピューター", "complexity_tier": "T4", "furigana": "彼[かれ]は、コンピューターの仕組[しく]みを研究[けんきゅう]する学者[がくしゃ]です。", "sentence_source": "generated"}, {"text": "コンピューターにウイルスが入ると、データが壊れることがあります。", "target_word": "コンピューター", "complexity_tier": "T4", "furigana": "コンピューターにウイルスが入[はい]ると、データが壊[こわ]れることがあります。", "sentence_source": "generated"}, {"text": "天気予報は、コンピューターによる計算をもとに作られます。", "target_word": "コンピューター", "complexity_tier": "T4", "furigana": "天気予報[てんきよほう]は、コンピューターによる計算[けいさん]をもとに作[つく]られます。", "sentence_source": "generated"}, {"text": "停電でコンピューターが止まり、作業が中断しました。", "target_word": "コンピューター", "complexity_tier": "T4", "furigana": "停電[ていでん]でコンピューターが止[と]まり、作業[さぎょう]が中断[ちゅうだん]しました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "コンピューター", "label": "基本形"}], "register": "標準（丁寧体）", "sense_fingerprint": "データの処理、計算、情報の保存や表示を行う電子機器", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a823ebd7-d8b4-4527-9bc5-56dd45c51f93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36173, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "コンピューター", "is_correct": true, "explanation": "大量のデータを処理できる電子機器として文が成り立つ語。"}, {"text": "ケーキ", "is_correct": false, "explanation": "食べ物の名前で、データを処理できないので合わない。"}, {"text": "ボタン", "is_correct": false, "explanation": "服の部品の名前で、データを処理できないので合わない。"}, {"text": "ドライヤー", "is_correct": false, "explanation": "髪を乾かす機器で、データを処理できないので合わない。"}], "explanations": {"コンピューター": "大量のデータを処理できる電子機器として文が成り立つ語。", "ケーキ": "食べ物の名前で、データを処理できないので合わない。", "ボタン": "服の部品の名前で、データを処理できないので合わない。", "ドライヤー": "髪を乾かす機器で、データを処理できないので合わない。"}, "sentence_index": 0, "correct_answer": "コンピューター"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "寒い夜は、コンピューターを毛布のかわりに体にかけて眠りました。", "explanation": "ここは〈寝具〉の役目。コンピューターは体を温める布ではないので合わない。"}, {"text": "夏は、コンピューターを扇風機のかわりに部屋へ置いて涼みました。", "explanation": "ここは〈冷房・送風〉の役目。コンピューターは風を送る機器ではないので合わない。"}, {"text": "重い荷物は、コンピューターに入れて運びました。", "explanation": "ここは〈箱・容器〉の役目。コンピューターは荷物を入れる入れ物ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19836b82-001c-42e6-ba97-1d1bf9ed206d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36173, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "コンピューター", "is_correct": true, "explanation": "仕組みを研究する対象として文が成り立つ語。"}, {"text": "ヨーグルト", "is_correct": false, "explanation": "食べ物の名前で、仕組みを研究する対象として文が成り立たないので合わない。"}, {"text": "シャンプー", "is_correct": false, "explanation": "洗髪料の名前で、仕組みを研究する対象として文が成り立たないので合わない。"}, {"text": "ティッシュ", "is_correct": false, "explanation": "紙製品の名前で、仕組みを研究する対象として文が成り立たないので合わない。"}], "explanations": {"コンピューター": "仕組みを研究する対象として文が成り立つ語。", "ヨーグルト": "食べ物の名前で、仕組みを研究する対象として文が成り立たないので合わない。", "シャンプー": "洗髪料の名前で、仕組みを研究する対象として文が成り立たないので合わない。", "ティッシュ": "紙製品の名前で、仕組みを研究する対象として文が成り立たないので合わない。"}, "sentence_index": 6, "correct_answer": "コンピューター"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "停電のとき、コンピューターでお湯をわかしました。", "explanation": "ここは〈湯わかし〉の道具の場面。コンピューターは湯を沸かす機器ではないので合わない。"}, {"text": "寒い冬、暖房のかわりにコンピューターを部屋で使いました。", "explanation": "ここは〈ストーブ〉の役目。コンピューターは部屋を暖める機器ではないので合わない。"}, {"text": "彼女は毎朝、コンピューターで髪を乾かします。", "explanation": "ここは〈ドライヤー〉の用途の場面。コンピューターは髪を乾かす機器ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19836b82-001c-42e6-ba97-1d1bf9ed206d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36173, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "古いコンピューターを、新しいソフトをインストールしました。", "corrected_sentence": "古いコンピューターに、新しいソフトをインストールしました。", "error_description": "『インストールする』の先は『に』で示すので、『を』は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19836b82-001c-42e6-ba97-1d1bf9ed206d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36173, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "研究所では、コンピューターを実験データを集計しています。", "corrected_sentence": "研究所では、コンピューターで実験データを集計しています。", "error_description": "『集計する』の手段は『で』で示すので、『コンピューターを』の『を』は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19836b82-001c-42e6-ba97-1d1bf9ed206d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36174, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「エレクトロのライブ」で、ジャンル名とライブをつなぐ「の」。"}, {"text": "が", "is_correct": false, "explanation": "「エレクトロがライブ」では、ライブの主語として成り立たない。"}, {"text": "を", "is_correct": false, "explanation": "「エレクトロをライブ」では、ライブを目的語にできず不自然。"}, {"text": "へ", "is_correct": false, "explanation": "「エレクトロへライブ」は方向の意味にならず、文が成り立たない。"}], "correct_answer": "の", "explanations": {"の": "「エレクトロのライブ」で、ジャンル名とライブをつなぐ「の」。", "が": "「エレクトロがライブ」では、ライブの主語として成り立たない。", "を": "「エレクトロをライブ」では、ライブを目的語にできず不自然。", "へ": "「エレクトロへライブ」は方向の意味にならず、文が成り立たない。"}, "error_tags": {"が": "主語", "を": "目的語", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8c29ec8-8fc2-4ddd-a8d5-f4dfa75a1261') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36174, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「エレクトロを聞きながら」で、聞く対象（音楽）を示す「を」。"}, {"text": "に", "is_correct": false, "explanation": "「エレクトロに聞きながら」では、人に尋ねる意味になり不自然。"}, {"text": "より", "is_correct": false, "explanation": "「エレクトロより聞きながら」は比較の文にならず、成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「エレクトロと聞きながら」は並列の意味にならず、文の流れが合わない。"}], "correct_answer": "を", "explanations": {"を": "「エレクトロを聞きながら」で、聞く対象（音楽）を示す「を」。", "に": "「エレクトロに聞きながら」では、人に尋ねる意味になり不自然。", "より": "「エレクトロより聞きながら」は比較の文にならず、成り立たない。", "と": "「エレクトロと聞きながら」は並列の意味にならず、文の流れが合わない。"}, "error_tags": {"に": "相手", "より": "比較", "と": "並列"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8c29ec8-8fc2-4ddd-a8d5-f4dfa75a1261') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36174, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "電子音を中心に作る音楽のジャンルのこと。", "primary_collocate": null, "pronunciation": "えれくとろ", "ipa": "eɾekɯtoɾo", "syllable_count": 5, "sentences": [{"text": "私はエレクトロが好きで、毎朝通学中に聞いています。", "target_word": "エレクトロ", "complexity_tier": "T3", "furigana": "私[わたし]はエレクトロが好[す]きで、毎朝[まいあさ]通学中[つうがくちゅう]に聞[き]いています。", "sentence_source": "generated"}, {"text": "友だちに勧められて、初めてエレクトロのライブに行きました。", "target_word": "エレクトロ", "complexity_tier": "T3", "furigana": "友[とも]だちに勧[すす]められて、初[はじ]めてエレクトロのライブに行[い]きました。", "sentence_source": "generated"}, {"text": "エレクトロは機械で作った音が多いので、ギターの音はあまり出てきません。", "target_word": "エレクトロ", "complexity_tier": "T3", "furigana": "エレクトロは機械[きかい]で作[つく]った音[おと]が多[おお]いので、ギターの音[おと]はあまり出[で]てきません。", "sentence_source": "generated"}, {"text": "この店ではいつもエレクトロが流れていて、少し未来の場所のようです。", "target_word": "エレクトロ", "complexity_tier": "T3", "furigana": "この店[みせ]ではいつもエレクトロが流[なが]れていて、少[すこ]し未来[みらい]の場所[ばしょ]のようです。", "sentence_source": "generated"}, {"text": "兄はパソコンでエレクトロの曲を作るのが趣味です。", "target_word": "エレクトロ", "complexity_tier": "T3", "furigana": "兄[あに]はパソコンでエレクトロの曲[きょく]を作[つく]るのが趣味[しゅみ]です。", "sentence_source": "generated"}, {"text": "クラシックは静かですが、エレクトロは速くて体が自然に動きます。", "target_word": "エレクトロ", "complexity_tier": "T3", "furigana": "クラシックは静[しず]かですが、エレクトロは速[はや]くて体[からだ]が自然[しぜん]に動[うご]きます。", "sentence_source": "generated"}, {"text": "夜のドライブにはエレクトロが合うと思って、新しい曲を集めました。", "target_word": "エレクトロ", "complexity_tier": "T3", "furigana": "夜[よる]のドライブにはエレクトロが合[あ]うと思[おも]って、新[あたら]しい曲[きょく]を集[あつ]めました。", "sentence_source": "generated"}, {"text": "エレクトロを聞きながら勉強すると、リズムが気になって集中できません。", "target_word": "エレクトロ", "complexity_tier": "T3", "furigana": "エレクトロを聞[き]きながら勉強[べんきょう]すると、リズムが気[き]になって集中[しゅうちゅう]できません。", "sentence_source": "generated"}, {"text": "彼女はバンド活動をやめて、エレクトロの音楽家になりました。", "target_word": "エレクトロ", "complexity_tier": "T3", "furigana": "彼女[かのじょ]はバンド活動[かつどう]をやめて、エレクトロの音楽家[おんがくか]になりました。", "sentence_source": "generated"}, {"text": "日本でもエレクトロのイベントが増えて、若い人が多く集まっています。", "target_word": "エレクトロ", "complexity_tier": "T3", "furigana": "日本[にほん]でもエレクトロのイベントが増[ふ]えて、若[わか]い人[ひと]が多[おお]く集[あつ]まっています。", "sentence_source": "generated"}], "morphological_forms": [{"form": "エレクトロ", "label": "基本形"}], "register": "標準（です・ます体中心）", "sense_fingerprint": "電子音で作る音楽。機械が作る音を中心にした曲のこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b78c6ea7-fce0-4b94-ac7e-cd644dd6d111') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36174, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "エレクトロ", "is_correct": true, "explanation": "電子音で作る音楽のジャンル名。「好きで聞いている」と自然につながる。"}, {"text": "楽譜", "is_correct": false, "explanation": "楽譜は読むものなので、「毎朝通学中に聞く」とは合わない。"}, {"text": "作曲", "is_correct": false, "explanation": "作曲は作る行為で、聞くものではないので「聞いています」と合わない。"}, {"text": "漫画", "is_correct": false, "explanation": "漫画は読むものなので、「通学中に聞く」とは続かない。"}], "explanations": {"エレクトロ": "電子音で作る音楽のジャンル名。「好きで聞いている」と自然につながる。", "楽譜": "楽譜は読むものなので、「毎朝通学中に聞く」とは合わない。", "作曲": "作曲は作る行為で、聞くものではないので「聞いています」と合わない。", "漫画": "漫画は読むものなので、「通学中に聞く」とは続かない。"}, "sentence_index": 0, "correct_answer": "エレクトロ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "お店の前に、新しいエレクトロが出ました。", "explanation": "ここは〈看板〉の意味。エレクトロは音楽のジャンルを指すので、店先に出す表示物には使えない。"}, {"text": "停電でエレクトロが消えて、部屋は真っ暗になりました。", "explanation": "ここは〈電気〉の意味。エレクトロは電気そのものではなく、電子音を使った音楽を指すので合わない。"}, {"text": "エレクトロは極めて小さく、原子の周りを回っています。", "explanation": "ここは〈電子〉（粒子）の意味。エレクトロは音楽や電子機器を指すので、原子の中の粒子には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8c29ec8-8fc2-4ddd-a8d5-f4dfa75a1261') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36174, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "エレクトロ", "is_correct": true, "explanation": "夜のドライブに合う、電子音の音楽ジャンル。「合う」と続いて文が成り立つ。"}, {"text": "辞書", "is_correct": false, "explanation": "辞書は調べるものなので、夜のドライブに合うとは言えない。"}, {"text": "日記", "is_correct": false, "explanation": "日記は書くものなので、ドライブに合う、とは続かない。"}, {"text": "教科書", "is_correct": false, "explanation": "教科書は勉強に使うもので、ドライブの曲の文脈には合わない。"}], "explanations": {"エレクトロ": "夜のドライブに合う、電子音の音楽ジャンル。「合う」と続いて文が成り立つ。", "辞書": "辞書は調べるものなので、夜のドライブに合うとは言えない。", "日記": "日記は書くものなので、ドライブに合う、とは続かない。", "教科書": "教科書は勉強に使うもので、ドライブの曲の文脈には合わない。"}, "sentence_index": 6, "correct_answer": "エレクトロ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "スマホのエレクトロが切れて、写真が撮れませんでした。", "explanation": "ここは〈電池〉の意味。「切れる」は電池の残りがなくなることに使うが、エレクトロは音楽のジャンルを指すので電池の残量の話には合わない。"}, {"text": "エレクトロが流れると、回路が熱くなります。", "explanation": "ここは〈電流〉の意味。エレクトロは音楽のジャンルで、回路を流れる電気は指さない。"}, {"text": "山の中でエレクトロが入らず、地図が見られませんでした。", "explanation": "ここは〈電波〉の意味。エレクトロは音楽のジャンルで、通信の電波が届かないことは表せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8c29ec8-8fc2-4ddd-a8d5-f4dfa75a1261') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36174, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "私は毎朝、通学中にエレクトロに聞いています。", "corrected_sentence": "私は毎朝、通学中にエレクトロを聞いています。", "error_description": "「聞く」の対象（音楽）には「を」を使う。「に」は人に尋ねる相手を示すので誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8c29ec8-8fc2-4ddd-a8d5-f4dfa75a1261') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36174, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "最近、エレクトロを好きな人が増えました。", "corrected_sentence": "最近、エレクトロが好きな人が増えました。", "error_description": "「好き」は「が」を取る。「を」は誤りで、正しくは「エレクトロが好きな人」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8c29ec8-8fc2-4ddd-a8d5-f4dfa75a1261') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
