INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36175, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "から", "options": [{"text": "から", "is_correct": true, "explanation": "「エレクトロから始まって」で、始まりの起点を示す「から」。"}, {"text": "と", "is_correct": false, "explanation": "「エレクトロと始まって」は並列の意味にならず、文が成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "「エレクトロより始まって」は比較の文にならず、不自然。"}, {"text": "へ", "is_correct": false, "explanation": "「エレクトロへ始まって」は方向の意味にならず、文が成り立たない。"}], "correct_answer": "から", "explanations": {"から": "「エレクトロから始まって」で、始まりの起点を示す「から」。", "と": "「エレクトロと始まって」は並列の意味にならず、文が成り立たない。", "より": "「エレクトロより始まって」は比較の文にならず、不自然。", "へ": "「エレクトロへ始まって」は方向の意味にならず、文が成り立たない。"}, "error_tags": {"と": "並列", "より": "比較", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8c29ec8-8fc2-4ddd-a8d5-f4dfa75a1261') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36175, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "電子技術を利用した音楽のジャンルの名前。", "primary_collocate": null, "pronunciation": "えれくとろ", "ipa": "eɾekɯtoɾo", "syllable_count": 5, "sentences": [{"text": "エレクトロというジャンルは、電子音を中心にした音楽です。", "target_word": "エレクトロ", "complexity_tier": "T3", "furigana": "エレクトロというジャンルは、電子音[でんしおん]を中心[ちゅうしん]にした音楽[おんがく]です。", "sentence_source": "generated"}, {"text": "音楽のジャンルの中で、私はロックよりエレクトロのほうが好きです。", "target_word": "エレクトロ", "complexity_tier": "T3", "furigana": "音楽[おんがく]のジャンルの中[なか]で、私[わたし]はロックよりエレクトロのほうが好[す]きです。", "sentence_source": "generated"}, {"text": "昔のゲーム音楽には、エレクトロの要素がたくさん入っています。", "target_word": "エレクトロ", "complexity_tier": "T3", "furigana": "昔[むかし]のゲーム音楽[おんがく]には、エレクトロの要素[ようそ]がたくさん入[はい]っています。", "sentence_source": "generated"}, {"text": "このアルバムは、ジャズとエレクトロを混ぜた新しい作品です。", "target_word": "エレクトロ", "complexity_tier": "T3", "furigana": "このアルバムは、ジャズとエレクトロを混[ま]ぜた新[あたら]しい作品[さくひん]です。", "sentence_source": "generated"}, {"text": "エレクトロの人気が上がって、ダンスクラブも増えました。", "target_word": "エレクトロ", "complexity_tier": "T3", "furigana": "エレクトロの人気[にんき]が上[あ]がって、ダンスクラブも増[ふ]えました。", "sentence_source": "generated"}, {"text": "先生は授業で、エレクトロの歴史を短く説明してくれました。", "target_word": "エレクトロ", "complexity_tier": "T3", "furigana": "先生[せんせい]は授業[じゅぎょう]で、エレクトロの歴史[れきし]を短[みじか]く説明[せつめい]してくれました。", "sentence_source": "generated"}, {"text": "電子楽器がなければ、エレクトロは生まれなかったでしょう。", "target_word": "エレクトロ", "complexity_tier": "T3", "furigana": "電子楽器[でんしがっき]がなければ、エレクトロは生[う]まれなかったでしょう。", "sentence_source": "generated"}, {"text": "彼のDJは、エレクトロから始まって最後はハウスで終わりました。", "target_word": "エレクトロ", "complexity_tier": "T3", "furigana": "彼[かれ]のDJは、エレクトロから始[はじ]まって最後[さいご]はハウスで終[お]わりました。", "sentence_source": "generated"}, {"text": "海外のフェスで、エレクトロの有名なグループを見ました。", "target_word": "エレクトロ", "complexity_tier": "T3", "furigana": "海外[かいがい]のフェスで、エレクトロの有名[ゆうめい]なグループを見[み]ました。", "sentence_source": "generated"}, {"text": "エレクトロは機械の音が主役なので、歌がない曲も珍しくありません。", "target_word": "エレクトロ", "complexity_tier": "T3", "furigana": "エレクトロは機械[きかい]の音[おと]が主役[しゅやく]なので、歌[うた]がない曲[きょく]も珍[めずら]しくありません。", "sentence_source": "generated"}], "morphological_forms": [{"form": "エレクトロ", "label": "基本形"}], "register": "標準（です・ます体中心）", "sense_fingerprint": "電子技術から生まれた音楽ジャンルの名前としてのエレクトロ", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b78c6ea7-fce0-4b94-ac7e-cd644dd6d111') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36175, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "エレクトロ", "is_correct": true, "explanation": "電子音中心の音楽ジャンルの名前。「というジャンル」に入って文が成り立つ。"}, {"text": "鉛筆", "is_correct": false, "explanation": "鉛筆はジャンルではないので、「というジャンル」と続かない。"}, {"text": "教室", "is_correct": false, "explanation": "教室は場所で、ジャンルの名前にはならない。"}, {"text": "天気", "is_correct": false, "explanation": "天気はジャンルの名前にならず、文が成り立たない。"}], "explanations": {"エレクトロ": "電子音中心の音楽ジャンルの名前。「というジャンル」に入って文が成り立つ。", "鉛筆": "鉛筆はジャンルではないので、「というジャンル」と続かない。", "教室": "教室は場所で、ジャンルの名前にはならない。", "天気": "天気はジャンルの名前にならず、文が成り立たない。"}, "sentence_index": 0, "correct_answer": "エレクトロ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "コップにエレクトロを入れて、ゆっくり飲みました。", "explanation": "ここは〈水〉の意味。エレクトロは音楽のジャンルや電子機器を指すので、飲み物として入れることはできない。"}, {"text": "エレクトロは原子の周りを回っています。", "explanation": "ここは〈電子〉（粒子）の意味。エレクトロは音楽や電子機器を指し、原子の中の粒子は指さない。"}, {"text": "雨が降ってきたので、エレクトロをさして歩きました。", "explanation": "ここは〈傘〉の意味。「さす」は傘に使う動詞で、音楽のジャンルには合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8c29ec8-8fc2-4ddd-a8d5-f4dfa75a1261') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36175, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "エレクトロ", "is_correct": true, "explanation": "電子楽器から生まれた音楽ジャンル。「生まれる」の主語として文が成り立つ。"}, {"text": "雨", "is_correct": false, "explanation": "雨は電子楽器から生まれるものではなく、文脈に合わない。"}, {"text": "辞書", "is_correct": false, "explanation": "辞書は電子楽器と関係がなく、「生まれる」の主語にならない。"}, {"text": "地図", "is_correct": false, "explanation": "地図は電子楽器から生まれるものではなく、文脈に合わない。"}], "explanations": {"エレクトロ": "電子楽器から生まれた音楽ジャンル。「生まれる」の主語として文が成り立つ。", "雨": "雨は電子楽器から生まれるものではなく、文脈に合わない。", "辞書": "辞書は電子楽器と関係がなく、「生まれる」の主語にならない。", "地図": "地図は電子楽器から生まれるものではなく、文脈に合わない。"}, "sentence_index": 6, "correct_answer": "エレクトロ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "エレクトロが遅れて、会議に間に合いませんでした。", "explanation": "ここは〈電車〉の意味。「遅れる」は乗り物の到着に使うが、エレクトロは音楽のジャンルや電子機器を指すので合わない。"}, {"text": "今日はエレクトロが悪いので、家でゆっくりしました。", "explanation": "ここは〈天気〉の意味。「悪い」は天気に使うが、エレクトロは音楽のジャンルを指すので合わない。"}, {"text": "夏休みのエレクトロを、朝のうちに終わらせました。", "explanation": "ここは〈宿題〉の意味。エレクトロは音楽のジャンルや電子機器なので、終わらせる課題には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8c29ec8-8fc2-4ddd-a8d5-f4dfa75a1261') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36175, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼はエレクトロに有名なDJです。", "corrected_sentence": "彼はエレクトロで有名なDJです。", "error_description": "「有名」には分野を示す「で」を使う。「に」は誤りで、正しくは「エレクトロで有名」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8c29ec8-8fc2-4ddd-a8d5-f4dfa75a1261') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36175, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "最近は、エレクトロで取り入れた曲が増えました。", "corrected_sentence": "最近は、エレクトロを取り入れた曲が増えました。", "error_description": "「取り入れる」は取り込む対象に「を」を使う。「で」は誤りで、正しくは「エレクトロを取り入れた」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8c29ec8-8fc2-4ddd-a8d5-f4dfa75a1261') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36177, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "所有・修飾の『の』。『アコースティックの音』のように名詞をつなぐ正しい形。"}, {"text": "に", "is_correct": false, "explanation": "位置・相手の格。『に』は場所や相手を表すので、名詞を修飾する位置には入らない。"}, {"text": "が", "is_correct": false, "explanation": "主語の格。『アコースティックが音』とすると名詞同士がつながらず、文の意味が通らない。"}, {"text": "へ", "is_correct": false, "explanation": "方向の格。『へ』は向かう先を表すので、名詞をつなぐ位置には合わない。"}], "correct_answer": "の", "explanations": {"の": "所有・修飾の『の』。『アコースティックの音』のように名詞をつなぐ正しい形。", "に": "位置・相手の格。『に』は場所や相手を表すので、名詞を修飾する位置には入らない。", "が": "主語の格。『アコースティックが音』とすると名詞同士がつながらず、文の意味が通らない。", "へ": "方向の格。『へ』は向かう先を表すので、名詞をつなぐ位置には合わない。"}, "error_tags": {}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6246d581-4712-49cb-8136-42a49a1494df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36177, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "対象の格。『〜を中心に』で中心に置くものを表すので『を』が正しい。"}, {"text": "と", "is_correct": false, "explanation": "共同・引用の格。『と』は並ぶ相手や引用を表すので、『中心に』の前には入らない。"}, {"text": "から", "is_correct": false, "explanation": "起点の格。『から』は出発点を表すが、中心となる対象は示せないので合わない。"}, {"text": "で", "is_correct": false, "explanation": "手段・場所の格。『で』は手段や場所を表すが、『中心に』の対象は『を』で示す。"}], "correct_answer": "を", "explanations": {"を": "対象の格。『〜を中心に』で中心に置くものを表すので『を』が正しい。", "と": "共同・引用の格。『と』は並ぶ相手や引用を表すので、『中心に』の前には入らない。", "から": "起点の格。『から』は出発点を表すが、中心となる対象は示せないので合わない。", "で": "手段・場所の格。『で』は手段や場所を表すが、『中心に』の対象は『を』で示す。"}, "error_tags": {}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6246d581-4712-49cb-8136-42a49a1494df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36177, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "電気で音を大きくしないで、楽器が自然に出す音や、その演奏のスタイル。", "primary_collocate": null, "pronunciation": "あこーすてぃっく", "ipa": "akoːsɯtikːɯ", "syllable_count": 7, "sentences": [{"text": "このバンドは、アコースティックの演奏で人気が出た。", "target_word": "アコースティック", "complexity_tier": "T3", "furigana": "このバンドは、アコースティックの演奏[えんそう]で人気[にんき]が出[で]た。", "sentence_source": "generated"}, {"text": "アコースティックの音は、あたたかくてやさしい。", "target_word": "アコースティック", "complexity_tier": "T3", "furigana": "アコースティックの音[おと]は、あたたかくてやさしい。", "sentence_source": "generated"}, {"text": "今夜のライブは、マイクを使わずアコースティックで歌う。", "target_word": "アコースティック", "complexity_tier": "T3", "furigana": "今夜[こんや]のライブは、マイクを使[つか]わずアコースティックで歌[うた]う。", "sentence_source": "generated"}, {"text": "小さな部屋では、アコースティックの響きがよく伝わる。", "target_word": "アコースティック", "complexity_tier": "T3", "furigana": "小[ちい]さな部屋[へや]では、アコースティックの響[ひび]きがよく伝[つた]わる。", "sentence_source": "generated"}, {"text": "彼は電気を使わず、アコースティックで曲を録音した。", "target_word": "アコースティック", "complexity_tier": "T3", "furigana": "彼[かれ]は電気[でんき]を使[つか]わず、アコースティックで曲[きょく]を録音[ろくおん]した。", "sentence_source": "generated"}, {"text": "この曲はアコースティックにすると、雰囲気が静かになる。", "target_word": "アコースティック", "complexity_tier": "T3", "furigana": "この曲[きょく]はアコースティックにすると、雰囲気[ふんいき]が静[しず]かになる。", "sentence_source": "generated"}, {"text": "カフェで、アコースティックのライブを聞いた。", "target_word": "アコースティック", "complexity_tier": "T3", "furigana": "カフェで、アコースティックのライブを聞[き]いた。", "sentence_source": "generated"}, {"text": "新しいアルバムは、アコースティックを中心に作られている。", "target_word": "アコースティック", "complexity_tier": "T3", "furigana": "新[あたら]しいアルバムは、アコースティックを中心[ちゅうしん]に作[つく]られている。", "sentence_source": "generated"}, {"text": "古い歌をアコースティックでやり直したら、また人気が出た。", "target_word": "アコースティック", "complexity_tier": "T3", "furigana": "古[ふる]い歌[うた]をアコースティックでやり直[なお]したら、また人気[にんき]が出[で]た。", "sentence_source": "generated"}, {"text": "アコースティックの音を聞くと、心が落ち着く。", "target_word": "アコースティック", "complexity_tier": "T3", "furigana": "アコースティックの音[おと]を聞[き]くと、心[こころ]が落[お]ち着[つ]く。", "sentence_source": "generated"}], "morphological_forms": [{"form": "アコースティック", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "電気で増幅しない、楽器が自然に出す音や演奏のスタイル", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8b526506-9c46-4ef2-864a-493950eda46d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36177, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "アコースティック", "is_correct": true, "explanation": "電気で増幅しない演奏のスタイルを指す。『このバンドの演奏』として自然に入る。"}, {"text": "ボリューム", "is_correct": false, "explanation": "ボリュームは音量の調節のことで、演奏の種類ではないので『ボリュームの演奏』とは言えない。"}, {"text": "チューナー", "is_correct": false, "explanation": "チューナーは音程を合わせる機械で、演奏のスタイルではないので文に合わない。"}, {"text": "テンポ", "is_correct": false, "explanation": "テンポは曲の速さのことで、演奏の種類とは言えないので『テンポの演奏』は合わない。"}], "explanations": {"アコースティック": "電気で増幅しない演奏のスタイルを指す。『このバンドの演奏』として自然に入る。", "ボリューム": "ボリュームは音量の調節のことで、演奏の種類ではないので『ボリュームの演奏』とは言えない。", "チューナー": "チューナーは音程を合わせる機械で、演奏のスタイルではないので文に合わない。", "テンポ": "テンポは曲の速さのことで、演奏の種類とは言えないので『テンポの演奏』は合わない。"}, "sentence_index": 0, "correct_answer": "アコースティック"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この曲は、アコースティックで音を電気で大きくして迫力を出す。", "explanation": "ここは〈エレキ（電気で増幅する）〉の意味。アコースティックは電気で音を大きくしない音のことなので、電気で大きくする文には合わない。"}, {"text": "新しいアルバムは、アコースティックで電子音を重ねて作られている。", "explanation": "ここは〈シンセサイザー〉の意味。電子音を作る機材の話で、電気を使わない自然な音を指すアコースティックとは合わない。"}, {"text": "会場の後ろまで音を届けるため、アコースティックを三台並べた。", "explanation": "ここは〈スピーカー〉の意味。台で数える音響機器の話で、音そのものを指すアコースティックは台では数えないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6246d581-4712-49cb-8136-42a49a1494df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36177, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "アコースティック", "is_correct": true, "explanation": "電気で増幅しない演奏スタイルの意味。カフェで聞くライブの種類として合う。"}, {"text": "電気", "is_correct": false, "explanation": "電気はライブの種類ではないので、『電気のライブ』は不自然。"}, {"text": "楽譜", "is_correct": false, "explanation": "楽譜は演奏の材料で、ライブの種類を表さないので文に合わない。"}, {"text": "作曲", "is_correct": false, "explanation": "作曲は曲を作る行為で、ライブの種類にはならないので合わない。"}], "explanations": {"アコースティック": "電気で増幅しない演奏スタイルの意味。カフェで聞くライブの種類として合う。", "電気": "電気はライブの種類ではないので、『電気のライブ』は不自然。", "楽譜": "楽譜は演奏の材料で、ライブの種類を表さないので文に合わない。", "作曲": "作曲は曲を作る行為で、ライブの種類にはならないので合わない。"}, "sentence_index": 6, "correct_answer": "アコースティック"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "アコースティックで各楽器の音量を調整する。", "explanation": "ここは〈ミキサー〉の意味。音量を調整する機材の働きで、電気を使わない意味のアコースティックでは扱えない。"}, {"text": "アコースティックをかけると、音がひずんで荒くなる。", "explanation": "ここは〈ディストーション（エフェクター）〉の意味。音を加工する機材の名前で、アコースティックとは合わない。"}, {"text": "ステージの前で、アコースティックを口元に近づけて声を拾った。", "explanation": "ここは〈マイク〉の意味。声を拾う機器の話で、楽器が自然に出す音を指すアコースティックとは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6246d581-4712-49cb-8136-42a49a1494df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36177, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "このカフェは、ふだんアコースティックを演奏をしている。", "corrected_sentence": "このカフェは、ふだんアコースティックで演奏をしている。", "error_description": "『を』が二つ重なっている（『アコースティックを』と『演奏をしている』）。手段や様式は『で』で示すので、正しくは『アコースティックで演奏をしている』。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6246d581-4712-49cb-8136-42a49a1494df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36177, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "弟は、アコースティックで歌いことを習っている。", "corrected_sentence": "弟は、アコースティックで歌うことを習っている。", "error_description": "『アコースティックで歌う』の『歌う』の活用が誤り。『歌いこと』ではなく辞書形の『歌うこと』が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6246d581-4712-49cb-8136-42a49a1494df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36178, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「読む」の目的語を示し、「文脈を読まずに」という自然な文になる。"}, {"text": "に", "is_correct": false, "explanation": "「文脈に読まず」は「読む」と結びつかず、不自然で意味が通らない。"}, {"text": "が", "is_correct": false, "explanation": "「文脈が読まず」は「読む」の主語として成り立たず、文が成立しない。"}, {"text": "へ", "is_correct": false, "explanation": "「文脈へ読まず」は方向を表すが、「読む」の対象として成り立たないので合わない。"}], "correct_answer": "を", "explanations": {"を": "「読む」の目的語を示し、「文脈を読まずに」という自然な文になる。", "に": "「文脈に読まず」は「読む」と結びつかず、不自然で意味が通らない。", "が": "「文脈が読まず」は「読む」の主語として成り立たず、文が成立しない。", "へ": "「文脈へ読まず」は方向を表すが、「読む」の対象として成り立たないので合わない。"}, "error_tags": {"に": "場所", "が": "主語", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8c29ec8-8fc2-4ddd-a8d5-f4dfa75a1261') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36178, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「知る」の目的語を示し、「歴史的な文脈を知ると」という自然な文になる。"}, {"text": "が", "is_correct": false, "explanation": "「文脈が知る」は主語と述語が成立せず、文の意味が通らない。"}, {"text": "と", "is_correct": false, "explanation": "「文脈と知ると」は意味が通らず、「知る」の対象として成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「文脈の知ると」は名詞を修飾する形にならず、文が成立しない。"}], "correct_answer": "を", "explanations": {"を": "「知る」の目的語を示し、「歴史的な文脈を知ると」という自然な文になる。", "が": "「文脈が知る」は主語と述語が成立せず、文の意味が通らない。", "と": "「文脈と知ると」は意味が通らず、「知る」の対象として成り立たない。", "の": "「文脈の知ると」は名詞を修飾する形にならず、文が成立しない。"}, "error_tags": {"が": "主語", "と": "相手", "の": "所属"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8c29ec8-8fc2-4ddd-a8d5-f4dfa75a1261') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36178, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "お話や文章の中で、ことばが使われている場面や状況のこと。", "primary_collocate": null, "pronunciation": "ぶんみゃく", "ipa": "bɯɴmʲaku", "syllable_count": 4, "sentences": [{"text": "この言葉の意味は、文脈によって変わる。", "target_word": "文脈", "complexity_tier": "T3", "furigana": "この言葉[ことば]の意味[いみ]は、文脈[ぶんみゃく]によって変[か]わる。", "sentence_source": "generated"}, {"text": "文脈を読まずに一文だけ取り出すと、誤解しやすい。", "target_word": "文脈", "complexity_tier": "T3", "furigana": "文脈[ぶんみゃく]を読[よ]まずに一文[いちぶん]だけ取[と]り出[だ]すと、誤解[ごかい]しやすい。", "sentence_source": "generated"}, {"text": "前後の文脈から、知らない単語の意味を推測した。", "target_word": "文脈", "complexity_tier": "T3", "furigana": "前後[ぜんご]の文脈[ぶんみゃく]から、知[し]らない単語[たんご]の意味[いみ]を推測[すいそく]した。", "sentence_source": "generated"}, {"text": "その冗談は、文脈がわからない人には通じない。", "target_word": "文脈", "complexity_tier": "T3", "furigana": "その冗談[じょうだん]は、文脈[ぶんみゃく]がわからない人[ひと]には通[つう]じない。", "sentence_source": "generated"}, {"text": "発言の一部だけが紹介され、本来の文脈が失われてしまった。", "target_word": "文脈", "complexity_tier": "T3", "furigana": "発言[はつげん]の一部[いちぶ]だけが紹介[しょうかい]され、本来[ほんらい]の文脈[ぶんみゃく]が失[うしな]われてしまった。", "sentence_source": "generated"}, {"text": "文脈に合った言葉を選んで、手紙を書き直した。", "target_word": "文脈", "complexity_tier": "T3", "furigana": "文脈[ぶんみゃく]に合[あ]った言葉[ことば]を選[えら]んで、手紙[てがみ]を書[か]き直[なお]した。", "sentence_source": "generated"}, {"text": "辞書だけでなく、文脈も見て訳語を決めるべきだ。", "target_word": "文脈", "complexity_tier": "T3", "furigana": "辞書[じしょ]だけでなく、文脈[ぶんみゃく]も見[み]て訳語[やくご]を決[き]めるべきだ。", "sentence_source": "generated"}, {"text": "歴史的な文脈を知ると、この小説がよく分かる。", "target_word": "文脈", "complexity_tier": "T3", "furigana": "歴史的[れきしてき]な文脈[ぶんみゃく]を知[し]ると、この小説[しょうせつ]がよく分[わ]かる。", "sentence_source": "generated"}, {"text": "話の文脈を無視して、彼は急に別の話題を始めた。", "target_word": "文脈", "complexity_tier": "T3", "furigana": "話[はなし]の文脈[ぶんみゃく]を無視[むし]して、彼[かれ]は急[きゅう]に別[べつ]の話題[わだい]を始[はじ]めた。", "sentence_source": "generated"}, {"text": "会話の文脈から、彼女が怒っていることがわかった。", "target_word": "文脈", "complexity_tier": "T3", "furigana": "会話[かいわ]の文脈[ぶんみゃく]から、彼女[かのじょ]が怒[おこ]っていることがわかった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "文脈", "label": "基本形"}], "register": "標準", "sense_fingerprint": "文章や会話の前後のつながりなど、言葉が使われている場面や状況を表す名詞", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b78c6ea7-fce0-4b94-ac7e-cd644dd6d111') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36178, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "文脈", "is_correct": true, "explanation": "「によって変わる」の前に入り、言葉の意味を左右する前後関係を表す名詞として自然に入る。"}, {"text": "体重", "is_correct": false, "explanation": "「体重によって変わる」は言葉の意味とは結びつかず、不自然なので合わない。"}, {"text": "値段", "is_correct": false, "explanation": "「値段によって変わる」は言葉の意味との関係がなく、意味が通らないので合わない。"}, {"text": "身長", "is_correct": false, "explanation": "「身長によって変わる」は言葉の意味とは無関係で、文として成立しないので合わない。"}], "explanations": {"文脈": "「によって変わる」の前に入り、言葉の意味を左右する前後関係を表す名詞として自然に入る。", "体重": "「体重によって変わる」は言葉の意味とは結びつかず、不自然なので合わない。", "値段": "「値段によって変わる」は言葉の意味との関係がなく、意味が通らないので合わない。", "身長": "「身長によって変わる」は言葉の意味とは無関係で、文として成立しないので合わない。"}, "sentence_index": 0, "correct_answer": "文脈"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この壁の文脈は、ずっと白いままだ。", "explanation": "ここは〈色〉の意味。壁の色は白いと言うが、文脈は言葉や話の前後関係を指すので、色としては合わない。"}, {"text": "この小説の文脈は、全部で三百ページある。", "explanation": "ここは〈文章〉の意味。作品の分量は文章と言うが、文脈は前後関係であり、ページ数を数えるものではないので合わない。"}, {"text": "この部屋の文脈は、ほのかに甘い香りがする。", "explanation": "ここは〈匂い〉の意味。部屋の匂いは甘い香りがすると言うが、文脈は言葉の前後関係を指すので、匂いとしては合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8c29ec8-8fc2-4ddd-a8d5-f4dfa75a1261') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36178, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "文脈", "is_correct": true, "explanation": "「も見て」の前に入り、訳語を決める手がかりになる前後関係を表す名詞として自然。"}, {"text": "手順", "is_correct": false, "explanation": "「手順も見て訳語を決める」は不自然で、訳語を決める手がかりにはならないので合わない。"}, {"text": "期限", "is_correct": false, "explanation": "「期限も見て訳語を決める」は意味が通らず、訳語の手がかりにならないので合わない。"}, {"text": "季節", "is_correct": false, "explanation": "「季節も見て訳語を決める」は不自然で、訳語を決める手がかりにはならないので合わない。"}], "explanations": {"文脈": "「も見て」の前に入り、訳語を決める手がかりになる前後関係を表す名詞として自然。", "手順": "「手順も見て訳語を決める」は不自然で、訳語を決める手がかりにはならないので合わない。", "期限": "「期限も見て訳語を決める」は意味が通らず、訳語の手がかりにならないので合わない。", "季節": "「季節も見て訳語を決める」は不自然で、訳語を決める手がかりにはならないので合わない。"}, "sentence_index": 6, "correct_answer": "文脈"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今日の文脈は晴れだ。", "explanation": "ここは〈天気〉の意味。今日の空模様は晴れだと言うが、文脈は言葉や話の前後関係を指すので、天気としては合わない。"}, {"text": "店の文脈がとても明るくて、居心地がよかった。", "explanation": "ここは〈雰囲気〉の意味。店の雰囲気は明るさで表すが、文脈は言葉の前後のつながりを指すので合わない。"}, {"text": "病気の文脈は、順調に回復している。", "explanation": "ここは〈経過〉の意味。病状の移り変わりは経過と言うが、文脈は言葉や話の前後関係を指すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8c29ec8-8fc2-4ddd-a8d5-f4dfa75a1261') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36178, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "その発言は、文脈が無視すると誤解されやすい。", "corrected_sentence": "その発言は、文脈を無視すると誤解されやすい。", "error_description": "「無視する」は「を」を取る他動詞なので「文脈を」が正しい。「文脈が」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8c29ec8-8fc2-4ddd-a8d5-f4dfa75a1261') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36178, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼の発言は、文脈で合わせて解釈すべきだ。", "corrected_sentence": "彼の発言は、文脈に合わせて解釈すべきだ。", "error_description": "「合わせる」は「に」を取るので「文脈に」が正しい。「文脈で」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8c29ec8-8fc2-4ddd-a8d5-f4dfa75a1261') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36182, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「知る」の目的語を示し、「この標識の意味を知っていますか」という自然な文になる。"}, {"text": "が", "is_correct": false, "explanation": "「意味が知っていますか」は主語と述語が成立せず、「知る」の対象にならないので合わない。"}, {"text": "に", "is_correct": false, "explanation": "「意味に知っている」は対象を示せず、意味が通らないので合わない。"}, {"text": "で", "is_correct": false, "explanation": "「意味で知っている」は手段や場所の意味になり、「知る」の対象にはならないので合わない。"}], "correct_answer": "を", "explanations": {"を": "「知る」の目的語を示し、「この標識の意味を知っていますか」という自然な文になる。", "が": "「意味が知っていますか」は主語と述語が成立せず、「知る」の対象にならないので合わない。", "に": "「意味に知っている」は対象を示せず、意味が通らないので合わない。", "で": "「意味で知っている」は手段や場所の意味になり、「知る」の対象にはならないので合わない。"}, "error_tags": {"が": "主語", "に": "場所", "で": "手段"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8c29ec8-8fc2-4ddd-a8d5-f4dfa75a1261') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36182, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「同じ意味の言葉」と名詞を続けて修飾する形になり、自然な文になる。"}, {"text": "へ", "is_correct": false, "explanation": "「同じ意味へ言葉は」は方向を表すが、意味が言葉の行き先になる文として成立しないので合わない。"}, {"text": "から", "is_correct": false, "explanation": "「同じ意味から言葉は」は起点を示すが、意味が言葉の出どころになる不自然な文なので合わない。"}, {"text": "より", "is_correct": false, "explanation": "「同じ意味より言葉は」は比較の形になるが、比べる内容がなく文として合わない。"}], "correct_answer": "の", "explanations": {"の": "「同じ意味の言葉」と名詞を続けて修飾する形になり、自然な文になる。", "へ": "「同じ意味へ言葉は」は方向を表すが、意味が言葉の行き先になる文として成立しないので合わない。", "から": "「同じ意味から言葉は」は起点を示すが、意味が言葉の出どころになる不自然な文なので合わない。", "より": "「同じ意味より言葉は」は比較の形になるが、比べる内容がなく文として合わない。"}, "error_tags": {"へ": "方向", "から": "起点", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8c29ec8-8fc2-4ddd-a8d5-f4dfa75a1261') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36182, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "言葉や記号が表す内容。", "primary_collocate": null, "pronunciation": "いみ", "ipa": "imi", "syllable_count": 2, "sentences": [{"text": "この単語の意味を、辞書で調べた。", "target_word": "意味", "complexity_tier": "T3", "furigana": "この単語[たんご]の意味[いみ]を、辞書[じしょ]で調[しら]べた。", "sentence_source": "generated"}, {"text": "道路にあるこの標識の意味を、知っていますか。", "target_word": "意味", "complexity_tier": "T3", "furigana": "道路[どうろ]にあるこの標識[ひょうしき]の意味[いみ]を、知[し]っていますか。", "sentence_source": "generated"}, {"text": "彼の言葉の意味が分からなくて、もう一度聞いた。", "target_word": "意味", "complexity_tier": "T3", "furigana": "彼[かれ]の言葉[ことば]の意味[いみ]が分[わ]からなくて、もう一度[いちど]聞[き]いた。", "sentence_source": "generated"}, {"text": "同じ記号でも、国によって意味が違うことがある。", "target_word": "意味", "complexity_tier": "T3", "furigana": "同[おな]じ記号[きごう]でも、国[くに]によって意味[いみ]が違[ちが]うことがある。", "sentence_source": "generated"}, {"text": "先生は、難しい漢字の意味をやさしく説明してくれた。", "target_word": "意味", "complexity_tier": "T3", "furigana": "先生[せんせい]は、難[むずか]しい漢字[かんじ]の意味[いみ]をやさしく説明[せつめい]してくれた。", "sentence_source": "generated"}, {"text": "この記号の意味[いみ]がわからなくて、係の人に聞いた。", "target_word": "意味", "complexity_tier": "T3", "furigana": "この記号[きごう]の意味[いみ]がわからなくて、係[かかり]の人[ひと]に聞[き]いた。", "sentence_source": "generated"}, {"text": "外国語の歌は、意味が分からなくても楽しめる。", "target_word": "意味", "complexity_tier": "T3", "furigana": "外国語[がいこくご]の歌[うた]は、意味[いみ]が分[わ]からなくても楽[たの]しめる。", "sentence_source": "generated"}, {"text": "「ありがとう」と同じ意味の言葉は、ほかの言語にもある。", "target_word": "意味", "complexity_tier": "T3", "furigana": "「ありがとう」と同[おな]じ意味[いみ]の言葉[ことば]は、ほかの言語[げんご]にもある。", "sentence_source": "generated"}, {"text": "辞書には、一つの言葉にいくつかの意味が書いてある。", "target_word": "意味", "complexity_tier": "T3", "furigana": "辞書[じしょ]には、一[ひと]つの言葉[ことば]にいくつかの意味[いみ]が書[か]いてある。", "sentence_source": "generated"}, {"text": "絵文字の意味を取り違えて、友達を怒らせてしまった。", "target_word": "意味", "complexity_tier": "T3", "furigana": "絵文字[えもじ]の意味[いみ]を取[と]り違[ちが]えて、友達[ともだち]を怒[おこ]らせてしまった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "意味", "label": "基本形"}], "register": "標準", "sense_fingerprint": "言葉・記号・標識などが表している内容を指す名詞", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b78c6ea7-fce0-4b94-ac7e-cd644dd6d111') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36182, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "意味", "is_correct": true, "explanation": "「この単語の」の後に続き、語が表す内容を指す名詞として辞書で調べる対象になる。"}, {"text": "天気", "is_correct": false, "explanation": "「この単語の天気を、辞書で調べた」は意味をなさず、天気は辞書で調べるものではないので合わない。"}, {"text": "身長", "is_correct": false, "explanation": "「この単語の身長」は不自然で、単語と身長は結びつかないので合わない。"}, {"text": "体重", "is_correct": false, "explanation": "「この単語の体重」は意味が通らず、辞書で調べる対象にならないので合わない。"}], "explanations": {"意味": "「この単語の」の後に続き、語が表す内容を指す名詞として辞書で調べる対象になる。", "天気": "「この単語の天気を、辞書で調べた」は意味をなさず、天気は辞書で調べるものではないので合わない。", "身長": "「この単語の身長」は不自然で、単語と身長は結びつかないので合わない。", "体重": "「この単語の体重」は意味が通らず、辞書で調べる対象にならないので合わない。"}, "sentence_index": 0, "correct_answer": "意味"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "このスープは意味が濃くて、少し塩辛い。", "explanation": "ここは〈味〉の意味。味の濃さは味が濃いと言うが、意味は内容を指し、濃さでは表さないので合わない。"}, {"text": "会議で多くの意味が出た。", "explanation": "ここは〈意見〉の意味。会議で意見が出ると言うが、意味は言葉の内容を指すので合わない。"}, {"text": "この花は意味が強く香る。", "explanation": "ここは〈香り〉の意味。花の香りは強く香ると言うが、意味は言葉の内容を指すので香りとしては合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8c29ec8-8fc2-4ddd-a8d5-f4dfa75a1261') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36182, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "意味", "is_correct": true, "explanation": "「外国語の歌は、」の後に続き、歌詞の内容を指す名詞として「分からなくても」につながる。"}, {"text": "値段", "is_correct": false, "explanation": "「値段が分からなくても楽しめる」は歌の楽しみとは関係がなく、不自然なので合わない。"}, {"text": "季節", "is_correct": false, "explanation": "「季節が分からなくても楽しめる」は歌とは関係がなく、意味が通らないので合わない。"}, {"text": "手順", "is_correct": false, "explanation": "「手順が分からなくても楽しめる」は歌の楽しみとは結びつかず、不自然なので合わない。"}], "explanations": {"意味": "「外国語の歌は、」の後に続き、歌詞の内容を指す名詞として「分からなくても」につながる。", "値段": "「値段が分からなくても楽しめる」は歌の楽しみとは関係がなく、不自然なので合わない。", "季節": "「季節が分からなくても楽しめる」は歌とは関係がなく、意味が通らないので合わない。", "手順": "「手順が分からなくても楽しめる」は歌の楽しみとは結びつかず、不自然なので合わない。"}, "sentence_index": 6, "correct_answer": "意味"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼女の意味はいつもより明るく、よく笑っている。", "explanation": "ここは〈表情〉の意味。明るさは表情で表すが、意味は言葉の内容を指すので合わない。"}, {"text": "彼の意味は、とても穏やかな印象だった。", "explanation": "ここは〈印象〉の意味。人から受ける感じは印象と言うが、意味は言葉の内容を指すので合わない。"}, {"text": "赤ちゃんの意味は、三十八度もある。", "explanation": "ここは〈体温〉の意味。体温は三十八度あると言うが、意味は言葉の内容を指し、温度で表さないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8c29ec8-8fc2-4ddd-a8d5-f4dfa75a1261') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36182, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この記号の意味に、係の人に聞いた。", "corrected_sentence": "この記号の意味を、係の人に聞いた。", "error_description": "「聞く」で尋ねる内容は「を」で示すので「意味を」が正しい。「意味に」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8c29ec8-8fc2-4ddd-a8d5-f4dfa75a1261') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36182, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "その言葉の意味が、二つの辞書で比べた。", "corrected_sentence": "その言葉の意味を、二つの辞書で比べた。", "error_description": "「比べる」は比べる対象に「を」を使う。「意味が」は誤りで、正しくは「意味を」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8c29ec8-8fc2-4ddd-a8d5-f4dfa75a1261') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36184, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「練習を続けた」で、続ける対象を示す。直前に続けるが来るので正しい。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示すので、続けるの対象には使えず合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、続ける対象を表す位置には合わない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は共同や並列を示し、続ける対象を示さないので合わない。"}], "correct_answer": "を", "explanations": {"を": "「練習を続けた」で、続ける対象を示す。直前に続けるが来るので正しい。", "が": "「が」は主語を示すので、続けるの対象には使えず合わない。", "へ": "「へ」は方向を示すので、続ける対象を表す位置には合わない。", "と": "「と」は共同や並列を示し、続ける対象を示さないので合わない。"}, "error_tags": {"が": "主語を示す", "へ": "方向を示す", "と": "共同・並列を示す"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "やめる", "is_correct": true, "explanation": "続けるは途中でやめずに行うことで、その対義語は「やめる」。辞書でも対義語として挙げられる。"}, {"text": "作る", "is_correct": false, "explanation": "作るは新しく形にすることで、続けるとは対義の関係にない。"}, {"text": "寝る", "is_correct": false, "explanation": "寝るは休む動作で、続けるとは対義語の関係にない。"}, {"text": "運ぶ", "is_correct": false, "explanation": "運ぶは物を移動させることで、続けるとは対義の関係にない。"}], "correct_answer": "やめる", "explanations": {"やめる": "続けるは途中でやめずに行うことで、その対義語は「やめる」。辞書でも対義語として挙げられる。", "作る": "作るは新しく形にすることで、続けるとは対義の関係にない。", "寝る": "寝るは休む動作で、続けるとは対義語の関係にない。", "運ぶ": "運ぶは物を移動させることで、続けるとは対義の関係にない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aad67c8f-e9b3-403f-a0ec-20e528ef9731') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36184, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「努力を続ければ」で、続ける対象を示す。直前に続けるが来るので正しい。"}, {"text": "に", "is_correct": false, "explanation": "「に」は到達点や相手を示すので、続ける対象には合わない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を示すので、続ける対象を表す位置には合わない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は所属や修飾を示し、動詞の前の対象を示さないので合わない。"}], "correct_answer": "を", "explanations": {"を": "「努力を続ければ」で、続ける対象を示す。直前に続けるが来るので正しい。", "に": "「に」は到達点や相手を示すので、続ける対象には合わない。", "より": "「より」は比較を示すので、続ける対象を表す位置には合わない。", "の": "「の」は所属や修飾を示し、動詞の前の対象を示さないので合わない。"}, "error_tags": {"に": "到達・相手を示す", "より": "比較を示す", "の": "所属・修飾を示す"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "やめる", "is_correct": true, "explanation": "続けるは途中でやめずに行うことで、その対義語は「やめる」。辞書でも対義語として挙げられる。"}, {"text": "覚える", "is_correct": false, "explanation": "覚えるは記憶に残すことで、続けるとは対義の関係にない。"}, {"text": "届ける", "is_correct": false, "explanation": "届けるは物を相手に運ぶことで、続けるとは対義の関係にない。"}, {"text": "選ぶ", "is_correct": false, "explanation": "選ぶは候補から決めることで、続けるとは対義の関係にない。"}], "correct_answer": "やめる", "explanations": {"やめる": "続けるは途中でやめずに行うことで、その対義語は「やめる」。辞書でも対義語として挙げられる。", "覚える": "覚えるは記憶に残すことで、続けるとは対義の関係にない。", "届ける": "届けるは物を相手に運ぶことで、続けるとは対義の関係にない。", "選ぶ": "選ぶは候補から決めることで、続けるとは対義の関係にない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aad67c8f-e9b3-403f-a0ec-20e528ef9731') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36184, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "やめないで、ずっと同じことをする。", "primary_collocate": null, "pronunciation": "つづける", "ipa": "tsɯzɯkeɾɯ", "syllable_count": 4, "sentences": [{"text": "毎朝、三十分走ることを続けています。", "target_word": "続けて", "complexity_tier": "T3", "furigana": "毎朝[まいあさ]、三十分[さんじゅっぷん]走[はし]ることを続[つづ]けています。", "sentence_source": "generated"}, {"text": "雨が降っても、彼は練習を続けた。", "target_word": "続けた", "complexity_tier": "T3", "furigana": "雨[あめ]が降[ふ]っても、彼[かれ]は練習[れんしゅう]を続[つづ]けた。", "sentence_source": "generated"}, {"text": "疲れていたが、最後まで勉強を続けることにした。", "target_word": "続ける", "complexity_tier": "T3", "furigana": "疲[つか]れていたが、最後[さいご]まで勉強[べんきょう]を続[つづ]けることにした。", "sentence_source": "generated"}, {"text": "英語を十年間続けて、やっと上手になりました。", "target_word": "続けて", "complexity_tier": "T3", "furigana": "英語[えいご]を十年間[じゅうねんかん]続[つづ]けて、やっと上手[じょうず]になりました。", "sentence_source": "generated"}, {"text": "母は体のために、毎日散歩を続けている。", "target_word": "続けて", "complexity_tier": "T3", "furigana": "母[はは]は体[からだ]のために、毎日[まいにち]散歩[さんぽ]を続[つづ]けている。", "sentence_source": "generated"}, {"text": "先生が止めても、彼は同じ質問を続けた。", "target_word": "続けた", "complexity_tier": "T3", "furigana": "先生[せんせい]が止[と]めても、彼[かれ]は同[おな]じ質問[しつもん]を続[つづ]けた。", "sentence_source": "generated"}, {"text": "結婚しても、この仕事を続けたいです。", "target_word": "続けたい", "complexity_tier": "T3", "furigana": "結婚[けっこん]しても、この仕事[しごと]を続[つづ]けたいです。", "sentence_source": "generated"}, {"text": "苦しくても努力を続ければ、きっと上手になる。", "target_word": "続ければ", "complexity_tier": "T3", "furigana": "苦[くる]しくても努力[どりょく]を続[つづ]ければ、きっと上手[じょうず]になる。", "sentence_source": "generated"}, {"text": "夜遅くまでゲームを続けないで、早く寝なさい。", "target_word": "続けないで", "complexity_tier": "T3", "furigana": "夜遅[よるおそ]くまでゲームを続[つづ]けないで、早[はや]く寝[ね]なさい。", "sentence_source": "generated"}, {"text": "彼女は父の店を続けるために、料理を習っています。", "target_word": "続ける", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は父[ちち]の店[みせ]を続[つづ]けるために、料理[りょうり]を習[なら]っています。", "sentence_source": "generated"}], "morphological_forms": [{"form": "続ける", "label": "辞書形"}, {"form": "続けます", "label": "ます形"}, {"form": "続けて", "label": "て形"}, {"form": "続けた", "label": "た形"}, {"form": "続けない", "label": "ない形"}, {"form": "続ければ", "label": "ば形"}, {"form": "続けたい", "label": "たい形"}], "register": "neutral", "sense_fingerprint": "同じ行動や状態をやめずに、そのまま長く行うこと(他動詞)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94f9763a-fbdb-4942-b840-f5e9ecdfccc6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36184, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "続けて", "is_correct": true, "explanation": "「走ることを続けています」で、同じ行動を長く続けている意味になり文に合う。"}, {"text": "洗って", "is_correct": false, "explanation": "「洗う」は物を洗う動作で、走ることを対象にする文には合わない。"}, {"text": "食べて", "is_correct": false, "explanation": "「食べる」は食事の動作で、走ることを対象にする文には合わない。"}, {"text": "書いて", "is_correct": false, "explanation": "「書く」は文字を書く動作で、走ることを対象にする文には合わない。"}], "explanations": {"続けて": "「走ることを続けています」で、同じ行動を長く続けている意味になり文に合う。", "洗って": "「洗う」は物を洗う動作で、走ることを対象にする文には合わない。", "食べて": "「食べる」は食事の動作で、走ることを対象にする文には合わない。", "書いて": "「書く」は文字を書く動作で、走ることを対象にする文には合わない。"}, "sentence_index": 0, "correct_answer": "続けて"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "二本のロープを続けて、一本の長い綱にした。", "explanation": "ここは〈つなぐ〉の意味。物を連結する場面では続けるとは言わないので合わない。"}, {"text": "締め切りを続けて、来週まで延ばした。", "explanation": "ここは〈延長する〉の意味。期限を後ろに延ばすことは続けるとは言わないので合わない。"}, {"text": "この店は料理を続けて、冷凍して一週間置いた。", "explanation": "ここは〈保存する〉の意味。料理を冷凍して長く置くのは保存であり、同じことをずっと続けるという意味は含まれないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aad67c8f-e9b3-403f-a0ec-20e528ef9731') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36184, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "続けたい", "is_correct": true, "explanation": "「この仕事を続けたいです」で、仕事を続けたいという希望の意味になり文に合う。"}, {"text": "飲みたい", "is_correct": false, "explanation": "「飲む」は飲料の対象に使うので、仕事を目的語にすると不自然で合わない。"}, {"text": "読みたい", "is_correct": false, "explanation": "「読む」は文字や本の対象に使うので、仕事を対象にすると合わない。"}, {"text": "寝たい", "is_correct": false, "explanation": "「寝る」は休む動作で、仕事を対象にする文には合わない。"}], "explanations": {"続けたい": "「この仕事を続けたいです」で、仕事を続けたいという希望の意味になり文に合う。", "飲みたい": "「飲む」は飲料の対象に使うので、仕事を目的語にすると不自然で合わない。", "読みたい": "「読む」は文字や本の対象に使うので、仕事を対象にすると合わない。", "寝たい": "「寝る」は休む動作で、仕事を対象にする文には合わない。"}, "sentence_index": 6, "correct_answer": "続けたい"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "先月中止した大会を、続けて来月開催した。", "explanation": "ここは〈再開する〉の意味。一度中止したものをまた始める場合は再開と言い、続けるとは言わないので合わない。"}, {"text": "来月の旅行を続けて、来年に延期した。", "explanation": "ここは〈延期する〉の意味。日程を後ろにずらすことは続けるとは言わないので合わない。"}, {"text": "雨の日は練習を続けて、来月まで休むことにした。", "explanation": "ここは〈休止する〉の意味。練習をやめて休みにするのは休止であり、同じことをずっと続けるという意味は含まれないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aad67c8f-e9b3-403f-a0ec-20e528ef9731') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36184, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夕方、一時間歩くことに続けています。", "corrected_sentence": "夕方、一時間歩くことを続けています。", "error_description": "「続ける」は目的語に「を」をとる。「に」は誤りで、「を」が正しい。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "続けた", "is_correct": true, "explanation": "「雨が降っても、彼は練習を続けた」で、過去の行動として文末に来る形で合う。"}, {"text": "続けて", "is_correct": false, "explanation": "て形は文末にならず、ここでは文を完結させられないので合わない。"}, {"text": "続けない", "is_correct": false, "explanation": "ない形は否定で、続けたという事実と反対になるので合わない。"}, {"text": "続けたら", "is_correct": false, "explanation": "「続けたら」は条件の形で、文を終えられず、ここでは文末にならない。"}], "correct_form": "続けた", "base_form": "続ける", "form_label": "た形", "sentence_index": 1, "explanations": {"続けた": "「雨が降っても、彼は練習を続けた」で、過去の行動として文末に来る形で合う。", "続けて": "て形は文末にならず、ここでは文を完結させられないので合わない。", "続けない": "ない形は否定で、続けたという事実と反対になるので合わない。", "続けたら": "「続けたら」は条件の形で、文を終えられず、ここでは文末にならない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aad67c8f-e9b3-403f-a0ec-20e528ef9731') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36184, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "寒くても運動を続けるば、体が丈夫になる。", "corrected_sentence": "寒くても運動を続ければ、体が丈夫になる。", "error_description": "条件を表す「ば形」は「続ければ」。「続けるば」は活用の誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "続ければ", "is_correct": true, "explanation": "「努力を続ければ、きっと上手になる」で、続けるという条件を表すば形が合う。"}, {"text": "続けなかった", "is_correct": false, "explanation": "否定の過去形では、続けなかったという結果になり、上手になるという文と合わない。"}, {"text": "続けさせる", "is_correct": false, "explanation": "使役形では、誰かに続けさせる意味になり、本人が努力を続ける文と合わない。"}, {"text": "続けよう", "is_correct": false, "explanation": "意志形は本人の決意を表し、条件の文の流れに合わない。"}], "correct_form": "続ければ", "base_form": "続ける", "form_label": "ば形", "sentence_index": 7, "explanations": {"続ければ": "「努力を続ければ、きっと上手になる」で、続けるという条件を表すば形が合う。", "続けなかった": "否定の過去形では、続けなかったという結果になり、上手になるという文と合わない。", "続けさせる": "使役形では、誰かに続けさせる意味になり、本人が努力を続ける文と合わない。", "続けよう": "意志形は本人の決意を表し、条件の文の流れに合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aad67c8f-e9b3-403f-a0ec-20e528ef9731') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
