INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36186, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "物事や用事が終わる。", "primary_collocate": null, "pronunciation": "すむ", "ipa": "sɯmɯ", "syllable_count": 2, "sentences": [{"text": "宿題が済んでから、友だちと遊びます。", "target_word": "済んで", "complexity_tier": "T3", "furigana": "宿題[しゅくだい]が済[す]んでから、友[とも]だちと遊[あそ]びます。", "sentence_source": "generated"}, {"text": "会議はもう済みましたか。", "target_word": "済みました", "complexity_tier": "T3", "furigana": "会議[かいぎ]はもう済[す]みましたか。", "sentence_source": "generated"}, {"text": "食事が済んだら、お皿を洗ってください。", "target_word": "済んだら", "complexity_tier": "T3", "furigana": "食事[しょくじ]が済[す]んだら、お皿[さら]を洗[あら]ってください。", "sentence_source": "generated"}, {"text": "手続きが済むまで、ここで待ってください。", "target_word": "済む", "complexity_tier": "T3", "furigana": "手続[てつづ]きが済[す]むまで、ここで待[ま]ってください。", "sentence_source": "generated"}, {"text": "掃除が済んだので、お茶を飲みました。", "target_word": "済んだ", "complexity_tier": "T3", "furigana": "掃除[そうじ]が済[す]んだので、お茶[ちゃ]を飲[の]みました。", "sentence_source": "generated"}, {"text": "仕事が済み次第、すぐに帰ります。", "target_word": "済み", "complexity_tier": "T3", "furigana": "仕事[しごと]が済[す]み次第[しだい]、すぐに帰[かえ]ります。", "sentence_source": "generated"}, {"text": "試験が済んで、やっと気持ちが楽になりました。", "target_word": "済んで", "complexity_tier": "T3", "furigana": "試験[しけん]が済[す]んで、やっと気持[きも]ちが楽[らく]になりました。", "sentence_source": "generated"}, {"text": "用事が済んだ人から、先に帰ってもいいです。", "target_word": "済んだ", "complexity_tier": "T3", "furigana": "用事[ようじ]が済[す]んだ人[ひと]から、先[さき]に帰[かえ]ってもいいです。", "sentence_source": "generated"}, {"text": "買い物が済んだら、駅で会いましょう。", "target_word": "済んだら", "complexity_tier": "T3", "furigana": "買[か]い物[もの]が済[す]んだら、駅[えき]で会[あ]いましょう。", "sentence_source": "generated"}, {"text": "授業が済むと、学生たちは急いで教室を出ました。", "target_word": "済む", "complexity_tier": "T3", "furigana": "授業[じゅぎょう]が済[す]むと、学生[がくせい]たちは急[いそ]いで教室[きょうしつ]を出[で]ました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "済む", "label": "辞書形"}, {"form": "済み", "label": "連用形"}, {"form": "済んで", "label": "て形"}, {"form": "済んだ", "label": "た形"}, {"form": "済まない", "label": "ない形"}, {"form": "済めば", "label": "ば形"}], "register": "neutral", "sense_fingerprint": "物事・用事・手続きなどが終わる、完了する", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f58e5a06-dc41-4937-81ba-37dc3d155f50') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36186, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "済んで", "is_correct": true, "explanation": "て形で「～てから」に続き、「宿題が終わってから」の意味になる。ここに入る正解。"}, {"text": "済ませて", "is_correct": false, "explanation": "「済ませる」は他動詞で目的語を取る。「宿題が済ませてから」は主語と動詞が合わない。"}, {"text": "済み", "is_correct": false, "explanation": "連用形のままでは「から」につながらず、文が途中で切れてしまう。"}, {"text": "済めば", "is_correct": false, "explanation": "ば形は仮定の「～ば」になり、「～から」と続けられない。"}], "explanations": {"済んで": "て形で「～てから」に続き、「宿題が終わってから」の意味になる。ここに入る正解。", "済ませて": "「済ませる」は他動詞で目的語を取る。「宿題が済ませてから」は主語と動詞が合わない。", "済み": "連用形のままでは「から」につながらず、文が途中で切れてしまう。", "済めば": "ば形は仮定の「～ば」になり、「～から」と続けられない。"}, "sentence_index": 0, "correct_answer": "済んで"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "雨がようやく済んで、虹が出てきた。", "explanation": "ここは〈止む〉の意味。「済む」は用事や作業が終わる意味で、雨がやむことには使わない。"}, {"text": "夏休みが済んで、学校が始まった。", "explanation": "ここは〈終わる〉の意味。「済む」は仕事や手続きの完了に使い、休みの期間には使わない。"}, {"text": "長年のストレスが済んで、気持ちが晴れた。", "explanation": "ここは〈解消〉の意味。「済む」は用事や手続きの完了に使い、ストレスの消失には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6fe1edb9-1a37-42aa-affb-5f6edb30cfd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36186, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "済んで", "is_correct": true, "explanation": "て形で「試験が終わって、やっと」と続き、結果を述べる文に自然につながる。"}, {"text": "済ませて", "is_correct": false, "explanation": "他動詞で、「試験が」を主語にする文では使えない。"}, {"text": "済もう", "is_correct": false, "explanation": "意志形で、「済もう、やっと楽になった」と結果の文が続かない。"}, {"text": "済むだろう", "is_correct": false, "explanation": "推量形でまだ終わっていない予想になり、「やっと楽になった」という結果と合わない。"}], "explanations": {"済んで": "て形で「試験が終わって、やっと」と続き、結果を述べる文に自然につながる。", "済ませて": "他動詞で、「試験が」を主語にする文では使えない。", "済もう": "意志形で、「済もう、やっと楽になった」と結果の文が続かない。", "済むだろう": "推量形でまだ終わっていない予想になり、「やっと楽になった」という結果と合わない。"}, "sentence_index": 6, "correct_answer": "済んで"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "部屋がすっかり済むと、気持ちがよくなりました。", "explanation": "ここは〈片づく〉の意味。「済む」は用事や作業の完了に使い、部屋の状態には使わない。"}, {"text": "長い物語が済むと、読者は満足そうに本を閉じた。", "explanation": "ここは〈完結〉の意味。「済む」は仕事や用事の完了に使い、物語の結末には使わない。"}, {"text": "橋がついに済むと、町の人々は集まって喜んだ。", "explanation": "ここは〈完成〉の意味。「済む」は構造物や作品の完成には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6fe1edb9-1a37-42aa-affb-5f6edb30cfd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36186, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "宿題を済んだら、友だちと遊びます。", "corrected_sentence": "宿題が済んだら、友だちと遊びます。", "error_description": "「済む」は自動詞なので、主語は「宿題が」と「が」で示す。「宿題を」の「を」は誤り（「済ませる」の目的語の形）。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "済みました", "is_correct": true, "explanation": "「済む」の連用形＋「ました」で丁寧な過去。「もう～ましたか」で完了の確認になる。"}, {"text": "済まなかった", "is_correct": false, "explanation": "否定の過去で「終わらなかった」の意味になり、「もう」の問いと合わない。"}, {"text": "済めば", "is_correct": false, "explanation": "ば形は仮定の形で、「会議はもう済めば」は文として成り立たない。"}, {"text": "済んで", "is_correct": false, "explanation": "て形は文末に立てず、「ましたか」の前には入らない。"}], "correct_form": "済みました", "base_form": "済む", "form_label": "丁寧な過去（ました形）", "sentence_index": 1, "explanations": {"済みました": "「済む」の連用形＋「ました」で丁寧な過去。「もう～ましたか」で完了の確認になる。", "済まなかった": "否定の過去で「終わらなかった」の意味になり、「もう」の問いと合わない。", "済めば": "ば形は仮定の形で、「会議はもう済めば」は文として成り立たない。", "済んで": "て形は文末に立てず、「ましたか」の前には入らない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6fe1edb9-1a37-42aa-affb-5f6edb30cfd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36186, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学期末の試験が済ませたので、気持ちが楽になりました。", "corrected_sentence": "学期末の試験が済んだので、気持ちが楽になりました。", "error_description": "「済ませた」は他動詞で目的語を取る形。自動詞「済む」の過去形「済んだ」が正しい。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "済んだ", "is_correct": true, "explanation": "過去の連体形で、「用事が済んだ人」と名詞を修飾する。"}, {"text": "済もう", "is_correct": false, "explanation": "意志形で、名詞を修飾できない。"}, {"text": "済まない", "is_correct": false, "explanation": "ない形で「終わっていない人」の意味になり、「終わった人から」と逆になる。"}, {"text": "済まなければ", "is_correct": false, "explanation": "なければ形は条件を表し、名詞を修飾できないので「人から」につながらない。"}], "correct_form": "済んだ", "base_form": "済む", "form_label": "過去の連体形", "sentence_index": 7, "explanations": {"済んだ": "過去の連体形で、「用事が済んだ人」と名詞を修飾する。", "済もう": "意志形で、名詞を修飾できない。", "済まない": "ない形で「終わっていない人」の意味になり、「終わった人から」と逆になる。", "済まなければ": "なければ形は条件を表し、名詞を修飾できないので「人から」につながらない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6fe1edb9-1a37-42aa-affb-5f6edb30cfd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36187, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "と", "options": [{"text": "と", "is_correct": true, "explanation": "「済むと思った」の引用の「と」。「～と思う」で、済みそうだという予想を表す。"}, {"text": "に", "is_correct": false, "explanation": "「済むに思った」は成り立たない。「に」は時間や場所を示し、思考の内容を導けない。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示すが、「済む」は目的語を取らないので「済むを思った」は不自然。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、「済むへ思った」は成り立たない。"}], "correct_answer": "と", "explanations": {"と": "「済むと思った」の引用の「と」。「～と思う」で、済みそうだという予想を表す。", "に": "「済むに思った」は成り立たない。「に」は時間や場所を示し、思考の内容を導けない。", "を": "「を」は目的語を示すが、「済む」は目的語を取らないので「済むを思った」は不自然。", "へ": "「へ」は方向を示すので、「済むへ思った」は成り立たない。"}, "error_tags": {"に": "場所・時間", "を": "目的語", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6fe1edb9-1a37-42aa-affb-5f6edb30cfd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36187, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6fe1edb9-1a37-42aa-affb-5f6edb30cfd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36187, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "物事が終わる。また、それで十分に間に合う。", "primary_collocate": null, "pronunciation": "すむ", "ipa": "sɯmɯ", "syllable_count": 2, "sentences": [{"text": "電話一本で済むので、会いに行かなくてもいいです。", "target_word": "済む", "complexity_tier": "T3", "furigana": "電話[でんわ]一本[いっぽん]で済[す]むので、会[あ]いに行[い]かなくてもいいです。", "sentence_source": "generated"}, {"text": "千円で済むと思ったが、実際は二千円かかった。", "target_word": "済む", "complexity_tier": "T3", "furigana": "千円[せんえん]で済[す]むと思[おも]ったが、実際[じっさい]は二千円[にせんえん]かかった。", "sentence_source": "generated"}, {"text": "謝って済む問題ではありません。", "target_word": "済む", "complexity_tier": "T3", "furigana": "謝[あやま]って済[す]む問題[もんだい]ではありません。", "sentence_source": "generated"}, {"text": "薬を飲まずに済んで、ほっとしました。", "target_word": "済んで", "complexity_tier": "T3", "furigana": "薬[くすり]を飲[の]まずに済[す]んで、ほっとしました。", "sentence_source": "generated"}, {"text": "傘がなくても済む程度の小雨だったので、身軽に出かけました。", "target_word": "済む", "complexity_tier": "T3", "furigana": "傘[かさ]がなくても済[す]む程度[ていど]の小雨[こさめ]だったので、身軽[みがる]に出[で]かけました。", "sentence_source": "generated"}, {"text": "メールで済む話なのに、わざわざ会議を開いた。", "target_word": "済む", "complexity_tier": "T3", "furigana": "メールで済[す]む話[はなし]なのに、わざわざ会議[かいぎ]を開[ひら]いた。", "sentence_source": "generated"}, {"text": "手続きはもう済んだので、心配しないでください。", "target_word": "済んだ", "complexity_tier": "T3", "furigana": "手続[てつづ]きはもう済[す]んだので、心配[しんぱい]しないでください。", "sentence_source": "generated"}, {"text": "簡単な修理で済んで、費用もあまりかかりませんでした。", "target_word": "済んで", "complexity_tier": "T3", "furigana": "簡単[かんたん]な修理[しゅうり]で済[す]んで、費用[ひよう]もあまりかかりませんでした。", "sentence_source": "generated"}, {"text": "今月は貯金のおかげで、借金せずに済みました。", "target_word": "済み", "complexity_tier": "T3", "furigana": "今月[こんげつ]は貯金[ちょきん]のおかげで、借金[しゃっきん]せずに済[す]みました。", "sentence_source": "generated"}, {"text": "軽いけがで済んだのは、運がよかったからです。", "target_word": "済んだ", "complexity_tier": "T3", "furigana": "軽[かる]いけがで済[す]んだのは、運[うん]がよかったからです。", "sentence_source": "generated"}], "morphological_forms": [{"form": "済む", "label": "辞書形"}, {"form": "済み", "label": "連用形"}, {"form": "済んで", "label": "て形"}, {"form": "済んだ", "label": "た形"}, {"form": "済まない", "label": "ない形"}, {"form": "済めば", "label": "ば形"}], "register": "neutral", "sense_fingerprint": "物事が終わる、またそれで足りる・問題なく片づく（〜で済む）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f58e5a06-dc41-4937-81ba-37dc3d155f50') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36187, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "済む", "is_correct": true, "explanation": "辞書形で「電話一本で済む」の形になり、理由の「ので」に続く。ここに入る正解。"}, {"text": "済んで", "is_correct": false, "explanation": "て形は「ので」に続かず、「済んでので」となって成り立たない。"}, {"text": "済み", "is_correct": false, "explanation": "連用形は「ので」の前に続かず、文法的に成り立たない。"}, {"text": "済めば", "is_correct": false, "explanation": "ば形は「ので」に続かず、「済めばので」となって成り立たない。"}], "explanations": {"済む": "辞書形で「電話一本で済む」の形になり、理由の「ので」に続く。ここに入る正解。", "済んで": "て形は「ので」に続かず、「済んでので」となって成り立たない。", "済み": "連用形は「ので」の前に続かず、文法的に成り立たない。", "済めば": "ば形は「ので」に続かず、「済めばので」となって成り立たない。"}, "sentence_index": 0, "correct_answer": "済む"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "雨がやっと済んで、空が明るくなった。", "explanation": "ここは〈止む〉の意味。「済む」は用事や手続きの完了に使い、雨がやむことには使わない。"}, {"text": "春が済んで、夏が来た。", "explanation": "ここは〈過ぎる〉の意味。「済む」は季節の移り変わりには使わない。"}, {"text": "霧が済んで、山がよく見えた。", "explanation": "ここは〈晴れる〉の意味。「済む」は手続きや用事の完了に使い、霧が晴れることには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6fe1edb9-1a37-42aa-affb-5f6edb30cfd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36187, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "済んだ", "is_correct": true, "explanation": "た形で「手続きはもう済んだので」と理由を表す。ここに入る正解。"}, {"text": "済もう", "is_correct": false, "explanation": "意志形で「もう済もう」となり、「ので」と続かず理由の文が成り立たない。"}, {"text": "済むだろう", "is_correct": false, "explanation": "推量形は「ので」に続かず、「済むだろうので」は文として成り立たない。"}, {"text": "済みそう", "is_correct": false, "explanation": "様態の形は「ので」に続かず、「済みそうので」は文として成り立たない。"}], "explanations": {"済んだ": "た形で「手続きはもう済んだので」と理由を表す。ここに入る正解。", "済もう": "意志形で「もう済もう」となり、「ので」と続かず理由の文が成り立たない。", "済むだろう": "推量形は「ので」に続かず、「済むだろうので」は文として成り立たない。", "済みそう": "様態の形は「ので」に続かず、「済みそうので」は文として成り立たない。"}, "sentence_index": 6, "correct_answer": "済んだ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "痛みが済んで、体が軽くなった。", "explanation": "ここは〈去る〉の意味。「済む」は用事や手続きの完了に使い、痛みが消えることには使わない。"}, {"text": "事件が済むと、警察は犯人の名前を発表した。", "explanation": "ここは〈解決〉の意味。「済む」は手続きや用事の完了に使い、事件の決着には使わない。"}, {"text": "戦争が済むと、人々はやっと家に帰れるようになった。", "explanation": "ここは〈終結〉の意味。「済む」は用事や手続きの完了に使い、戦争の終わりには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6fe1edb9-1a37-42aa-affb-5f6edb30cfd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36187, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "電話一本に済むので、わざわざ来なくてもいいです。", "corrected_sentence": "電話一本で済むので、わざわざ来なくてもいいです。", "error_description": "「済む」は手段を表す「で」を取る（「電話一本で済む」）。「に」は誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "済む", "is_correct": true, "explanation": "辞書形で、「千円で済むと思った」と「と思う」に続く。"}, {"text": "済んで", "is_correct": false, "explanation": "て形は「と思った」に直接続かず、「千円で済んでと思った」は不自然。"}, {"text": "済み", "is_correct": false, "explanation": "連用形は文を続けられず、「と思った」にも続かない。"}, {"text": "済め", "is_correct": false, "explanation": "命令形は「と思った」に続かず、文として成り立たない。"}], "correct_form": "済む", "base_form": "済む", "form_label": "辞書形（基本形）", "sentence_index": 1, "explanations": {"済む": "辞書形で、「千円で済むと思った」と「と思う」に続く。", "済んで": "て形は「と思った」に直接続かず、「千円で済んでと思った」は不自然。", "済み": "連用形は文を続けられず、「と思った」にも続かない。", "済め": "命令形は「と思った」に続かず、文として成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6fe1edb9-1a37-42aa-affb-5f6edb30cfd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36187, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "仕事はもう済みので、今日は安心して休みます。", "corrected_sentence": "仕事はもう済んだので、今日は安心して休みます。", "error_description": "「済み」は連用形で、「ので」の前には「済んだ」（た形）が必要。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "済んで", "is_correct": true, "explanation": "て形で、「修理で済んで、費用も～」と後ろに続けて結果を述べる。"}, {"text": "済む", "is_correct": false, "explanation": "辞書形で文が切れてしまい、後半の「費用も～」と続かない。"}, {"text": "済めば", "is_correct": false, "explanation": "ば形は仮定になり、過去の結果を述べる文と合わない。"}, {"text": "済もう", "is_correct": false, "explanation": "意志形で、事実を述べる文に合わない。"}], "correct_form": "済んで", "base_form": "済む", "form_label": "て形（接続）", "sentence_index": 7, "explanations": {"済んで": "て形で、「修理で済んで、費用も～」と後ろに続けて結果を述べる。", "済む": "辞書形で文が切れてしまい、後半の「費用も～」と続かない。", "済めば": "ば形は仮定になり、過去の結果を述べる文と合わない。", "済もう": "意志形で、事実を述べる文に合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6fe1edb9-1a37-42aa-affb-5f6edb30cfd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36188, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「探す」の目的語を示す「を」。「眼鏡を探しました」となる。"}, {"text": "に", "is_correct": false, "explanation": "「眼鏡に探しました」は成り立たない。「に」は目的の対象を示せない。"}, {"text": "が", "is_correct": false, "explanation": "「眼鏡が探しました」だと眼鏡が探す主体になり、不自然。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、「眼鏡へ探しました」は成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「探す」の目的語を示す「を」。「眼鏡を探しました」となる。", "に": "「眼鏡に探しました」は成り立たない。「に」は目的の対象を示せない。", "が": "「眼鏡が探しました」だと眼鏡が探す主体になり、不自然。", "へ": "「へ」は方向を示すので、「眼鏡へ探しました」は成り立たない。"}, "error_tags": {"に": "場所・相手", "が": "主語", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6fe1edb9-1a37-42aa-affb-5f6edb30cfd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36188, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「かける」の目的語を示す「を」。「眼鏡をかけています」となる。"}, {"text": "で", "is_correct": false, "explanation": "「眼鏡でかけています」は成り立たない。「で」は手段や場所を示す。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、「眼鏡へかけています」は不自然。"}, {"text": "と", "is_correct": false, "explanation": "「と」は相手や引用を示すので、「眼鏡とかけています」は成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「かける」の目的語を示す「を」。「眼鏡をかけています」となる。", "で": "「眼鏡でかけています」は成り立たない。「で」は手段や場所を示す。", "へ": "「へ」は方向を示すので、「眼鏡へかけています」は不自然。", "と": "「と」は相手や引用を示すので、「眼鏡とかけています」は成り立たない。"}, "error_tags": {"で": "手段・場所", "へ": "方向", "と": "相手・引用"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6fe1edb9-1a37-42aa-affb-5f6edb30cfd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36188, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "めがねは、目をよく見えるようにするために、顔にかけるものです。", "primary_collocate": null, "pronunciation": "めがね", "ipa": "meɡane", "syllable_count": 3, "sentences": [{"text": "眼鏡をかけないと、黒板の字がよく見えません。", "target_word": "眼鏡", "complexity_tier": "T3", "furigana": "眼鏡[めがね]をかけないと、黒板[こくばん]の字[じ]がよく見[み]えません。", "sentence_source": "generated"}, {"text": "朝起きて、まず眼鏡を探しました。", "target_word": "眼鏡", "complexity_tier": "T3", "furigana": "朝[あさ]起[お]きて、まず眼鏡[めがね]を探[さが]しました。", "sentence_source": "generated"}, {"text": "母は新しい眼鏡を買うために、駅前の店へ行きました。", "target_word": "眼鏡", "complexity_tier": "T3", "furigana": "母[はは]は新[あたら]しい眼鏡[めがね]を買[か]うために、駅前[えきまえ]の店[みせ]へ行[い]きました。", "sentence_source": "generated"}, {"text": "眼鏡を忘れたので、本が読めませんでした。", "target_word": "眼鏡", "complexity_tier": "T3", "furigana": "眼鏡[めがね]を忘[わす]れたので、本[ほん]が読[よ]めませんでした。", "sentence_source": "generated"}, {"text": "祖父は眼鏡をかけて、新聞を読んでいます。", "target_word": "眼鏡", "complexity_tier": "T3", "furigana": "祖父[そふ]は眼鏡[めがね]をかけて、新聞[しんぶん]を読[よ]んでいます。", "sentence_source": "generated"}, {"text": "風呂に入ると、眼鏡が曇って前が見えなくなります。", "target_word": "眼鏡", "complexity_tier": "T3", "furigana": "風呂[ふろ]に入[はい]ると、眼鏡[めがね]が曇[くも]って前[まえ]が見[み]えなくなります。", "sentence_source": "generated"}, {"text": "眼鏡を落として、レンズが割れてしまいました。", "target_word": "眼鏡", "complexity_tier": "T3", "furigana": "眼鏡[めがね]を落[お]として、レンズが割[わ]れてしまいました。", "sentence_source": "generated"}, {"text": "兄は目が悪いので、いつも眼鏡をかけています。", "target_word": "眼鏡", "complexity_tier": "T3", "furigana": "兄[あに]は目[め]が悪[わる]いので、いつも眼鏡[めがね]をかけています。", "sentence_source": "generated"}, {"text": "この眼鏡は軽くて、長い時間かけても疲れません。", "target_word": "眼鏡", "complexity_tier": "T3", "furigana": "この眼鏡[めがね]は軽[かる]くて、長[なが]い時間[じかん]かけても疲[つか]れません。", "sentence_source": "generated"}, {"text": "眼鏡をはずして、顔を洗いました。", "target_word": "眼鏡", "complexity_tier": "T3", "furigana": "眼鏡[めがね]をはずして、顔[かお]を洗[あら]いました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "眼鏡", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "よく見えるように顔にかける道具（日常のめがね）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f58e5a06-dc41-4937-81ba-37dc3d155f50') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36188, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "眼鏡", "is_correct": true, "explanation": "顔にかけて視力を補う道具で、「眼鏡をかけないと」と自然に続く。ここに入る正解。"}, {"text": "指輪", "is_correct": false, "explanation": "指輪は顔にかけるものではなく、「指輪をかけないと字が見えない」は意味が通らない。"}, {"text": "ネクタイ", "is_correct": false, "explanation": "ネクタイは首に締めるもので、目の見え方とは関係しない。"}, {"text": "マフラー", "is_correct": false, "explanation": "マフラーは首に巻くもので、字の見え方とは関係しない。"}], "explanations": {"眼鏡": "顔にかけて視力を補う道具で、「眼鏡をかけないと」と自然に続く。ここに入る正解。", "指輪": "指輪は顔にかけるものではなく、「指輪をかけないと字が見えない」は意味が通らない。", "ネクタイ": "ネクタイは首に締めるもので、目の見え方とは関係しない。", "マフラー": "マフラーは首に巻くもので、字の見え方とは関係しない。"}, "sentence_index": 0, "correct_answer": "眼鏡"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "朝、眼鏡を目に入れてから家を出た。", "explanation": "ここは〈コンタクト〉の意味。眼鏡は顔にかける道具で、目に入れるものではない。"}, {"text": "眼鏡で前髪をとめた。", "explanation": "ここは〈ヘアピン〉の意味。眼鏡は髪をとめる道具ではなく、顔にかけるものなので合わない。"}, {"text": "騒がしいので、眼鏡で耳をふさいだ。", "explanation": "ここは〈耳栓〉の意味。眼鏡は耳をふさぐ道具ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6fe1edb9-1a37-42aa-affb-5f6edb30cfd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36188, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "眼鏡", "is_correct": true, "explanation": "「眼鏡を落として」で落とした物を示す。レンズが割れる話と合う。ここに入る正解。"}, {"text": "帽子", "is_correct": false, "explanation": "帽子にはレンズがなく、レンズが割れる話と合わない。"}, {"text": "財布", "is_correct": false, "explanation": "財布にはレンズがなく、「レンズが割れてしまいました」と続かない。"}, {"text": "腕時計", "is_correct": false, "explanation": "腕時計にはレンズがなく、レンズが割れる話と合わない。"}], "explanations": {"眼鏡": "「眼鏡を落として」で落とした物を示す。レンズが割れる話と合う。ここに入る正解。", "帽子": "帽子にはレンズがなく、レンズが割れる話と合わない。", "財布": "財布にはレンズがなく、「レンズが割れてしまいました」と続かない。", "腕時計": "腕時計にはレンズがなく、レンズが割れる話と合わない。"}, "sentence_index": 6, "correct_answer": "眼鏡"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "日差しが強いので、眼鏡をかぶって外に出た。", "explanation": "ここは〈帽子〉の意味。眼鏡はかぶるものではなく、顔にかける。"}, {"text": "汗をかいたので、眼鏡で顔をふいた。", "explanation": "ここは〈ハンカチ〉の意味。眼鏡は顔をふく道具ではないので合わない。"}, {"text": "朝、眼鏡を指にはめてから、庭に出た。", "explanation": "ここは〈指輪〉の意味。眼鏡は指にはめるものではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6fe1edb9-1a37-42aa-affb-5f6edb30cfd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36188, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夜、眼鏡に探しました。", "corrected_sentence": "夜、眼鏡を探しました。", "error_description": "「探す」は目的語に「を」を取るので、「眼鏡を探しました」が正しい。「に」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6fe1edb9-1a37-42aa-affb-5f6edb30cfd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36188, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "兄は眼鏡をはめて、本を読みます。", "corrected_sentence": "兄は眼鏡をかけて、本を読みます。", "error_description": "「眼鏡」は顔にかけるものなので「かける」を使う。「はめる」は指輪や手袋などに使う。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6fe1edb9-1a37-42aa-affb-5f6edb30cfd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36189, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「かける」の目的語を示す「を」。「眼鏡をかけると」となる。"}, {"text": "が", "is_correct": false, "explanation": "「眼鏡がかけると」だと眼鏡が主語になり、不自然。"}, {"text": "で", "is_correct": false, "explanation": "「眼鏡でかけると」は成り立たない。「で」は手段を示す。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、「眼鏡へかけると」は成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「かける」の目的語を示す「を」。「眼鏡をかけると」となる。", "が": "「眼鏡がかけると」だと眼鏡が主語になり、不自然。", "で": "「眼鏡でかけると」は成り立たない。「で」は手段を示す。", "へ": "「へ」は方向を示すので、「眼鏡へかけると」は成り立たない。"}, "error_tags": {"が": "主語", "で": "手段", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6fe1edb9-1a37-42aa-affb-5f6edb30cfd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36189, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「慣れる」の対象を示す「に」。「眼鏡に慣れる」となる。"}, {"text": "を", "is_correct": false, "explanation": "「慣れる」は目的語を取らないので、「眼鏡を慣れる」は成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、「眼鏡へ慣れる」は不自然。"}, {"text": "と", "is_correct": false, "explanation": "「と」は相手や並列を示すので、「眼鏡と慣れる」は成り立たない。"}], "correct_answer": "に", "explanations": {"に": "「慣れる」の対象を示す「に」。「眼鏡に慣れる」となる。", "を": "「慣れる」は目的語を取らないので、「眼鏡を慣れる」は成り立たない。", "へ": "「へ」は方向を示すので、「眼鏡へ慣れる」は不自然。", "と": "「と」は相手や並列を示すので、「眼鏡と慣れる」は成り立たない。"}, "error_tags": {"を": "目的語", "へ": "方向", "と": "相手・並列"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6fe1edb9-1a37-42aa-affb-5f6edb30cfd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36189, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "視力を補正したり、目を保護したりするために、顔に装着する器具。", "primary_collocate": null, "pronunciation": "めがね", "ipa": "meɡane", "syllable_count": 3, "sentences": [{"text": "視力が落ちたので、検査を受けて眼鏡を作り直した。", "target_word": "眼鏡", "complexity_tier": "T3", "furigana": "視力[しりょく]が落[お]ちたので、検査[けんさ]を受[う]けて眼鏡[めがね]を作[つく]り直[なお]した。", "sentence_source": "generated"}, {"text": "彼は眼鏡をかけると、急に知的な印象になる。", "target_word": "眼鏡", "complexity_tier": "T3", "furigana": "彼[かれ]は眼鏡[めがね]をかけると、急[きゅう]に知的[ちてき]な印象[いんしょう]になる。", "sentence_source": "generated"}, {"text": "運転するときは、必ず眼鏡を着用してください。", "target_word": "眼鏡", "complexity_tier": "T3", "furigana": "運転[うんてん]するときは、必[かなら]ず眼鏡[めがね]を着用[ちゃくよう]してください。", "sentence_source": "generated"}, {"text": "花粉の季節は、眼鏡をかけると目の痛みが少しやわらぐ。", "target_word": "眼鏡", "complexity_tier": "T3", "furigana": "花粉[かふん]の季節[きせつ]は、眼鏡[めがね]をかけると目[め]の痛[いた]みが少[すこ]しやわらぐ。", "sentence_source": "generated"}, {"text": "度が合わない眼鏡を使い続けると、頭痛の原因になる。", "target_word": "眼鏡", "complexity_tier": "T3", "furigana": "度[ど]が合[あ]わない眼鏡[めがね]を使[つか]い続[つづ]けると、頭痛[ずつう]の原因[げんいん]になる。", "sentence_source": "generated"}, {"text": "工場では、作業中に眼鏡をつけて目を守る決まりだ。", "target_word": "眼鏡", "complexity_tier": "T3", "furigana": "工場[こうじょう]では、作業中[さぎょうちゅう]に眼鏡[めがね]をつけて目[め]を守[まも]る決[き]まりだ。", "sentence_source": "generated"}, {"text": "眼鏡のレンズを専用の布で丁寧にふいた。", "target_word": "眼鏡", "complexity_tier": "T3", "furigana": "眼鏡[めがね]のレンズを専用[せんよう]の布[ぬの]で丁寧[ていねい]にふいた。", "sentence_source": "generated"}, {"text": "新しい眼鏡に慣れるまで、数日かかった。", "target_word": "眼鏡", "complexity_tier": "T3", "furigana": "新[あたら]しい眼鏡[めがね]に慣[な]れるまで、数日[すうじつ]かかった。", "sentence_source": "generated"}, {"text": "子どもの視力に合わせて、眼鏡を調整してもらった。", "target_word": "眼鏡", "complexity_tier": "T3", "furigana": "子[こ]どもの視力[しりょく]に合[あ]わせて、眼鏡[めがね]を調整[ちょうせい]してもらった。", "sentence_source": "generated"}, {"text": "祖母は眼鏡がないと、小さな文字が読めない。", "target_word": "眼鏡", "complexity_tier": "T3", "furigana": "祖母[そぼ]は眼鏡[めがね]がないと、小[ちい]さな文字[もじ]が読[よ]めない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "眼鏡", "label": "基本形"}], "register": "formal", "sense_fingerprint": "視力の補正や目の保護のために顔に装着する器具", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 3 above tier T3: contains vocabulary far above tier T3: やわらぐ (Zipf 1.97)']::text[], 'f58e5a06-dc41-4937-81ba-37dc3d155f50') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36189, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "眼鏡", "is_correct": true, "explanation": "「眼鏡を作り直した」で、視力に合わせて作り直すものを示す。ここに入る正解。"}, {"text": "検査", "is_correct": false, "explanation": "「検査を作り直した」は不自然で、眼鏡の文脈に合わない。"}, {"text": "視力", "is_correct": false, "explanation": "視力は作り直すものではなく、「視力を作り直した」は成り立たない。"}, {"text": "病院", "is_correct": false, "explanation": "「病院を作り直した」は文脈に合わず、眼鏡の作り直しの流れに入らない。"}], "explanations": {"眼鏡": "「眼鏡を作り直した」で、視力に合わせて作り直すものを示す。ここに入る正解。", "検査": "「検査を作り直した」は不自然で、眼鏡の文脈に合わない。", "視力": "視力は作り直すものではなく、「視力を作り直した」は成り立たない。", "病院": "「病院を作り直した」は文脈に合わず、眼鏡の作り直しの流れに入らない。"}, "sentence_index": 0, "correct_answer": "眼鏡"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "寒い日は、眼鏡で鍋を温めた。", "explanation": "ここは〈コンロ〉の意味。眼鏡は熱を出す道具ではないので合わない。"}, {"text": "洗面所で眼鏡に顔を映して、髪を整えた。", "explanation": "ここは〈鏡〉の意味。眼鏡は顔を映す道具ではなく、身だしなみの確認には使わない。"}, {"text": "工場では眼鏡で手を守る決まりだ。", "explanation": "ここは〈手袋〉の意味。眼鏡は手を守る道具ではなく、作業の保護には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6fe1edb9-1a37-42aa-affb-5f6edb30cfd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36189, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "眼鏡", "is_correct": true, "explanation": "「眼鏡のレンズ」の形で、レンズを持つ道具を示す。ここに入る正解。"}, {"text": "窓", "is_correct": false, "explanation": "窓は「窓のレンズ」とは言わず、ここでは合わない。"}, {"text": "黒板", "is_correct": false, "explanation": "黒板にはレンズがなく、「黒板のレンズ」は成り立たない。"}, {"text": "靴", "is_correct": false, "explanation": "靴にはレンズがなく、「靴のレンズ」は成り立たない。"}], "explanations": {"眼鏡": "「眼鏡のレンズ」の形で、レンズを持つ道具を示す。ここに入る正解。", "窓": "窓は「窓のレンズ」とは言わず、ここでは合わない。", "黒板": "黒板にはレンズがなく、「黒板のレンズ」は成り立たない。", "靴": "靴にはレンズがなく、「靴のレンズ」は成り立たない。"}, "sentence_index": 6, "correct_answer": "眼鏡"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "寒いので、眼鏡で耳をおおった。", "explanation": "ここは〈イヤーマフ〉の意味。眼鏡は耳をおおう道具ではない。"}, {"text": "メモを取るため、眼鏡で文字を書いた。", "explanation": "ここは〈鉛筆〉の意味。眼鏡は文字を書く道具ではない。"}, {"text": "朝、眼鏡で歯を磨いた。", "explanation": "ここは〈歯ブラシ〉の意味。眼鏡は歯を磨く道具ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6fe1edb9-1a37-42aa-affb-5f6edb30cfd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36189, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "眼鏡が作り直したので、よく見えるようになりました。", "corrected_sentence": "眼鏡を作り直したので、よく見えるようになりました。", "error_description": "「作り直す」は他動詞で、目的語を「を」で示す。「眼鏡が」は主語として誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6fe1edb9-1a37-42aa-affb-5f6edb30cfd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36189, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "私は眼鏡をかぶって、本を読みます。", "corrected_sentence": "私は眼鏡をかけて、本を読みます。", "error_description": "「眼鏡」は顔にかけるものなので「かける」を使う。「かぶる」は帽子などに使う。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6fe1edb9-1a37-42aa-affb-5f6edb30cfd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36190, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「ニュースを見ています」の「を」。「見る」の目的語を示す。"}, {"text": "に", "is_correct": false, "explanation": "「ニュースに見ています」は成り立たない。「に」は目的の対象を示せない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、「ニュースへ見ています」は目的語の役割を果たさず成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は相手や引用を示すので、「ニュースと見ています」は見る対象を示せず不自然。"}], "correct_answer": "を", "explanations": {"を": "「ニュースを見ています」の「を」。「見る」の目的語を示す。", "に": "「ニュースに見ています」は成り立たない。「に」は目的の対象を示せない。", "へ": "「へ」は方向を示すので、「ニュースへ見ています」は目的語の役割を果たさず成り立たない。", "と": "「と」は相手や引用を示すので、「ニュースと見ています」は見る対象を示せず不自然。"}, "error_tags": {"に": "対象の不一致", "へ": "方向", "と": "相手"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6fe1edb9-1a37-42aa-affb-5f6edb30cfd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36190, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「黒板を見て」の「を」。「見る」の目的語を示す。"}, {"text": "に", "is_correct": false, "explanation": "「黒板に見て」は成り立たない。「に」は位置や方向を示し、見る対象は示せない。"}, {"text": "が", "is_correct": false, "explanation": "「黒板が見て」だと黒板が見る主体になり、文の意味が合わない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は相手を示すので、「黒板と見て」は見る対象を表せず成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「黒板を見て」の「を」。「見る」の目的語を示す。", "に": "「黒板に見て」は成り立たない。「に」は位置や方向を示し、見る対象は示せない。", "が": "「黒板が見て」だと黒板が見る主体になり、文の意味が合わない。", "と": "「と」は相手を示すので、「黒板と見て」は見る対象を表せず成り立たない。"}, "error_tags": {"に": "位置", "が": "主語", "と": "相手"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6fe1edb9-1a37-42aa-affb-5f6edb30cfd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36190, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "めで ものを みること", "primary_collocate": null, "pronunciation": "みる", "ipa": "miɾɯ", "syllable_count": 2, "sentences": [{"text": "窓から山を見ます。", "target_word": "見ます", "complexity_tier": "T3", "furigana": "窓[まど]から山[やま]を見[み]ます。", "sentence_source": "generated"}, {"text": "毎晩、テレビでニュースを見ています。", "target_word": "見ています", "complexity_tier": "T3", "furigana": "毎晩[まいばん]、テレビでニュースを見[み]ています。", "sentence_source": "generated"}, {"text": "妹は空を見て、「きれいね」と言いました。", "target_word": "見て", "complexity_tier": "T3", "furigana": "妹[いもうと]は空[そら]を見[み]て、「きれいね」と言[い]いました。", "sentence_source": "generated"}, {"text": "昨日、友だちと映画を見ました。", "target_word": "見ました", "complexity_tier": "T3", "furigana": "昨日[きのう]、友[とも]だちと映画[えいが]を見[み]ました。", "sentence_source": "generated"}, {"text": "父は新聞を見ながら、朝ごはんを食べます。", "target_word": "見ながら", "complexity_tier": "T3", "furigana": "父[ちち]は新聞[しんぶん]を見[み]ながら、朝[あさ]ごはんを食[た]べます。", "sentence_source": "generated"}, {"text": "地図を見れば、駅までの道がわかります。", "target_word": "見れば", "complexity_tier": "T3", "furigana": "地図[ちず]を見[み]れば、駅[えき]までの道[みち]がわかります。", "sentence_source": "generated"}, {"text": "夜、空を見ると、星がたくさん出ていました。", "target_word": "見ると", "complexity_tier": "T3", "furigana": "夜[よる]、空[そら]を見[み]ると、星[ほし]がたくさん出[で]ていました。", "sentence_source": "generated"}, {"text": "先生は黒板を見て、学生の名前を呼びました。", "target_word": "見て", "complexity_tier": "T3", "furigana": "先生[せんせい]は黒板[こくばん]を見[み]て、学生[がくせい]の名前[なまえ]を呼[よ]びました。", "sentence_source": "generated"}, {"text": "公園で、子どもたちが遊ぶのを見ました。", "target_word": "見ました", "complexity_tier": "T3", "furigana": "公園[こうえん]で、子[こ]どもたちが遊[あそ]ぶのを見[み]ました。", "sentence_source": "generated"}, {"text": "私は毎朝、鏡を見て髪をなおします。", "target_word": "見て", "complexity_tier": "T3", "furigana": "私[わたし]は毎朝[まいあさ]、鏡[かがみ]を見[み]て髪[かみ]をなおします。", "sentence_source": "generated"}], "morphological_forms": [{"form": "見る", "label": "辞書形"}, {"form": "見ます", "label": "ます形"}, {"form": "見て", "label": "て形"}, {"form": "見た", "label": "た形"}, {"form": "見ない", "label": "ない形"}, {"form": "見れば", "label": "ば形"}], "register": "neutral", "sense_fingerprint": "目で物や景色などを見る", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f58e5a06-dc41-4937-81ba-37dc3d155f50') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36190, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "見ます", "is_correct": true, "explanation": "丁寧な終止形なので、文末の「。」で文を言い切れる。窓から山を見る、という事実を述べる形。"}, {"text": "見れば", "is_correct": false, "explanation": "条件の形で、文末では続く主節がなく文が完結しない。"}, {"text": "見ると", "is_correct": false, "explanation": "条件の形で、続く主節がないと文が完結しない。「窓から山を見ると。」では文として終わらない。"}, {"text": "見ながら", "is_correct": false, "explanation": "同時進行の「～ながら」なので文末では使えない。後ろに主節が必要になる。"}], "explanations": {"見ます": "丁寧な終止形なので、文末の「。」で文を言い切れる。窓から山を見る、という事実を述べる形。", "見れば": "条件の形で、文末では続く主節がなく文が完結しない。", "見ると": "条件の形で、続く主節がないと文が完結しない。「窓から山を見ると。」では文として終わらない。", "見ながら": "同時進行の「～ながら」なので文末では使えない。後ろに主節が必要になる。"}, "sentence_index": 0, "correct_answer": "見ます"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "昨日、友だちと本の手触りを見ました。", "explanation": "〈触る〉と混同している。手触りは手で感じるもので、目で見るものではない。"}, {"text": "昨日、友だちと外を歩いて、寒さを見ました。", "explanation": "〈感じる〉と混同している。寒さは肌で感じるもので、目で見ることはできない。"}, {"text": "昨日、友だちと音楽を見ました。", "explanation": "〈聴く〉と混同している。音楽は耳で聞くもので、〈見る〉とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6fe1edb9-1a37-42aa-affb-5f6edb30cfd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36190, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "見ると", "is_correct": true, "explanation": "「～と」の条件形で、「空を見ると、星が出ていた」と後ろの文に自然につながる。"}, {"text": "見よう", "is_correct": false, "explanation": "意志の形で、後ろの「星がたくさん出ていました」と続かない。"}, {"text": "見ろ", "is_correct": false, "explanation": "命令の形になり、過去の出来事を説明する文として成り立たない。"}, {"text": "見させる", "is_correct": false, "explanation": "使役の形で「人に見せる」の意味になり、ここでは意味が合わない。"}], "explanations": {"見ると": "「～と」の条件形で、「空を見ると、星が出ていた」と後ろの文に自然につながる。", "見よう": "意志の形で、後ろの「星がたくさん出ていました」と続かない。", "見ろ": "命令の形になり、過去の出来事を説明する文として成り立たない。", "見させる": "使役の形で「人に見せる」の意味になり、ここでは意味が合わない。"}, "sentence_index": 6, "correct_answer": "見ると"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夜、ワインの甘さを見て、ゆっくり飲みました。", "explanation": "〈味わう〉と混同している。甘さは舌で感じるもので、目で見ることはできない。"}, {"text": "朝、コーヒーの匂いを見て、目を覚まします。", "explanation": "〈嗅ぐ〉と混同している。匂いは鼻で感じるもので、目で見ることはできない。"}, {"text": "来週、お見合いで相手にあいさつを見ます。", "explanation": "〈あいさつする〉と混同している。あいさつは交わすもので、目で見るものではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6fe1edb9-1a37-42aa-affb-5f6edb30cfd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36190, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "庭から花に見ました。", "corrected_sentence": "庭から花を見ました。", "error_description": "正しくは「を」。「見る」は目的語に「を」をとるので、「花」に付く助詞は「を」。「に」では「花に見ました」となり文が成り立たない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "見ています", "is_correct": true, "explanation": "「～ている」の形で、毎晩くり返す習慣を表す。文の時制と合う。"}, {"text": "見ていれば", "is_correct": false, "explanation": "条件の形で、文末では主節がなく文が完結しない。"}, {"text": "見ていて", "is_correct": false, "explanation": "て形のままでは文が終わらず、文として成り立たない。"}, {"text": "見ていたら", "is_correct": false, "explanation": "条件の形で、文末では続く主節がなく文が完結しない。"}], "correct_form": "見ています", "base_form": "見る", "form_label": "～ている（進行・習慣）", "sentence_index": 1, "explanations": {"見ています": "「～ている」の形で、毎晩くり返す習慣を表す。文の時制と合う。", "見ていれば": "条件の形で、文末では主節がなく文が完結しない。", "見ていて": "て形のままでは文が終わらず、文として成り立たない。", "見ていたら": "条件の形で、文末では続く主節がなく文が完結しない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6fe1edb9-1a37-42aa-affb-5f6edb30cfd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36190, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "朝、窓から雨を見で、傘を持ちました。", "corrected_sentence": "朝、窓から雨を見て、傘を持ちました。", "error_description": "正しくは「見て」。「見る」のて形は「見て」で、濁らせた「見で」は誤った活用形。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "見て", "is_correct": true, "explanation": "て形で、「黒板を見て、名前を呼んだ」と動作の順序を表す。"}, {"text": "見よう", "is_correct": false, "explanation": "意志の形が文中で切れ、後の文と続かない。"}, {"text": "見させ", "is_correct": false, "explanation": "使役の連用形で目的語がなく、文が途中で切れて不完全。"}, {"text": "見ろ", "is_correct": false, "explanation": "命令の形が文中に入り、後の文と続かない。"}], "correct_form": "見て", "base_form": "見る", "form_label": "て形（動作の順序を表す）", "sentence_index": 7, "explanations": {"見て": "て形で、「黒板を見て、名前を呼んだ」と動作の順序を表す。", "見よう": "意志の形が文中で切れ、後の文と続かない。", "見させ": "使役の連用形で目的語がなく、文が途中で切れて不完全。", "見ろ": "命令の形が文中に入り、後の文と続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6fe1edb9-1a37-42aa-affb-5f6edb30cfd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36192, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「英語の先生」で、英語が先生を修飾する「の」。この位置に入る。"}, {"text": "が", "is_correct": false, "explanation": "「英語が先生」だと言語が主語になり、言語は先生ではないので文が成り立たない。"}, {"text": "を", "is_correct": false, "explanation": "「英語を先生」だと目的語の「を」になり、名詞「先生」につながらないので合わない。"}, {"text": "に", "is_correct": false, "explanation": "「英語に先生」は位置や相手を示す「に」で、名詞同士をつなぐ位置には入らない。"}], "correct_answer": "の", "explanations": {"の": "「英語の先生」で、英語が先生を修飾する「の」。この位置に入る。", "が": "「英語が先生」だと言語が主語になり、言語は先生ではないので文が成り立たない。", "を": "「英語を先生」だと目的語の「を」になり、名詞「先生」につながらないので合わない。", "に": "「英語に先生」は位置や相手を示す「に」で、名詞同士をつなぐ位置には入らない。"}, "error_tags": {"が": "主語", "を": "目的語", "に": "位置"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6fe1edb9-1a37-42aa-affb-5f6edb30cfd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36192, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「英語で道をたずねる」と、手段・使用言語を表して自然に続く。"}, {"text": "と", "is_correct": false, "explanation": "「英語と道をたずねる」だと言語を並ぶ相手のように扱うことになり、言語は道をたずねないので合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「英語へ道をたずねる」だと尋ねる先が言語になってしまい、言語には道を尋ねられないので合わない。"}, {"text": "から", "is_correct": false, "explanation": "「英語から道をたずねる」だと起点を示し、言語から道を聞くことになるので合わない。"}], "correct_answer": "で", "explanations": {"で": "「英語で道をたずねる」と、手段・使用言語を表して自然に続く。", "と": "「英語と道をたずねる」だと言語を並ぶ相手のように扱うことになり、言語は道をたずねないので合わない。", "へ": "「英語へ道をたずねる」だと尋ねる先が言語になってしまい、言語には道を尋ねられないので合わない。", "から": "「英語から道をたずねる」だと起点を示し、言語から道を聞くことになるので合わない。"}, "error_tags": {"と": "並列・相手", "へ": "方向", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6fe1edb9-1a37-42aa-affb-5f6edb30cfd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36192, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "えいごの ことばです。", "primary_collocate": null, "pronunciation": "えいご", "ipa": "eːɡo", "syllable_count": 3, "sentences": [{"text": "私は毎日、英語を勉強しています。", "target_word": "英語", "complexity_tier": "T3", "furigana": "私[わたし]は毎日[まいにち]、英語[えいご]を勉強[べんきょう]しています。", "sentence_source": "generated"}, {"text": "英語の先生は、アメリカから来た人です。", "target_word": "英語", "complexity_tier": "T3", "furigana": "英語[えいご]の先生[せんせい]は、アメリカから来[き]た人[ひと]です。", "sentence_source": "generated"}, {"text": "この手紙は英語で書いてあります。", "target_word": "英語", "complexity_tier": "T3", "furigana": "この手紙[てがみ]は英語[えいご]で書[か]いてあります。", "sentence_source": "generated"}, {"text": "兄は英語が上手なので、外国人とよく話します。", "target_word": "英語", "complexity_tier": "T3", "furigana": "兄[あに]は英語[えいご]が上手[じょうず]なので、外国人[がいこくじん]とよく話[はな]します。", "sentence_source": "generated"}, {"text": "英語の歌を聞いて、ことばをおぼえました。", "target_word": "英語", "complexity_tier": "T3", "furigana": "英語[えいご]の歌[うた]を聞[き]いて、ことばをおぼえました。", "sentence_source": "generated"}, {"text": "空港の案内は、日本語と英語で放送されます。", "target_word": "英語", "complexity_tier": "T3", "furigana": "空港[くうこう]の案内[あんない]は、日本語[にほんご]と英語[えいご]で放送[ほうそう]されます。", "sentence_source": "generated"}, {"text": "英語の辞書を引いて、意味を調べました。", "target_word": "英語", "complexity_tier": "T3", "furigana": "英語[えいご]の辞書[じしょ]を引[ひ]いて、意味[いみ]を調[しら]べました。", "sentence_source": "generated"}, {"text": "旅行のまえに、英語で道をたずねる練習をしました。", "target_word": "英語", "complexity_tier": "T3", "furigana": "旅行[りょこう]のまえに、英語[えいご]で道[みち]をたずねる練習[れんしゅう]をしました。", "sentence_source": "generated"}, {"text": "英語がわからなくて、メニューが読めませんでした。", "target_word": "英語", "complexity_tier": "T3", "furigana": "英語[えいご]がわからなくて、メニューが読[よ]めませんでした。", "sentence_source": "generated"}, {"text": "学校で、英語のテストがありました。", "target_word": "英語", "complexity_tier": "T3", "furigana": "学校[がっこう]で、英語[えいご]のテストがありました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "英語", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "英国・米国などで使われる言語、English", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 7 above tier T1: contains vocabulary far above tier T1: たずねる (Zipf 2.27)']::text[], 'f58e5a06-dc41-4937-81ba-37dc3d155f50') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36192, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "英語", "is_correct": true, "explanation": "勉強の対象になる言語の名前で、「英語を勉強している」と自然に続く。"}, {"text": "英和", "is_correct": false, "explanation": "英和辞典の略で、勉強の対象となる言語ではない。"}, {"text": "英雄", "is_correct": false, "explanation": "人物を指し、勉強の対象となる言語ではない。"}, {"text": "英気", "is_correct": false, "explanation": "気力を指し、勉強の対象にはならない。"}], "explanations": {"英語": "勉強の対象になる言語の名前で、「英語を勉強している」と自然に続く。", "英和": "英和辞典の略で、勉強の対象となる言語ではない。", "英雄": "人物を指し、勉強の対象となる言語ではない。", "英気": "気力を指し、勉強の対象にはならない。"}, "sentence_index": 0, "correct_answer": "英語"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "兄は英語が高いので、外国人とよく話します。", "explanation": "ここは〈英語力〉の意味。言語そのものを高い・低いとは言わないので合わない。"}, {"text": "兄は英語の料理が上手なので、外国人とよく話します。", "explanation": "ここは〈英国料理〉の意味。言語は料理を指さないので合わない。"}, {"text": "兄は英語の人なので、外国人とよく話します。", "explanation": "ここは〈英語圏の人〉の意味。言語は人を指さないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6fe1edb9-1a37-42aa-affb-5f6edb30cfd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36192, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "英語", "is_correct": true, "explanation": "辞書で調べる対象の言語の名前で、「英語の辞書」として自然に続く。"}, {"text": "英米", "is_correct": false, "explanation": "英国とアメリカをまとめた言い方で、言語を指さないので辞書の前には置けない。"}, {"text": "英会話", "is_correct": false, "explanation": "会話の活動を指し、辞書の対象にはならない。"}, {"text": "英雄", "is_correct": false, "explanation": "人物を指し、辞書の対象にはならない。"}], "explanations": {"英語": "辞書で調べる対象の言語の名前で、「英語の辞書」として自然に続く。", "英米": "英国とアメリカをまとめた言い方で、言語を指さないので辞書の前には置けない。", "英会話": "会話の活動を指し、辞書の対象にはならない。", "英雄": "人物を指し、辞書の対象にはならない。"}, "sentence_index": 6, "correct_answer": "英語"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学校で、英語の大使館がありました。", "explanation": "〈英国〉の意味。言語は大使館を持たないので、「英語の大使館」とは言えず合わない。"}, {"text": "学校で、英語への修学旅行がありました。", "explanation": "〈英語圏〉の意味。言語は行き先にならず、「英語圏への修学旅行」と言う。"}, {"text": "学校で、英語の大統領が話をしました。", "explanation": "〈英米〉の国の指導者を指す意味で、言語には大統領がいないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6fe1edb9-1a37-42aa-affb-5f6edb30cfd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36192, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妹は英語を授業で、先生に質問しました。", "corrected_sentence": "妹は英語の授業で、先生に質問しました。", "error_description": "正しくは「の」。「英語」は「授業」を修飾するので「の」が必要。「を」では「英語」が目的語になり、文が成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6fe1edb9-1a37-42aa-affb-5f6edb30cfd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36192, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妹は英語を飲むのが得意です。", "corrected_sentence": "妹は英語を話すのが得意です。", "error_description": "正しくは「話す」。「英語」と組み合わせる動詞は「話す」「書く」などで、「飲む」は合わない。「英語を飲む」は誤った組み合わせ。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6fe1edb9-1a37-42aa-affb-5f6edb30cfd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36193, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「英語が上手だ」の形で、上手の対象を示して「英語が上手なので」と続く。"}, {"text": "を", "is_correct": false, "explanation": "「英語を上手なので」では「上手だ」と結びつかず、「英語が上手」の形にならない。"}, {"text": "に", "is_correct": false, "explanation": "「英語に上手」は「上手だ」の対象を示す形にならず、言い方として成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「英語と上手」は並べる意味になり、「英語が上手」のように上手の対象を示せない。"}], "correct_answer": "が", "explanations": {"が": "「英語が上手だ」の形で、上手の対象を示して「英語が上手なので」と続く。", "を": "「英語を上手なので」では「上手だ」と結びつかず、「英語が上手」の形にならない。", "に": "「英語に上手」は「上手だ」の対象を示す形にならず、言い方として成り立たない。", "と": "「英語と上手」は並べる意味になり、「英語が上手」のように上手の対象を示せない。"}, "error_tags": {"を": "目的語", "に": "位置", "と": "相手"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6fe1edb9-1a37-42aa-affb-5f6edb30cfd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36193, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「英語の授業」で、英語が授業を修飾する「の」。この位置に入る。"}, {"text": "を", "is_correct": false, "explanation": "「英語を授業」は目的語の「を」になり、名詞「授業」につながらないので合わない。"}, {"text": "に", "is_correct": false, "explanation": "「英語に授業」は位置や相手を示す「に」で、名詞「授業」を修飾する形にはならない。"}, {"text": "へ", "is_correct": false, "explanation": "「英語へ授業」は方向を示す「へ」で、名詞を修飾する位置には入らない。"}], "correct_answer": "の", "explanations": {"の": "「英語の授業」で、英語が授業を修飾する「の」。この位置に入る。", "を": "「英語を授業」は目的語の「を」になり、名詞「授業」につながらないので合わない。", "に": "「英語に授業」は位置や相手を示す「に」で、名詞「授業」を修飾する形にはならない。", "へ": "「英語へ授業」は方向を示す「へ」で、名詞を修飾する位置には入らない。"}, "error_tags": {"を": "目的語", "に": "位置", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6fe1edb9-1a37-42aa-affb-5f6edb30cfd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36193, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "イギリスやアメリカなどでつかわれる言語。", "primary_collocate": null, "pronunciation": "えいご", "ipa": "eːɡo", "syllable_count": 3, "sentences": [{"text": "私は毎日三十分、英語を勉強しています。", "target_word": "英語", "complexity_tier": "T3", "furigana": "私[わたし]は毎日[まいにち]三十分[さんじゅっぷん]、英語[えいご]を勉強[べんきょう]しています。", "sentence_source": "generated"}, {"text": "彼女は英語が上手なので、外国のお客さんと話せます。", "target_word": "英語", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は英語[えいご]が上手[じょうず]なので、外国[がいこく]のお客[きゃく]さんと話[はな]せます。", "sentence_source": "generated"}, {"text": "この手紙は英語で書いてあるので、辞書が必要です。", "target_word": "英語", "complexity_tier": "T3", "furigana": "この手紙[てがみ]は英語[えいご]で書[か]いてあるので、辞書[じしょ]が必要[ひつよう]です。", "sentence_source": "generated"}, {"text": "英語の先生は、アメリカから来た人です。", "target_word": "英語", "complexity_tier": "T3", "furigana": "英語[えいご]の先生[せんせい]は、アメリカから来[き]た人[ひと]です。", "sentence_source": "generated"}, {"text": "兄は英語の歌を聞いて、発音を練習しています。", "target_word": "英語", "complexity_tier": "T3", "furigana": "兄[あに]は英語[えいご]の歌[うた]を聞[き]いて、発音[はつおん]を練習[れんしゅう]しています。", "sentence_source": "generated"}, {"text": "空港の案内は、日本語のほかに英語でも流れます。", "target_word": "英語", "complexity_tier": "T3", "furigana": "空港[くうこう]の案内[あんない]は、日本語[にほんご]のほかに英語[えいご]でも流[なが]れます。", "sentence_source": "generated"}, {"text": "英語はわかりますが、まだ上手に話せません。", "target_word": "英語", "complexity_tier": "T3", "furigana": "英語[えいご]はわかりますが、まだ上手[じょうず]に話[はな]せません。", "sentence_source": "generated"}, {"text": "学校では、一年生から英語の授業があります。", "target_word": "英語", "complexity_tier": "T3", "furigana": "学校[がっこう]では、一年生[いちねんせい]から英語[えいご]の授業[じゅぎょう]があります。", "sentence_source": "generated"}, {"text": "海外旅行に行く前に、英語の本を読んでおきました。", "target_word": "英語", "complexity_tier": "T3", "furigana": "海外[かいがい]旅行[りょこう]に行[い]く前[まえ]に、英語[えいご]の本[ほん]を読[よ]んでおきました。", "sentence_source": "generated"}, {"text": "英語の試験でいい点が取れて、うれしかったです。", "target_word": "英語", "complexity_tier": "T3", "furigana": "英語[えいご]の試験[しけん]でいい点[てん]が取[と]れて、うれしかったです。", "sentence_source": "generated"}], "morphological_forms": [{"form": "英語", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "英語という言語。イギリスやアメリカなどで使われる言語", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f58e5a06-dc41-4937-81ba-37dc3d155f50') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36193, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "英語", "is_correct": true, "explanation": "勉強の対象になる言語の名前で、「英語を勉強している」と自然に続く。"}, {"text": "英米", "is_correct": false, "explanation": "国の組み合わせを指し、勉強の対象となる言語ではない。"}, {"text": "英雄", "is_correct": false, "explanation": "人物を指し、勉強の対象となる言語ではない。"}, {"text": "英気", "is_correct": false, "explanation": "気力を指し、勉強の対象にはならない。"}], "explanations": {"英語": "勉強の対象になる言語の名前で、「英語を勉強している」と自然に続く。", "英米": "国の組み合わせを指し、勉強の対象となる言語ではない。", "英雄": "人物を指し、勉強の対象となる言語ではない。", "英気": "気力を指し、勉強の対象にはならない。"}, "sentence_index": 0, "correct_answer": "英語"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "兄の友だちは、英語から来た人です。", "explanation": "言語は国や地域ではないので、「英語から来た」とは言わない。ここは〈アメリカ〉の意味で合わない。"}, {"text": "英語の先生は、英語が高い人です。", "explanation": "ここは〈英語力〉の意味。言語そのものを高い・低いとは言わないので合わない。"}, {"text": "英語の先生は、英語の首都に住んでいます。", "explanation": "〈首都〉の意味。言語には首都がないので、「英語の首都」とは言わず合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6fe1edb9-1a37-42aa-affb-5f6edb30cfd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36193, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "英語", "is_correct": true, "explanation": "「わかる」の主語になる言語の名前で、「英語はわかります」と自然に続く。"}, {"text": "英才", "is_correct": false, "explanation": "優れた才能を持つ人を指し、「わかる」の対象となる言語ではない。"}, {"text": "英訳", "is_correct": false, "explanation": "翻訳の結果を指し、言語そのものを表さない。"}, {"text": "英断", "is_correct": false, "explanation": "思い切った決断を指し、「わかる」の対象とはならない。"}], "explanations": {"英語": "「わかる」の主語になる言語の名前で、「英語はわかります」と自然に続く。", "英才": "優れた才能を持つ人を指し、「わかる」の対象となる言語ではない。", "英訳": "翻訳の結果を指し、言語そのものを表さない。", "英断": "思い切った決断を指し、「わかる」の対象とはならない。"}, "sentence_index": 6, "correct_answer": "英語"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "英語の大使館で、いい点が取れて、うれしかったです。", "explanation": "〈英国〉の意味。言語は大使館を持たないので合わない。"}, {"text": "英語への修学旅行で、いい点が取れて、うれしかったです。", "explanation": "〈英語圏〉の意味。言語は行き先にならないので、「英語圏への修学旅行」と言う。"}, {"text": "英語の大統領に試験でいい点をほめられて、うれしかったです。", "explanation": "〈英米〉の国の指導者を指す意味で、言語には大統領がいないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6fe1edb9-1a37-42aa-affb-5f6edb30cfd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36193, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妹は英語を弾くのが得意です。", "corrected_sentence": "妹は英語を話すのが得意です。", "error_description": "正しくは「話す」。「弾く」は楽器の演奏に使う動詞で、「英語」とは合わない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6fe1edb9-1a37-42aa-affb-5f6edb30cfd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36193, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "英語を上手な妹は、外国人と話せます。", "corrected_sentence": "英語が上手な妹は、外国人と話せます。", "error_description": "正しくは「が」。「上手だ」は「〜が上手だ」の形をとるので、「英語」の後には「が」が必要。「を」では「上手」と結びつかない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6fe1edb9-1a37-42aa-affb-5f6edb30cfd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
