INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36196, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "走ったり泳いだりして計った、かかった時間の長さ。", "primary_collocate": null, "pronunciation": "たいむ", "ipa": "taimɯ", "syllable_count": 3, "sentences": [{"text": "今日のタイムは、昨日よりずっと遅かった。", "target_word": "タイム", "complexity_tier": "T3", "furigana": "今日[きょう]のタイムは、昨日[きのう]よりずっと遅[おそ]かった。", "sentence_source": "generated"}, {"text": "兄は五十メートル走のタイムを友だちと比べた。", "target_word": "タイム", "complexity_tier": "T3", "furigana": "兄[あに]は五十[ごじゅう]メートル走[そう]のタイムを友[とも]だちと比[くら]べた。", "sentence_source": "generated"}, {"text": "大会の前に、自分のタイムを必ず記録しておく。", "target_word": "タイム", "complexity_tier": "T3", "furigana": "大会[たいかい]の前[まえ]に、自分[じぶん]のタイムを必[かなら]ず記録[きろく]しておく。", "sentence_source": "generated"}, {"text": "タイムが縮まらなくて、少し悔しかった。", "target_word": "タイム", "complexity_tier": "T3", "furigana": "タイムが縮[ちぢ]まらなくて、少[すこ]し悔[くや]しかった。", "sentence_source": "generated"}, {"text": "駅伝では、各選手のタイムが順番に発表される。", "target_word": "タイム", "complexity_tier": "T3", "furigana": "駅伝[えきでん]では、各[かく]選手[せんしゅ]のタイムが順番[じゅんばん]に発表[はっぴょう]される。", "sentence_source": "generated"}, {"text": "計った結果、プールで泳いだタイムは一分だった。", "target_word": "タイム", "complexity_tier": "T3", "furigana": "計[はか]った結果[けっか]、プールで泳[およ]いだタイムは一分[いっぷん]だった。", "sentence_source": "generated"}, {"text": "彼のタイムは学校で一番だと言われている。", "target_word": "タイム", "complexity_tier": "T3", "furigana": "彼[かれ]のタイムは学校[がっこう]で一番[いちばん]だと言[い]われている。", "sentence_source": "generated"}, {"text": "毎週タイムを測れば、成長がよくわかる。", "target_word": "タイム", "complexity_tier": "T3", "furigana": "毎週[まいしゅう]タイムを測[はか]れば、成長[せいちょう]がよくわかる。", "sentence_source": "generated"}, {"text": "新しいくつを履いたら、走るタイムが少し良くなった。", "target_word": "タイム", "complexity_tier": "T3", "furigana": "新[あたら]しいくつを履[は]いたら、走[はし]るタイムが少[すこ]し良[よ]くなった。", "sentence_source": "generated"}, {"text": "良いタイムを出した選手に、大きな拍手が送られた。", "target_word": "タイム", "complexity_tier": "T3", "furigana": "良[よ]いタイムを出[だ]した選手[せんしゅ]に、大[おお]きな拍手[はくしゅ]が送[おく]られた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "タイム", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "時間。走る・泳ぐなどで計ったかかった時間の長さ", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 3 above tier T2: contains vocabulary far above tier T2: 縮まら (Zipf 2.02)']::text[], 'd6bd5b2a-24c0-4711-bcdb-72baf5213c95') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36196, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "タイム", "is_correct": true, "explanation": "走るなどしてかかった時間を指し、「今日の〜は昨日より遅かった」で自然。"}, {"text": "虹", "is_correct": false, "explanation": "虹は空の現象の名前で、「遅かった」と評価できない。"}, {"text": "湖", "is_correct": false, "explanation": "湖は場所の名前で、「昨日より遅かった」とは言わない。"}, {"text": "窓", "is_correct": false, "explanation": "窓は物の名前で、「遅かった」と評価できない。"}], "explanations": {"タイム": "走るなどしてかかった時間を指し、「今日の〜は昨日より遅かった」で自然。", "虹": "虹は空の現象の名前で、「遅かった」と評価できない。", "湖": "湖は場所の名前で、「昨日より遅かった」とは言わない。", "窓": "窓は物の名前で、「遅かった」と評価できない。"}, "sentence_index": 0, "correct_answer": "タイム"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "服のタイムが小さかったので、買い直した。", "explanation": "服の大きさを指すなら〈サイズ〉。タイムは時間の意味なので、服には使わない。"}, {"text": "電車のタイムを確認してから、ホームに向かった。", "explanation": "時計の時刻を指すなら〈時刻〉。タイムは計った時間の長さを指すので合わない。"}, {"text": "宿題のタイムを守るのが、いちばん大切だ。", "explanation": "締め切りを指すなら〈期限〉。タイムは計った時間の長さを指すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8ba898d-26ba-45b0-8878-cd9248f53336') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36196, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "タイム", "is_correct": true, "explanation": "走りや泳ぎで計った記録を指し、「彼のタイムは学校で一番」と評価できる。"}, {"text": "滝", "is_correct": false, "explanation": "滝は自然の景観の名前で、「学校で一番」と評価できない。"}, {"text": "雲", "is_correct": false, "explanation": "雲は空の現象の名前で、「彼の雲は学校で一番」とは言えない。"}, {"text": "梯子", "is_correct": false, "explanation": "梯子は道具の名前で、「学校で一番」と評価できない。"}], "explanations": {"タイム": "走りや泳ぎで計った記録を指し、「彼のタイムは学校で一番」と評価できる。", "滝": "滝は自然の景観の名前で、「学校で一番」と評価できない。", "雲": "雲は空の現象の名前で、「彼の雲は学校で一番」とは言えない。", "梯子": "梯子は道具の名前で、「学校で一番」と評価できない。"}, "sentence_index": 6, "correct_answer": "タイム"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "旅行のタイムは一週間で、予定はもう決まっている。", "explanation": "期間の意味は〈期間〉。タイムは計った時間の記録を指すので、旅行の期間には使わない。"}, {"text": "番号札のタイムが呼ばれて、窓口へ行った。", "explanation": "順番を指すなら〈順番〉。タイムは計った時間の意味で、呼ばれる順番には使わない。"}, {"text": "授業のタイムを延ばしたので、帰りが遅れた。", "explanation": "過ごす時間の長さを指すなら〈時間〉。タイムは計測された所要時間を指すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8ba898d-26ba-45b0-8878-cd9248f53336') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36196, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "記録会で、二百メートルのタイムを一秒縮まった。", "corrected_sentence": "記録会で、二百メートルのタイムが一秒縮まった。", "error_description": "「縮まる」は主語に「が」を取る自動詞。「タイムを」は誤りで、正しくは「タイムが」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8ba898d-26ba-45b0-8878-cd9248f53336') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36196, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "毎朝の練習でタイムを縮めよう努力している。", "corrected_sentence": "毎朝の練習でタイムを縮めようと努力している。", "error_description": "「努力する」には「〜ように」（辞書形）か「〜ようと」（意向形＋と）が続く。「縮めよう努力」は「と」が抜けている。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8ba898d-26ba-45b0-8878-cd9248f53336') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36198, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「さみしさを感ずる」で、感じる対象を示す「を」が入る。"}, {"text": "に", "is_correct": false, "explanation": "「さみしさに感ずる」では感じる対象を目的語として示せず、文が成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「さみしさと感ずる」は並べる意味になり、感じる対象を示せない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す「へ」は、感じる対象を示す位置には入らない。"}], "correct_answer": "を", "explanations": {"を": "「さみしさを感ずる」で、感じる対象を示す「を」が入る。", "に": "「さみしさに感ずる」では感じる対象を目的語として示せず、文が成り立たない。", "と": "「さみしさと感ずる」は並べる意味になり、感じる対象を示せない。", "へ": "方向を示す「へ」は、感じる対象を示す位置には入らない。"}, "error_tags": {"に": "位置", "と": "相手", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6fe1edb9-1a37-42aa-affb-5f6edb30cfd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36198, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6fe1edb9-1a37-42aa-affb-5f6edb30cfd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36198, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "体や心の働きで、ある気持ち・感覚・印象を受け取ること。", "primary_collocate": null, "pronunciation": "かんずる", "ipa": "kaɲzɯɾɯ", "syllable_count": 4, "sentences": [{"text": "試合に負けたとき、彼は強い責任を感じた。", "target_word": "感じた", "complexity_tier": "T3", "furigana": "試合[しあい]に負[ま]けたとき、彼[かれ]は強[つよ]い責任[せきにん]を感[かん]じた。", "sentence_source": "generated"}, {"text": "新しい町に来て、少しさみしさを感ずる。", "target_word": "感ずる", "complexity_tier": "T3", "furigana": "新[あたら]しい町[まち]に来[き]て、少[すこ]しさみしさを感[かん]ずる。", "sentence_source": "generated"}, {"text": "この絵からは、画家の深い悲しみを感ずる。", "target_word": "感ずる", "complexity_tier": "T3", "furigana": "この絵[え]からは、画家[がか]の深[ふか]い悲[かな]しみを感[かん]ずる。", "sentence_source": "generated"}, {"text": "母の手紙を読んで、家族のありがたみを感じた。", "target_word": "感じた", "complexity_tier": "T3", "furigana": "母[はは]の手紙[てがみ]を読[よ]んで、家族[かぞく]のありがたみを感[かん]じた。", "sentence_source": "generated"}, {"text": "彼の話し方に不自然なものを感じて、少し疑った。", "target_word": "感じて", "complexity_tier": "T3", "furigana": "彼[かれ]の話[はな]し方[かた]に不自然[ふしぜん]なものを感[かん]じて、少[すこ]し疑[うたが]った。", "sentence_source": "generated"}, {"text": "多くの人が将来に不安を感ずる時代だ。", "target_word": "感ずる", "complexity_tier": "T3", "furigana": "多[おお]くの人[ひと]が将来[しょうらい]に不安[ふあん]を感[かん]ずる時代[じだい]だ。", "sentence_source": "generated"}, {"text": "先生の言葉に力強さを感じて、もう一度挑戦した。", "target_word": "感じて", "complexity_tier": "T3", "furigana": "先生[せんせい]の言葉[ことば]に力強[ちからづよ]さを感[かん]じて、もう一度[いちど]挑戦[ちょうせん]した。", "sentence_source": "generated"}, {"text": "失敗しても何も感じないなら、人は成長しない。", "target_word": "感じない", "complexity_tier": "T3", "furigana": "失敗[しっぱい]しても何[なに]も感[かん]じないなら、人[ひと]は成長[せいちょう]しない。", "sentence_source": "generated"}, {"text": "古いお寺を歩くと、長い歴史を感ずる。", "target_word": "感ずる", "complexity_tier": "T3", "furigana": "古[ふる]いお寺[てら]を歩[ある]くと、長[なが]い歴史[れきし]を感[かん]ずる。", "sentence_source": "generated"}, {"text": "彼女の笑顔にやさしさを感じて、安心した。", "target_word": "感じて", "complexity_tier": "T3", "furigana": "彼女[かのじょ]の笑顔[えがお]にやさしさを感[かん]じて、安心[あんしん]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "感ずる", "label": "基本形"}, {"form": "感じた", "label": "過去形"}, {"form": "感じて", "label": "て形"}, {"form": "感じない", "label": "否定形"}, {"form": "感じます", "label": "丁寧形"}], "register": "formal", "sense_fingerprint": "責任・不安・悲しみなどの気持ちや印象を心の中で抱く", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f58e5a06-dc41-4937-81ba-37dc3d155f50') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36198, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "感じた", "is_correct": true, "explanation": "過去の終止形なので、「強い責任を感じた。」と文を言い切れる。"}, {"text": "感じて", "is_correct": false, "explanation": "て形のままでは文が終わらず、「強い責任を感じて。」は文として成り立たない。"}, {"text": "感じると", "is_correct": false, "explanation": "条件の形で、続く主節がないと文が完結しない。"}, {"text": "感じながら", "is_correct": false, "explanation": "同時進行の形で、文末では使えない。"}], "explanations": {"感じた": "過去の終止形なので、「強い責任を感じた。」と文を言い切れる。", "感じて": "て形のままでは文が終わらず、「強い責任を感じて。」は文として成り立たない。", "感じると": "条件の形で、続く主節がないと文が完結しない。", "感じながら": "同時進行の形で、文末では使えない。"}, "sentence_index": 0, "correct_answer": "感じた"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "母の手紙を読んで、家族の人数を感じた。", "explanation": "〈数える〉と混同している。人数は数えるもので、感じるものではない。"}, {"text": "母の手紙を読んで、予算を感じた。", "explanation": "〈見積もる〉と混同している。予算は見積もるもので、感じるものではない。"}, {"text": "母の手紙を読んで、家族の名前を感じた。", "explanation": "〈覚える〉と混同している。名前は覚えるもので、感じるものではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6fe1edb9-1a37-42aa-affb-5f6edb30cfd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36198, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "感じて", "is_correct": true, "explanation": "て形で、「力強さを感じて、もう一度挑戦した」と動作の流れを表す。"}, {"text": "感じよう", "is_correct": false, "explanation": "意志の形で、「力強さを感じよう、もう一度挑戦した」とは続かない。"}, {"text": "感じろ", "is_correct": false, "explanation": "命令の形になり、過去の出来事を述べる文として成り立たない。"}, {"text": "感じさせる", "is_correct": false, "explanation": "使役の形で「人に感じさせる」の意味になり、ここでは合わない。"}], "explanations": {"感じて": "て形で、「力強さを感じて、もう一度挑戦した」と動作の流れを表す。", "感じよう": "意志の形で、「力強さを感じよう、もう一度挑戦した」とは続かない。", "感じろ": "命令の形になり、過去の出来事を述べる文として成り立たない。", "感じさせる": "使役の形で「人に感じさせる」の意味になり、ここでは合わない。"}, "sentence_index": 6, "correct_answer": "感じて"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼女の笑顔の値段を感じて、安心した。", "explanation": "〈見積もる〉と混同している。値段は見積もるもので、感じ取るものではない。"}, {"text": "彼女の笑顔の住所を感じて、安心した。", "explanation": "〈調べる〉と混同している。住所は調べるもので、感じ取るものではない。"}, {"text": "彼女の笑顔の点数を感じて、安心した。", "explanation": "〈採点する〉と混同している。点数は付けるもので、感じ取るものではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6fe1edb9-1a37-42aa-affb-5f6edb30cfd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36198, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夜の駅で、一人きりの寂しさが感じた。", "corrected_sentence": "夜の駅で、一人きりの寂しさを感じた。", "error_description": "正しくは「を」。「感じる」は目的語に「を」をとる。「が」を付けると「寂しさが感じた」となり、文が成り立たない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "感ずる", "is_correct": true, "explanation": "基本形で、現在の気持ちを述べる文の形と合う。"}, {"text": "感じて", "is_correct": false, "explanation": "て形のままでは文が終わらず、「さみしさを感じて。」は文として成り立たない。"}, {"text": "感じれば", "is_correct": false, "explanation": "条件の形で、文末に来ると主節がなく文が完結しない。"}, {"text": "感じられ", "is_correct": false, "explanation": "途中で切れた形で、文末では完結しない。"}], "correct_form": "感ずる", "base_form": "感ずる", "form_label": "基本形（現在・肯定）", "sentence_index": 1, "explanations": {"感ずる": "基本形で、現在の気持ちを述べる文の形と合う。", "感じて": "て形のままでは文が終わらず、「さみしさを感じて。」は文として成り立たない。", "感じれば": "条件の形で、文末に来ると主節がなく文が完結しない。", "感じられ": "途中で切れた形で、文末では完結しない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6fe1edb9-1a37-42aa-affb-5f6edb30cfd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36198, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "駅の鐘の音に寂しさを感じで、家に帰りました。", "corrected_sentence": "駅の鐘の音に寂しさを感じて、家に帰りました。", "error_description": "正しくは「感じて」。「感じる」のて形は「感じて」で、濁らせた「感じで」は誤った活用形。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "感じない", "is_correct": true, "explanation": "否定の形で、「何も感じないなら」と条件を表す文に合う。"}, {"text": "感じます", "is_correct": false, "explanation": "丁寧形で、「何も感じますなら」となり、条件の文として成り立たない。"}, {"text": "感じよう", "is_correct": false, "explanation": "意志の形で、「何も感じようなら」となり文として不自然。"}, {"text": "感じて", "is_correct": false, "explanation": "て形のままでは「なら」に続かず、文として成り立たない。"}], "correct_form": "感じない", "base_form": "感ずる", "form_label": "否定形（ない形）", "sentence_index": 7, "explanations": {"感じない": "否定の形で、「何も感じないなら」と条件を表す文に合う。", "感じます": "丁寧形で、「何も感じますなら」となり、条件の文として成り立たない。", "感じよう": "意志の形で、「何も感じようなら」となり文として不自然。", "感じて": "て形のままでは「なら」に続かず、文として成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6fe1edb9-1a37-42aa-affb-5f6edb30cfd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36199, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "『責任を感ずる』と、感じる対象を示す『を』が正しい。"}, {"text": "が", "is_correct": false, "explanation": "『責任が感ずる』では責任が感じる主体になり、人を修飾する文の意味が崩れる。"}, {"text": "に", "is_correct": false, "explanation": "『責任に感ずる』では、感じる対象の示し方として不自然。"}, {"text": "で", "is_correct": false, "explanation": "『責任で感ずる』では手段・原因の意味になり、感じる対象を表せない。"}], "correct_answer": "を", "explanations": {"を": "『責任を感ずる』と、感じる対象を示す『を』が正しい。", "が": "『責任が感ずる』では責任が感じる主体になり、人を修飾する文の意味が崩れる。", "に": "『責任に感ずる』では、感じる対象の示し方として不自然。", "で": "『責任で感ずる』では手段・原因の意味になり、感じる対象を表せない。"}, "error_tags": {"が": "主語", "に": "方向・相手", "で": "手段・原因"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b772f74f-5395-4c72-9d02-b305fd6c8efb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36199, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "『未来への希望を感ずる』と、感じる対象を示す『を』が正しい。"}, {"text": "と", "is_correct": false, "explanation": "『未来への希望と感ずる』では並べる・引用の意味になり、感じる対象を示せない。"}, {"text": "へ", "is_correct": false, "explanation": "『未来への希望へ感ずる』では向かう先を表す『へ』になり、感じる対象の示し方として不自然。"}, {"text": "の", "is_correct": false, "explanation": "『未来への希望の感ずる』では名詞を修飾する形になり、動詞の目的語を示せないため文が成り立たない。"}], "correct_answer": "を", "explanations": {"を": "『未来への希望を感ずる』と、感じる対象を示す『を』が正しい。", "と": "『未来への希望と感ずる』では並べる・引用の意味になり、感じる対象を示せない。", "へ": "『未来への希望へ感ずる』では向かう先を表す『へ』になり、感じる対象の示し方として不自然。", "の": "『未来への希望の感ずる』では名詞を修飾する形になり、動詞の目的語を示せないため文が成り立たない。"}, "error_tags": {"と": "並列・引用", "へ": "方向・相手", "の": "所属・修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b772f74f-5395-4c72-9d02-b305fd6c8efb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36199, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "物事に接して、心や体に何かが起こる。感じる。", "primary_collocate": null, "pronunciation": "かんずる", "ipa": "kaɴzɯɾɯ", "syllable_count": 3, "sentences": [{"text": "風の冷たさに、私は秋の訪れを感ずる。", "target_word": "感ずる", "complexity_tier": "T3", "furigana": "風[かぜ]の冷[つめ]たさに、私[わたし]は秋[あき]の訪[おとず]れを感[かん]ずる。", "sentence_source": "generated"}, {"text": "彼は自分の言葉に責任を感ずる人だ。", "target_word": "感ずる", "complexity_tier": "T3", "furigana": "彼[かれ]は自分[じぶん]の言葉[ことば]に責任[せきにん]を感[かん]ずる人[ひと]だ。", "sentence_source": "generated"}, {"text": "山道で危険を感ずるや、彼はすぐに引き返した。", "target_word": "感ずる", "complexity_tier": "T3", "furigana": "山道[やまみち]で危険[きけん]を感[かん]ずるや、彼[かれ]はすぐに引[ひ]き返[かえ]した。", "sentence_source": "generated"}, {"text": "古い寺の前に立つと、長い歴史の重みを感ずる。", "target_word": "感ずる", "complexity_tier": "T3", "furigana": "古[ふる]い寺[てら]の前[まえ]に立[た]つと、長[なが]い歴史[れきし]の重[おも]みを感[かん]ずる。", "sentence_source": "generated"}, {"text": "私は先生の恩を深く感ずるがゆえに、今も手紙を書いている。", "target_word": "感ずる", "complexity_tier": "T3", "furigana": "私[わたし]は先生[せんせい]の恩[おん]を深[ふか]く感[かん]ずるがゆえに、今[いま]も手紙[てがみ]を書[か]いている。", "sentence_source": "generated"}, {"text": "少しの痛みも感ぜず、彼は最後まで走り続けた。", "target_word": "感ぜず", "complexity_tier": "T3", "furigana": "少[すこ]しの痛[いた]みも感[かん]ぜず、彼[かれ]は最後[さいご]まで走[はし]り続[つづ]けた。", "sentence_source": "generated"}, {"text": "彼の沈黙に、深い悲しみを感ずる。", "target_word": "感ずる", "complexity_tier": "T3", "furigana": "彼[かれ]の沈黙[ちんもく]に、深[ふか]い悲[かな]しみを感[かん]ずる。", "sentence_source": "generated"}, {"text": "子どもたちの笑顔に、未来への希望を感ずる。", "target_word": "感ずる", "complexity_tier": "T3", "furigana": "子[こ]どもたちの笑顔[えがお]に、未来[みらい]への希望[きぼう]を感[かん]ずる。", "sentence_source": "generated"}, {"text": "作品の中に作者の強い思いを感ずれば、見方も変わるだろう。", "target_word": "感ずれば", "complexity_tier": "T3", "furigana": "作品[さくひん]の中[なか]に作者[さくしゃ]の強[つよ]い思[おも]いを感[かん]ずれば、見方[みかた]も変[か]わるだろう。", "sentence_source": "generated"}, {"text": "夜の静けさの中で、私はひとりの寂しさを感ずる。", "target_word": "感ずる", "complexity_tier": "T3", "furigana": "夜[よる]の静[しず]けさの中[なか]で、私[わたし]はひとりの寂[さび]しさを感[かん]ずる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "感ずる", "label": "終止形・連体形"}, {"form": "感ずれば", "label": "仮定形"}, {"form": "感じた", "label": "過去形"}, {"form": "感ぜず", "label": "否定形(文語的)"}], "register": "literary", "sense_fingerprint": "外からの刺激や出来事に接して、気配・責任・思いなどを心や体で受け取る。「感じる」の文語的な形", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4e5da86-1411-4fd5-9f5f-e54c321bb1e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36199, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "感ずる", "is_correct": true, "explanation": "『秋の訪れを感ずる』と、気配を心や体で受け取る動作を表し、文末の終止形として自然。"}, {"text": "眠る", "is_correct": false, "explanation": "眠るは感じ取る対象にならず、『秋の訪れを眠る』は意味が通らない。"}, {"text": "磨く", "is_correct": false, "explanation": "磨くは物の表面をなめらかにする動作で、『秋の訪れを磨く』は意味が通らない。"}, {"text": "縮む", "is_correct": false, "explanation": "縮むは形が小さくなる動作で、『秋の訪れを縮む』は不自然。"}], "explanations": {"感ずる": "『秋の訪れを感ずる』と、気配を心や体で受け取る動作を表し、文末の終止形として自然。", "眠る": "眠るは感じ取る対象にならず、『秋の訪れを眠る』は意味が通らない。", "磨く": "磨くは物の表面をなめらかにする動作で、『秋の訪れを磨く』は意味が通らない。", "縮む": "縮むは形が小さくなる動作で、『秋の訪れを縮む』は不自然。"}, "sentence_index": 0, "correct_answer": "感ずる"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "子どものころの夏の日々を、ふと感ずることがある。", "explanation": "ここは〈思い出す〉の意味。過去の日々は感じ取るものではなく、思い起こすものなので〈感ずる〉の意味に合わない。"}, {"text": "その問題の解き方を、もう一度感じてみよう。", "explanation": "ここは〈考える〉の意味。解き方は感覚で受け取るものではなく、考えて組み立てるものなので合わない。"}, {"text": "彼は行くことを感ずると、すぐに荷物をまとめた。", "explanation": "ここは〈決める〉の意味。行くかどうかは感覚で受け取るものではなく、決めるものなので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b772f74f-5395-4c72-9d02-b305fd6c8efb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36199, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "感ずる", "is_correct": true, "explanation": "『深い悲しみを感ずる』と、心に生じる感情を受け取る動作として自然。"}, {"text": "煮る", "is_correct": false, "explanation": "煮るは料理の動作で、『深い悲しみを煮る』は意味が通らない。"}, {"text": "掘る", "is_correct": false, "explanation": "掘るは地面を削る動作で、感情を対象にすると文が成り立たない。"}, {"text": "跳ねる", "is_correct": false, "explanation": "跳ねるは体の動きを表し、『深い悲しみを跳ねる』では意味が通らない。"}], "explanations": {"感ずる": "『深い悲しみを感ずる』と、心に生じる感情を受け取る動作として自然。", "煮る": "煮るは料理の動作で、『深い悲しみを煮る』は意味が通らない。", "掘る": "掘るは地面を削る動作で、感情を対象にすると文が成り立たない。", "跳ねる": "跳ねるは体の動きを表し、『深い悲しみを跳ねる』では意味が通らない。"}, "sentence_index": 6, "correct_answer": "感ずる"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "試験のため、毎晩単語を感ずる練習をした。", "explanation": "ここは〈覚える〉（記憶する）の意味。単語を頭に入れる場面は『覚える』を使い、『感ずる』は心や体に何かが起こることなので、記憶の意味では使わない。"}, {"text": "母は毎朝、家族のために弁当を感ずる。", "explanation": "ここは〈作る〉の意味。料理や弁当を作る行為は『作る』で、『感ずる』は心や体に何かが起こることなので、ものを作る文には使わない。"}, {"text": "なくした財布を感ずるため、部屋中を探した。", "explanation": "ここは〈見つける〉の意味。なくしたものを探して手に入れることは『見つける』で、『感ずる』は心や体に何かが起こることなので、発見の意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b772f74f-5395-4c72-9d02-b305fd6c8efb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36199, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "作品の中に人の温かさが感ずると、読み終えたあとも心に残る。", "corrected_sentence": "作品の中に人の温かさを感ずると、読み終えたあとも心に残る。", "error_description": "『感ずる』の目的語は『を』で示す。『が』にすると『温かさが感ずる』となり、感じる主体と対象の関係が崩れる。正しくは『を』。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "感ずる", "is_correct": true, "explanation": "終止形・連体形で、『責任を感ずる人だ』と後ろの名詞を修飾する形として正しい。"}, {"text": "感ずれば", "is_correct": false, "explanation": "仮定形で、『感ずれば人だ』と条件を表すため、人を修飾する文に合わない。"}, {"text": "感じて", "is_correct": false, "explanation": "連用形（て）で、『責任を感じて人だ』と名詞を修飾できず、文として成り立たない。"}, {"text": "感ぜず", "is_correct": false, "explanation": "文語の否定形で、『感ぜず人だ』と名詞に続けられず、文として成り立たない。"}], "correct_form": "感ずる", "base_form": "感ずる", "form_label": "終止形・連体形", "sentence_index": 1, "explanations": {"感ずる": "終止形・連体形で、『責任を感ずる人だ』と後ろの名詞を修飾する形として正しい。", "感ずれば": "仮定形で、『感ずれば人だ』と条件を表すため、人を修飾する文に合わない。", "感じて": "連用形（て）で、『責任を感じて人だ』と名詞を修飾できず、文として成り立たない。", "感ぜず": "文語の否定形で、『感ぜず人だ』と名詞に続けられず、文として成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b772f74f-5395-4c72-9d02-b305fd6c8efb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36199, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夕暮れの海辺に、静かな寂しさが感ずる。", "corrected_sentence": "夕暮れの海辺に、静かな寂しさを感ずる。", "error_description": "『感ずる』の目的語は『を』で示す。『が』にすると『寂しさが感ずる』となり、感じる主体と対象の関係が崩れる。正しくは『を』。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "感ずる", "is_correct": true, "explanation": "終止形で、文末に置いて『希望を感ずる』と言い切る形として正しい。"}, {"text": "感じて", "is_correct": false, "explanation": "連用形（て）で、文を途中で続ける形。文末に置くと『希望を感じて。』と言い切れず、文が終わらない。"}, {"text": "感じない", "is_correct": false, "explanation": "否定形で、『希望を感じない』と打ち消すと文の意味が逆になり、笑顔に希望を感じるという内容と合わない。"}, {"text": "感じよう", "is_correct": false, "explanation": "意向形で、『希望を感じよう』は自分の意志を表す。文は感じている事実を述べるので合わない。"}], "correct_form": "感ずる", "base_form": "感ずる", "form_label": "終止形・連体形", "sentence_index": 7, "explanations": {"感ずる": "終止形で、文末に置いて『希望を感ずる』と言い切る形として正しい。", "感じて": "連用形（て）で、文を途中で続ける形。文末に置くと『希望を感じて。』と言い切れず、文が終わらない。", "感じない": "否定形で、『希望を感じない』と打ち消すと文の意味が逆になり、笑顔に希望を感じるという内容と合わない。", "感じよう": "意向形で、『希望を感じよう』は自分の意志を表す。文は感じている事実を述べるので合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b772f74f-5395-4c72-9d02-b305fd6c8efb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36200, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「毎日が続く」の「が」。毎日が主語になり、続くにつながる。"}, {"text": "を", "is_correct": false, "explanation": "「続く」は自動詞なので目的語の「を」は取れず、ここに合わない。"}, {"text": "で", "is_correct": false, "explanation": "「毎日で続く」は手段・場所の「で」では主語を示せず、成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「毎日と続く」は並列・引用の「と」では文が成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「毎日が続く」の「が」。毎日が主語になり、続くにつながる。", "を": "「続く」は自動詞なので目的語の「を」は取れず、ここに合わない。", "で": "「毎日で続く」は手段・場所の「で」では主語を示せず、成り立たない。", "と": "「毎日と続く」は並列・引用の「と」では文が成り立たない。"}, "error_tags": {"を": "目的語の格助詞。「続く」は自動詞なので「を」は不要", "で": "手段・場所の格助詞。「毎日で続く」は主語を示せない", "と": "並列・引用の格助詞。「毎日と続く」は文として成り立たない"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2bad5028-fea7-4a05-b046-8c14601ff2f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36200, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「毎日の通勤電車」の「の」。毎日が通勤電車を修飾する形で、ここに合う。"}, {"text": "が", "is_correct": false, "explanation": "「毎日が通勤電車」は名詞を続けられず、修飾関係が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「毎日に通勤電車」は位置・時の「に」では修飾関係が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「毎日へ通勤電車」は方向の「へ」では意味をなさない。"}], "correct_answer": "の", "explanations": {"の": "「毎日の通勤電車」の「の」。毎日が通勤電車を修飾する形で、ここに合う。", "が": "「毎日が通勤電車」は名詞を続けられず、修飾関係が成り立たない。", "に": "「毎日に通勤電車」は位置・時の「に」では修飾関係が成り立たない。", "へ": "「毎日へ通勤電車」は方向の「へ」では意味をなさない。"}, "error_tags": {"が": "主語の格助詞。「毎日が通勤電車」は名詞を続けられない", "に": "位置・時の格助詞。「毎日に通勤電車」は修飾関係が成り立たない", "へ": "方向の格助詞。「毎日へ通勤電車」は意味をなさない"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2bad5028-fea7-4a05-b046-8c14601ff2f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36200, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "名詞「毎日」は、日々くり返される生活や習慣としての毎日のこと。", "primary_collocate": null, "pronunciation": "まいにち", "ipa": "maiɲitɕi", "syllable_count": 4, "sentences": [{"text": "毎日の散歩は、私にとって大切な時間です。", "target_word": "毎日", "complexity_tier": "T3", "furigana": "毎日[まいにち]の散歩[さんぽ]は、私[わたし]にとって大切[たいせつ]な時間[じかん]です。", "sentence_source": "generated"}, {"text": "忙しい毎日が続いて、少し疲れました。", "target_word": "毎日", "complexity_tier": "T3", "furigana": "忙[いそが]しい毎日[まいにち]が続[つづ]いて、少[すこ]し疲[つか]れました。", "sentence_source": "generated"}, {"text": "毎日の食事には、野菜を多く入れています。", "target_word": "毎日", "complexity_tier": "T3", "furigana": "毎日[まいにち]の食事[しょくじ]には、野菜[やさい]を多[おお]く入[い]れています。", "sentence_source": "generated"}, {"text": "新しい町での毎日は、とても楽しいです。", "target_word": "毎日", "complexity_tier": "T3", "furigana": "新[あたら]しい町[まち]での毎日[まいにち]は、とても楽[たの]しいです。", "sentence_source": "generated"}, {"text": "毎日のそうじを続けると、部屋がきれいになります。", "target_word": "毎日", "complexity_tier": "T3", "furigana": "毎日[まいにち]のそうじを続[つづ]けると、部屋[へや]がきれいになります。", "sentence_source": "generated"}, {"text": "子どもが生まれてから、毎日が大きく変わりました。", "target_word": "毎日", "complexity_tier": "T3", "furigana": "子[こ]どもが生[う]まれてから、毎日[まいにち]が大[おお]きく変[か]わりました。", "sentence_source": "generated"}, {"text": "毎日の宿題は、夕飯の前に終わらせます。", "target_word": "毎日", "complexity_tier": "T3", "furigana": "毎日[まいにち]の宿題[しゅくだい]は、夕飯[ゆうはん]の前[まえ]に終[お]わらせます。", "sentence_source": "generated"}, {"text": "毎日の通勤電車は、いつも混んでいます。", "target_word": "毎日", "complexity_tier": "T3", "furigana": "毎日[まいにち]の通勤電車[つうきんでんしゃ]は、いつも混[こ]んでいます。", "sentence_source": "generated"}, {"text": "彼女は毎日の出来事を、ノートに書いています。", "target_word": "毎日", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は毎日[まいにち]の出来事[できごと]を、ノートに書[か]いています。", "sentence_source": "generated"}, {"text": "毎日のあいさつを大切にしている学校です。", "target_word": "毎日", "complexity_tier": "T3", "furigana": "毎日[まいにち]のあいさつを大切[たいせつ]にしている学校[がっこう]です。", "sentence_source": "generated"}], "morphological_forms": [{"form": "毎日", "label": "基本形"}], "register": "標準（丁寧体）", "sense_fingerprint": "日々くり返される生活や習慣としての毎日を表す名詞", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5d009b0-9a2b-46b1-b29d-64697f5f3725') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36200, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "毎日", "is_correct": true, "explanation": "正解。「毎日の散歩」は日々くり返される散歩を指し、文脈に合う。"}, {"text": "押し入れ", "is_correct": false, "explanation": "「押し入れ」は収納場所を表すので、散歩を修飾する語としては成り立たない。"}, {"text": "仕送り", "is_correct": false, "explanation": "「仕送り」は送金の意味なので、散歩にはつながらない。"}, {"text": "貯金", "is_correct": false, "explanation": "「貯金」はお金をためる行為なので、散歩を修飾する語としては合わない。"}], "explanations": {"毎日": "正解。「毎日の散歩」は日々くり返される散歩を指し、文脈に合う。", "押し入れ": "「押し入れ」は収納場所を表すので、散歩を修飾する語としては成り立たない。", "仕送り": "「仕送り」は送金の意味なので、散歩にはつながらない。", "貯金": "「貯金」はお金をためる行為なので、散歩を修飾する語としては合わない。"}, "sentence_index": 0, "correct_answer": "毎日"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この町の毎日は、春と夏の二つしかない。", "explanation": "ここは〈季節〉（春夏秋冬の区分）の意味。季節の区切りは〈季節〉で言い、〈毎日〉（日々の生活）とは合わない。"}, {"text": "その町の毎日は、千年の歴史を持っています。", "explanation": "ここは〈歴史〉の意味。〈毎日〉（日々の生活）は千年の歴史を持つとは言えず、〈歴史〉と入れ替えると不自然になる。"}, {"text": "毎日は、一年の始まりです。", "explanation": "ここは〈元日〉の意味。一年の始まりを指すのは〈元日〉で、〈毎日〉（くり返される日々）とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2bad5028-fea7-4a05-b046-8c14601ff2f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36200, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "毎日", "is_correct": true, "explanation": "正解。「毎日の宿題」は日々出される宿題を指し、文脈に合う。"}, {"text": "温泉", "is_correct": false, "explanation": "「温泉」は入浴場所を表すので、宿題を修飾する語としては合わない。"}, {"text": "押し入れ", "is_correct": false, "explanation": "「押し入れ」は収納場所なので、宿題とは結びつかない。"}, {"text": "渋滞", "is_correct": false, "explanation": "「渋滞」は交通の混雑を表すので、宿題とは結びつかない。"}], "explanations": {"毎日": "正解。「毎日の宿題」は日々出される宿題を指し、文脈に合う。", "温泉": "「温泉」は入浴場所を表すので、宿題を修飾する語としては合わない。", "押し入れ": "「押し入れ」は収納場所なので、宿題とは結びつかない。", "渋滞": "「渋滞」は交通の混雑を表すので、宿題とは結びつかない。"}, "sentence_index": 6, "correct_answer": "毎日"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この国の毎日は、年に十日ある。", "explanation": "ここは〈祝日〉（国が定めた休日）の意味。特定の休日は〈祝日〉で言い、〈毎日〉（日々の生活）とは合わない。"}, {"text": "入学式は、毎日の大切な行事です。", "explanation": "ここは〈行事〉（特定の日の催し）の意味。入学式は年に一度の行事なので、〈毎日〉のくり返しとは合わない。"}, {"text": "この学校の創立記念日は毎日です。", "explanation": "ここは〈記念日〉の意味。一年に一度の特定の日を指す語なので、〈毎日〉とは言えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2bad5028-fea7-4a05-b046-8c14601ff2f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36200, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "毎日が食事は、家族みんなで囲むことが多いです。", "corrected_sentence": "毎日の食事は、家族みんなで囲むことが多いです。", "error_description": "「毎日」を名詞として修飾するには「の」が必要。「が」を付けると「毎日が食事」となり、名詞を修飾できない。正しくは「毎日の食事」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2bad5028-fea7-4a05-b046-8c14601ff2f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36200, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "毎日な運動は、体を元気にしてくれます。", "corrected_sentence": "毎日の運動は、体を元気にしてくれます。", "error_description": "「毎日」は名詞として「の」で修飾するので、「な」は誤り。形容動詞の語尾を付けると不自然になる。正しくは「毎日の運動」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2bad5028-fea7-4a05-b046-8c14601ff2f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
