INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36201, 3, 'prompt1_core', '{"pos": "副詞", "semantic_class": "function", "definition": "毎日（まいにち）は、一週間のすべての日、または休みなく続く日々を指す副詞です。", "primary_collocate": null, "pronunciation": "まいにち", "ipa": "maiɲitɕi", "syllable_count": 4, "sentences": [{"text": "わたしは毎日、このTシャツをきます。", "target_word": "毎日", "complexity_tier": "T3", "furigana": "わたしは毎日[まいにち]、このTシャツをきます。", "sentence_source": "mined"}, {"text": "毎日、七時に起きて学校へ行きます。", "target_word": "毎日", "complexity_tier": "T3", "furigana": "毎日[まいにち]、七時[しちじ]に起[お]きて学校[がっこう]へ行[い]きます。", "sentence_source": "generated"}, {"text": "姉は健康のために、毎日三十分歩いています。", "target_word": "毎日", "complexity_tier": "T3", "furigana": "姉[あね]は健康[けんこう]のために、毎日[まいにち]三十分[さんじゅっぷん]歩[ある]いています。", "sentence_source": "generated"}, {"text": "この店は毎日開いているので、いつでも買い物ができます。", "target_word": "毎日", "complexity_tier": "T3", "furigana": "この店[みせ]は毎日[まいにち]開[あ]いているので、いつでも買[か]い物[もの]ができます。", "sentence_source": "generated"}, {"text": "毎日練習したので、ピアノが上手になりました。", "target_word": "毎日", "complexity_tier": "T3", "furigana": "毎日[まいにち]練習[れんしゅう]したので、ピアノが上手[じょうず]になりました。", "sentence_source": "generated"}, {"text": "私は毎日、夜にお風呂に入ります。", "target_word": "毎日", "complexity_tier": "T3", "furigana": "私[わたし]は毎日[まいにち]、夜[よる]にお風呂[ふろ]に入[はい]ります。", "sentence_source": "generated"}, {"text": "毎日雨が降って、洗濯物がかわきません。", "target_word": "毎日", "complexity_tier": "T3", "furigana": "毎日[まいにち]雨[あめ]が降[ふ]って、洗濯物[せんたくもの]がかわきません。", "sentence_source": "generated"}, {"text": "祖母は毎日、庭の花に水をやります。", "target_word": "毎日", "complexity_tier": "T3", "furigana": "祖母[そぼ]は毎日[まいにち]、庭[にわ]の花[はな]に水[みず]をやります。", "sentence_source": "generated"}, {"text": "弟は毎日牛乳を飲むので、背が高くなりました。", "target_word": "毎日", "complexity_tier": "T3", "furigana": "弟[おとうと]は毎日[まいにち]牛乳[ぎゅうにゅう]を飲[の]むので、背[せ]が高[たか]くなりました。", "sentence_source": "generated"}, {"text": "毎日日記を書いて、日本語を勉強しています。", "target_word": "毎日", "complexity_tier": "T3", "furigana": "毎日[まいにち]日記[にっき]を書[か]いて、日本語[にほんご]を勉強[べんきょう]しています。", "sentence_source": "generated"}], "morphological_forms": [{"form": "毎日", "label": "基本形"}], "register": "標準（丁寧体）", "sense_fingerprint": "動作や状態が、毎日休みなく繰り返されることを表す副詞", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 6 above tier T1: contains vocabulary far above tier T1: かわき (Zipf 1.96)']::text[], 'd5d009b0-9a2b-46b1-b29d-64697f5f3725') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36201, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "毎日", "is_correct": true, "explanation": "正解。「わたしは毎日、このTシャツをきます」は、服を休みなく着る頻度を表し、文脈に合う。"}, {"text": "ぐっすり", "is_correct": false, "explanation": "「ぐっすり」は眠りの深さを表す副詞なので、服を着る頻度には合わない。"}, {"text": "きらきら", "is_correct": false, "explanation": "「きらきら」は光が輝く様子を表すので、服を着る頻度を表せない。"}, {"text": "にこにこ", "is_correct": false, "explanation": "「にこにこ」は笑顔の様子を表すので、服を着る頻度には使えない。"}], "explanations": {"毎日": "正解。「わたしは毎日、このTシャツをきます」は、服を休みなく着る頻度を表し、文脈に合う。", "ぐっすり": "「ぐっすり」は眠りの深さを表す副詞なので、服を着る頻度には合わない。", "きらきら": "「きらきら」は光が輝く様子を表すので、服を着る頻度を表せない。", "にこにこ": "「にこにこ」は笑顔の様子を表すので、服を着る頻度には使えない。"}, "sentence_index": 0, "correct_answer": "毎日"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この山は毎日、標高が高い。", "explanation": "ここは〈いつも〉（常に、状態が続く）の意味。状態の持続は〈いつも〉で言い、〈毎日〉（くり返し）とは合わない。"}, {"text": "この祭りは毎日八月に行われます。", "explanation": "ここは〈毎年〉の意味。年に一度の行事に〈毎日〉を置くと、八月という時期の指定とも矛盾する。"}, {"text": "ごみ収集は毎日月曜日に出されます。", "explanation": "ここは〈毎週〉の意味。曜日を指定する頻度は〈毎週〉で言い、〈毎日〉とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2bad5028-fea7-4a05-b046-8c14601ff2f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36201, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "毎日", "is_correct": true, "explanation": "正解。「毎日雨が降って」は雨が休みなく降り続く頻度を表し、文脈に合う。"}, {"text": "ぴかぴか", "is_correct": false, "explanation": "「ぴかぴか」は光沢のある様子を表すので、雨の降り方には合わない。"}, {"text": "くるくる", "is_correct": false, "explanation": "「くるくる」は回る様子を表すので、雨が降る頻度を表せない。"}, {"text": "がちゃがちゃ", "is_correct": false, "explanation": "「がちゃがちゃ」は物がぶつかる音を表すので、雨には使えない。"}], "explanations": {"毎日": "正解。「毎日雨が降って」は雨が休みなく降り続く頻度を表し、文脈に合う。", "ぴかぴか": "「ぴかぴか」は光沢のある様子を表すので、雨の降り方には合わない。", "くるくる": "「くるくる」は回る様子を表すので、雨が降る頻度を表せない。", "がちゃがちゃ": "「がちゃがちゃ」は物がぶつかる音を表すので、雨には使えない。"}, "sentence_index": 6, "correct_answer": "毎日"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この雑誌は毎日十五日に発売されます。", "explanation": "ここは〈毎月〉の意味。毎月の決まった日付を言うときに〈毎日〉を置くと、日付の指定と矛盾する。"}, {"text": "私は毎日、たまに海外旅行に行きます。", "explanation": "ここは〈たまに〉（時々）の意味。時々の出来事に〈毎日〉を置くと、くり返しの意味と矛盾する。"}, {"text": "この薬は毎日、一日おきに飲みます。", "explanation": "ここは〈隔日〉（一日おき）の意味。一日おきの間隔は〈隔日〉で言い、〈毎日〉（日々くり返す）とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2bad5028-fea7-4a05-b046-8c14601ff2f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36201, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "毎日を、ジョギングをしてから出勤します。", "corrected_sentence": "毎日、ジョギングをしてから出勤します。", "error_description": "副詞の「毎日」には助詞「を」を付けない。「毎日、」と読点で区切るのが正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2bad5028-fea7-4a05-b046-8c14601ff2f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36201, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "毎日、日記を書くことがあります。", "corrected_sentence": "毎日、日記を書いています。", "error_description": "「毎日」は休みなく繰り返すことを表すので、「〜ことがあります（時々）」と矛盾する。正しくは「書いています」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2bad5028-fea7-4a05-b046-8c14601ff2f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36204, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "破る", "is_correct": true, "explanation": "決まりを守らない意味で、この文の〈守る〉の対義語。"}, {"text": "選ぶ", "is_correct": false, "explanation": "選択を表す動詞で、〈守る〉の対義語ではない。"}, {"text": "描く", "is_correct": false, "explanation": "絵を描く動作で、〈守る〉の対義語ではない。"}, {"text": "運ぶ", "is_correct": false, "explanation": "物を移動させる動作で、〈守る〉の対義語ではない。"}], "correct_answer": "破る", "explanations": {"破る": "決まりを守らない意味で、この文の〈守る〉の対義語。", "選ぶ": "選択を表す動詞で、〈守る〉の対義語ではない。", "描く": "絵を描く動作で、〈守る〉の対義語ではない。", "運ぶ": "物を移動させる動作で、〈守る〉の対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f74069d6-6885-444a-ab73-e4da8b3095d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36204, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "破る", "is_correct": true, "explanation": "決まりや約束を守らない意味で、この文の〈守る〉の対義語。"}, {"text": "拾う", "is_correct": false, "explanation": "落ちたものを取る動作で、〈守る〉の対義語ではない。"}, {"text": "誘う", "is_correct": false, "explanation": "誘いかける動作で、〈守る〉の対義語ではない。"}, {"text": "眺める", "is_correct": false, "explanation": "見て楽しむ動作で、〈守る〉の対義語ではない。"}], "correct_answer": "破る", "explanations": {"破る": "決まりや約束を守らない意味で、この文の〈守る〉の対義語。", "拾う": "落ちたものを取る動作で、〈守る〉の対義語ではない。", "誘う": "誘いかける動作で、〈守る〉の対義語ではない。", "眺める": "見て楽しむ動作で、〈守る〉の対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f74069d6-6885-444a-ab73-e4da8b3095d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36204, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "やくそくしたことや きめたことを そのとおりに する。", "primary_collocate": null, "pronunciation": "まもる", "ipa": "mamoɾɯ", "syllable_count": 3, "sentences": [{"text": "私は友達との約束を必ず守る。", "target_word": "守る", "complexity_tier": "T3", "furigana": "私(わたし)は友達(ともだち)との約束(やくそく)を必(かなら)ず守(まも)る。", "sentence_source": "generated"}, {"text": "先生は、時間を守るように生徒に言った。", "target_word": "守る", "complexity_tier": "T3", "furigana": "先生(せんせい)は、時間(じかん)を守(まも)るように生徒(せいと)に言(い)った。", "sentence_source": "generated"}, {"text": "弟は宿題の提出期限を守らなかったので、先生に注意された。", "target_word": "守らなかった", "complexity_tier": "T3", "furigana": "弟[おとうと]は宿題[しゅくだい]の提出期限[ていしゅつきげん]を守[まも]らなかったので、先生[せんせい]に注意[ちゅうい]された。", "sentence_source": "generated"}, {"text": "学校の決まりを守れば、みんなが気持ちよく過ごせる。", "target_word": "守れば", "complexity_tier": "T3", "furigana": "学校(がっこう)の決(き)まりを守(まも)れば、みんなが気持(きも)ちよく過(す)ごせる。", "sentence_source": "generated"}, {"text": "父は約束を守る人で、うそをつかない。", "target_word": "守る", "complexity_tier": "T3", "furigana": "父(ちち)は約束(やくそく)を守(まも)る人(ひと)で、うそをつかない。", "sentence_source": "generated"}, {"text": "交通ルールを守って、赤信号では必ず止まる。", "target_word": "守って", "complexity_tier": "T3", "furigana": "交通(こうつう)ルールを守(まも)って、赤信号(あかしんごう)では必(かなら)ず止(と)まる。", "sentence_source": "generated"}, {"text": "約束の時間を守れなくて、友達を待たせてしまった。", "target_word": "守れなくて", "complexity_tier": "T3", "furigana": "約束(やくそく)の時間(じかん)を守(まも)れなくて、友達(ともだち)を待(ま)たせてしまった。", "sentence_source": "generated"}, {"text": "姉は毎日、自分で決めた勉強の時間を守っている。", "target_word": "守って", "complexity_tier": "T3", "furigana": "姉(あね)は毎日(まいにち)、自分(じぶん)で決(き)めた勉強(べんきょう)の時間(じかん)を守(まも)っている。", "sentence_source": "generated"}, {"text": "約束を守らないと、友達に信じてもらえなくなる。", "target_word": "守らない", "complexity_tier": "T3", "furigana": "約束(やくそく)を守(まも)らないと、友達(ともだち)に信(しん)じてもらえなくなる。", "sentence_source": "generated"}, {"text": "試合では、ルールを守って正々堂々と戦った。", "target_word": "守って", "complexity_tier": "T3", "furigana": "試合(しあい)では、ルールを守(まも)って正々堂々(せいせいどうどう)と戦(たたか)った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "守る", "label": "辞書形"}, {"form": "守らない", "label": "否定形"}, {"form": "守ります", "label": "丁寧形"}, {"form": "守って", "label": "て形"}, {"form": "守った", "label": "過去形"}, {"form": "守れば", "label": "仮定形"}, {"form": "守れ", "label": "命令形"}], "register": "neutral", "sense_fingerprint": "約束や決まりをそのとおりに行う", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85f31001-e24e-4d36-97fe-2a4a88c33e43') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36204, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "守る", "is_correct": true, "explanation": "約束をそのとおりに果たすという意味で、「必ず守る」に合う。"}, {"text": "食べる", "is_correct": false, "explanation": "「約束を必ず食べる」は意味が通らない。"}, {"text": "測る", "is_correct": false, "explanation": "「約束を必ず測る」は意味が通らない。"}, {"text": "煮る", "is_correct": false, "explanation": "「約束を必ず煮る」は意味が通らない。"}], "explanations": {"守る": "約束をそのとおりに果たすという意味で、「必ず守る」に合う。", "食べる": "「約束を必ず食べる」は意味が通らない。", "測る": "「約束を必ず測る」は意味が通らない。", "煮る": "「約束を必ず煮る」は意味が通らない。"}, "sentence_index": 0, "correct_answer": "守る"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼女は告白を守った。", "explanation": "告白には「守る」を使わない。〈守る〉は約束や決まりに従う意味で、告白を断る意味にはならない。"}, {"text": "部屋の湿度を一定に守るため、加湿器を使う。", "explanation": "「保つ」との混同。〈守る〉は決まりや約束に従うことで、湿度のような状態には使わない。"}, {"text": "上司は彼の提案を守った。", "explanation": "提案には「守る」を使わない。〈守る〉は約束や決まりに従う意味で、提案を退ける意味にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f74069d6-6885-444a-ab73-e4da8b3095d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36204, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "守れなくて", "is_correct": true, "explanation": "約束の時間を守れなかったという、結果を述べる形。"}, {"text": "数えて", "is_correct": false, "explanation": "「約束の時間を数えて」は文脈に合わず、意味が通らない。"}, {"text": "磨いて", "is_correct": false, "explanation": "「約束の時間を磨いて」は意味が通らない。"}, {"text": "焼いて", "is_correct": false, "explanation": "「約束の時間を焼いて」は意味が通らない。"}], "explanations": {"守れなくて": "約束の時間を守れなかったという、結果を述べる形。", "数えて": "「約束の時間を数えて」は文脈に合わず、意味が通らない。", "磨いて": "「約束の時間を磨いて」は意味が通らない。", "焼いて": "「約束の時間を焼いて」は意味が通らない。"}, "sentence_index": 6, "correct_answer": "守れなくて"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "体温を一定に守るため、厚着をする。", "explanation": "「維持する」との混同。〈守る〉は決まりや約束に従うことで、体温のような状態には使わない。"}, {"text": "食欲を守るために、夕食は少なめにした。", "explanation": "「抑える」との混同。〈守る〉は約束や決まりを実行することで、食欲には使わない。"}, {"text": "彼は母に電話を守った。", "explanation": "電話には「守る」を使わない。〈守る〉は約束や決まりに従う意味で、電話をかける意味にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f74069d6-6885-444a-ab73-e4da8b3095d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36204, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "私は後輩との約束に必ず守る。", "corrected_sentence": "私は後輩との約束を必ず守る。", "error_description": "〈守る〉の目的語には「を」が要る。「約束に」は誤りで、正しくは「約束を」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "守る", "is_correct": true, "explanation": "「守るように」と辞書形で続き、言う内容の目的を表す。"}, {"text": "守れ", "is_correct": false, "explanation": "命令形は「守れように」となり、文として成立しない。"}, {"text": "守って", "is_correct": false, "explanation": "て形は「守ってように」となり、文として成立しない。"}, {"text": "守れば", "is_correct": false, "explanation": "仮定形は「守ればように」となり、文として成立しない。"}], "correct_form": "守る", "base_form": "守る", "form_label": "辞書形", "sentence_index": 1, "explanations": {"守る": "「守るように」と辞書形で続き、言う内容の目的を表す。", "守れ": "命令形は「守れように」となり、文として成立しない。", "守って": "て形は「守ってように」となり、文として成立しない。", "守れば": "仮定形は「守ればように」となり、文として成立しない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f74069d6-6885-444a-ab73-e4da8b3095d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36204, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "待ち合わせの約束の時間に守れなくて、友達を待たせてしまった。", "corrected_sentence": "待ち合わせの約束の時間を守れなくて、友達を待たせてしまった。", "error_description": "〈守る〉の目的語には「を」が要る。「時間に」は誤りで、正しくは「時間を」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "守って", "is_correct": true, "explanation": "「守っている」の て形。勉強の時間を続けているという意味に合う。"}, {"text": "守った", "is_correct": false, "explanation": "「守ったいる」となり、「守っている」の形にならない。"}, {"text": "守らない", "is_correct": false, "explanation": "否定形では、時間を守っていないという反対の意味になる。"}, {"text": "守ろう", "is_correct": false, "explanation": "意向形は「守ろうている」となり、文として成立しない。"}], "correct_form": "守って", "base_form": "守る", "form_label": "て形", "sentence_index": 7, "explanations": {"守って": "「守っている」の て形。勉強の時間を続けているという意味に合う。", "守った": "「守ったいる」となり、「守っている」の形にならない。", "守らない": "否定形では、時間を守っていないという反対の意味になる。", "守ろう": "意向形は「守ろうている」となり、文として成立しない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f74069d6-6885-444a-ab73-e4da8b3095d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36205, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "破る", "is_correct": true, "explanation": "規則や約束を守らない意味で、この文の〈守る〉の対義語。"}, {"text": "歩く", "is_correct": false, "explanation": "移動を表す動詞で、規則や約束とは関係がない。"}, {"text": "読む", "is_correct": false, "explanation": "文字を追う動作で、〈守る〉の対義語ではない。"}, {"text": "数える", "is_correct": false, "explanation": "数量を数える動作で、〈守る〉の対義語ではない。"}], "correct_answer": "破る", "explanations": {"破る": "規則や約束を守らない意味で、この文の〈守る〉の対義語。", "歩く": "移動を表す動詞で、規則や約束とは関係がない。", "読む": "文字を追う動作で、〈守る〉の対義語ではない。", "数える": "数量を数える動作で、〈守る〉の対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f74069d6-6885-444a-ab73-e4da8b3095d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
