INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36205, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "決めたことや約束したことに従って、それを実行したり、それを維持したりする。", "primary_collocate": null, "pronunciation": "まもる", "ipa": "mamoɾɯ", "syllable_count": 3, "sentences": [{"text": "友達との約束は、どんなことがあっても必ず守る。", "target_word": "守る", "complexity_tier": "T3", "furigana": "友達(ともだち)との約束(やくそく)は、どんなことがあっても必(かなら)ず守(まも)る。", "sentence_source": "generated"}, {"text": "約束の時間を守るのは、社会人として当たり前のことだ。", "target_word": "守る", "complexity_tier": "T3", "furigana": "約束(やくそく)の時間(じかん)を守(まも)るのは、社会人(しゃかいじん)として当(あ)たり前(まえ)のことだ。", "sentence_source": "generated"}, {"text": "彼は締め切りを守らなかったので、みんなに迷惑をかけた。", "target_word": "守らなかった", "complexity_tier": "T3", "furigana": "彼(かれ)は締(し)め切(き)りを守(まも)らなかったので、みんなに迷惑(めいわく)をかけた。", "sentence_source": "generated"}, {"text": "図書館では、静かにするというルールを守らなければならない。", "target_word": "守らなければ", "complexity_tier": "T3", "furigana": "図書館(としょかん)では、静(しず)かにするというルールを守(まも)らなければならない。", "sentence_source": "generated"}, {"text": "友達との約束を守れず、とても申し訳ない気持ちになった。", "target_word": "守れず", "complexity_tier": "T3", "furigana": "友達(ともだち)との約束(やくそく)を守(まも)れず、とても申(もう)し訳(わけ)ない気持(きも)ちになった。", "sentence_source": "generated"}, {"text": "交通ルールを守らない人が多いと、事故が起きやすくなる。", "target_word": "守らない", "complexity_tier": "T3", "furigana": "交通(こうつう)ルールを守(まも)らない人(ひと)が多(おお)いと、事故(じこ)が起(お)きやすくなる。", "sentence_source": "generated"}, {"text": "祖父は若いころに決めた習慣を、今でも毎朝守っている。", "target_word": "守って", "complexity_tier": "T3", "furigana": "祖父(そふ)は若(わか)いころに決(き)めた習慣(しゅうかん)を、今(いま)でも毎朝(まいあさ)守(まも)っている。", "sentence_source": "generated"}, {"text": "約束を守る人だから、みんなが彼を信頼している。", "target_word": "守る", "complexity_tier": "T3", "furigana": "約束(やくそく)を守(まも)る人(ひと)だから、みんなが彼(かれ)を信頼(しんらい)している。", "sentence_source": "generated"}, {"text": "校則を守らない生徒が増え、先生たちは対応に困っている。", "target_word": "守らない", "complexity_tier": "T3", "furigana": "校則(こうそく)を守(まも)らない生徒(せいと)が増(ふ)え、先生(せんせい)たちは対応(たいおう)に困(こま)っている。", "sentence_source": "generated"}, {"text": "母との約束を守って、毎晩十時までに家に帰った。", "target_word": "守って", "complexity_tier": "T3", "furigana": "母(はは)との約束(やくそく)を守(まも)って、毎晩(まいばん)十時(じゅうじ)までに家(いえ)に帰(かえ)った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "守る", "label": "辞書形"}, {"form": "守らない", "label": "否定形"}, {"form": "守ります", "label": "丁寧形"}, {"form": "守って", "label": "て形"}, {"form": "守った", "label": "過去形"}, {"form": "守れば", "label": "仮定形"}, {"form": "守られる", "label": "受身形"}], "register": "neutral", "sense_fingerprint": "約束・規則・決めたことに従って実行し維持する", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85f31001-e24e-4d36-97fe-2a4a88c33e43') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36205, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "守る", "is_correct": true, "explanation": "約束をそのとおり果たすという意味で、「必ず守る」に合う。"}, {"text": "焼く", "is_correct": false, "explanation": "「約束を焼く」は意味が通らない。"}, {"text": "煮る", "is_correct": false, "explanation": "「約束を煮る」は意味が通らない。"}, {"text": "食べる", "is_correct": false, "explanation": "「約束を食べる」は意味が通らない。"}], "explanations": {"守る": "約束をそのとおり果たすという意味で、「必ず守る」に合う。", "焼く": "「約束を焼く」は意味が通らない。", "煮る": "「約束を煮る」は意味が通らない。", "食べる": "「約束を食べる」は意味が通らない。"}, "sentence_index": 0, "correct_answer": "守る"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は昨日の誘いを守った。", "explanation": "誘いには「守る」を使わない。〈守る〉は約束や決まりに従う意味で、誘いを断る意味にはならない。"}, {"text": "部屋の温度を一定に守るため、エアコンをつけておく。", "explanation": "「保つ」の意味との混同。〈守る〉は決まりや約束に従うことで、温度のような状態には使わない。"}, {"text": "健康のために、彼はタバコを守った。", "explanation": "タバコには「守る」を使わない。〈守る〉は約束や決まりに従う意味で、習慣をやめる意味にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f74069d6-6885-444a-ab73-e4da8b3095d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36205, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "守って", "is_correct": true, "explanation": "「守っている」の形。習慣を今も毎朝続けているという文脈に合う。"}, {"text": "凍らせて", "is_correct": false, "explanation": "「習慣を毎朝凍らせている」は意味が通らない。"}, {"text": "削って", "is_correct": false, "explanation": "「習慣を毎朝削っている」は文脈に合わない。"}, {"text": "張って", "is_correct": false, "explanation": "「習慣を毎朝張っている」は意味が通らない。"}], "explanations": {"守って": "「守っている」の形。習慣を今も毎朝続けているという文脈に合う。", "凍らせて": "「習慣を毎朝凍らせている」は意味が通らない。", "削って": "「習慣を毎朝削っている」は文脈に合わない。", "張って": "「習慣を毎朝張っている」は意味が通らない。"}, "sentence_index": 6, "correct_answer": "守って"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "運動のあと、心拍数を一定に守るためにゆっくり歩く。", "explanation": "「維持する」との混同。〈守る〉は決まりや約束に従うことで、心拍数のような状態には使わない。"}, {"text": "大事な場面では怒りを守って、深呼吸して落ち着く。", "explanation": "「抑える」との混同。〈守る〉は約束や決まりを実行することで、感情には使わない。"}, {"text": "番犬は夜通し、飼い主の帰りを守っていた。", "explanation": "「帰りを守る」は不自然で、〈守る〉の約束や決まりに従う意味ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f74069d6-6885-444a-ab73-e4da8b3095d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36205, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "取引先との約束の時間に守るのは、社会人として当たり前のことだ。", "corrected_sentence": "取引先との約束の時間を守るのは、社会人として当たり前のことだ。", "error_description": "〈守る〉の目的語には「を」が要る。「時間に守る」は誤りで、正しくは「時間を守る」。助詞「に」が誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "守る", "is_correct": true, "explanation": "名詞化の「の」の前は辞書形。「守るのは」が正しい形。"}, {"text": "守って", "is_correct": false, "explanation": "て形は「〜のは」の前に置けず、文が成り立たない。"}, {"text": "守れ", "is_correct": false, "explanation": "命令形は「〜のは」で名詞化して主語にできない。"}, {"text": "守ろう", "is_correct": false, "explanation": "意向形は「〜のは」の前に置けず、この文の構造に合わない。"}], "correct_form": "守る", "base_form": "守る", "form_label": "辞書形", "sentence_index": 1, "explanations": {"守る": "名詞化の「の」の前は辞書形。「守るのは」が正しい形。", "守って": "て形は「〜のは」の前に置けず、文が成り立たない。", "守れ": "命令形は「〜のは」で名詞化して主語にできない。", "守ろう": "意向形は「〜のは」の前に置けず、この文の構造に合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f74069d6-6885-444a-ab73-e4da8b3095d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36205, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "祖父は若いころに決めた生活の習慣が、今でも毎朝守っている。", "corrected_sentence": "祖父は若いころに決めた生活の習慣を、今でも毎朝守っている。", "error_description": "〈守る〉の目的語には「を」が要る。「習慣が」は誤りで、正しくは「習慣を」。主格の「が」が誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "守る", "is_correct": true, "explanation": "「守る人」と名詞を修飾する辞書形。習慣を実行する人という意味に合う。"}, {"text": "守って", "is_correct": false, "explanation": "て形は名詞を修飾できず、「守って人」は成立しない。"}, {"text": "守らない", "is_correct": false, "explanation": "否定形では約束を守らない人の意味になり、文の内容と反対になる。"}, {"text": "守れば", "is_correct": false, "explanation": "仮定形は名詞を修飾できず、「守れば人」は成立しない。"}], "correct_form": "守る", "base_form": "守る", "form_label": "辞書形", "sentence_index": 7, "explanations": {"守る": "「守る人」と名詞を修飾する辞書形。習慣を実行する人という意味に合う。", "守って": "て形は名詞を修飾できず、「守って人」は成立しない。", "守らない": "否定形では約束を守らない人の意味になり、文の内容と反対になる。", "守れば": "仮定形は名詞を修飾できず、「守れば人」は成立しない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f74069d6-6885-444a-ab73-e4da8b3095d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36207, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「週の終わり」で、週に属する部分を示す。直前に週が来るので正しい。"}, {"text": "を", "is_correct": false, "explanation": "「を」は対象を示すので、「週を終わり」では成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、「週へ終わり」では意味が通らない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や共同を示すので、「週と終わり」では意味が通らない。"}], "correct_answer": "の", "explanations": {"の": "「週の終わり」で、週に属する部分を示す。直前に週が来るので正しい。", "を": "「を」は対象を示すので、「週を終わり」では成り立たない。", "へ": "「へ」は方向を示すので、「週へ終わり」では意味が通らない。", "と": "「と」は並列や共同を示すので、「週と終わり」では意味が通らない。"}, "error_tags": {"を": "対象を示す", "へ": "方向を示す", "と": "並列・共同を示す"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aad67c8f-e9b3-403f-a0ec-20e528ef9731') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36207, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「週に一度」で、週の中での頻度を示す。直前に週が来るので正しい。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示すので、「週が一度」では頻度の表現として合わない。"}, {"text": "を", "is_correct": false, "explanation": "「を」は対象を示すので、「週を一度」は頻度の表現として成り立たず合わない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を示すので、「週より一度」では意味が通らない。"}], "correct_answer": "に", "explanations": {"に": "「週に一度」で、週の中での頻度を示す。直前に週が来るので正しい。", "が": "「が」は主語を示すので、「週が一度」では頻度の表現として合わない。", "を": "「を」は対象を示すので、「週を一度」は頻度の表現として成り立たず合わない。", "より": "「より」は比較を示すので、「週より一度」では意味が通らない。"}, "error_tags": {"が": "主語を示す", "を": "対象を示す", "より": "比較を示す"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aad67c8f-e9b3-403f-a0ec-20e528ef9731') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36207, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "時間の単位の一つ。日曜日から土曜日までの七日間を一週間といいます。", "primary_collocate": null, "pronunciation": "しゅう", "ipa": "ɕɯː", "syllable_count": 2, "sentences": [{"text": "週に二日だけ、アルバイトをしています。", "target_word": "週", "complexity_tier": "T3", "furigana": "週[しゅう]に二日[ふつか]だけ、アルバイトをしています。", "sentence_source": "generated"}, {"text": "週の終わりに、家族で買い物に行きます。", "target_word": "週", "complexity_tier": "T3", "furigana": "週[しゅう]の終[お]わりに、家族[かぞく]で買[か]い物[もの]に行[い]きます。", "sentence_source": "generated"}, {"text": "このクラスは週に四時間、日本語を勉強します。", "target_word": "週", "complexity_tier": "T3", "furigana": "このクラスは週[しゅう]に四時間[よじかん]、日本語[にほんご]を勉強[べんきょう]します。", "sentence_source": "generated"}, {"text": "彼女は週に一冊、本を読むと決めている。", "target_word": "週", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は週[しゅう]に一冊[いっさつ]、本[ほん]を読[よ]むと決[き]めている。", "sentence_source": "generated"}, {"text": "七日が集まって、一つの週になります。", "target_word": "週", "complexity_tier": "T3", "furigana": "七日[なのか]が集[あつ]まって、一[ひと]つの週[しゅう]になります。", "sentence_source": "generated"}, {"text": "時間の単位には、日や月のほかに週もあります。", "target_word": "週", "complexity_tier": "T3", "furigana": "時間[じかん]の単位[たんい]には、日[ひ]や月[つき]のほかに週[しゅう]もあります。", "sentence_source": "generated"}, {"text": "週の前半は晴れでしたが、後半は雨が降りました。", "target_word": "週", "complexity_tier": "T3", "furigana": "週[しゅう]の前半[ぜんはん]は晴[は]れでしたが、後半[こうはん]は雨[あめ]が降[ふ]りました。", "sentence_source": "generated"}, {"text": "週に一度、ごみを出す日が決まっています。", "target_word": "週", "complexity_tier": "T3", "furigana": "週[しゅう]に一度[いちど]、ごみを出[だ]す日[ひ]が決[き]まっています。", "sentence_source": "generated"}, {"text": "日曜日から土曜日までが、カレンダーでは一つの週です。", "target_word": "週", "complexity_tier": "T3", "furigana": "日曜日[にちようび]から土曜日[どようび]までが、カレンダーでは一[ひと]つの週[しゅう]です。", "sentence_source": "generated"}, {"text": "医者に、薬を週に三回飲むように言われました。", "target_word": "週", "complexity_tier": "T3", "furigana": "医者[いしゃ]に、薬[くすり]を週[しゅう]に三回[さんかい]飲[の]むように言[い]われました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "週", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "日・月などと並ぶ時間の単位としての週(日曜から土曜までの七日間)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94f9763a-fbdb-4942-b840-f5e9ecdfccc6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36207, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "週", "is_correct": true, "explanation": "「週に二日だけ」で、週単位の頻度を示し、アルバイトをしている文に合う。"}, {"text": "病院", "is_correct": false, "explanation": "病院は場所なので、「病院に二日だけ」では頻度の表現として合わない。"}, {"text": "教室", "is_correct": false, "explanation": "教室は場所なので、「教室に二日だけ」では頻度の表現として合わない。"}, {"text": "電車", "is_correct": false, "explanation": "電車は乗り物なので、「電車に二日だけ」では頻度の表現として合わない。"}], "explanations": {"週": "「週に二日だけ」で、週単位の頻度を示し、アルバイトをしている文に合う。", "病院": "病院は場所なので、「病院に二日だけ」では頻度の表現として合わない。", "教室": "教室は場所なので、「教室に二日だけ」では頻度の表現として合わない。", "電車": "電車は乗り物なので、「電車に二日だけ」では頻度の表現として合わない。"}, "sentence_index": 0, "correct_answer": "週"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼女は週の一年に一冊、本を読むと決めている。", "explanation": "ここは〈年〉の意味。年単位の頻度に週を当てると期間の単位が合わないので誤り。"}, {"text": "彼女は週の夜に一冊、本を読むと決めている。", "explanation": "ここは〈夜〉の意味。一日の時間帯を週の単位で言い表すことはできないので合わない。"}, {"text": "彼女は週の一分で一冊、本を読むと決めている。", "explanation": "ここは〈分〉の意味。短い時間を週の単位で言うことはできないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aad67c8f-e9b3-403f-a0ec-20e528ef9731') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36207, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "週", "is_correct": true, "explanation": "「週の前半」で、七日間のまとまりの前半を指し、天気の文に合う。"}, {"text": "公園", "is_correct": false, "explanation": "公園は場所なので、「公園の前半は晴れでした」では意味が通らない。"}, {"text": "手紙", "is_correct": false, "explanation": "手紙は文書なので、「手紙の前半は晴れ」とは言えず合わない。"}, {"text": "窓", "is_correct": false, "explanation": "窓は建物の部分なので、「窓の前半」は天気の文と意味がつながらない。"}], "explanations": {"週": "「週の前半」で、七日間のまとまりの前半を指し、天気の文に合う。", "公園": "公園は場所なので、「公園の前半は晴れでした」では意味が通らない。", "手紙": "手紙は文書なので、「手紙の前半は晴れ」とは言えず合わない。", "窓": "窓は建物の部分なので、「窓の前半」は天気の文と意味がつながらない。"}, "sentence_index": 6, "correct_answer": "週"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "医者に、薬を週の朝に三回飲むように言われました。", "explanation": "ここは〈朝〉の意味。一日の時間帯を週の単位で言い表すことはできないので合わない。"}, {"text": "医者に、薬を週の一時間おきに三回飲むように言われました。", "explanation": "ここは〈時間〉の意味。時間の間隔に週を当てると単位が合わないので誤り。"}, {"text": "医者に、薬を週の一秒おきに三回飲むように言われました。", "explanation": "ここは〈秒〉の意味。極めて短い間隔に週を当てることはできないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aad67c8f-e9b3-403f-a0ec-20e528ef9731') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36207, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "週を二日だけ、塾で教えています。", "corrected_sentence": "週に二日だけ、塾で教えています。", "error_description": "頻度を表す「週」には助詞「に」を使う。「を」は対象を示すので誤りで、「に」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aad67c8f-e9b3-403f-a0ec-20e528ef9731') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36207, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "先生に、薬を週を三回飲むように言われました。", "corrected_sentence": "先生に、薬を週に三回飲むように言われました。", "error_description": "頻度を表す「週」には助詞「に」を使う。「を」は誤りで、「に」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aad67c8f-e9b3-403f-a0ec-20e528ef9731') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
