INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36208, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "「すき」は、何かを楽しいと感じたり、自分に合っていると思うことです。", "primary_collocate": null, "pronunciation": "すき", "ipa": "sɯki", "syllable_count": 2, "sentences": [{"text": "好きな仕事をしているので、毎日が楽しいです。", "target_word": "好き", "complexity_tier": "T3", "furigana": "好[す]きな仕事[しごと]をしているので、毎日[まいにち]が楽[たの]しいです。", "sentence_source": "generated"}, {"text": "この町の静かな雰囲気が好きで、ここに住むことにしました。", "target_word": "好き", "complexity_tier": "T3", "furigana": "この町[まち]の静[しず]かな雰囲気[ふんいき]が好[す]きで、ここに住[す]むことにしました。", "sentence_source": "generated"}, {"text": "絵をかくことが好きになって、美術部に入りました。", "target_word": "好き", "complexity_tier": "T3", "furigana": "絵[え]をかくことが好[す]きになって、美術部[びじゅつぶ]に入[はい]りました。", "sentence_source": "generated"}, {"text": "この服はデザインが好きで、よく着ています。", "target_word": "好き", "complexity_tier": "T3", "furigana": "この服[ふく]はデザインが好[す]きで、よく着[き]ています。", "sentence_source": "generated"}, {"text": "彼はサッカーが好きで、休みの日はいつも公園で練習しています。", "target_word": "好き", "complexity_tier": "T3", "furigana": "彼[かれ]はサッカーが好[す]きで、休[やす]みの日[ひ]はいつも公園[こうえん]で練習[れんしゅう]しています。", "sentence_source": "generated"}, {"text": "料理が好きな姉は、新しいレシピをよく試します。", "target_word": "好き", "complexity_tier": "T3", "furigana": "料理[りょうり]が好[す]きな姉[あね]は、新[あたら]しいレシピをよく試[ため]します。", "sentence_source": "generated"}, {"text": "私は自分のペースで歩けるので、一人で旅行するのが好きです。", "target_word": "好き", "complexity_tier": "T3", "furigana": "私[わたし]は自分[じぶん]のペースで歩[ある]けるので、一人[ひとり]で旅行[りょこう]するのが好[す]きです。", "sentence_source": "generated"}, {"text": "好きではない科目でも、先生が楽しければ勉強したくなります。", "target_word": "好き", "complexity_tier": "T3", "furigana": "好[す]きではない科目[かもく]でも、先生[せんせい]が楽[たの]しければ勉強[べんきょう]したくなります。", "sentence_source": "generated"}, {"text": "祖父は釣りが好きで、朝早くから川へ出かけます。", "target_word": "好き", "complexity_tier": "T3", "furigana": "祖父[そふ]は釣[つ]りが好[す]きで、朝早[あさはや]くから川[かわ]へ出[で]かけます。", "sentence_source": "generated"}, {"text": "本屋で好きな作家の新しい本を見つけました。", "target_word": "好き", "complexity_tier": "T3", "furigana": "本屋[ほんや]で好[す]きな作家[さっか]の新[あたら]しい本[ほん]を見[み]つけました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "好きだ", "label": "終止形"}, {"form": "好きです", "label": "丁寧形"}, {"form": "好きな", "label": "連体形"}, {"form": "好きに", "label": "連用形"}, {"form": "好きだった", "label": "過去形"}, {"form": "好きではない", "label": "否定形"}], "register": "標準（丁寧体）", "sense_fingerprint": "楽しい、自分に合っていると感じる気持ちを表す形状詞", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5d009b0-9a2b-46b1-b29d-64697f5f3725') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36208, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "好き", "is_correct": true, "explanation": "「好きな仕事」の語幹。ここに合う。"}, {"text": "好きに", "is_correct": false, "explanation": "連用形。「な仕事」には続かない。"}, {"text": "好きだ", "is_correct": false, "explanation": "終止形。「な仕事」には続かない。"}, {"text": "好きで", "is_correct": false, "explanation": "「で」の中止形。「な仕事」には続かない。"}], "explanations": {"好き": "「好きな仕事」の語幹。ここに合う。", "好きに": "連用形。「な仕事」には続かない。", "好きだ": "終止形。「な仕事」には続かない。", "好きで": "「で」の中止形。「な仕事」には続かない。"}, "sentence_index": 0, "correct_answer": "好き"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "壁の好きから冷たい風が入ってくる。", "explanation": "ここは〈隙間〉の意味の別の語。「好き」は好ましいと感じることなので、すきまには使わない。"}, {"text": "新しい環境で、ようやく好きが得られた。", "explanation": "「満足」の語を入れ替えた文。「満足が得られる」は自然だが、「好きが得られる」とは言わない。"}, {"text": "この二人は、なぜか好きが合う。", "explanation": "「相性」の語を入れ替えた文。「相性が合う」は自然だが、「好きが合う」とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2bad5028-fea7-4a05-b046-8c14601ff2f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36208, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "好き", "is_correct": true, "explanation": "「好きです」の語幹。ここに合う。"}, {"text": "好きな", "is_correct": false, "explanation": "連体形。述語の位置には置けない。"}, {"text": "好きだろう", "is_correct": false, "explanation": "推量形。「です」とは重ならない。"}, {"text": "好きそうに", "is_correct": false, "explanation": "副詞形。述語の位置に合わない。"}], "explanations": {"好き": "「好きです」の語幹。ここに合う。", "好きな": "連体形。述語の位置には置けない。", "好きだろう": "推量形。「です」とは重ならない。", "好きそうに": "副詞形。述語の位置に合わない。"}, "sentence_index": 6, "correct_answer": "好き"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は先輩の仕事ぶりに好きを寄せている。", "explanation": "「信頼」の語を入れ替えた文。「信頼を寄せる」は自然だが、「好きを寄せる」とは言わない。"}, {"text": "この新作は好きが高まっていて、発売が待ち遠しい。", "explanation": "「期待」の語を入れ替えた文。「期待が高まる」は自然だが、「好きが高まる」とは言わない。"}, {"text": "この企画は細かい好きを加えて、完成度が上がった。", "explanation": "「改善」の語を入れ替えた文。「改善を加える」は自然だが、「好きを加える」とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2bad5028-fea7-4a05-b046-8c14601ff2f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36208, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "休みの日は、好きの場所へ出かけます。", "corrected_sentence": "休みの日は、好きな場所へ出かけます。", "error_description": "形状詞「好き」は連体形「好きな」で後ろの名詞を修飾する。「好きの」は誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "好き", "is_correct": true, "explanation": "「好きで」の語幹。「で」に続く形。"}, {"text": "好きだ", "is_correct": false, "explanation": "終止形。「で」の前には置けない。"}, {"text": "好きな", "is_correct": false, "explanation": "連体形。「で」の前には置けない。"}, {"text": "好きだった", "is_correct": false, "explanation": "過去形。「で」の前には置けない。"}], "correct_form": "好き", "base_form": "好きだ", "form_label": "語幹（「で」に続く形）", "sentence_index": 1, "explanations": {"好き": "「好きで」の語幹。「で」に続く形。", "好きだ": "終止形。「で」の前には置けない。", "好きな": "連体形。「で」の前には置けない。", "好きだった": "過去形。「で」の前には置けない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2bad5028-fea7-4a05-b046-8c14601ff2f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36208, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妹は絵をかくのが好きに、毎日描いています。", "corrected_sentence": "妹は絵をかくのが好きで、毎日描いています。", "error_description": "「好き」は形状詞なので述語には「好きです」「好きで」の形が要る。連用形「好きに」は「思うまま」の副詞で、ここでは述語にならず文が成り立たない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "好き", "is_correct": true, "explanation": "「ではない」の前の語幹。ここに合う。"}, {"text": "好きで", "is_correct": false, "explanation": "「で」の中止形。「ではない」の前には置けない。"}, {"text": "好きに", "is_correct": false, "explanation": "連用形。「ではない」には続かない。"}, {"text": "好きです", "is_correct": false, "explanation": "丁寧形。「ではない」に続かない。"}], "correct_form": "好き", "base_form": "好きだ", "form_label": "語幹（「ではない」に続く形）", "sentence_index": 7, "explanations": {"好き": "「ではない」の前の語幹。ここに合う。", "好きで": "「で」の中止形。「ではない」の前には置けない。", "好きに": "連用形。「ではない」には続かない。", "好きです": "丁寧形。「ではない」に続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2bad5028-fea7-4a05-b046-8c14601ff2f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36209, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "嫌い", "is_correct": true, "explanation": "「好き」の対義語。好ましく思う気持ちの反対。"}, {"text": "静か", "is_correct": false, "explanation": "形状詞だが、「好き」の対義語ではない。"}, {"text": "元気", "is_correct": false, "explanation": "形状詞だが、「好き」の対義語ではない。"}, {"text": "大切", "is_correct": false, "explanation": "形状詞だが、「好き」の対義語ではない。"}], "correct_answer": "嫌い", "explanations": {"嫌い": "「好き」の対義語。好ましく思う気持ちの反対。", "静か": "形状詞だが、「好き」の対義語ではない。", "元気": "形状詞だが、「好き」の対義語ではない。", "大切": "形状詞だが、「好き」の対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2bad5028-fea7-4a05-b046-8c14601ff2f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36209, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "嫌い", "is_correct": true, "explanation": "「好き」の対義語。好ましく思う気持ちの反対。"}, {"text": "丈夫", "is_correct": false, "explanation": "形状詞だが、「好き」の対義語ではない（頑丈さを表す）。"}, {"text": "穏やか", "is_correct": false, "explanation": "形状詞だが、「好き」の対義語ではない（落ち着いた様子）。"}, {"text": "不便", "is_correct": false, "explanation": "形状詞だが、「好き」の対義語ではない（都合が悪い）。"}], "correct_answer": "嫌い", "explanations": {"嫌い": "「好き」の対義語。好ましく思う気持ちの反対。", "丈夫": "形状詞だが、「好き」の対義語ではない（頑丈さを表す）。", "穏やか": "形状詞だが、「好き」の対義語ではない（落ち着いた様子）。", "不便": "形状詞だが、「好き」の対義語ではない（都合が悪い）。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2bad5028-fea7-4a05-b046-8c14601ff2f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36209, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "ある物事や人に対して、好ましい気持ちを持っている状態。", "primary_collocate": null, "pronunciation": "すき", "ipa": "sɯki", "syllable_count": 2, "sentences": [{"text": "くまの絵がすきです。", "target_word": "すき", "complexity_tier": "T3", "furigana": "くまの絵[え]がすきです。", "sentence_source": "mined"}, {"text": "わたしは甘いものが好きで、毎日ケーキを食べます。", "target_word": "好き", "complexity_tier": "T3", "furigana": "わたしは甘[あま]いものが好[す]きで、毎日[まいにち]ケーキを食[た]べます。", "sentence_source": "generated"}, {"text": "弟は電車が好きなので、休みの日は駅へ見に行きます。", "target_word": "好き", "complexity_tier": "T3", "furigana": "弟[おとうと]は電車[でんしゃ]が好[す]きなので、休[やす]みの日[ひ]は駅[えき]へ見[み]に行[い]きます。", "sentence_source": "generated"}, {"text": "父はコーヒーが好きで、朝は必ず飲みます。", "target_word": "好き", "complexity_tier": "T3", "furigana": "父[ちち]はコーヒーが好[す]きで、朝[あさ]は必[かなら]ず飲[の]みます。", "sentence_source": "generated"}, {"text": "好きな色を聞かれて、青と答えました。", "target_word": "好き", "complexity_tier": "T3", "furigana": "好[す]きな色[いろ]を聞[き]かれて、青[あお]と答[こた]えました。", "sentence_source": "generated"}, {"text": "私は雨の日の静かな音が好きです。", "target_word": "好き", "complexity_tier": "T3", "furigana": "私[わたし]は雨[あめ]の日[ひ]の静[しず]かな音[おと]が好[す]きです。", "sentence_source": "generated"}, {"text": "彼女は犬が好きなので、散歩をするのも楽しそうです。", "target_word": "好き", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は犬[いぬ]が好[す]きなので、散歩[さんぽ]をするのも楽[たの]しそうです。", "sentence_source": "generated"}, {"text": "好きな歌手のコンサートに行くので、とてもわくわくしています。", "target_word": "好き", "complexity_tier": "T3", "furigana": "好[す]きな歌手[かしゅ]のコンサートに行[い]くので、とてもわくわくしています。", "sentence_source": "generated"}, {"text": "好きな先生の授業は、時間が早く過ぎるように感じます。", "target_word": "好き", "complexity_tier": "T3", "furigana": "好[す]きな先生[せんせい]の授業[じゅぎょう]は、時間[じかん]が早[はや]く過[す]ぎるように感[かん]じます。", "sentence_source": "generated"}, {"text": "子どものころは野菜が好きではありませんでした。", "target_word": "好き", "complexity_tier": "T3", "furigana": "子[こ]どものころは野菜[やさい]が好[す]きではありませんでした。", "sentence_source": "generated"}], "morphological_forms": [{"form": "好きだ", "label": "終止形"}, {"form": "好きです", "label": "丁寧形"}, {"form": "好きな", "label": "連体形"}, {"form": "好きに", "label": "連用形"}, {"form": "好きだった", "label": "過去形"}, {"form": "好きではない", "label": "否定形"}], "register": "標準（丁寧体）", "sense_fingerprint": "物事や人に好ましい気持ちを持つ状態を表す形状詞", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5d009b0-9a2b-46b1-b29d-64697f5f3725') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36209, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "すき", "is_correct": true, "explanation": "「くまの絵が好きです」の述語。ここに合う。"}, {"text": "すきな", "is_correct": false, "explanation": "連体形。「です」の前には置けず、文が成り立たない。"}, {"text": "すきだ", "is_correct": false, "explanation": "終止形。「です」と重ねると不自然で、文に合わない。"}, {"text": "すきに", "is_correct": false, "explanation": "連用形。ここでは文が続かない。"}], "explanations": {"すき": "「くまの絵が好きです」の述語。ここに合う。", "すきな": "連体形。「です」の前には置けず、文が成り立たない。", "すきだ": "終止形。「です」と重ねると不自然で、文に合わない。", "すきに": "連用形。ここでは文が続かない。"}, "sentence_index": 0, "correct_answer": "すき"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "母は娘に好きをかけて、大切に育てた。", "explanation": "「愛情」の語を入れ替えた文。「愛情をかける」は自然だが、「好きをかける」とは言わない。"}, {"text": "壁の好きから冷たい風が入ってくる。", "explanation": "ここは〈隙間〉の意味の別の語。「好き」は好ましいと感じることなので、すきまには使わない。"}, {"text": "彼は本に好きを持って、毎日読んでいる。", "explanation": "「興味」の語を入れ替えた文。「興味を持つ」は自然だが、「好きを持つ」とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2bad5028-fea7-4a05-b046-8c14601ff2f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36209, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "好き", "is_correct": true, "explanation": "「好きなので」の語幹。原因を表す形でここに合う。"}, {"text": "好きで", "is_correct": false, "explanation": "「で」の中止形。「なので」には続かない。"}, {"text": "好きだろう", "is_correct": false, "explanation": "推量形。「犬が〜なので」の形に合わない。"}, {"text": "好きそうに", "is_correct": false, "explanation": "副詞形。「犬が〜なので」の形に合わない。"}], "explanations": {"好き": "「好きなので」の語幹。原因を表す形でここに合う。", "好きで": "「で」の中止形。「なので」には続かない。", "好きだろう": "推量形。「犬が〜なので」の形に合わない。", "好きそうに": "副詞形。「犬が〜なので」の形に合わない。"}, "sentence_index": 6, "correct_answer": "好き"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は練習に好きがあって、毎朝走っている。", "explanation": "「熱意」の語を入れ替えた文。「熱意がある」は自然だが、「好きがある」とは言わない。"}, {"text": "古いぬいぐるみに好きが湧いて、手放せない。", "explanation": "「愛着」の語を入れ替えた文。「愛着が湧く」は自然だが、「好きが湧く」とは言わない。"}, {"text": "彼女は先輩に好きを抱いて、いつも相談する。", "explanation": "「尊敬」の語を入れ替えた文。「尊敬を抱く」は自然だが、「好きを抱く」とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2bad5028-fea7-4a05-b046-8c14601ff2f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36209, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "私は魚が好きのので、週末は釣りに行きます。", "corrected_sentence": "私は魚が好きなので、週末は釣りに行きます。", "error_description": "形状詞「好き」は連体形「好きな」で後ろの名詞を修飾する。「好きの」は誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "好き", "is_correct": true, "explanation": "「好きで」の語幹。「で」に続く形。"}, {"text": "好きだ", "is_correct": false, "explanation": "終止形。「で」の前には置けない。"}, {"text": "好きな", "is_correct": false, "explanation": "連体形。「で」の前には置けない。"}, {"text": "好きに", "is_correct": false, "explanation": "連用形。「で」の前には置けない。"}], "correct_form": "好き", "base_form": "好きだ", "form_label": "語幹（「で」に続く形）", "sentence_index": 1, "explanations": {"好き": "「好きで」の語幹。「で」に続く形。", "好きだ": "終止形。「で」の前には置けない。", "好きな": "連体形。「で」の前には置けない。", "好きに": "連用形。「で」の前には置けない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2bad5028-fea7-4a05-b046-8c14601ff2f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36209, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼は映画が好きに、よく見に行きます。", "corrected_sentence": "彼は映画が好きで、よく見に行きます。", "error_description": "理由をつなぐ「好きで」が正しい。「好きに」は「思うまま」の意味になり、文の続きに合わない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "好き", "is_correct": true, "explanation": "連体修飾「好きな」の語幹。「な」に続く形。"}, {"text": "好きで", "is_correct": false, "explanation": "「で」の中止形。「な歌手」には続かない。"}, {"text": "好きに", "is_correct": false, "explanation": "連用形。「な歌手」には続かない。"}, {"text": "好きです", "is_correct": false, "explanation": "丁寧形。「な歌手」には続かない。"}], "correct_form": "好き", "base_form": "好きだ", "form_label": "語幹（「な」に続く形）", "sentence_index": 7, "explanations": {"好き": "連体修飾「好きな」の語幹。「な」に続く形。", "好きで": "「で」の中止形。「な歌手」には続かない。", "好きに": "連用形。「な歌手」には続かない。", "好きです": "丁寧形。「な歌手」には続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2bad5028-fea7-4a05-b046-8c14601ff2f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36210, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "と", "options": [{"text": "と", "is_correct": true, "explanation": "「感ずると語った」で、引用の「と」が正しい。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語で、ここでは「語った」の内容を導けない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所で、語った内容は導けない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向で、語る内容は導けない。"}], "correct_answer": "と", "explanations": {"と": "「感ずると語った」で、引用の「と」が正しい。", "を": "「を」は目的語で、ここでは「語った」の内容を導けない。", "で": "「で」は手段や場所で、語った内容は導けない。", "へ": "「へ」は方向で、語る内容は導けない。"}, "error_tags": {"を": "目的語", "で": "手段・場所", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '616496e4-4d0a-47ad-b093-14a19d5697f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
