INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36210, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "「感ずる」は、なにかにふれて、それがどういうものかわかることです。", "primary_collocate": null, "pronunciation": "かんずる", "ipa": "kaɴzɯɾɯ", "syllable_count": 4, "sentences": [{"text": "山の上では、平地よりも寒さを感ずる。", "target_word": "感ずる", "complexity_tier": "T3", "furigana": "山[やま]の上[うえ]では、平地[へいち]よりも寒[さむ]さを感[かん]ずる。", "sentence_source": "generated"}, {"text": "彼は自分の失敗に責任を感ずると語った。", "target_word": "感ずる", "complexity_tier": "T3", "furigana": "彼[かれ]は自分[じぶん]の失敗[しっぱい]に責任[せきにん]を感[かん]ずると語[かた]った。", "sentence_source": "generated"}, {"text": "人は美しい景色を見ると、心の安らぎを感ずる。", "target_word": "感ずる", "complexity_tier": "T3", "furigana": "人[ひと]は美[うつく]しい景色[けしき]を見[み]ると、心[こころ]の安[やす]らぎを感[かん]ずる。", "sentence_source": "generated"}, {"text": "足の痛みを感ずる人は、早めに医者に相談したほうがよい。", "target_word": "感ずる", "complexity_tier": "T3", "furigana": "足[あし]の痛[いた]みを感[かん]ずる人[ひと]は、早[はや]めに医者[いしゃ]に相談[そうだん]したほうがよい。", "sentence_source": "generated"}, {"text": "私はこの町に来るたびに、なつかしさを感ずる。", "target_word": "感ずる", "complexity_tier": "T3", "furigana": "私[わたし]はこの町[まち]に来[く]るたびに、なつかしさを感[かん]ずる。", "sentence_source": "generated"}, {"text": "地震の前に、動物が何かを感ずることがあるという。", "target_word": "感ずる", "complexity_tier": "T3", "furigana": "地震[じしん]の前[まえ]に、動物[どうぶつ]が何[なに]かを感[かん]ずることがあるという。", "sentence_source": "generated"}, {"text": "彼女の話を聞いて、深い悲しみを感ずるようになった。", "target_word": "感ずる", "complexity_tier": "T3", "furigana": "彼女[かのじょ]の話[はなし]を聞[き]いて、深[ふか]い悲[かな]しみを感[かん]ずるようになった。", "sentence_source": "generated"}, {"text": "年をとると、時の流れを早く感ずるものだ。", "target_word": "感ずる", "complexity_tier": "T3", "furigana": "年[とし]をとると、時[とき]の流[なが]れを早[はや]く感[かん]ずるものだ。", "sentence_source": "generated"}, {"text": "強い視線を感ずるので、後ろをふり返った。", "target_word": "感ずる", "complexity_tier": "T3", "furigana": "強[つよ]い視線[しせん]を感[かん]ずるので、後[うし]ろをふり返[かえ]った。", "sentence_source": "generated"}, {"text": "この絵から、作者の孤独を感ずる人も多い。", "target_word": "感ずる", "complexity_tier": "T3", "furigana": "この絵[え]から、作者[さくしゃ]の孤独[こどく]を感[かん]ずる人[ひと]も多[おお]い。", "sentence_source": "generated"}], "morphological_forms": [{"form": "感ずる", "label": "辞書形"}, {"form": "感じない", "label": "否定形"}, {"form": "感じた", "label": "過去形"}, {"form": "感じて", "label": "て形"}, {"form": "感ずれば", "label": "仮定形"}], "register": "formal, written (文語的)", "sense_fingerprint": "感ずる: literary form of 感じる; to take in a feeling, pain or presence through the senses or the heart", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e19b2205-6e13-41a2-a86e-2a42bff0feea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36210, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "感ずる", "is_correct": true, "explanation": "寒さは体で感じるもので、「寒さを感ずる」と合う。"}, {"text": "数える", "is_correct": false, "explanation": "寒さは数えるものではないので合わない。"}, {"text": "見る", "is_correct": false, "explanation": "寒さは見るものではないので合わない。"}, {"text": "書く", "is_correct": false, "explanation": "寒さは書くものではないので合わない。"}], "explanations": {"感ずる": "寒さは体で感じるもので、「寒さを感ずる」と合う。", "数える": "寒さは数えるものではないので合わない。", "見る": "寒さは見るものではないので合わない。", "書く": "寒さは書くものではないので合わない。"}, "sentence_index": 0, "correct_answer": "感ずる"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "その道は一度通っただけで、もうすっかり感ずる。", "explanation": "ここは〈覚える〉の意味。感ずるは感覚で受け取る意味で、道を記憶する意味では使わない。"}, {"text": "会議の終わりに、皆は次の方針を感ずることにした。", "explanation": "ここは〈決める〉の意味。感ずるは感覚で受け取る意味で、方針を決定する意味では使わない。"}, {"text": "彼は急いで答えを感ずると、すぐに提出した。", "explanation": "ここは〈書く〉の意味。感ずるは感覚で受け取る意味で、答えを書き入れる意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '616496e4-4d0a-47ad-b093-14a19d5697f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36210, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "感ずる", "is_correct": true, "explanation": "深い悲しみは心で感じるもので、「悲しみを感ずる」と合う。"}, {"text": "切る", "is_correct": false, "explanation": "悲しみは切るものではないので合わない。"}, {"text": "焼く", "is_correct": false, "explanation": "悲しみは焼くものではないので合わない。"}, {"text": "割る", "is_correct": false, "explanation": "悲しみは割るものではないので合わない。"}], "explanations": {"感ずる": "深い悲しみは心で感じるもので、「悲しみを感ずる」と合う。", "切る": "悲しみは切るものではないので合わない。", "焼く": "悲しみは焼くものではないので合わない。", "割る": "悲しみは割るものではないので合わない。"}, "sentence_index": 6, "correct_answer": "感ずる"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "母は夕飯の材料を感ずるため、市場へ出かけた。", "explanation": "ここは〈買う〉の意味。感ずるは感覚で受け取る意味で、材料を手に入れるとは言わない。"}, {"text": "壊れた車を、彼は感ずるために工場へ運んだ。", "explanation": "ここは〈修理する〉の意味。感ずるは感覚で受け取る意味で、車を直す意味では使わない。"}, {"text": "先生は答案を感ずるために、一晩中机に向かった。", "explanation": "ここは〈採点する〉の意味。感ずるは感覚で受け取る意味で、答案を評価する意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '616496e4-4d0a-47ad-b093-14a19d5697f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36210, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "寒い夜、私は寒さが感ずる。", "corrected_sentence": "寒い夜、私は寒さを感ずる。", "error_description": "「感ずる」の対象は「を」で示す。「寒さが感ずる」は「が」が誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "感ずる", "is_correct": true, "explanation": "文の述語になる辞書形で、「と語った」に続く形として正しい。"}, {"text": "感じ", "is_correct": false, "explanation": "連用形で、「と語った」に続けると文が途中で止まる。"}, {"text": "感ずれ", "is_correct": false, "explanation": "已然形で、「と語った」とは続かず文が成り立たない。"}, {"text": "感ずれば", "is_correct": false, "explanation": "仮定形で、「語った」と続くと条件の文が完結しない。"}], "correct_form": "感ずる", "base_form": "感ずる", "form_label": "辞書形", "sentence_index": 1, "explanations": {"感ずる": "文の述語になる辞書形で、「と語った」に続く形として正しい。", "感じ": "連用形で、「と語った」に続けると文が途中で止まる。", "感ずれ": "已然形で、「と語った」とは続かず文が成り立たない。", "感ずれば": "仮定形で、「語った」と続くと条件の文が完結しない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '616496e4-4d0a-47ad-b093-14a19d5697f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36210, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼女の話を聞いて、深い悲しみをますます感ずてようになった。", "corrected_sentence": "彼女の話を聞いて、深い悲しみをますます感ずるようになった。", "error_description": "「感ずる」は辞書形で続く。「感ずてよう」は活用が誤りで、「感ずるようになった」が正しい。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "感ずる", "is_correct": true, "explanation": "「ものだ」の前に来る連体形で、ここに合う。"}, {"text": "感ぜ", "is_correct": false, "explanation": "未然形で、名詞「もの」の前には続かない。"}, {"text": "感ぜよ", "is_correct": false, "explanation": "命令形で、「ものだ」とは続かない。"}, {"text": "感じられ", "is_correct": false, "explanation": "受身・可能の語幹で、「ものだ」の前には文が合わない。"}], "correct_form": "感ずる", "base_form": "感ずる", "form_label": "連体形", "sentence_index": 7, "explanations": {"感ずる": "「ものだ」の前に来る連体形で、ここに合う。", "感ぜ": "未然形で、名詞「もの」の前には続かない。", "感ぜよ": "命令形で、「ものだ」とは続かない。", "感じられ": "受身・可能の語幹で、「ものだ」の前には文が合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '616496e4-4d0a-47ad-b093-14a19d5697f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
