INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36213, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "property", "definition": "二つ以上のものが同じでないこと。一致しないこと。", "primary_collocate": null, "pronunciation": "ちがう", "ipa": "tɕiɡaɯ", "syllable_count": 3, "sentences": [{"text": "病院での薬の選び方は、昔と今で違います。", "target_word": "違います", "complexity_tier": "T3", "furigana": "病院[びょういん]での薬[くすり]の選[えら]び方[かた]は、昔[むかし]と今[いま]で違[ちが]います。", "sentence_source": "mined"}, {"text": "兄と私は、好きな食べ物が違います。", "target_word": "違います", "complexity_tier": "T2", "furigana": "兄[あに]と私[わたし]は、好[す]きな食[た]べ物[もの]が違[ちが]います。", "sentence_source": "generated"}, {"text": "答えが違っていたので、先生が直してくれました。", "target_word": "違っていた", "complexity_tier": "T3", "furigana": "答[こた]えが違[ちが]っていたので、先生[せんせい]が直[なお]してくれました。", "sentence_source": "generated"}, {"text": "去年と今年では、町の様子がずいぶん違います。", "target_word": "違います", "complexity_tier": "T3", "furigana": "去年[きょねん]と今年[ことし]では、町[まち]の様子[ようす]がずいぶん違[ちが]います。", "sentence_source": "generated"}, {"text": "国によって、あいさつの仕方が違います。", "target_word": "違います", "complexity_tier": "T3", "furigana": "国[くに]によって、あいさつの仕方[しかた]が違[ちが]います。", "sentence_source": "generated"}, {"text": "姉と私は、笑い方がまったく違います。", "target_word": "違います", "complexity_tier": "T3", "furigana": "姉[あね]と私[わたし]は、笑[わら]い方[かた]がまったく違[ちが]います。", "sentence_source": "generated"}, {"text": "二つの写真は、小さなところが三つ違います。", "target_word": "違います", "complexity_tier": "T3", "furigana": "二(ふた)つの写真(しゃしん)は、小(ちい)さなところが三(みっ)つ違(ちが)います。", "sentence_source": "generated"}, {"text": "昨日聞いた話と違うので、もう一度確かめます。", "target_word": "違う", "complexity_tier": "T3", "furigana": "昨日[きのう]聞[き]いた話[はなし]と違[ちが]うので、もう一度[いちど]確[たし]かめます。", "sentence_source": "generated"}, {"text": "私の意見は、あなたの意見とは少し違います。", "target_word": "違います", "complexity_tier": "T3", "furigana": "私[わたし]の意見[いけん]は、あなたの意見[いけん]とは少[すこ]し違[ちが]います。", "sentence_source": "generated"}, {"text": "地図と違う道を歩いたため、迷ってしまいました。", "target_word": "違う", "complexity_tier": "T4", "furigana": "地図[ちず]と違[ちが]う道[みち]を歩[ある]いたため、迷[まよ]ってしまいました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "違う", "label": "辞書形"}, {"form": "違います", "label": "丁寧形"}, {"form": "違わない", "label": "否定形"}, {"form": "違った", "label": "過去形"}, {"form": "違って", "label": "て形"}, {"form": "違い", "label": "名詞形"}], "register": "neutral", "sense_fingerprint": "比べた物どうしが同じでなく、一致しない", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4be6f74-22e6-41bf-9393-a52cbcefdc01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36213, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "違います", "is_correct": true, "explanation": "昔と今で状態が一致しないことを表し、丁寧形で文を結べる。"}, {"text": "遅れます", "is_correct": false, "explanation": "「昔と今で遅れる」では比較の内容にならず、文脈に合わない。"}, {"text": "届きます", "is_correct": false, "explanation": "物が届く動きを表し、昔と今の差の説明にはならない。"}, {"text": "閉まります", "is_correct": false, "explanation": "扉などが閉じる意味で、薬の選び方の比較とは関係がない。"}], "explanations": {"違います": "昔と今で状態が一致しないことを表し、丁寧形で文を結べる。", "遅れます": "「昔と今で遅れる」では比較の内容にならず、文脈に合わない。", "届きます": "物が届く動きを表し、昔と今の差の説明にはならない。", "閉まります": "扉などが閉じる意味で、薬の選び方の比較とは関係がない。"}, "sentence_index": 0, "correct_answer": "違います"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "雨粒が窓ガラスに違った。", "explanation": "ここは〈当たる〉の意味。物がぶつかる意味は当たるで表し、違うは使わない。"}, {"text": "石が屋根に違った。", "explanation": "ここは〈当たる〉の意味。物がぶつかる意味は当たるで表し、違うは使わない。"}, {"text": "ボールが壁に違った。", "explanation": "ここは〈当たる〉の意味。物がぶつかる意味は当たるで表し、違うは使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7e69683-7b61-4b7f-b730-c66856906d1f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36213, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "違います", "is_correct": true, "explanation": "写真どうしの小さなところが一致しないことを表し、丁寧形で文を結べる。"}, {"text": "寝ます", "is_correct": false, "explanation": "写真の部分が寝るとは言えず、文の意味が成り立たない。"}, {"text": "泣きます", "is_correct": false, "explanation": "写真の部分が泣く意味になり、比較の文脈に合わない。"}, {"text": "座ります", "is_correct": false, "explanation": "物が座る動きを表し、写真の違いの説明にはならない。"}], "explanations": {"違います": "写真どうしの小さなところが一致しないことを表し、丁寧形で文を結べる。", "寝ます": "写真の部分が寝るとは言えず、文の意味が成り立たない。", "泣きます": "写真の部分が泣く意味になり、比較の文脈に合わない。", "座ります": "物が座る動きを表し、写真の違いの説明にはならない。"}, "sentence_index": 6, "correct_answer": "違います"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "雷が屋根に違った。", "explanation": "ここは〈当たる〉の意味。物がぶつかる意味は当たるで表し、違うは使わない。"}, {"text": "風が木に違った。", "explanation": "ここは〈当たる〉の意味。物がぶつかる意味は当たるで表し、違うは使わない。"}, {"text": "ボールが窓に違った。", "explanation": "ここは〈当たる〉の意味。物がぶつかる意味は当たるで表し、違うは使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7e69683-7b61-4b7f-b730-c66856906d1f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36213, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "私の家と友だちの家は、夕食の時間を違います。", "corrected_sentence": "私の家と友だちの家は、夕食の時間が違います。", "error_description": "「違う」は「が」で主語を取る。「を」は誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "違います", "is_correct": true, "explanation": "丁寧形で、同じく丁寧体の文「好きな食べ物が違います」を結ぶ。"}, {"text": "違えば", "is_correct": false, "explanation": "仮定形は文を終えられず、「違えば。」では文が成り立たない。"}, {"text": "違わない", "is_correct": false, "explanation": "否定形にすると「同じだ」の意味になり、文の内容が逆転する。"}, {"text": "違った", "is_correct": false, "explanation": "過去形にすると現在の好みの説明ではなくなる。"}], "correct_form": "違います", "base_form": "違う", "form_label": "丁寧形", "sentence_index": 1, "explanations": {"違います": "丁寧形で、同じく丁寧体の文「好きな食べ物が違います」を結ぶ。", "違えば": "仮定形は文を終えられず、「違えば。」では文が成り立たない。", "違わない": "否定形にすると「同じだ」の意味になり、文の内容が逆転する。", "違った": "過去形にすると現在の好みの説明ではなくなる。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7e69683-7b61-4b7f-b730-c66856906d1f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36213, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "山の上と下では、気温が違いです。", "corrected_sentence": "山の上と下では、気温が違います。", "error_description": "「違う」の丁寧形は「違います」。「違いです」は誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "違う", "is_correct": true, "explanation": "辞書形で、理由を表す「ので」へ続けられる。"}, {"text": "違って", "is_correct": false, "explanation": "て形は「ので」へ続けられず、「話と違ってので」は文法的に成り立たない。"}, {"text": "違い", "is_correct": false, "explanation": "名詞形は「ので」の前に置けず、「話と違いので」は文が成り立たない。"}, {"text": "違えば", "is_correct": false, "explanation": "仮定形は「ので」へ続けられず、「話と違えばので」は文法的に誤り。"}], "correct_form": "違う", "base_form": "違う", "form_label": "辞書形", "sentence_index": 7, "explanations": {"違う": "辞書形で、理由を表す「ので」へ続けられる。", "違って": "て形は「ので」へ続けられず、「話と違ってので」は文法的に成り立たない。", "違い": "名詞形は「ので」の前に置けず、「話と違いので」は文が成り立たない。", "違えば": "仮定形は「ので」へ続けられず、「話と違えばので」は文法的に誤り。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7e69683-7b61-4b7f-b730-c66856906d1f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36218, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「バスは大きいので」と、バスについて述べる話題を示す「は」。"}, {"text": "を", "is_correct": false, "explanation": "「を」は動作の対象を示すが、「バスを大きいので」では続かない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を示すが、「バスで大きいので」では意味が通らない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や相手を示すが、「バスと大きいので」では文が続かない。"}], "correct_answer": "は", "explanations": {"は": "「バスは大きいので」と、バスについて述べる話題を示す「は」。", "を": "「を」は動作の対象を示すが、「バスを大きいので」では続かない。", "で": "「で」は手段や場所を示すが、「バスで大きいので」では意味が通らない。", "と": "「と」は並列や相手を示すが、「バスと大きいので」では文が続かない。"}, "error_tags": {"を": "目的語", "で": "手段・場所", "と": "並列・相手"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ff88f66-a23a-43b4-812c-c0d92e99400c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36218, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "が", "is_correct": false, "explanation": "「が」は主語を示すが、「バスが急いで乗った」では乗る相手として成り立たない。"}, {"text": "に", "is_correct": true, "explanation": "乗る先を示す「に」。「朝のバスに急いで乗った」と続く。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や相手を示すが、「バスと急いで乗った」では文が続かない。"}, {"text": "を", "is_correct": false, "explanation": "「バスを」と続けて乗る動作の目的語にすると、乗る先として成り立たない。"}], "correct_answer": "に", "explanations": {"が": "「が」は主語を示すが、「バスが急いで乗った」では乗る相手として成り立たない。", "に": "乗る先を示す「に」。「朝のバスに急いで乗った」と続く。", "と": "「と」は並列や相手を示すが、「バスと急いで乗った」では文が続かない。", "を": "「バスを」と続けて乗る動作の目的語にすると、乗る先として成り立たない。"}, "error_tags": {"が": "主語", "と": "並列・相手", "を": "目的語"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ff88f66-a23a-43b4-812c-c0d92e99400c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36218, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "のるための おおきな くるまだよ。", "primary_collocate": null, "pronunciation": "ばす", "ipa": "basɯ", "syllable_count": 2, "sentences": [{"text": "バスに乗って、おばあちゃんの家へ行きます。", "target_word": "バス", "complexity_tier": "T3", "furigana": "バスに乗[の]って、おばあちゃんの家[いえ]へ行[い]きます。", "sentence_source": "generated"}, {"text": "バスは大きいので、たくさんの人が乗れます。", "target_word": "バス", "complexity_tier": "T3", "furigana": "バスは大[おお]きいので、たくさんの人[ひと]が乗[の]れます。", "sentence_source": "generated"}, {"text": "雨がふっていたので、歩かないでバスで学校へ行った。", "target_word": "バス", "complexity_tier": "T3", "furigana": "雨[あめ]がふっていたので、歩[ある]かないでバスで学校[がっこう]へ行[い]った。", "sentence_source": "generated"}, {"text": "遠足の日は、みんなでバスに乗って山へ行きます。", "target_word": "バス", "complexity_tier": "T3", "furigana": "遠足[えんそく]の日[ひ]は、みんなでバスに乗[の]って山[やま]へ行[い]きます。", "sentence_source": "generated"}, {"text": "バスの中では、立っている人にせきをゆずりましょう。", "target_word": "バス", "complexity_tier": "T3", "furigana": "バスの中[なか]では、立[た]っている人[ひと]にせきをゆずりましょう。", "sentence_source": "generated"}, {"text": "駅の前に、青いバスが止まっています。", "target_word": "バス", "complexity_tier": "T3", "furigana": "駅[えき]の前[まえ]に、青[あお]いバスが止[と]まっています。", "sentence_source": "generated"}, {"text": "運転手さんが、バスのドアを開けてくれた。", "target_word": "バス", "complexity_tier": "T3", "furigana": "運転手[うんてんしゅ]さんが、バスのドアを開[あ]けてくれた。", "sentence_source": "generated"}, {"text": "間に合うように、朝のバスに急いで乗った。", "target_word": "バス", "complexity_tier": "T3", "furigana": "間[ま]に合[あ]うように、朝[あさ]のバスに急[いそ]いで乗[の]った。", "sentence_source": "generated"}, {"text": "バスに遅れたので、次のバスを待った。", "target_word": "バス", "complexity_tier": "T3", "furigana": "バスに遅[おく]れたので、次[つぎ]のバスを待[ま]った。", "sentence_source": "generated"}, {"text": "まどの外を見ながら、バスにゆられて家へ帰った。", "target_word": "バス", "complexity_tier": "T3", "furigana": "まどの外[そと]を見[み]ながら、バスにゆられて家[いえ]へ帰[かえ]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "バス", "label": "基本形"}], "register": "一般・やさしい文", "sense_fingerprint": "人が乗る大きな乗り物のバス（子ども向けの日常語）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa11b1da-6a01-497b-ba17-85963d2f0c23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36218, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "バス", "is_correct": true, "explanation": "人が乗って遠くへ行く乗り物を表す語。「に乗って」に入るのはこの語だけ。"}, {"text": "ケーキ", "is_correct": false, "explanation": "「ケーキに乗って」は意味が通らず、乗り物ではない。"}, {"text": "まくら", "is_correct": false, "explanation": "「まくらに乗って」は不自然で、乗り物ではない。"}, {"text": "ごはん", "is_correct": false, "explanation": "「ごはんに乗って」は意味が通らず、乗り物ではない。"}], "explanations": {"バス": "人が乗って遠くへ行く乗り物を表す語。「に乗って」に入るのはこの語だけ。", "ケーキ": "「ケーキに乗って」は意味が通らず、乗り物ではない。", "まくら": "「まくらに乗って」は不自然で、乗り物ではない。", "ごはん": "「ごはんに乗って」は意味が通らず、乗り物ではない。"}, "sentence_index": 0, "correct_answer": "バス"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ケーブルカーの代わりに、バスが線路を登って山頂へ向かう。", "explanation": "ここは〈ケーブルカー〉（線路を登る乗り物）の意味。バスは線路を走らないので合わない。"}, {"text": "夜は、シャワーのかわりにバスを浴びてから寝る。", "explanation": "ここは〈ふろ〉の意味。湯船は「浴びる」ものではなく「入る」ものなので、この文脈には合わない。"}, {"text": "島へは、毎朝バスで空を渡ります。", "explanation": "ここは〈飛行機〉の意味（空を渡る乗り物）。バスは空を飛べないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ff88f66-a23a-43b4-812c-c0d92e99400c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36218, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "りんご", "is_correct": false, "explanation": "「運転手さんが、りんごのドアを開けた」は意味が通らない。"}, {"text": "ほん", "is_correct": false, "explanation": "「ほんのドア」は意味が通らず、乗り物の話にも合わない。"}, {"text": "バス", "is_correct": true, "explanation": "運転手がドアを開ける乗り物を表す語。空欄に入るのはこの語だけ。"}, {"text": "えんぴつ", "is_correct": false, "explanation": "「えんぴつのドア」は意味が通らず、運転手の文脈に合わない。"}], "explanations": {"りんご": "「運転手さんが、りんごのドアを開けた」は意味が通らない。", "ほん": "「ほんのドア」は意味が通らず、乗り物の話にも合わない。", "バス": "運転手がドアを開ける乗り物を表す語。空欄に入るのはこの語だけ。", "えんぴつ": "「えんぴつのドア」は意味が通らず、運転手の文脈に合わない。"}, "sentence_index": 6, "correct_answer": "バス"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ライブでは、ドラムのかわりにバスを叩いた。", "explanation": "ここは〈バスドラム〉（大太鼓）の意味。乗り物のバスは楽器ではないので合わない。"}, {"text": "湖の上で、ボートのかわりにバスをこいだ。", "explanation": "ここは〈ボート〉（手でこぐ船）の意味。バスは水の上をこげないので合わない。"}, {"text": "バスは、ワイヤーで引かれて急な山を登る。", "explanation": "ここは〈ロープウェイ〉の意味（ワイヤーで引かれる乗り物）。バスは自分で走るので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ff88f66-a23a-43b4-812c-c0d92e99400c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36218, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "バスが乗って、山の上まで行きます。", "corrected_sentence": "バスに乗って、山の上まで行きます。", "error_description": "「乗る」の対象には「に」を使う（バスに乗る）。「が」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ff88f66-a23a-43b4-812c-c0d92e99400c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36218, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "雨の日は、ふだんよりバスを聞いて通学する。", "corrected_sentence": "雨の日は、ふだんよりバスを使って通学する。", "error_description": "「バスを使う」（利用する）が正しい。「聞く」はバスには合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ff88f66-a23a-43b4-812c-c0d92e99400c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36219, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「バスは時刻表どおりに」と、バスについて述べる話題を示す「は」。"}, {"text": "を", "is_correct": false, "explanation": "「バスを時刻表どおりに」では、動作の対象として到着と続かない。"}, {"text": "へ", "is_correct": false, "explanation": "「バスへ」は乗り物を到着先のように扱うことになり、「停留所に到着した」と続けると不自然。"}, {"text": "と", "is_correct": false, "explanation": "「バスと時刻表どおりに」は並列の意味になり、到着の主語として成り立たない。"}], "correct_answer": "は", "explanations": {"は": "「バスは時刻表どおりに」と、バスについて述べる話題を示す「は」。", "を": "「バスを時刻表どおりに」では、動作の対象として到着と続かない。", "へ": "「バスへ」は乗り物を到着先のように扱うことになり、「停留所に到着した」と続けると不自然。", "と": "「バスと時刻表どおりに」は並列の意味になり、到着の主語として成り立たない。"}, "error_tags": {"を": "目的語", "へ": "方向", "と": "並列・相手"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ff88f66-a23a-43b4-812c-c0d92e99400c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36219, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "に", "is_correct": false, "explanation": "「に」は場所や方向を示すが、「バスに走っている」では文が続かない。"}, {"text": "が", "is_correct": true, "explanation": "走っている主語を示す「が」。「バスが走っている」と続く。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を示すが、「バスから走っている」では意味が通らない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すが、「バスへ走っている」では主語として成り立たない。"}], "correct_answer": "が", "explanations": {"に": "「に」は場所や方向を示すが、「バスに走っている」では文が続かない。", "が": "走っている主語を示す「が」。「バスが走っている」と続く。", "から": "「から」は起点を示すが、「バスから走っている」では意味が通らない。", "へ": "「へ」は方向を示すが、「バスへ走っている」では主語として成り立たない。"}, "error_tags": {"に": "場所・方向", "から": "起点", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ff88f66-a23a-43b4-812c-c0d92e99400c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36219, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "たくさんの人がのれる、大きな車です。きまった道を走ります。", "primary_collocate": null, "pronunciation": "ばす", "ipa": "basɯ", "syllable_count": 2, "sentences": [{"text": "このバスは、決まった道を走って駅へ向かいます。", "target_word": "バス", "complexity_tier": "T3", "furigana": "このバスは、決[き]まった道[みち]を走[はし]って駅[えき]へ向[む]かいます。", "sentence_source": "generated"}, {"text": "バスは時刻表どおりに、停留所に到着した。", "target_word": "バス", "complexity_tier": "T3", "furigana": "バスは時刻表[じこくひょう]どおりに、停留所[ていりゅうじょ]に到着[とうちゃく]した。", "sentence_source": "generated"}, {"text": "通勤のため、毎朝七時のバスに乗っています。", "target_word": "バス", "complexity_tier": "T3", "furigana": "通勤[つうきん]のため、毎朝[まいあさ]七時[しちじ]のバスに乗[の]っています。", "sentence_source": "generated"}, {"text": "病院までは、バスで二十分ほどかかります。", "target_word": "バス", "complexity_tier": "T3", "furigana": "病院[びょういん]までは、バスで二十[にじゅう]分[ぷん]ほどかかります。", "sentence_source": "generated"}, {"text": "バスの料金は、降りるときに運転手さんに払う。", "target_word": "バス", "complexity_tier": "T3", "furigana": "バスの料金[りょうきん]は、降[お]りるときに運転手[うんてんしゅ]さんに払[はら]う。", "sentence_source": "generated"}, {"text": "雪のせいで、バスが三十分も遅れた。", "target_word": "バス", "complexity_tier": "T3", "furigana": "雪[ゆき]のせいで、バスが三十[さんじゅっ]分[ぷん]も遅[おく]れた。", "sentence_source": "generated"}, {"text": "車がないので、買い物にはバスを使っている。", "target_word": "バス", "complexity_tier": "T3", "furigana": "車[くるま]がないので、買[か]い物[もの]にはバスを使[つか]っている。", "sentence_source": "generated"}, {"text": "小さな町でも、駅と学校をつなぐバスが走っている。", "target_word": "バス", "complexity_tier": "T3", "furigana": "小[ちい]さな町[まち]でも、駅[えき]と学校[がっこう]をつなぐバスが走[はし]っている。", "sentence_source": "generated"}, {"text": "バスを乗りかえて、やっと目的地に着いた。", "target_word": "バス", "complexity_tier": "T3", "furigana": "バスを乗[の]りかえて、やっと目的地[もくてきち]に着[つ]いた。", "sentence_source": "generated"}, {"text": "最終のバスに間に合わず、タクシーで帰った。", "target_word": "バス", "complexity_tier": "T3", "furigana": "最終[さいしゅう]のバスに間[ま]に合[あ]わず、タクシーで帰[かえ]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "バス", "label": "基本形"}], "register": "一般", "sense_fingerprint": "決まった道（路線）を走る、大勢が乗れる公共の乗り物のバス", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 8 above tier T1: contains vocabulary far above tier T1: 乗りかえ (Zipf 2.08)']::text[], 'fa11b1da-6a01-497b-ba17-85963d2f0c23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36219, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "りんご", "is_correct": false, "explanation": "「このりんごは、決まった道を走って駅へ向かう」は意味が通らない。"}, {"text": "ほん", "is_correct": false, "explanation": "「この本は、決まった道を走る」は意味が通らず、乗り物の話に合わない。"}, {"text": "バス", "is_correct": true, "explanation": "決まった道を走り、人が乗る公共の乗り物を表す語。空欄に入るのはこの語だけ。"}, {"text": "ごはん", "is_correct": false, "explanation": "「このごはんは、決まった道を走る」は意味が通らない。"}], "explanations": {"りんご": "「このりんごは、決まった道を走って駅へ向かう」は意味が通らない。", "ほん": "「この本は、決まった道を走る」は意味が通らず、乗り物の話に合わない。", "バス": "決まった道を走り、人が乗る公共の乗り物を表す語。空欄に入るのはこの語だけ。", "ごはん": "「このごはんは、決まった道を走る」は意味が通らない。"}, "sentence_index": 0, "correct_answer": "バス"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "バスは、線路の上を走って駅から駅へ進む。", "explanation": "ここは〈電車〉（線路を走る乗り物）の意味。路線バスは道路を走るので、線路の上を進むのは合わない。"}, {"text": "バスは、海の上を決まった航路で走る大きな船だ。", "explanation": "ここは〈フェリー〉（船）の意味。バスは海の上を走れないので合わない。"}, {"text": "バスは、料金を前払いして地下のトンネルを走る。", "explanation": "ここは〈地下鉄〉の意味。バスは地下を走らないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ff88f66-a23a-43b4-812c-c0d92e99400c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36219, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ケーキ", "is_correct": false, "explanation": "「買い物にはケーキを使っている」は意味が通らない。"}, {"text": "まくら", "is_correct": false, "explanation": "「買い物にはまくらを使っている」は意味が通らない。"}, {"text": "バス", "is_correct": true, "explanation": "車がない人が買い物に使う移動手段を表す語。空欄に入るのはこの語だけ。"}, {"text": "えんぴつ", "is_correct": false, "explanation": "「買い物にはえんぴつを使っている」は移動手段の話に合わない。"}], "explanations": {"ケーキ": "「買い物にはケーキを使っている」は意味が通らない。", "まくら": "「買い物にはまくらを使っている」は意味が通らない。", "バス": "車がない人が買い物に使う移動手段を表す語。空欄に入るのはこの語だけ。", "えんぴつ": "「買い物にはえんぴつを使っている」は移動手段の話に合わない。"}, "sentence_index": 6, "correct_answer": "バス"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ぬるめのバスで、ゆっくり泳いだ。", "explanation": "ここは〈浴槽〉（ふろの湯船）の意味。湯船の中では泳げないので合わない。"}, {"text": "バスは、翼を広げて遠くの町へ飛ぶ。", "explanation": "ここは〈飛行機〉の意味。バスは翼がなく飛べないので合わない。"}, {"text": "バスは、ワイヤーで引かれて急な山を登る。", "explanation": "ここは〈ロープウェイ〉の意味（ワイヤーで引かれる乗り物）。バスは自分で走るので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ff88f66-a23a-43b4-812c-c0d92e99400c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36219, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "このバスを、駅まで行きます。", "corrected_sentence": "このバスで、駅まで行きます。", "error_description": "「バスで行く」（手段）が正しい。「バスを行く」は誤りで、「で」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ff88f66-a23a-43b4-812c-c0d92e99400c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36219, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "次のバスを、停留所でずっと食べる。", "corrected_sentence": "次のバスを、停留所でずっと待つ。", "error_description": "「バスを待つ」が正しい。「食べる」はバスには合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ff88f66-a23a-43b4-812c-c0d92e99400c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36221, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「勉強で忙しい」は原因を示す「で」で、文の意味に合います。"}, {"text": "に", "is_correct": false, "explanation": "「勉強に忙しい」とは言わないので、「に」は合いません。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示すため、「勉強を忙しい」は成り立ちません。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や相手を示すので、「勉強と忙しい」は文に合いません。"}], "correct_answer": "で", "explanations": {"で": "「勉強で忙しい」は原因を示す「で」で、文の意味に合います。", "に": "「勉強に忙しい」とは言わないので、「に」は合いません。", "を": "「を」は目的語を示すため、「勉強を忙しい」は成り立ちません。", "と": "「と」は並列や相手を示すので、「勉強と忙しい」は文に合いません。"}, "error_tags": {"に": "相手・帰着点", "を": "目的語", "と": "並列・相手"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '405b9007-2f6d-4980-b97d-529b26d9b94a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
