INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36221, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "新しいことを学んだり、練習したりすること。", "primary_collocate": null, "pronunciation": "べんきょう", "ipa": "beɴkʲoː", "syllable_count": 4, "sentences": [{"text": "私は毎晩、日本語の勉強をしています。", "target_word": "勉強", "complexity_tier": "T3", "furigana": "私[わたし]は毎晩[まいばん]、日本語[にほんご]の勉強[べんきょう]をしています。", "sentence_source": "generated"}, {"text": "試験が近いので、今週は勉強で忙しいです。", "target_word": "勉強", "complexity_tier": "T3", "furigana": "試験[しけん]が近[ちか]いので、今週[こんしゅう]は勉強[べんきょう]で忙[いそが]しいです。", "sentence_source": "generated"}, {"text": "図書館で友達と勉強しました。", "target_word": "勉強", "complexity_tier": "T3", "furigana": "図書館[としょかん]で友達[ともだち]と勉強[べんきょう]しました。", "sentence_source": "generated"}, {"text": "勉強のあとで、少し休みましょう。", "target_word": "勉強", "complexity_tier": "T3", "furigana": "勉強[べんきょう]のあとで、少[すこ]し休[やす]みましょう。", "sentence_source": "generated"}, {"text": "弟は勉強が嫌いで、ゲームばかりしています。", "target_word": "勉強", "complexity_tier": "T3", "furigana": "弟[おとうと]は勉強[べんきょう]が嫌[きら]いで、ゲームばかりしています。", "sentence_source": "generated"}, {"text": "外国の人と話すのは、とてもいい勉強になります。", "target_word": "勉強", "complexity_tier": "T3", "furigana": "外国[がいこく]の人[ひと]と話[はな]すのは、とてもいい勉強[べんきょう]になります。", "sentence_source": "generated"}, {"text": "朝は静かなので、勉強がしやすいです。", "target_word": "勉強", "complexity_tier": "T3", "furigana": "朝[あさ]は静[しず]かなので、勉強[べんきょう]がしやすいです。", "sentence_source": "generated"}, {"text": "毎日勉強したので、テストでいい点を取れました。", "target_word": "勉強", "complexity_tier": "T3", "furigana": "毎日[まいにち]勉強[べんきょう]したので、テストでいい点[てん]を取[と]れました。", "sentence_source": "generated"}, {"text": "姉は外国で医学を勉強しています。", "target_word": "勉強", "complexity_tier": "T3", "furigana": "姉[あね]は外国[がいこく]で医学[いがく]を勉強[べんきょう]しています。", "sentence_source": "generated"}, {"text": "眠いときは、勉強しても頭に入りません。", "target_word": "勉強", "complexity_tier": "T3", "furigana": "眠[ねむ]いときは、勉強[べんきょう]しても頭[あたま]に入[はい]りません。", "sentence_source": "generated"}], "morphological_forms": [{"form": "勉強", "label": "基本形"}, {"form": "勉強する", "label": "サ変動詞"}, {"form": "勉強した", "label": "過去形"}], "register": "中立（丁寧体）", "sense_fingerprint": "知識や技能を身につけるために学ぶこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95344bd9-fdcd-410b-94e3-d1adfb174457') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36221, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "勉強", "is_correct": true, "explanation": "「日本語の勉強をしています」は学ぶ意味で自然に成り立ち、文に合います。"}, {"text": "掃除", "is_correct": false, "explanation": "掃除は部屋などをきれいにすることなので、「日本語の掃除」とは言えません。"}, {"text": "料理", "is_correct": false, "explanation": "料理は食べ物を作ることなので、「日本語の料理」は文に合いません。"}, {"text": "運動", "is_correct": false, "explanation": "運動は体を動かすことなので、「日本語の運動」は意味が通りません。"}], "explanations": {"勉強": "「日本語の勉強をしています」は学ぶ意味で自然に成り立ち、文に合います。", "掃除": "掃除は部屋などをきれいにすることなので、「日本語の掃除」とは言えません。", "料理": "料理は食べ物を作ることなので、「日本語の料理」は文に合いません。", "運動": "運動は体を動かすことなので、「日本語の運動」は意味が通りません。"}, "sentence_index": 0, "correct_answer": "勉強"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "お昼に、サンドイッチを勉強しました。", "explanation": "ここは〈食べる〉の意味です。勉強は学ぶことなので、食べ物を口にする意味では使いません。"}, {"text": "週末は、友達と遊園地で勉強しました。", "explanation": "ここは〈遊び〉の意味です。勉強は学ぶことなので、遊ぶ場面には使いません。"}, {"text": "今日は、ごちゃごちゃの引き出しを勉強しました。", "explanation": "ここは〈整理〉の意味です。勉強は学ぶことなので、物を片付ける意味では使いません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '405b9007-2f6d-4980-b97d-529b26d9b94a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36221, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "勉強", "is_correct": true, "explanation": "「勉強がしやすい」は学ぶことが進めやすいという意味で、文に合います。"}, {"text": "試験", "is_correct": false, "explanation": "試験は受けるものなので、「しやすい」と結びつきません。"}, {"text": "面接", "is_correct": false, "explanation": "面接は受けるものなので、「面接がしやすい」は文に合いません。"}, {"text": "課題", "is_correct": false, "explanation": "課題は取り組むものなので、「課題がしやすい」は文に合いません。"}], "explanations": {"勉強": "「勉強がしやすい」は学ぶことが進めやすいという意味で、文に合います。", "試験": "試験は受けるものなので、「しやすい」と結びつきません。", "面接": "面接は受けるものなので、「面接がしやすい」は文に合いません。", "課題": "課題は取り組むものなので、「課題がしやすい」は文に合いません。"}, "sentence_index": 6, "correct_answer": "勉強"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "毎朝の勉強で体が軽くなりました。", "explanation": "ここは〈運動〉の意味です。勉強は学ぶことなので、体を動かす意味では使いません。"}, {"text": "夕食は、家族のために勉強をしました。", "explanation": "ここは〈料理〉の意味です。勉強は学ぶことなので、食事を作る意味では使いません。"}, {"text": "雨の日は、車を勉強して駅まで行きました。", "explanation": "ここは〈運転〉の意味です。勉強は学ぶことなので、車を動かす意味では使いません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '405b9007-2f6d-4980-b97d-529b26d9b94a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36221, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "来月から、日本語の勉強に始めます。", "corrected_sentence": "来月から、日本語の勉強を始めます。", "error_description": "「始める」は目的語に「を」を取るので、「勉強に」は「勉強を」にする必要があります。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '405b9007-2f6d-4980-b97d-529b26d9b94a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36221, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "大学で勉強を取ります。", "corrected_sentence": "大学で勉強をします。", "error_description": "「勉強」は「する」と組んで使うので、「取ります」は「します」にする必要があります。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '405b9007-2f6d-4980-b97d-529b26d9b94a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36222, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「いっぱいだ」の主語を示す「が」。「スケジュールがいっぱい」の形になる。"}, {"text": "を", "is_correct": false, "explanation": "「を」は他動詞の目的語に付く。「いっぱいだ」は状態を表すので合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表す。状態を表す「いっぱい」には続かない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を表す。「スケジュールからいっぱい」は意味が通らない。"}], "correct_answer": "が", "explanations": {"が": "「いっぱいだ」の主語を示す「が」。「スケジュールがいっぱい」の形になる。", "を": "「を」は他動詞の目的語に付く。「いっぱいだ」は状態を表すので合わない。", "へ": "「へ」は方向を表す。状態を表す「いっぱい」には続かない。", "から": "「から」は起点を表す。「スケジュールからいっぱい」は意味が通らない。"}, "error_tags": {"を": "object_marker", "へ": "direction", "から": "source"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7c8b42d-f3e7-4b88-90bd-76c3f6398d22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36222, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7c8b42d-f3e7-4b88-90bd-76c3f6398d22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36222, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "けいかく。たとえば、「きょうのよてい」のことです。", "primary_collocate": null, "pronunciation": "すけじゅーる", "ipa": "sɯkedʑɯːɾɯ", "syllable_count": 5, "sentences": [{"text": "今日のスケジュールを教えてください。", "target_word": "スケジュール", "complexity_tier": "T3", "furigana": "今日[きょう]のスケジュールを教[おし]えてください。", "sentence_source": "generated"}, {"text": "来週はスケジュールがいっぱいで、遊ぶ時間がありません。", "target_word": "スケジュール", "complexity_tier": "T3", "furigana": "来週[らいしゅう]はスケジュールがいっぱいで、遊[あそ]ぶ時間[じかん]がありません。", "sentence_source": "generated"}, {"text": "スケジュールを変えたので、会う時間も変わります。", "target_word": "スケジュール", "complexity_tier": "T3", "furigana": "スケジュールを変[か]えたので、会[あ]う時間[じかん]も変[か]わります。", "sentence_source": "generated"}, {"text": "母は毎朝、手帳でその日のスケジュールを確かめる。", "target_word": "スケジュール", "complexity_tier": "T3", "furigana": "母[はは]は毎朝[まいあさ]、手帳[てちょう]でその日[ひ]のスケジュールを確[たし]かめる。", "sentence_source": "generated"}, {"text": "試験の前は、勉強のスケジュールを立てたほうがいい。", "target_word": "スケジュール", "complexity_tier": "T3", "furigana": "試験[しけん]の前[まえ]は、勉強[べんきょう]のスケジュールを立[た]てたほうがいい。", "sentence_source": "generated"}, {"text": "スケジュールが合わなかったので、今回の食事会は行けません。", "target_word": "スケジュール", "complexity_tier": "T3", "furigana": "スケジュールが合[あ]わなかったので、今回[こんかい]の食事会[しょくじかい]は行[い]けません。", "sentence_source": "generated"}, {"text": "旅行のスケジュールは、先生が黒板に書いてくれた。", "target_word": "スケジュール", "complexity_tier": "T3", "furigana": "旅行[りょこう]のスケジュールは、先生[せんせい]が黒板[こくばん]に書[か]いてくれた。", "sentence_source": "generated"}, {"text": "彼はスケジュールどおりに駅に着いた。", "target_word": "スケジュール", "complexity_tier": "T3", "furigana": "彼[かれ]はスケジュールどおりに駅[えき]に着[つ]いた。", "sentence_source": "generated"}, {"text": "このスケジュールでは、宿題を終えるのは無理だ。", "target_word": "スケジュール", "complexity_tier": "T3", "furigana": "このスケジュールでは、宿題[しゅくだい]を終[お]えるのは無理[むり]だ。", "sentence_source": "generated"}, {"text": "明日のスケジュールを確認してから、返事をします。", "target_word": "スケジュール", "complexity_tier": "T3", "furigana": "明日[あした]のスケジュールを確認[かくにん]してから、返事[へんじ]をします。", "sentence_source": "generated"}], "morphological_forms": [{"form": "スケジュール", "label": "基本形"}, {"form": "スケジュールを", "label": "を格"}, {"form": "スケジュールが", "label": "が格"}], "register": "neutral", "sense_fingerprint": "その日や期間にすることを決めた予定", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e60ae888-bad4-41d8-9618-5085bc76d610') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36222, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "スケジュール", "is_correct": true, "explanation": "「今日の予定」を尋ねる文なので、予定を表すスケジュールが入る。"}, {"text": "玄関", "is_correct": false, "explanation": "玄関は家の出入口で、教えてもらう内容にならない。"}, {"text": "冷蔵庫", "is_correct": false, "explanation": "冷蔵庫は家電で、今日の予定を尋ねる文には入らない。"}, {"text": "座布団", "is_correct": false, "explanation": "座布団は敷物で、「教えてください」の対象にならない。"}], "explanations": {"スケジュール": "「今日の予定」を尋ねる文なので、予定を表すスケジュールが入る。", "玄関": "玄関は家の出入口で、教えてもらう内容にならない。", "冷蔵庫": "冷蔵庫は家電で、今日の予定を尋ねる文には入らない。", "座布団": "座布団は敷物で、「教えてください」の対象にならない。"}, "sentence_index": 0, "correct_answer": "スケジュール"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "テレビの天気コーナーで、明日のスケジュールは晴れだと言っていた。", "explanation": "ここは〈天気予報〉の意味。スケジュールは自分の予定を指すので、天気の見通しには使わない。"}, {"text": "熱を測ったら、スケジュールは三十八度あった。", "explanation": "ここは〈体温〉の意味。スケジュールは予定のことで、体の温度は表せない。"}, {"text": "毎月、スケジュールに支出をまとめて、お金の使い道を確かめている。", "explanation": "ここは〈家計簿〉の意味。スケジュールは時間の予定で、お金の支出の記録には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7c8b42d-f3e7-4b88-90bd-76c3f6398d22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36222, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "スケジュール", "is_correct": true, "explanation": "旅行の予定を先生が黒板に書いてくれた、という意味になる。"}, {"text": "体育館", "is_correct": false, "explanation": "体育館は施設で、黒板に書いてもらう内容にはならない。"}, {"text": "教室", "is_correct": false, "explanation": "教室は場所で、旅行の対象として意味が通らない。"}, {"text": "給食", "is_correct": false, "explanation": "給食は食事で、黒板に書いてもらう内容として不自然。"}], "explanations": {"スケジュール": "旅行の予定を先生が黒板に書いてくれた、という意味になる。", "体育館": "体育館は施設で、黒板に書いてもらう内容にはならない。", "教室": "教室は場所で、旅行の対象として意味が通らない。", "給食": "給食は食事で、黒板に書いてもらう内容として不自然。"}, "sentence_index": 6, "correct_answer": "スケジュール"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "分からない単語は、スケジュールで意味を調べる。", "explanation": "ここは〈辞書〉の意味。スケジュールは時間の予定で、言葉の意味を調べる道具ではない。"}, {"text": "窓口の前で並んで、スケジュールが来るのを待つ。", "explanation": "ここは〈順番〉の意味。スケジュールは予定の一覧で、並んだ列で自分の番が来ることは指さない。"}, {"text": "このスープは、スケジュールが濃くて飲みにくい。", "explanation": "ここは〈味〉の意味。スケジュールは予定のことで、味の濃さは表さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7c8b42d-f3e7-4b88-90bd-76c3f6398d22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36222, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "明日のスケジュールが確認してから、出かけます。", "corrected_sentence": "明日のスケジュールを確認してから、出かけます。", "error_description": "「確認する」は他動詞なので、目的語は「を」で示す。「が」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7c8b42d-f3e7-4b88-90bd-76c3f6398d22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36222, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "会議のスケジュールが変更したので、資料も作り直す。", "corrected_sentence": "会議のスケジュールを変更したので、資料も作り直す。", "error_description": "「変更する」は他動詞で、目的語は「を」で示す。「が」では「変更した」と続かない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7c8b42d-f3e7-4b88-90bd-76c3f6398d22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36223, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「決まる」の主語を示す「が」。「スケジュールが決まる」の形になる。"}, {"text": "を", "is_correct": false, "explanation": "「を」は他動詞の目的語に付く。「決まる」は自動詞なので合わない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞をつなぐ。動詞「決まる」の主語を示すことはできない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を表す。「決まる」の主語にはならない。"}], "correct_answer": "が", "explanations": {"が": "「決まる」の主語を示す「が」。「スケジュールが決まる」の形になる。", "を": "「を」は他動詞の目的語に付く。「決まる」は自動詞なので合わない。", "の": "「の」は名詞をつなぐ。動詞「決まる」の主語を示すことはできない。", "より": "「より」は比較を表す。「決まる」の主語にはならない。"}, "error_tags": {"を": "object_marker", "の": "genitive", "より": "comparison"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7c8b42d-f3e7-4b88-90bd-76c3f6398d22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36223, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「組み直す」は他動詞で、目的語「スケジュール」に「を」を付ける。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示す。組み直す動作の目的語には使わない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を表す。組み直す対象を示す「を」が必要で、「で」では目的語にならない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞をつなぐ。目的語を示すことはできない。"}], "correct_answer": "を", "explanations": {"を": "「組み直す」は他動詞で、目的語「スケジュール」に「を」を付ける。", "が": "「が」は主語を示す。組み直す動作の目的語には使わない。", "で": "「で」は手段や場所を表す。組み直す対象を示す「を」が必要で、「で」では目的語にならない。", "の": "「の」は名詞をつなぐ。目的語を示すことはできない。"}, "error_tags": {"が": "subject_marker", "で": "means", "の": "genitive"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7c8b42d-f3e7-4b88-90bd-76c3f6398d22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36223, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "あらかじめ決めた予定や計画。人との約束や仕事の順序を時間に沿ってまとめたもの。", "primary_collocate": null, "pronunciation": "すけじゅーる", "ipa": "sɯkedʑɯːɾɯ", "syllable_count": 5, "sentences": [{"text": "部長のスケジュールを確認して、会議の時間を決めます。", "target_word": "スケジュール", "complexity_tier": "T3", "furigana": "部長[ぶちょう]のスケジュールを確認[かくにん]して、会議[かいぎ]の時間[じかん]を決[き]めます。", "sentence_source": "generated"}, {"text": "出張のスケジュールが決まったら、ホテルを予約してください。", "target_word": "スケジュール", "complexity_tier": "T3", "furigana": "出張[しゅっちょう]のスケジュールが決[き]まったら、ホテルを予約[よやく]してください。", "sentence_source": "generated"}, {"text": "工事のスケジュールが遅れているため、完成は来月になる。", "target_word": "スケジュール", "complexity_tier": "T4", "furigana": "工事[こうじ]のスケジュールが遅[おく]れているため、完成[かんせい]は来月[らいげつ]になる。", "sentence_source": "generated"}, {"text": "今週は打ち合わせが続き、スケジュールに余裕がない。", "target_word": "スケジュール", "complexity_tier": "T3", "furigana": "今週[こんしゅう]は打[う]ち合[あ]わせが続[つづ]き、スケジュールに余裕[よゆう]がない。", "sentence_source": "generated"}, {"text": "スケジュールを共有しておけば、約束が重ならずにすむ。", "target_word": "スケジュール", "complexity_tier": "T4", "furigana": "スケジュールを共有[きょうゆう]しておけば、約束[やくそく]が重[かさ]ならずにすむ。", "sentence_source": "generated"}, {"text": "社長は海外出張のため、来月のスケジュールがほぼ埋まっている。", "target_word": "スケジュール", "complexity_tier": "T4", "furigana": "社長[しゃちょう]は海外出張[かいがいしゅっちょう]のため、来月[らいげつ]のスケジュールがほぼ埋[う]まっている。", "sentence_source": "generated"}, {"text": "彼女は仕事のスケジュールを細かく管理している。", "target_word": "スケジュール", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は仕事[しごと]のスケジュールを細[こま]かく管理[かんり]している。", "sentence_source": "generated"}, {"text": "急な会議が入って、午後のスケジュールを組み直した。", "target_word": "スケジュール", "complexity_tier": "T3", "furigana": "急[きゅう]な会議[かいぎ]が入[はい]って、午後[ごご]のスケジュールを組[く]み直[なお]した。", "sentence_source": "generated"}, {"text": "発表会のスケジュールは、来週の月曜日に配られます。", "target_word": "スケジュール", "complexity_tier": "T3", "furigana": "発表会[はっぴょうかい]のスケジュールは、来週[らいしゅう]の月曜日[げつようび]に配[くば]られます。", "sentence_source": "generated"}, {"text": "忙しくてスケジュールが合わず、お会いできませんでした。", "target_word": "スケジュール", "complexity_tier": "T3", "furigana": "忙[いそが]しくてスケジュールが合[あ]わず、お会[あ]いできませんでした。", "sentence_source": "generated"}], "morphological_forms": [{"form": "スケジュール", "label": "基本形"}, {"form": "スケジュールを", "label": "を格"}, {"form": "スケジュールに", "label": "に格"}], "register": "neutral", "sense_fingerprint": "仕事や約束を時間順にまとめた計画", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e60ae888-bad4-41d8-9618-5085bc76d610') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36223, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "スケジュール", "is_correct": true, "explanation": "部長の予定を確認して会議の時間を決める、という意味になる。"}, {"text": "食器棚", "is_correct": false, "explanation": "食器棚は家具で、確認して会議の時間を決める対象ではない。"}, {"text": "掃除機", "is_correct": false, "explanation": "掃除機は家電で、会議の時間を決める文に関係しない。"}, {"text": "湯呑み", "is_correct": false, "explanation": "湯呑みは食器で、会議の時間を決める文に合わない。"}], "explanations": {"スケジュール": "部長の予定を確認して会議の時間を決める、という意味になる。", "食器棚": "食器棚は家具で、確認して会議の時間を決める対象ではない。", "掃除機": "掃除機は家電で、会議の時間を決める文に関係しない。", "湯呑み": "湯呑みは食器で、会議の時間を決める文に合わない。"}, "sentence_index": 0, "correct_answer": "スケジュール"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "市場で野菜のスケジュールを確かめて、新鮮なものを選んだ。", "explanation": "ここは〈鮮度〉の意味。スケジュールは予定のことで、野菜の新しさは表せない。"}, {"text": "初めての町では、スケジュールを見れば道に迷わない。", "explanation": "ここは〈地図〉の意味。スケジュールは時間の予定で、道順や位置を示す道具にはならない。"}, {"text": "明日のスケジュールは雨だと、ニュースで言っていた。", "explanation": "ここは〈天気予報〉の意味。スケジュールは自分の予定で、天気の見通しを表さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7c8b42d-f3e7-4b88-90bd-76c3f6398d22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36223, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "スケジュール", "is_correct": true, "explanation": "仕事の予定を細かく管理している、という意味になる。"}, {"text": "天井", "is_correct": false, "explanation": "天井は建物の一部で、管理の対象として意味が通らない。"}, {"text": "押し入れ", "is_correct": false, "explanation": "押し入れは収納で、仕事の管理対象にはならない。"}, {"text": "植木鉢", "is_correct": false, "explanation": "植木鉢は容器で、仕事の管理対象にならない。"}], "explanations": {"スケジュール": "仕事の予定を細かく管理している、という意味になる。", "天井": "天井は建物の一部で、管理の対象として意味が通らない。", "押し入れ": "押し入れは収納で、仕事の管理対象にはならない。", "植木鉢": "植木鉢は容器で、仕事の管理対象にならない。"}, "sentence_index": 6, "correct_answer": "スケジュール"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "分からない漢字は、スケジュールで読み方を調べる。", "explanation": "ここは〈辞書〉の意味。スケジュールは時間の予定で、漢字の読み方を調べる道具ではない。"}, {"text": "スケジュールが合わず、ドアが開かなかった。", "explanation": "ここは〈鍵〉の意味。鍵は穴に合ってはじめて開くが、スケジュールは物ではなく開閉に使えない。"}, {"text": "サイズが足に合わず、店でスケジュールを買い直した。", "explanation": "ここは〈靴〉の意味。スケジュールは予定で、足に合わせて買い直す物にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7c8b42d-f3e7-4b88-90bd-76c3f6398d22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36223, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "出張のスケジュールが決めたら、航空券も取ってください。", "corrected_sentence": "出張のスケジュールが決まったら、航空券も取ってください。", "error_description": "「決まる」は自動詞で「スケジュールが決まる」と使う。「決める」は他動詞なので、「が」の主語とは合わない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7c8b42d-f3e7-4b88-90bd-76c3f6398d22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36223, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼はスケジュールに細かく管理するので、遅れがない。", "corrected_sentence": "彼はスケジュールを細かく管理するので、遅れがない。", "error_description": "「管理する」は他動詞で、目的語は「を」で示す。「に」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7c8b42d-f3e7-4b88-90bd-76c3f6398d22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
