INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36228, 3, 'prompt1_core', '{"pos": "副詞", "semantic_class": "property", "definition": "動きや話し方が、はやくないこと。", "primary_collocate": null, "pronunciation": "ゆっくり", "ipa": "jɯk̚kɯɾi", "syllable_count": 4, "sentences": [{"text": "祖父は杖をついて、庭をゆっくり歩いている。", "target_word": "ゆっくり", "complexity_tier": "T3", "furigana": "祖父[そふ]は杖[つえ]をついて、庭[にわ]をゆっくり歩[ある]いている。", "sentence_source": "generated"}, {"text": "先生はゆっくり話してくれたので、よく聞き取れた。", "target_word": "ゆっくり", "complexity_tier": "T3", "furigana": "先生[せんせい]はゆっくり話[はな]してくれたので、よく聞[き]き取[と]れた。", "sentence_source": "generated"}, {"text": "電車はホームにゆっくり入ってきて、静かに止まった。", "target_word": "ゆっくり", "complexity_tier": "T3", "furigana": "電車[でんしゃ]はホームにゆっくり入[はい]ってきて、静[しず]かに止[と]まった。", "sentence_source": "generated"}, {"text": "赤ちゃんが目を覚まさないように、ゆっくり扉を閉めた。", "target_word": "ゆっくり", "complexity_tier": "T3", "furigana": "赤[あか]ちゃんが目[め]を覚[さ]まさないように、ゆっくり扉[とびら]を閉[し]めた。", "sentence_source": "generated"}, {"text": "彼はゆっくりした口調で、事故の様子を語った。", "target_word": "ゆっくり", "complexity_tier": "T3", "furigana": "彼[かれ]はゆっくりした口調[くちょう]で、事故[じこ]の様子[ようす]を語[かた]った。", "sentence_source": "generated"}, {"text": "大きな船が港からゆっくり離れていった。", "target_word": "ゆっくり", "complexity_tier": "T3", "furigana": "大[おお]きな船[ふね]が港[みなと]からゆっくり離[はな]れていった。", "sentence_source": "generated"}, {"text": "速く走るより、最初はゆっくり走るほうが長く続けられる。", "target_word": "ゆっくり", "complexity_tier": "T3", "furigana": "速[はや]く走[はし]るより、最初[さいしょ]はゆっくり走[はし]るほうが長[なが]く続[つづ]けられる。", "sentence_source": "generated"}, {"text": "外国語は、ゆっくり話してもらえると分かりやすい。", "target_word": "ゆっくり", "complexity_tier": "T3", "furigana": "外国語[がいこくご]は、ゆっくり話[はな]してもらえると分[わ]かりやすい。", "sentence_source": "generated"}, {"text": "雲がゆっくり流れて、月が顔を出した。", "target_word": "ゆっくり", "complexity_tier": "T3", "furigana": "雲[くも]がゆっくり流[なが]れて、月[つき]が顔[かお]を出[だ]した。", "sentence_source": "generated"}, {"text": "彼女はゆっくり立ち上がって、窓の外を見た。", "target_word": "ゆっくり", "complexity_tier": "T3", "furigana": "彼女[かのじょ]はゆっくり立[た]ち上[あ]がって、窓[まど]の外[そと]を見[み]た。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ゆっくり", "label": "基本形"}, {"form": "ゆっくりと", "label": "と付き形"}, {"form": "ゆっくりした", "label": "連体形（した）"}], "register": "中立（普通体）", "sense_fingerprint": "動きや話す速さが遅いこと。速度の遅さに焦点がある", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7012c6de-6897-46e9-9295-f4be4ed38c8d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36228, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ゆっくり", "is_correct": true, "explanation": "杖をついて庭を歩く、動作の速度が遅い様子に合う。"}, {"text": "急いで", "is_correct": false, "explanation": "速く急ぐ動きで、杖をついて庭を歩く様子と矛盾する。"}, {"text": "ぴょんぴょん", "is_correct": false, "explanation": "跳ねるような動きで、杖をついて歩く様子と合わない。"}, {"text": "勢いよく", "is_correct": false, "explanation": "速く力強い動きを表し、杖をついて歩く様子と矛盾する。"}], "explanations": {"ゆっくり": "杖をついて庭を歩く、動作の速度が遅い様子に合う。", "急いで": "速く急ぐ動きで、杖をついて庭を歩く様子と矛盾する。", "ぴょんぴょん": "跳ねるような動きで、杖をついて歩く様子と合わない。", "勢いよく": "速く力強い動きを表し、杖をついて歩く様子と矛盾する。"}, "sentence_index": 0, "correct_answer": "ゆっくり"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "雷が落ちて、窓がゆっくり光った。", "explanation": "ここは〈ぱっと〉の意味。一瞬で光る現象には『ぱっと』が合い、ゆっくりは合わない。"}, {"text": "急な雨に降られ、私は傘をゆっくり差して店へ駆け込んだ。", "explanation": "ここは〈さっと〉の意味。駆け込む急ぎの場面では『さっと』が合い、ゆっくりは合わない。"}, {"text": "今日は遅刻しないように、ゆっくり朝食を流し込んだ。", "explanation": "ここは〈一気に〉の意味。流し込む動作は急ぎの行為で、ゆっくりは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc5fdf7e-84de-4db4-ae61-c81bedd001fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36228, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ゆっくり", "is_correct": true, "explanation": "最初は速度を抑えて走る、という意味に合う。"}, {"text": "必死に", "is_correct": false, "explanation": "懸命に全力を出す意味で、長く続ける走り方と矛盾する。"}, {"text": "一気に", "is_correct": false, "explanation": "速く一度に進める意味で、続けやすさを説明する文と矛盾する。"}, {"text": "力強く", "is_correct": false, "explanation": "力を込めた動きを表し、長く続けるための走り方とは合わない。"}], "explanations": {"ゆっくり": "最初は速度を抑えて走る、という意味に合う。", "必死に": "懸命に全力を出す意味で、長く続ける走り方と矛盾する。", "一気に": "速く一度に進める意味で、続けやすさを説明する文と矛盾する。", "力強く": "力を込めた動きを表し、長く続けるための走り方とは合わない。"}, "sentence_index": 6, "correct_answer": "ゆっくり"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "試合終盤、選手はゆっくり相手陣地へボールを蹴り込んだ。", "explanation": "ここは〈勢いよく〉の意味。蹴り込む強い動きにゆっくりは合わない。"}, {"text": "雷が鳴ったので、子どもたちはゆっくり耳をふさいで叫んだ。", "explanation": "ここは〈とっさに〉の意味。驚いて反応する場面では『とっさに』が合い、ゆっくりは合わない。"}, {"text": "列車の遅延を聞いた彼は、ゆっくり駅の階段を駆け下りた。", "explanation": "ここは〈すばやく〉の意味。駆け下りる急ぎの動作にゆっくりは合わず、『さっと』が自然。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc5fdf7e-84de-4db4-ae61-c81bedd001fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36228, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "その老人は、ゆっくりの足取りで川沿いを歩いた。", "corrected_sentence": "その老人は、ゆっくりとした足取りで川沿いを歩いた。", "error_description": "「ゆっくり」は名詞を直接修飾しないので「の」は誤り。「ゆっくりとした」の形で名詞を修飾する。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc5fdf7e-84de-4db4-ae61-c81bedd001fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36228, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "朝の雲が、ゆっくりに流れて、ようやく晴れた。", "corrected_sentence": "朝の雲が、ゆっくり流れて、ようやく晴れた。", "error_description": "「ゆっくり」は副詞なので「に」を付けない。「流れて」を直接修飾する形にする。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc5fdf7e-84de-4db4-ae61-c81bedd001fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
