INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36229, 3, 'prompt1_core', '{"pos": "副詞", "semantic_class": "property", "definition": "急がず、時間をかけて落ち着いて行うさま。", "primary_collocate": null, "pronunciation": "ゆっくり", "ipa": "jɯk̚kɯɾi", "syllable_count": 4, "sentences": [{"text": "私は遺産整理のために錆びついたドアノブに手をかけ、ゆっくりとそれを開けた。", "target_word": "ゆっくり", "complexity_tier": "T4", "furigana": "私[わたし]は遺産整理[いさんせいり]のために錆[さ]びついたドアノブに手[て]をかけ、ゆっくりとそれを開[あ]けた。", "sentence_source": "mined"}, {"text": "日曜日は朝寝をして、コーヒーをゆっくり飲むのが楽しみだ。", "target_word": "ゆっくり", "complexity_tier": "T3", "furigana": "日曜日[にちようび]は朝寝[あさね]をして、コーヒーをゆっくり飲[の]むのが楽[たの]しみだ。", "sentence_source": "generated"}, {"text": "時間はたっぷりあるから、ゆっくり選ぼう。", "target_word": "ゆっくり", "complexity_tier": "T3", "furigana": "時間[じかん]はたっぷりあるから、ゆっくり選[えら]ぼう。", "sentence_source": "generated"}, {"text": "今夜は温泉に入って、ゆっくり休みたい。", "target_word": "ゆっくり", "complexity_tier": "T3", "furigana": "今夜[こんや]は温泉[おんせん]に入[はい]って、ゆっくり休[やす]みたい。", "sentence_source": "generated"}, {"text": "彼女は手紙を一文字ずつ、ゆっくりと読み返した。", "target_word": "ゆっくり", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は手紙[てがみ]を一文字[ひともじ]ずつ、ゆっくりと読[よ]み返[かえ]した。", "sentence_source": "generated"}, {"text": "結論を急がず、ゆっくり話し合って決めよう。", "target_word": "ゆっくり", "complexity_tier": "T3", "furigana": "結論[けつろん]を急[いそ]がず、ゆっくり話[はな]し合[あ]って決[き]めよう。", "sentence_source": "generated"}, {"text": "忙しい毎日を離れて、海辺でゆっくり過ごしたい。", "target_word": "ゆっくり", "complexity_tier": "T3", "furigana": "忙[いそが]しい毎日[まいにち]を離[はな]れて、海辺[うみべ]でゆっくり過[す]ごしたい。", "sentence_source": "generated"}, {"text": "病み上がりなので、無理をせずゆっくり歩いて帰った。", "target_word": "ゆっくり", "complexity_tier": "T3", "furigana": "病[や]み上[あ]がりなので、無理[むり]をせずゆっくり歩[ある]いて帰[かえ]った。", "sentence_source": "generated"}, {"text": "朝のうちは雪がゆっくり降っていたが、昼から強くなった。", "target_word": "ゆっくり", "complexity_tier": "T3", "furigana": "朝[あさ]のうちは雪[ゆき]がゆっくり降[ふ]っていたが、昼[ひる]から強[つよ]くなった。", "sentence_source": "generated"}, {"text": "弱火で、ゆっくり野菜を煮込むと甘みが出る。", "target_word": "ゆっくり", "complexity_tier": "T3", "furigana": "弱火[じゃくび]で、ゆっくり野菜[やさい]を煮込[にこ]むと甘[あま]みが出[で]る。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ゆっくり", "label": "基本形"}, {"form": "ゆっくりと", "label": "と付き形"}, {"form": "ゆっくりした", "label": "連体形（した）"}], "register": "中立（普通体）", "sense_fingerprint": "急がず時間をかけて落ち着いて行うさま。くつろぐ・じっくり行う意味を含む", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T2: contains vocabulary far above tier T2: 錆びつい (Zipf 2.08)','sentence 1 above tier T2: contains vocabulary far above tier T2: 朝寝 (Zipf 2.05)','sentence 7 above tier T2: contains vocabulary far above tier T2: 病み上がり (Zipf 2.41)']::text[], '7012c6de-6897-46e9-9295-f4be4ed38c8d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36229, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ゆっくり", "is_correct": true, "explanation": "時間をかけて落ち着いて開ける様子を表す副詞。文の動作に合う。"}, {"text": "大声で", "is_correct": false, "explanation": "大声で開けるのは、落ち着いた動作の文脈と合わない。"}, {"text": "毎日", "is_correct": false, "explanation": "一度の動作を表す文に、毎日という頻度は合わない。"}, {"text": "いつも", "is_correct": false, "explanation": "一度きりの動作を表す文に、習慣的な頻度は合わない。"}], "explanations": {"ゆっくり": "時間をかけて落ち着いて開ける様子を表す副詞。文の動作に合う。", "大声で": "大声で開けるのは、落ち着いた動作の文脈と合わない。", "毎日": "一度の動作を表す文に、毎日という頻度は合わない。", "いつも": "一度きりの動作を表す文に、習慣的な頻度は合わない。"}, "sentence_index": 0, "correct_answer": "ゆっくり"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "長い練習のあと、彼は床にゆっくり疲れ果てて座り込んだ。", "explanation": "ここは〈ぐったり・力が抜けた〉の意味。ゆっくりは速さや落ち着きを表すので、疲労の様子は『ぐったり』で表す。"}, {"text": "雷鳴に驚いて、子どもはゆっくり母の腕に飛びついた。", "explanation": "ここは〈すばやく〉の意味。驚いて飛びつく瞬間の動作には『さっと』が合い、ゆっくりは合わない。"}, {"text": "試験終了の合図で、彼女は答案をゆっくり机に叩きつけた。", "explanation": "ここは〈勢いよく〉の意味。叩きつける動作は『ばんと』などの勢いのある語で表す。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc5fdf7e-84de-4db4-ae61-c81bedd001fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36229, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ゆっくり", "is_correct": true, "explanation": "海辺で落ち着いて過ごす様子を表す副詞。文の意味に合う。"}, {"text": "慌ただしく", "is_correct": false, "explanation": "せわしなく行う意味で、落ち着いて過ごす文脈と矛盾する。"}, {"text": "一気に", "is_correct": false, "explanation": "一度に進める意味で、落ち着いて過ごしたい文脈と矛盾する。"}, {"text": "力強く", "is_correct": false, "explanation": "力強さを表す語で、休みたいという文脈と合わない。"}], "explanations": {"ゆっくり": "海辺で落ち着いて過ごす様子を表す副詞。文の意味に合う。", "慌ただしく": "せわしなく行う意味で、落ち着いて過ごす文脈と矛盾する。", "一気に": "一度に進める意味で、落ち着いて過ごしたい文脈と矛盾する。", "力強く": "力強さを表す語で、休みたいという文脈と合わない。"}, "sentence_index": 6, "correct_answer": "ゆっくり"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼はゆっくり扉を蹴り開けて、部屋を出ていった。", "explanation": "ここは〈勢いよく〉の意味。蹴り開ける動作の激しさにゆっくりは合わない。"}, {"text": "列車の発車ベルが鳴り、乗客はゆっくり改札を飛び出した。", "explanation": "ここは〈すばやく〉の意味。飛び出す動作にゆっくりは合わず、『さっと』が自然。"}, {"text": "残り一分の放送を聞き、彼女はゆっくり答案を机に投げ出した。", "explanation": "ここは〈勢いよく〉の意味。投げ出す動きには『ばさっと』が合う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc5fdf7e-84de-4db4-ae61-c81bedd001fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36229, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "娘は朝の支度を、ゆっくりに済ませた。", "corrected_sentence": "娘は朝の支度を、ゆっくり済ませた。", "error_description": "「ゆっくり」は副詞なので「に」を付けない。「済ませた」を直接修飾する形にする。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc5fdf7e-84de-4db4-ae61-c81bedd001fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36229, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼はゆっくりに話すので、皆に親しまれている。", "corrected_sentence": "彼はゆっくり話すので、皆に親しまれている。", "error_description": "「ゆっくり」は副詞なので「に」を付けない。「話す」を直接修飾する形にする。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc5fdf7e-84de-4db4-ae61-c81bedd001fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36230, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「家で過ごした」で、過ごす場所を示す格助詞として正しい。"}, {"text": "を", "is_correct": false, "explanation": "「家を過ごした」は場所を示せず、目的語としても不自然。"}, {"text": "へ", "is_correct": false, "explanation": "「家へ過ごした」は移動先を示す形で、過ごす場所にはならない。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」で、過ごす場所を示せない。"}], "correct_answer": "で", "explanations": {"で": "「家で過ごした」で、過ごす場所を示す格助詞として正しい。", "を": "「家を過ごした」は場所を示せず、目的語としても不自然。", "へ": "「家へ過ごした」は移動先を示す形で、過ごす場所にはならない。", "より": "比較の「より」で、過ごす場所を示せない。"}, "error_tags": {"を": "対象", "へ": "方向", "より": "比較"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b5a8c7b-643d-4f5e-afc9-22ef6f2db6a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36230, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「部屋で過ごすこと」で、過ごす場所を示す格助詞として正しい。"}, {"text": "が", "is_correct": false, "explanation": "「部屋が過ごすこと」は部屋が主語になり、不自然。"}, {"text": "から", "is_correct": false, "explanation": "起点を示す「から」で、過ごす場所にはならない。"}, {"text": "と", "is_correct": false, "explanation": "相手を示す「と」で、部屋を相手として過ごす文にはならない。"}], "correct_answer": "で", "explanations": {"で": "「部屋で過ごすこと」で、過ごす場所を示す格助詞として正しい。", "が": "「部屋が過ごすこと」は部屋が主語になり、不自然。", "から": "起点を示す「から」で、過ごす場所にはならない。", "と": "相手を示す「と」で、部屋を相手として過ごす文にはならない。"}, "error_tags": {"が": "主語", "から": "起点", "と": "相手"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b5a8c7b-643d-4f5e-afc9-22ef6f2db6a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36230, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "じかんを どう つかうか という こと。たとえば、あそんだり、べんきょうしたり する じかん。", "primary_collocate": null, "pronunciation": "すごすこと", "ipa": "sɯɡosɯkoto", "syllable_count": 5, "sentences": [{"text": "休みの日は、家族とゆっくり過ごす。", "target_word": "過ごす", "complexity_tier": "T3", "furigana": "休[やす]みの日[ひ]は、家族[かぞく]とゆっくり過[す]ごす。", "sentence_source": "generated"}, {"text": "夏休みを祖母の家で過ごした。", "target_word": "過ごした", "complexity_tier": "T3", "furigana": "夏休[なつやす]みを祖母[そぼ]の家[いえ]で過[す]ごした。", "sentence_source": "generated"}, {"text": "楽しく過ごすことが、いちばん大切だ。", "target_word": "過ごすこと", "complexity_tier": "T3", "furigana": "楽[たの]しく過[す]ごすことが、いちばん大切[たいせつ]だ。", "sentence_source": "generated"}, {"text": "勉強ばかりでなく、友達と過ごす時間も大事だ。", "target_word": "過ごす", "complexity_tier": "T3", "furigana": "勉強[べんきょう]ばかりでなく、友達[ともだち]と過[す]ごす時間[じかん]も大事[だいじ]だ。", "sentence_source": "generated"}, {"text": "雨の日は、本を読んで過ごすことにしている。", "target_word": "過ごすこと", "complexity_tier": "T3", "furigana": "雨[あめ]の日[ひ]は、本[ほん]を読[よ]んで過[す]ごすことにしている。", "sentence_source": "generated"}, {"text": "一人で静かに過ごす夜が好きだ。", "target_word": "過ごす", "complexity_tier": "T3", "furigana": "一人[ひとり]で静[しず]かに過[す]ごす夜[よる]が好[す]きだ。", "sentence_source": "generated"}, {"text": "毎日をむだに過ごしてしまい、反省している。", "target_word": "過ごして", "complexity_tier": "T3", "furigana": "毎日[まいにち]をむだに過[す]ごしてしまい、反省[はんせい]している。", "sentence_source": "generated"}, {"text": "冬は暖かい部屋で過ごすことが多い。", "target_word": "過ごすこと", "complexity_tier": "T3", "furigana": "冬[ふゆ]は暖[あたた]かい部屋[へや]で過[す]ごすことが多[おお]い。", "sentence_source": "generated"}, {"text": "子どもたちは公園で一日中遊んで過ごした。", "target_word": "過ごした", "complexity_tier": "T3", "furigana": "子[こ]どもたちは公園[こうえん]で一日中[いちにちじゅう]遊[あそ]んで過[す]ごした。", "sentence_source": "generated"}, {"text": "退院してからは、家で穏やかに過ごしている。", "target_word": "過ごしている", "complexity_tier": "T3", "furigana": "退院[たいいん]してからは、家[いえ]で穏[おだ]やかに過[す]ごしている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "過ごす", "label": "辞書形"}, {"form": "過ごして", "label": "て形"}, {"form": "過ごした", "label": "た形"}, {"form": "過ごさない", "label": "ない形"}, {"form": "過ごすこと", "label": "名詞化"}], "register": "中立（普通体）", "sense_fingerprint": "ある時間をどのように使って暮らすか", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '52b57e1b-0418-4914-982e-e477e0ea17e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36230, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "過ごす", "is_correct": true, "explanation": "辞書形で、習慣として休みの日の過ごし方を述べる文に合う。"}, {"text": "過ごせば", "is_correct": false, "explanation": "仮定形で、文が途中で終わり、述語として成立しない。"}, {"text": "過ごして", "is_correct": false, "explanation": "て形のため、ここで文が終わらず、述語として成立しない。"}, {"text": "過ごさない", "is_correct": false, "explanation": "否定形になり、家族と過ごすという文の内容と矛盾する。"}], "explanations": {"過ごす": "辞書形で、習慣として休みの日の過ごし方を述べる文に合う。", "過ごせば": "仮定形で、文が途中で終わり、述語として成立しない。", "過ごして": "て形のため、ここで文が終わらず、述語として成立しない。", "過ごさない": "否定形になり、家族と過ごすという文の内容と矛盾する。"}, "sentence_index": 0, "correct_answer": "過ごす"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夏休みがあっという間に過ごした。", "explanation": "過ごすは人が時間を使う語なので、時間が主語の文には合わない。"}, {"text": "彼は毎月の給料を過ごしている。", "explanation": "給料は時間ではなくお金なので、「過ごす」とは言えない。"}, {"text": "勉強ばかりでなく、荷物を過ごす時間も大事だ。", "explanation": "過ごすは人が時間を使う語なので、荷物を目的語にできない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b5a8c7b-643d-4f5e-afc9-22ef6f2db6a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36230, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "過ごして", "is_correct": true, "explanation": "て形で、「過ごしてしまい、反省している」と続く文の流れに合う。"}, {"text": "過ごせば", "is_correct": false, "explanation": "仮定形で、「しまい」と続かず、むだに時間を使ったという文の流れに合わない。"}, {"text": "過ごそう", "is_correct": false, "explanation": "意志形で、「しまい」に続かず、むだにしてしまったと反省する文と合わない。"}, {"text": "過ごせ", "is_correct": false, "explanation": "命令形のため、「てしまい」の位置に入らず、反省の文の流れと合わない。"}], "explanations": {"過ごして": "て形で、「過ごしてしまい、反省している」と続く文の流れに合う。", "過ごせば": "仮定形で、「しまい」と続かず、むだに時間を使ったという文の流れに合わない。", "過ごそう": "意志形で、「しまい」に続かず、むだにしてしまったと反省する文と合わない。", "過ごせ": "命令形のため、「てしまい」の位置に入らず、反省の文の流れと合わない。"}, "sentence_index": 6, "correct_answer": "過ごして"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "退院後は、家でおかゆを過ごしている。", "explanation": "過ごすは時間の使い方を言う語なので、おかゆを目的語にする文には使わない。"}, {"text": "退院後は、家へ食材を過ごしている。", "explanation": "過ごすは人が時間を使う語なので、食材を家へ移す文には合わない。"}, {"text": "退院後は、家でテレビを過ごしている。", "explanation": "過ごすは時間の使い方を言う語なので、テレビを見る動作には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b5a8c7b-643d-4f5e-afc9-22ef6f2db6a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36230, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "週末は、家族を楽しく過ごす。", "corrected_sentence": "週末は、家族と楽しく過ごす。", "error_description": "「過ごす」の相手には「と」を使う。「を」は誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "過ごした", "is_correct": true, "explanation": "た形で、夏休みを祖母の家で過ごしたという過去の出来事に合う。"}, {"text": "過ごす", "is_correct": false, "explanation": "辞書形で、過去の出来事を述べる文と時制が合わない。"}, {"text": "過ごして", "is_correct": false, "explanation": "て形のため、ここで文が終わらず、述語として成立しない。"}, {"text": "過ごさない", "is_correct": false, "explanation": "否定形になり、過ごしたという文の内容と矛盾する。"}], "correct_form": "過ごした", "base_form": "過ごす", "form_label": "た形", "sentence_index": 1, "explanations": {"過ごした": "た形で、夏休みを祖母の家で過ごしたという過去の出来事に合う。", "過ごす": "辞書形で、過去の出来事を述べる文と時制が合わない。", "過ごして": "て形のため、ここで文が終わらず、述語として成立しない。", "過ごさない": "否定形になり、過ごしたという文の内容と矛盾する。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b5a8c7b-643d-4f5e-afc9-22ef6f2db6a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36230, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "連休は一人で静かに過ごしてしまいた。", "corrected_sentence": "連休は一人で静かに過ごしてしまった。", "error_description": "「過ごしてしまった」の「た」の形が正しい。「しまいた」は誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "過ごすこと", "is_correct": true, "explanation": "名詞化した形で、「〜ことが多い」の主語として文の内容に合う。"}, {"text": "過ごし", "is_correct": false, "explanation": "連用形で、「ことが多い」と続かず、名詞句として成立しない。"}, {"text": "過ごせ", "is_correct": false, "explanation": "命令形のため、「ことが多い」の主語にならず、文が成立しない。"}, {"text": "過ごそう", "is_correct": false, "explanation": "意志形で、「ことが多い」と続かず、習慣を述べる文と合わない。"}], "correct_form": "過ごすこと", "base_form": "過ごす", "form_label": "名詞化", "sentence_index": 7, "explanations": {"過ごすこと": "名詞化した形で、「〜ことが多い」の主語として文の内容に合う。", "過ごし": "連用形で、「ことが多い」と続かず、名詞句として成立しない。", "過ごせ": "命令形のため、「ことが多い」の主語にならず、文が成立しない。", "過ごそう": "意志形で、「ことが多い」と続かず、習慣を述べる文と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b5a8c7b-643d-4f5e-afc9-22ef6f2db6a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36232, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "特別", "is_correct": true, "explanation": "「普通」(特別ではない)の対義語。"}, {"text": "大量", "is_correct": false, "explanation": "数の多さを表す名詞で、「普通」の反対語ではない。"}, {"text": "明朗", "is_correct": false, "explanation": "明るく朗らかな様子を表す語で、「普通」の対義語にはならない。"}, {"text": "衛生", "is_correct": false, "explanation": "清潔さに関する語で、「普通」とは対義関係にない。"}], "correct_answer": "特別", "explanations": {"特別": "「普通」(特別ではない)の対義語。", "大量": "数の多さを表す名詞で、「普通」の反対語ではない。", "明朗": "明るく朗らかな様子を表す語で、「普通」の対義語にはならない。", "衛生": "清潔さに関する語で、「普通」とは対義関係にない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aad67c8f-e9b3-403f-a0ec-20e528ef9731') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
