INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36232, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "ふつうは、みんなとおなじで、とくべつじゃないこと。", "primary_collocate": null, "pronunciation": "ふつう", "ipa": "ɸɯtsɯː", "syllable_count": 3, "sentences": [{"text": "私は普通の高校生です。", "target_word": "普通", "complexity_tier": "T2", "furigana": "私[わたし]は普通[ふつう]の高校生[こうこうせい]です。", "sentence_source": "generated"}, {"text": "この店のラーメンは普通の味で、特別においしくはない。", "target_word": "普通", "complexity_tier": "T3", "furigana": "この店[みせ]のラーメンは普通[ふつう]の味[あじ]で、特別[とくべつ]においしくはない。", "sentence_source": "generated"}, {"text": "彼は普通の人と同じように、毎日会社へ行っています。", "target_word": "普通", "complexity_tier": "T3", "furigana": "彼[かれ]は普通[ふつう]の人[ひと]と同[おな]じように、毎日[まいにち]会社[かいしゃ]へ行[い]っています。", "sentence_source": "generated"}, {"text": "普通の服でいいですから、気軽に来てください。", "target_word": "普通", "complexity_tier": "T3", "furigana": "普通[ふつう]の服[ふく]でいいですから、気軽[きがる]に来[き]てください。", "sentence_source": "generated"}, {"text": "特別な日ではなく、普通の一日でした。", "target_word": "普通", "complexity_tier": "T3", "furigana": "特別[とくべつ]な日[ひ]ではなく、普通[ふつう]の一日[いちにち]でした。", "sentence_source": "generated"}, {"text": "試験の結果は普通で、よくも悪くもなかった。", "target_word": "普通", "complexity_tier": "T3", "furigana": "試験[しけん]の結果[けっか]は普通[ふつう]で、よくも悪[わる]くもなかった。", "sentence_source": "generated"}, {"text": "私の家は普通の住宅地にあります。", "target_word": "普通", "complexity_tier": "T2", "furigana": "私[わたし]の家[いえ]は普通[ふつう]の住宅地[じゅうたくち]にあります。", "sentence_source": "generated"}, {"text": "彼女は有名な歌手なのに、話すと普通の女の子だった。", "target_word": "普通", "complexity_tier": "T4", "furigana": "彼女[かのじょ]は有名[ゆうめい]な歌手[かしゅ]なのに、話[はな]すと普通[ふつう]の女[おんな]の子[こ]だった。", "sentence_source": "generated"}, {"text": "うちの犬は普通の犬より少し大きいです。", "target_word": "普通", "complexity_tier": "T3", "furigana": "うちの犬[いぬ]は普通[ふつう]の犬[いぬ]より少[すこ]し大[おお]きいです。", "sentence_source": "generated"}, {"text": "この問題は、普通の中学生にはむずかしい。", "target_word": "普通", "complexity_tier": "T3", "furigana": "この問題[もんだい]は、普通[ふつう]の中学生[ちゅうがくせい]にはむずかしい。", "sentence_source": "generated"}], "morphological_forms": [{"form": "普通の", "label": "連体形(名詞+の)"}, {"form": "普通だ", "label": "断定"}, {"form": "普通で", "label": "中止形"}, {"form": "普通に", "label": "連用形"}], "register": "中立(話し言葉・書き言葉)", "sense_fingerprint": "他の人と同じで特別ではない、ありふれた様子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94f9763a-fbdb-4942-b840-f5e9ecdfccc6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36232, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "普通", "is_correct": true, "explanation": "「普通の高校生」で、特別ではない一般の高校生という意味に合う。空所に入る正解。"}, {"text": "静か", "is_correct": false, "explanation": "形容動詞で、「静かの高校生」と名詞に「の」でつなぐ形は成り立たない。"}, {"text": "真剣", "is_correct": false, "explanation": "真剣な態度を表す語で、「真剣の高校生」とは続かない。"}, {"text": "手作り", "is_correct": false, "explanation": "手で作ったものを指す語で、人の「高校生」とは結びつかない。"}], "explanations": {"普通": "「普通の高校生」で、特別ではない一般の高校生という意味に合う。空所に入る正解。", "静か": "形容動詞で、「静かの高校生」と名詞に「の」でつなぐ形は成り立たない。", "真剣": "真剣な態度を表す語で、「真剣の高校生」とは続かない。", "手作り": "手で作ったものを指す語で、人の「高校生」とは結びつかない。"}, "sentence_index": 0, "correct_answer": "普通"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "次の普通列車は、すべての駅に止まります。", "explanation": "ここは〈普通列車〉（各駅に止まる列車）の意味。〈特別ではない〉の意味では使われていない。"}, {"text": "この口座は普通預金にしてください。", "explanation": "ここは〈普通預金〉（預金の種類）の意味。〈特別ではない〉の意味では使われていない。"}, {"text": "「犬」は普通名詞です。", "explanation": "ここは〈普通名詞〉（名詞の分類）の意味。〈特別ではない〉の意味では使われていない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aad67c8f-e9b3-403f-a0ec-20e528ef9731') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36232, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "普通", "is_correct": true, "explanation": "「私の家は普通の住宅地にあります」で、特別ではない一般的な住宅地を表す。空所に入る正解。"}, {"text": "不便", "is_correct": false, "explanation": "使いにくい状態を表す語で、「不便の家」「不便に育つ」は成り立たない。"}, {"text": "大切", "is_correct": false, "explanation": "大事だという意味の語で、ここでは家や育ち方に続かない。"}, {"text": "静粛", "is_correct": false, "explanation": "静かにすることを表す語で、家や育ち方の様子には合わない。"}], "explanations": {"普通": "「私の家は普通の住宅地にあります」で、特別ではない一般的な住宅地を表す。空所に入る正解。", "不便": "使いにくい状態を表す語で、「不便の家」「不便に育つ」は成り立たない。", "大切": "大事だという意味の語で、ここでは家や育ち方に続かない。", "静粛": "静かにすることを表す語で、家や育ち方の様子には合わない。"}, "sentence_index": 6, "correct_answer": "普通"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "給料は普通預金に振り込まれます。", "explanation": "ここは〈普通預金〉（預金の種類）の意味。〈特別ではない〉の意味では使われていない。"}, {"text": "「山」は普通名詞です。", "explanation": "ここは〈普通名詞〉（名詞の分類）の意味。〈特別ではない〉の意味では使われていない。"}, {"text": "普通列車で三十分ほどかかります。", "explanation": "ここは〈普通列車〉（各駅に止まる列車）の意味。〈特別ではない〉の意味では使われていない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aad67c8f-e9b3-403f-a0ec-20e528ef9731') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36232, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ぼくは普通を大学生です。", "corrected_sentence": "ぼくは普通の大学生です。", "error_description": "名詞「大学生」を修飾するには「の」が必要。「を」は目的語を示すため、「普通を大学生」は誤り。正しくは「普通の」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aad67c8f-e9b3-403f-a0ec-20e528ef9731') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36232, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妹は普通小学生です。", "corrected_sentence": "妹は普通の小学生です。", "error_description": "名詞「小学生」を修飾する「の」が抜けている。「普通の小学生」と続けるのが正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aad67c8f-e9b3-403f-a0ec-20e528ef9731') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
