INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36233, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "一般的なこと。特別ではないこと。通常の状態。", "primary_collocate": null, "pronunciation": "ふつう", "ipa": "ɸɯtsɯː", "syllable_count": 3, "sentences": [{"text": "普通は朝七時に起きますが、今日は六時に起きました。", "target_word": "普通", "complexity_tier": "T3", "furigana": "普通[ふつう]は朝[あさ]七時[しちじ]に起[お]きますが、今日[きょう]は六時[ろくじ]に起[お]きました。", "sentence_source": "generated"}, {"text": "普通、日本では家の中で靴をぬぎます。", "target_word": "普通", "complexity_tier": "T3", "furigana": "普通[ふつう]、日本[にほん]では家[いえ]の中[なか]で靴[くつ]をぬぎます。", "sentence_source": "generated"}, {"text": "雨がふっても、普通どおり授業があります。", "target_word": "普通", "complexity_tier": "T3", "furigana": "雨[あめ]がふっても、普通[ふつう]どおり授業[じゅぎょう]があります。", "sentence_source": "generated"}, {"text": "病気が治って、普通の生活にもどった。", "target_word": "普通", "complexity_tier": "T3", "furigana": "病気[びょうき]が治[なお]って、普通[ふつう]の生活[せいかつ]にもどった。", "sentence_source": "generated"}, {"text": "この時間は普通なら道がすいているはずだ。", "target_word": "普通", "complexity_tier": "T3", "furigana": "この時間[じかん]は普通[ふつう]なら道[みち]がすいているはずだ。", "sentence_source": "generated"}, {"text": "普通に考えれば、そんなことはありえない。", "target_word": "普通", "complexity_tier": "T4", "furigana": "普通[ふつう]に考[かんが]えれば、そんなことはありえない。", "sentence_source": "generated"}, {"text": "今日は普通より早く着いた。", "target_word": "普通", "complexity_tier": "T3", "furigana": "今日[きょう]は普通[ふつう]より早[はや]く着[つ]いた。", "sentence_source": "generated"}, {"text": "普通の状態では、体温は三十六度ぐらいです。", "target_word": "普通", "complexity_tier": "T3", "furigana": "普通[ふつう]の状態[じょうたい]では、体温[たいおん]は三十六度[さんじゅうろくど]ぐらいです。", "sentence_source": "generated"}, {"text": "休みの日でも、普通は図書館が開いています。", "target_word": "普通", "complexity_tier": "T3", "furigana": "休[やす]みの日[ひ]でも、普通[ふつう]は図書館[としょかん]が開[あ]いています。", "sentence_source": "generated"}, {"text": "地震のあと、電車が普通に動くまで二時間かかった。", "target_word": "普通", "complexity_tier": "T4", "furigana": "地震[じしん]のあと、電車[でんしゃ]が普通[ふつう]に動[うご]くまで二時間[にじかん]かかった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "普通の", "label": "連体形(名詞+の)"}, {"form": "普通は", "label": "主題(名詞+は)"}, {"form": "普通なら", "label": "仮定形"}, {"form": "普通に", "label": "連用形"}], "register": "中立(話し言葉・書き言葉)", "sense_fingerprint": "いつもの、通常の状態や一般的なやり方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 1 above tier T1: contains vocabulary far above tier T1: ぬぎ (Zipf 2.34)']::text[], '94f9763a-fbdb-4942-b840-f5e9ecdfccc6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36233, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "普通", "is_correct": true, "explanation": "「普通は朝七時に起きます」で、いつもの通常の状態を表す。空所に入る正解。"}, {"text": "迷惑", "is_correct": false, "explanation": "人に負担をかけることを表す名詞で、「迷惑は朝七時に起きます」とは続かない。"}, {"text": "静粛", "is_correct": false, "explanation": "静かにすることを表す語で、起きる時刻の文脈には合わない。"}, {"text": "豊富", "is_correct": false, "explanation": "たくさんあることを表す語で、「豊富は朝七時に起きます」は成り立たない。"}], "explanations": {"普通": "「普通は朝七時に起きます」で、いつもの通常の状態を表す。空所に入る正解。", "迷惑": "人に負担をかけることを表す名詞で、「迷惑は朝七時に起きます」とは続かない。", "静粛": "静かにすることを表す語で、起きる時刻の文脈には合わない。", "豊富": "たくさんあることを表す語で、「豊富は朝七時に起きます」は成り立たない。"}, "sentence_index": 0, "correct_answer": "普通"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "給料は普通預金に振り込まれます。", "explanation": "ここは〈普通預金〉（預金の種類）の意味。〈一般的な〉の意味では使われていない。"}, {"text": "「花」は普通名詞です。", "explanation": "ここは〈普通名詞〉（名詞の分類）の意味。〈一般的な〉の意味では使われていない。"}, {"text": "次の普通列車は、すべての駅に止まります。", "explanation": "ここは〈普通列車〉（各駅に止まる列車）の意味。〈一般的な〉の意味では使われていない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aad67c8f-e9b3-403f-a0ec-20e528ef9731') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36233, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "普通", "is_correct": true, "explanation": "「今日は普通より早く着いた」で、いつもの状態と比べる意味に合う。空所に入る正解。"}, {"text": "不便", "is_correct": false, "explanation": "使いにくい状態を表す語で、「今日は不便より早く」とは続かない。"}, {"text": "大切", "is_correct": false, "explanation": "大事だという意味の語で、「大切より早く」と比べる形にはならない。"}, {"text": "活発", "is_correct": false, "explanation": "動きが盛んな様子を表す語で、「活発より早く」とは続かない。"}], "explanations": {"普通": "「今日は普通より早く着いた」で、いつもの状態と比べる意味に合う。空所に入る正解。", "不便": "使いにくい状態を表す語で、「今日は不便より早く」とは続かない。", "大切": "大事だという意味の語で、「大切より早く」と比べる形にはならない。", "活発": "動きが盛んな様子を表す語で、「活発より早く」とは続かない。"}, "sentence_index": 6, "correct_answer": "普通"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この口座は普通預金にしてください。", "explanation": "ここは〈普通預金〉（預金の種類）の意味。〈いつもどおり〉の意味では使われていない。"}, {"text": "「海」は普通名詞です。", "explanation": "ここは〈普通名詞〉（名詞の分類）の意味。〈いつもどおり〉の意味では使われていない。"}, {"text": "急行に乗らず、普通列車で帰った。", "explanation": "ここは〈普通列車〉（各駅に止まる列車）の意味。〈いつもどおり〉の意味では使われていない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aad67c8f-e9b3-403f-a0ec-20e528ef9731') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36233, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "普通が朝六時に起きる人が多いです。", "corrected_sentence": "普通は朝六時に起きる人が多いです。", "error_description": "主題を示すには「は」が正しい。「が」は主語を示すため、「普通が」と続けると不自然。誤りは「が」を「は」にすること。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aad67c8f-e9b3-403f-a0ec-20e528ef9731') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36233, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "事故のあと、新幹線が普通動くまで三時間かかった。", "corrected_sentence": "事故のあと、新幹線が普通に動くまで三時間かかった。", "error_description": "動詞「動く」を修飾する副詞には「に」が必要。「に」が抜けているため、「普通動く」は誤り。正しくは「普通に動く」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aad67c8f-e9b3-403f-a0ec-20e528ef9731') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36234, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「友達」は「います」の主語なので「が」を使う。"}, {"text": "を", "is_correct": false, "explanation": "「います」は目的語を取らないので、「を」は合わない。"}, {"text": "で", "is_correct": false, "explanation": "存在を述べる文に場所や手段の「で」は合わない。"}, {"text": "の", "is_correct": false, "explanation": "「友達の三人います」とは連体修飾にならず、文が成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「友達」は「います」の主語なので「が」を使う。", "を": "「います」は目的語を取らないので、「を」は合わない。", "で": "存在を述べる文に場所や手段の「で」は合わない。", "の": "「友達の三人います」とは連体修飾にならず、文が成り立たない。"}, "error_tags": {"を": "対象", "で": "場所・手段", "の": "連体修飾"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aad67c8f-e9b3-403f-a0ec-20e528ef9731') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36234, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "と", "options": [{"text": "と", "is_correct": true, "explanation": "「話す」の相手を表す「と」で、「友達と電話で話した」に合う。"}, {"text": "を", "is_correct": false, "explanation": "「話す」の相手は「と」で示し、「を」は不自然。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」は、この文の「話した」という動作の相手を示せない。"}, {"text": "で", "is_correct": false, "explanation": "「友達で」と名詞に「で」は続かず、文が成り立たない。"}], "correct_answer": "と", "explanations": {"と": "「話す」の相手を表す「と」で、「友達と電話で話した」に合う。", "を": "「話す」の相手は「と」で示し、「を」は不自然。", "より": "比較の「より」は、この文の「話した」という動作の相手を示せない。", "で": "「友達で」と名詞に「で」は続かず、文が成り立たない。"}, "error_tags": {"を": "対象", "で": "場所・手段", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aad67c8f-e9b3-403f-a0ec-20e528ef9731') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36234, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "いっしょにあそんだり、はなしたりする、なかのいいひと。", "primary_collocate": null, "pronunciation": "ともだち", "ipa": "tomodat͡ɕi", "syllable_count": 4, "sentences": [{"text": "友達と公園でサッカーをしました。", "target_word": "友達", "complexity_tier": "T2", "furigana": "友達[ともだち]と公園[こうえん]でサッカーをしました。", "sentence_source": "generated"}, {"text": "私には、小学校からの友達が三人います。", "target_word": "友達", "complexity_tier": "T3", "furigana": "私[わたし]には、小学校[しょうがっこう]からの友達[ともだち]が三人[さんにん]います。", "sentence_source": "generated"}, {"text": "友達に借りた本を、今日返します。", "target_word": "友達", "complexity_tier": "T3", "furigana": "友達[ともだち]に借[か]りた本[ほん]を、今日[きょう]返[かえ]します。", "sentence_source": "generated"}, {"text": "新しい学校で、すぐに友達ができた。", "target_word": "友達", "complexity_tier": "T3", "furigana": "新[あたら]しい学校[がっこう]で、すぐに友達[ともだち]ができた。", "sentence_source": "generated"}, {"text": "友達の誕生日に、手紙を書きました。", "target_word": "友達", "complexity_tier": "T3", "furigana": "友達[ともだち]の誕生日[たんじょうび]に、手紙[てがみ]を書[か]きました。", "sentence_source": "generated"}, {"text": "昨日は友達の家に泊まりました。", "target_word": "友達", "complexity_tier": "T3", "furigana": "昨日[きのう]は友達[ともだち]の家[いえ]に泊[と]まりました。", "sentence_source": "generated"}, {"text": "困ったときは、友達が助けてくれる。", "target_word": "友達", "complexity_tier": "T3", "furigana": "困[こま]ったときは、友達[ともだち]が助[たす]けてくれる。", "sentence_source": "generated"}, {"text": "友達と電話で二時間も話してしまった。", "target_word": "友達", "complexity_tier": "T3", "furigana": "友達[ともだち]と電話[でんわ]で二時間[にじかん]も話[はな]してしまった。", "sentence_source": "generated"}, {"text": "彼は私の一番の友達で、何でも相談できる。", "target_word": "友達", "complexity_tier": "T3", "furigana": "彼[かれ]は私[わたし]の一番[いちばん]の友達[ともだち]で、何[なん]でも相談[そうだん]できる。", "sentence_source": "generated"}, {"text": "友達とけんかをしたので、悲しい気持ちです。", "target_word": "友達", "complexity_tier": "T3", "furigana": "友達[ともだち]とけんかをしたので、悲[かな]しい気持[きも]ちです。", "sentence_source": "generated"}], "morphological_forms": [{"form": "友達", "label": "基本形"}, {"form": "友達の", "label": "名詞+の"}, {"form": "友達と", "label": "名詞+と"}, {"form": "友達だ", "label": "断定"}], "register": "中立(話し言葉)", "sense_fingerprint": "仲がよく、いっしょに遊んだり話したりする人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94f9763a-fbdb-4942-b840-f5e9ecdfccc6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36234, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "友達", "is_correct": true, "explanation": "一緒に遊ぶ相手を表し、「公園でサッカーをしました」に合う。"}, {"text": "冷蔵庫", "is_correct": false, "explanation": "家電の名前で、一緒にサッカーをする相手にならない。"}, {"text": "教科書", "is_correct": false, "explanation": "勉強に使う本で、一緒にサッカーをする相手ではない。"}, {"text": "切符", "is_correct": false, "explanation": "乗車に使う紙で、人と一緒にサッカーをすることはない。"}], "explanations": {"友達": "一緒に遊ぶ相手を表し、「公園でサッカーをしました」に合う。", "冷蔵庫": "家電の名前で、一緒にサッカーをする相手にならない。", "教科書": "勉強に使う本で、一緒にサッカーをする相手ではない。", "切符": "乗車に使う紙で、人と一緒にサッカーをすることはない。"}, "sentence_index": 0, "correct_answer": "友達"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "その店には、毎月新しい友達が商品を買いに来る。", "explanation": "ここは〈顧客〉の意味。商品を買いに来る人は〈顧客〉で、〈友達〉（親しい間柄の人）とは言わない。"}, {"text": "この展示会の友達は、毎年二千人を超える。", "explanation": "ここは〈来場者〉の意味。展示会に訪れる人の数を表す〈来場者〉で、〈友達〉（親しい間柄の人）とは言わない。"}, {"text": "社長は、会議で友達に次の仕事を指示した。", "explanation": "ここは〈部下〉の意味。指示を出す相手は〈部下〉で、対等な親しい関係の〈友達〉とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aad67c8f-e9b3-403f-a0ec-20e528ef9731') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36234, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "友達", "is_correct": true, "explanation": "困っている人を助ける主語として自然で、文の意味に合う。"}, {"text": "雨", "is_correct": false, "explanation": "自然現象で、人を助けるという文脈に合わない。"}, {"text": "電柱", "is_correct": false, "explanation": "物の名前で、助けてくれる主語にならない。"}, {"text": "窓ガラス", "is_correct": false, "explanation": "物の名前で、人を助ける主語として成り立たない。"}], "explanations": {"友達": "困っている人を助ける主語として自然で、文の意味に合う。", "雨": "自然現象で、人を助けるという文脈に合わない。", "電柱": "物の名前で、助けてくれる主語にならない。", "窓ガラス": "物の名前で、人を助ける主語として成り立たない。"}, "sentence_index": 6, "correct_answer": "友達"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "先生は、授業で友達に宿題を出した。", "explanation": "ここは〈生徒〉の意味。宿題を出す相手は〈生徒〉で、親しい間柄の〈友達〉とは言わない。"}, {"text": "この雑誌の友達は、毎月の記事を楽しみに待っている。", "explanation": "ここは〈読者〉の意味。雑誌の記事を楽しみに待つ人は〈読者〉で、〈友達〉（親しい間柄の人）とは言わない。"}, {"text": "この予約サイトには、毎日百万人の友達がアクセスする。", "explanation": "ここは〈利用者〉の意味。サイトを使う多くの人は〈利用者〉で、〈友達〉（親しい間柄の人）とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aad67c8f-e9b3-403f-a0ec-20e528ef9731') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36234, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "昨日、友達を電話で長く話した。", "corrected_sentence": "昨日、友達と電話で長く話した。", "error_description": "「話す」の相手を表す助詞は「と」。「友達を」は誤りで、「友達と」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aad67c8f-e9b3-403f-a0ec-20e528ef9731') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
