INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36236, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「作る」の目的語として「会う時間を」の「を」が正しい。"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」は、目的語を取る「作る」には合わない。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」は、この文の「作る」の対象を示せない。"}, {"text": "が", "is_correct": false, "explanation": "「作る」の目的語に「が」は使えず、「時間が作る」は不自然。"}], "correct_answer": "を", "explanations": {"を": "「作る」の目的語として「会う時間を」の「を」が正しい。", "へ": "方向の「へ」は、目的語を取る「作る」には合わない。", "より": "比較の「より」は、この文の「作る」の対象を示せない。", "が": "「作る」の目的語に「が」は使えず、「時間が作る」は不自然。"}, "error_tags": {"へ": "方向", "より": "比較", "が": "主語"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aad67c8f-e9b3-403f-a0ec-20e528ef9731') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36236, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「会う時間は」の「は」は、文全体の主題を示して「めったにとれない」に続く。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所の「で」は、「会う時間で」の形で文の意味に合わない。"}, {"text": "に", "is_correct": false, "explanation": "「とれない」の対象を示す「に」は、「時間にとれない」となり不自然。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾の「の」では、「会う時間のめったにとれない」が成り立たない。"}], "correct_answer": "は", "explanations": {"は": "「会う時間は」の「は」は、文全体の主題を示して「めったにとれない」に続く。", "で": "手段や場所の「で」は、「会う時間で」の形で文の意味に合わない。", "に": "「とれない」の対象を示す「に」は、「時間にとれない」となり不自然。", "の": "連体修飾の「の」では、「会う時間のめったにとれない」が成り立たない。"}, "error_tags": {"で": "手段・場所", "に": "位置・到達", "の": "連体修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aad67c8f-e9b3-403f-a0ec-20e528ef9731') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36236, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ともだちと いっしょに いる じかんのこと。", "primary_collocate": null, "pronunciation": "あうじかん", "ipa": "audʑikaɴ", "syllable_count": 5, "sentences": [{"text": "仕事が忙しくて、友達と会う時間がない。", "target_word": "会う時間", "complexity_tier": "T3", "furigana": "仕事[しごと]が忙[いそが]しくて、友達[ともだち]と会[あ]う時間[じかん]がない。", "sentence_source": "generated"}, {"text": "週末は友達と会う時間を作るようにしています。", "target_word": "会う時間", "complexity_tier": "T3", "furigana": "週末[しゅうまつ]は友達[ともだち]と会[あ]う時間[じかん]を作[つく]るようにしています。", "sentence_source": "generated"}, {"text": "友達と会う時間は、いつも楽しくてあっという間に終わる。", "target_word": "会う時間", "complexity_tier": "T4", "furigana": "友達[ともだち]と会[あ]う時間[じかん]は、いつも楽[たの]しくてあっという間[ま]に終[お]わる。", "sentence_source": "generated"}, {"text": "友達と会う時間を決めるために、電話をかけた。", "target_word": "会う時間", "complexity_tier": "T3", "furigana": "友達[ともだち]と会[あ]う時間[じかん]を決[き]めるために、電話[でんわ]をかけた。", "sentence_source": "generated"}, {"text": "試験の前は、友達と会う時間をへらして勉強した。", "target_word": "会う時間", "complexity_tier": "T3", "furigana": "試験[しけん]の前[まえ]は、友達[ともだち]と会[あ]う時間[じかん]をへらして勉強[べんきょう]した。", "sentence_source": "generated"}, {"text": "私は、友達と会う時間が一番のたのしみです。", "target_word": "会う時間", "complexity_tier": "T3", "furigana": "私[わたし]は、友達[ともだち]と会[あ]う時間[じかん]が一番[いちばん]のたのしみです。", "sentence_source": "generated"}, {"text": "夜は家族の時間なので、友達と会う時間は昼にしています。", "target_word": "会う時間", "complexity_tier": "T4", "furigana": "夜[よる]は家族[かぞく]の時間[じかん]なので、友達[ともだち]と会[あ]う時間[じかん]は昼[ひる]にしています。", "sentence_source": "generated"}, {"text": "遠くに住んでいるので、友達と会う時間はめったにとれない。", "target_word": "会う時間", "complexity_tier": "T4", "furigana": "遠[とお]くに住[す]んでいるので、友達[ともだち]と会[あ]う時間[じかん]はめったにとれない。", "sentence_source": "generated"}, {"text": "月に一度、友達と会う時間が私の元気のもとだ。", "target_word": "会う時間", "complexity_tier": "T4", "furigana": "月[つき]に一度[いちど]、友達[ともだち]と会[あ]う時間[じかん]が私[わたし]の元気[げんき]のもとだ。", "sentence_source": "generated"}, {"text": "友達と会う時間より、一人で本を読む時間のほうが好きだ。", "target_word": "会う時間", "complexity_tier": "T4", "furigana": "友達[ともだち]と会[あ]う時間[じかん]より、一人[ひとり]で本[ほん]を読[よ]む時間[じかん]のほうが好[す]きだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "会う時間", "label": "基本形"}, {"form": "会う時間が", "label": "名詞+が"}, {"form": "会う時間を", "label": "名詞+を"}, {"form": "会う時間は", "label": "名詞+は"}], "register": "中立(話し言葉)", "sense_fingerprint": "友達と会って一緒に過ごす時間", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 4 above tier T2: contains vocabulary far above tier T2: へらし (Zipf 1.54)']::text[], '94f9763a-fbdb-4942-b840-f5e9ecdfccc6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36236, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "会う時間", "is_correct": true, "explanation": "友達と過ごす時間の意味で、「〜がない」の対象として文に合う。"}, {"text": "性格", "is_correct": false, "explanation": "人の性質を表し、「時間がない」の対象にならない。"}, {"text": "理由", "is_correct": false, "explanation": "原因を表す語で、「友達と〜がない」の対象として成り立たない。"}, {"text": "予算", "is_correct": false, "explanation": "お金の枠を表し、友達と「ない」の対象として不自然。"}], "explanations": {"会う時間": "友達と過ごす時間の意味で、「〜がない」の対象として文に合う。", "性格": "人の性質を表し、「時間がない」の対象にならない。", "理由": "原因を表す語で、「友達と〜がない」の対象として成り立たない。", "予算": "お金の枠を表し、友達と「ない」の対象として不自然。"}, "sentence_index": 0, "correct_answer": "会う時間"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "病院では、診察の会う時間が三時間もあった。", "explanation": "ここは〈待ち時間〉の意味。診察を待つ時間は〈会う時間〉ではなく、友達と会う時間の意味にならない。"}, {"text": "刑務所の会う時間は、一回三十分までです。", "explanation": "ここは〈面会時間〉の意味。刑務所で家族などを訪ねる時間は〈面会時間〉で、〈会う時間〉（友達と一緒にいる時間）とは言わない。"}, {"text": "この店の会う時間は、朝九時から夜十時までだ。", "explanation": "ここは〈営業時間〉の意味。店が開いている時間を〈会う時間〉とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aad67c8f-e9b3-403f-a0ec-20e528ef9731') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36236, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "会う時間", "is_correct": true, "explanation": "友達と過ごす時間の意味で、「は昼にしています」の主題として文に合う。"}, {"text": "天気", "is_correct": false, "explanation": "空模様を表し、友達との予定の内容としては合わない。"}, {"text": "体重", "is_correct": false, "explanation": "体の重さを表し、昼にする予定の対象にならない。"}, {"text": "年齢", "is_correct": false, "explanation": "人の年数を表し、予定の時間帯の主題として成り立たない。"}], "explanations": {"会う時間": "友達と過ごす時間の意味で、「は昼にしています」の主題として文に合う。", "天気": "空模様を表し、友達との予定の内容としては合わない。", "体重": "体の重さを表し、昼にする予定の対象にならない。", "年齢": "人の年数を表し、予定の時間帯の主題として成り立たない。"}, "sentence_index": 6, "correct_answer": "会う時間"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "毎朝、会う時間が一時間もかかるので、早起きしている。", "explanation": "ここは〈通勤時間〉の意味。家から職場までの移動時間は〈会う時間〉とは言わない。"}, {"text": "カレーの会う時間は三十分だ。", "explanation": "ここは〈調理時間〉の意味。料理にかかる時間を〈会う時間〉とは言わない。"}, {"text": "この番組は、会う時間が三十分しかない。", "explanation": "ここは〈放送時間〉の意味。番組が流れる時間を〈会う時間〉とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aad67c8f-e9b3-403f-a0ec-20e528ef9731') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36236, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "毎日、友達と会う時間に作ります。", "corrected_sentence": "毎日、友達と会う時間を作ります。", "error_description": "「作る」の目的語は「を」で示す。「に」は誤りで、「会う時間を」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aad67c8f-e9b3-403f-a0ec-20e528ef9731') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36236, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "週末は、友達と会う時間を作るない。", "corrected_sentence": "週末は、友達と会う時間を作らない。", "error_description": "否定形は「作らない」。「作るない」は活用の誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aad67c8f-e9b3-403f-a0ec-20e528ef9731') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36238, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "速い", "is_correct": true, "explanation": "速さの意味での対義語で、「遅い」と反対の関係にある。"}, {"text": "高い", "is_correct": false, "explanation": "対義語ではない。高さや値段を表す語。"}, {"text": "大きい", "is_correct": false, "explanation": "対義語ではない。大きさを表す語。"}, {"text": "薄い", "is_correct": false, "explanation": "対義語ではない。厚さや濃さを表す語。"}], "correct_answer": "速い", "explanations": {"速い": "速さの意味での対義語で、「遅い」と反対の関係にある。", "高い": "対義語ではない。高さや値段を表す語。", "大きい": "対義語ではない。大きさを表す語。", "薄い": "対義語ではない。厚さや濃さを表す語。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aad67c8f-e9b3-403f-a0ec-20e528ef9731') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36238, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "速い", "is_correct": true, "explanation": "速さの意味での対義語で、「遅い」と反対の関係にある。"}, {"text": "深い", "is_correct": false, "explanation": "対義語ではない。深さを表す語。"}, {"text": "広い", "is_correct": false, "explanation": "対義語ではない。面積や範囲の広さを表す語。"}, {"text": "太い", "is_correct": false, "explanation": "対義語ではない。太さを表す語。"}], "correct_answer": "速い", "explanations": {"速い": "速さの意味での対義語で、「遅い」と反対の関係にある。", "深い": "対義語ではない。深さを表す語。", "広い": "対義語ではない。面積や範囲の広さを表す語。", "太い": "対義語ではない。太さを表す語。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aad67c8f-e9b3-403f-a0ec-20e528ef9731') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36238, 3, 'prompt1_core', '{"pos": "形容詞", "semantic_class": "property", "definition": "じかんが たくさん かかる ことです。", "primary_collocate": null, "pronunciation": "おそい", "ipa": "osoi", "syllable_count": 3, "sentences": [{"text": "この電車は遅いので、急行に乗りましょう。", "target_word": "遅い", "complexity_tier": "T3", "furigana": "この電車[でんしゃ]は遅[おそ]いので、急行[きゅうこう]に乗[の]りましょう。", "sentence_source": "generated"}, {"text": "弟は走るのが遅くて、いつも最後になる。", "target_word": "遅く", "complexity_tier": "T3", "furigana": "弟[おとうと]は走[はし]るのが遅[おそ]くて、いつも最後[さいご]になる。", "sentence_source": "generated"}, {"text": "古いパソコンは動きが遅い。", "target_word": "遅い", "complexity_tier": "T3", "furigana": "古[ふる]いパソコンは動[うご]きが遅[おそ]い。", "sentence_source": "generated"}, {"text": "祖父は歩くのが遅いので、バスに乗ってもらいました。", "target_word": "遅い", "complexity_tier": "T3", "furigana": "祖父[そふ]は歩[ある]くのが遅[おそ]いので、バスに乗[の]ってもらいました。", "sentence_source": "generated"}, {"text": "雪道では、車が遅く走っている。", "target_word": "遅く", "complexity_tier": "T3", "furigana": "雪道[ゆきみち]では、車[くるま]が遅[おそ]く走[はし]っている。", "sentence_source": "generated"}, {"text": "インターネットが遅くて、動画が見られない。", "target_word": "遅く", "complexity_tier": "T3", "furigana": "インターネットが遅[おそ]くて、動画[どうが]が見[み]られない。", "sentence_source": "generated"}, {"text": "彼は食べるのが遅いから、先に食べ始めてください。", "target_word": "遅い", "complexity_tier": "T3", "furigana": "彼[かれ]は食[た]べるのが遅[おそ]いから、先[さき]に食[た]べ始[はじ]めてください。", "sentence_source": "generated"}, {"text": "私は計算が遅いので、テストの時間が足りなかった。", "target_word": "遅い", "complexity_tier": "T3", "furigana": "私[わたし]は計算[けいさん]が遅[おそ]いので、テストの時間[じかん]が足[た]りなかった。", "sentence_source": "generated"}, {"text": "この機械は動きが遅くて、仕事がなかなか進まない。", "target_word": "遅くて", "complexity_tier": "T3", "furigana": "この機械[きかい]は動[うご]きが遅[おそ]くて、仕事[しごと]がなかなか進[すす]まない。", "sentence_source": "generated"}, {"text": "川の流れが遅い所では、魚がよく集まる。", "target_word": "遅い", "complexity_tier": "T4", "furigana": "川[かわ]の流[なが]れが遅[おそ]い所[ところ]では、魚[さかな]がよく集[あつ]まる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "遅い", "label": "終止形"}, {"form": "遅く", "label": "連用形"}, {"form": "遅かった", "label": "過去形"}, {"form": "遅くない", "label": "否定形"}, {"form": "遅ければ", "label": "仮定形"}], "register": "中立(話し言葉・書き言葉)", "sense_fingerprint": "動きや速さがゆっくりで、時間がかかる(速度が遅い)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94f9763a-fbdb-4942-b840-f5e9ecdfccc6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36238, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "遅い", "is_correct": true, "explanation": "速さが遅いという意味で、「ので」の理由として文に合う。"}, {"text": "甘い", "is_correct": false, "explanation": "味を表す語で、電車の速さの理由にならない。"}, {"text": "辛い", "is_correct": false, "explanation": "味や感覚の語で、電車には当てはまらない。"}, {"text": "柔らかい", "is_correct": false, "explanation": "触感の語で、電車の速さの理由として成り立たない。"}], "explanations": {"遅い": "速さが遅いという意味で、「ので」の理由として文に合う。", "甘い": "味を表す語で、電車の速さの理由にならない。", "辛い": "味や感覚の語で、電車には当てはまらない。", "柔らかい": "触感の語で、電車の速さの理由として成り立たない。"}, "sentence_index": 0, "correct_answer": "遅い"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この天井は遅くて、背の高い人は頭をぶつける。", "explanation": "ここは〈低い〉（上までの高さが少ない）の意味。〈遅い〉は時間や速さの語で、高さには使わない。"}, {"text": "このナイフは切れ味が遅い。", "explanation": "ここは〈鈍い〉（切れ味が悪い）の意味。〈遅い〉は速さの語で、切れ味には使わない。"}, {"text": "この店の値段がとても遅かった。", "explanation": "ここは〈高い〉（値段が多い）の意味。〈遅い〉は時間や速さの語で、値段には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aad67c8f-e9b3-403f-a0ec-20e528ef9731') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36238, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "遅い", "is_correct": true, "explanation": "食べる速さが遅いという理由を表し、「から」に続いて文に合う。"}, {"text": "重い", "is_correct": false, "explanation": "重さを表す語で、食べる速さの説明にならない。"}, {"text": "高い", "is_correct": false, "explanation": "値段や高さの語で、食べ方の説明には使わない。"}, {"text": "寒い", "is_correct": false, "explanation": "温度の語で、「食べるのが寒い」は成り立たない。"}], "explanations": {"遅い": "食べる速さが遅いという理由を表し、「から」に続いて文に合う。", "重い": "重さを表す語で、食べる速さの説明にならない。", "高い": "値段や高さの語で、食べ方の説明には使わない。", "寒い": "温度の語で、「食べるのが寒い」は成り立たない。"}, "sentence_index": 6, "correct_answer": "遅い"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "このスープは遅くて、味がほとんどしない。", "explanation": "ここは〈薄い〉（味が淡い）の意味。〈遅い〉は時間や速さの語で、味には使わない。"}, {"text": "このロープは遅くて、力のある人でも切れない。", "explanation": "ここは〈太い〉（幅が大きい）の意味。〈遅い〉は時間や速さの語で、太さには使わない。"}, {"text": "このパンは遅くて、かみ切れない。", "explanation": "ここは〈硬い〉（かたさが強い）の意味。〈遅い〉は時間や速さの語で、かたさには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aad67c8f-e9b3-403f-a0ec-20e528ef9731') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36238, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "今日は、電車が遅くいので、駅で待った。", "corrected_sentence": "今日は、電車が遅いので、駅で待った。", "error_description": "い形容詞「遅い」の理由の形は「遅いので」。「遅くいので」は活用の誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "遅く", "is_correct": true, "explanation": "「走るのが遅くて」の「て」に続く連用形で、文に合う。"}, {"text": "遅い", "is_correct": false, "explanation": "終止形なので、「て」に続く文脈にはつながらない。"}, {"text": "遅かった", "is_correct": false, "explanation": "過去形なので、「て」で文を続ける部分に合わない。"}, {"text": "遅ければ", "is_correct": false, "explanation": "仮定形なので、事実を述べるこの文の形に合わない。"}], "correct_form": "遅く", "base_form": "遅い", "form_label": "連用形（〜て）", "sentence_index": 1, "explanations": {"遅く": "「走るのが遅くて」の「て」に続く連用形で、文に合う。", "遅い": "終止形なので、「て」に続く文脈にはつながらない。", "遅かった": "過去形なので、「て」で文を続ける部分に合わない。", "遅ければ": "仮定形なので、事実を述べるこの文の形に合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aad67c8f-e9b3-403f-a0ec-20e528ef9731') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36238, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "私は書くのが遅さので、宿題が終わらなかった。", "corrected_sentence": "私は書くのが遅いので、宿題が終わらなかった。", "error_description": "理由を表すには形容詞の「遅いので」。「遅さ」は名詞なので「遅さので」は誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "遅い", "is_correct": true, "explanation": "「計算が遅いので」の「ので」に続く終止形で、理由を述べる文に合う。"}, {"text": "遅く", "is_correct": false, "explanation": "連用形は「ので」の前に直接は続かず、この文の形に合わない。"}, {"text": "遅ければ", "is_correct": false, "explanation": "仮定形なので、「ので」の前には続かず文が成り立たない。"}, {"text": "遅さ", "is_correct": false, "explanation": "名詞なので「計算が遅さので」となり文が成り立たない。"}], "correct_form": "遅い", "base_form": "遅い", "form_label": "終止形（〜ので）", "sentence_index": 7, "explanations": {"遅い": "「計算が遅いので」の「ので」に続く終止形で、理由を述べる文に合う。", "遅く": "連用形は「ので」の前に直接は続かず、この文の形に合わない。", "遅ければ": "仮定形なので、「ので」の前には続かず文が成り立たない。", "遅さ": "名詞なので「計算が遅さので」となり文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aad67c8f-e9b3-403f-a0ec-20e528ef9731') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36239, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "早く", "is_correct": true, "explanation": "時刻の意味での対義語で、「遅く」と反対の関係にある。"}, {"text": "高く", "is_correct": false, "explanation": "対義語ではない。高さを表す副詞。"}, {"text": "大きく", "is_correct": false, "explanation": "対義語ではない。大きさを表す副詞。"}, {"text": "軽く", "is_correct": false, "explanation": "対義語ではない。重さを表す副詞。"}], "correct_answer": "早く", "explanations": {"早く": "時刻の意味での対義語で、「遅く」と反対の関係にある。", "高く": "対義語ではない。高さを表す副詞。", "大きく": "対義語ではない。大きさを表す副詞。", "軽く": "対義語ではない。重さを表す副詞。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aad67c8f-e9b3-403f-a0ec-20e528ef9731') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36239, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "早かった", "is_correct": true, "explanation": "時刻の意味での対義語で、「遅かった」と反対の関係にある。"}, {"text": "重かった", "is_correct": false, "explanation": "対義語ではない。重さを表す語。"}, {"text": "太かった", "is_correct": false, "explanation": "対義語ではない。太さを表す語。"}, {"text": "薄かった", "is_correct": false, "explanation": "対義語ではない。厚さや濃さを表す語。"}], "correct_answer": "早かった", "explanations": {"早かった": "時刻の意味での対義語で、「遅かった」と反対の関係にある。", "重かった": "対義語ではない。重さを表す語。", "太かった": "対義語ではない。太さを表す語。", "薄かった": "対義語ではない。厚さや濃さを表す語。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aad67c8f-e9b3-403f-a0ec-20e528ef9731') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36239, 3, 'prompt1_core', '{"pos": "形容詞", "semantic_class": "property", "definition": "あることや、あるものが、おこるまでに、ふつうより じかんが かかる こと。", "primary_collocate": null, "pronunciation": "おそい", "ipa": "osoi", "syllable_count": 3, "sentences": [{"text": "今日は帰りが遅くなります。", "target_word": "遅く", "complexity_tier": "T2", "furigana": "今日[きょう]は帰[かえ]りが遅[おそ]くなります。", "sentence_source": "generated"}, {"text": "夜遅い時間に電話をしてごめんなさい。", "target_word": "遅い", "complexity_tier": "T3", "furigana": "夜[よる]遅[おそ]い時間[じかん]に電話[でんわ]をしてごめんなさい。", "sentence_source": "generated"}, {"text": "遅い時間なので、もう寝ましょう。", "target_word": "遅い", "complexity_tier": "T3", "furigana": "遅[おそ]い時間[じかん]なので、もう寝[ね]ましょう。", "sentence_source": "generated"}, {"text": "寝坊して、朝ごはんが遅くなった。", "target_word": "遅く", "complexity_tier": "T3", "furigana": "寝坊[ねぼう]して、朝[あさ]ごはんが遅[おそ]くなった。", "sentence_source": "generated"}, {"text": "今年は春が来るのが遅い。", "target_word": "遅い", "complexity_tier": "T3", "furigana": "今年[ことし]は春[はる]が来[く]るのが遅[おそ]い。", "sentence_source": "generated"}, {"text": "今から行っても遅いですよ、もう終わりました。", "target_word": "遅い", "complexity_tier": "T3", "furigana": "今[いま]から行[い]っても遅[おそ]いですよ、もう終[お]わりました。", "sentence_source": "generated"}, {"text": "遅い昼ごはんを食べて、そのまま昼寝をした。", "target_word": "遅い", "complexity_tier": "T3", "furigana": "遅[おそ]い昼[ひる]ごはんを食[た]べて、そのまま昼寝[ひるね]をした。", "sentence_source": "generated"}, {"text": "今年は雪が降るのが遅かったので、スキー場はまだ開いていない。", "target_word": "遅かった", "complexity_tier": "T4", "furigana": "今年[ことし]は雪[ゆき]が降[ふ]るのが遅[おそ]かったので、スキー場[じょう]はまだ開[あ]いていない。", "sentence_source": "generated"}, {"text": "夜遅くまで勉強していて、朝起きられなかった。", "target_word": "遅く", "complexity_tier": "T3", "furigana": "夜[よる]遅[おそ]くまで勉強[べんきょう]していて、朝[あさ]起[お]きられなかった。", "sentence_source": "generated"}, {"text": "駅に着くのが遅かったので、終電に乗れなかった。", "target_word": "遅かった", "complexity_tier": "T3", "furigana": "駅[えき]に着[つ]くのが遅[おそ]かったので、終電[しゅうでん]に乗[の]れなかった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "遅い", "label": "終止形"}, {"form": "遅く", "label": "連用形"}, {"form": "遅かった", "label": "過去形"}, {"form": "遅くなる", "label": "変化表現"}, {"form": "遅ければ", "label": "仮定形"}], "register": "中立(話し言葉・書き言葉)", "sense_fingerprint": "予定や普通の時刻より後になる(時刻・時期が遅い)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94f9763a-fbdb-4942-b840-f5e9ecdfccc6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36239, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "遅く", "is_correct": true, "explanation": "帰りの時刻が遅くなるという意味で、「なります」に合う。"}, {"text": "白く", "is_correct": false, "explanation": "色の語で、帰りの時刻の変化には合わない。"}, {"text": "広く", "is_correct": false, "explanation": "面積の語で、時刻の文脈に合わない。"}, {"text": "冷たく", "is_correct": false, "explanation": "温度や態度の語で、「帰りが冷たくなる」とは言わない。"}], "explanations": {"遅く": "帰りの時刻が遅くなるという意味で、「なります」に合う。", "白く": "色の語で、帰りの時刻の変化には合わない。", "広く": "面積の語で、時刻の文脈に合わない。", "冷たく": "温度や態度の語で、「帰りが冷たくなる」とは言わない。"}, "sentence_index": 0, "correct_answer": "遅く"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この荷物は遅くて、一人では持ち上げられない。", "explanation": "ここは〈重い〉（重さが大きい）の意味。〈遅い〉は時間や速さの語で、重さには使わない。"}, {"text": "この店の値段が遅くなった。", "explanation": "ここは〈低くなる〉（値段が下がる）の意味。〈遅い〉は時刻の語で、値段には使わない。"}, {"text": "熱が遅くなった。", "explanation": "ここは〈高くなる〉（熱が上がる）の意味。〈遅い〉は時刻の語で、体温には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aad67c8f-e9b3-403f-a0ec-20e528ef9731') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36239, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "遅い", "is_correct": true, "explanation": "時間が遅い昼食の意味で、「昼ごはん」を修飾して文に合う。"}, {"text": "青い", "is_correct": false, "explanation": "色の語で、食事の時間を表さない。"}, {"text": "黒い", "is_correct": false, "explanation": "色の語で、昼ごはんの時間の説明にならない。"}, {"text": "丸い", "is_correct": false, "explanation": "形の語で、食事の時刻を表せない。"}], "explanations": {"遅い": "時間が遅い昼食の意味で、「昼ごはん」を修飾して文に合う。", "青い": "色の語で、食事の時間を表さない。", "黒い": "色の語で、昼ごはんの時間の説明にならない。", "丸い": "形の語で、食事の時刻を表せない。"}, "sentence_index": 6, "correct_answer": "遅い"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この通路は遅くて、人がすれ違えない。", "explanation": "ここは〈狭い〉（幅が小さい）の意味。〈遅い〉は時間や速さの語で、幅には使わない。"}, {"text": "スープが遅かった。", "explanation": "ここは〈薄い〉（味が淡い）の意味。〈遅い〉は時刻や速さの語で、味には使わない。"}, {"text": "部屋が遅かった。", "explanation": "ここは〈大きい〉（広さ）の意味。〈遅い〉は時刻や速さの語で、広さには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aad67c8f-e9b3-403f-a0ec-20e528ef9731') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36239, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "残業で、帰りがずっと遅いなった。", "corrected_sentence": "残業で、帰りがずっと遅くなった。", "error_description": "「なる」に続けるときは連用形「遅く」。「遅いなった」は活用の誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "遅い", "is_correct": true, "explanation": "「夜遅い時間」と名詞を修飾する連体形で、文に合う。"}, {"text": "遅く", "is_correct": false, "explanation": "連用形は名詞を直接修飾できず、「時間」の前に置けない。"}, {"text": "遅さ", "is_correct": false, "explanation": "名詞なので、「時間」の前に直接は続かず文が成り立たない。"}, {"text": "遅ければ", "is_correct": false, "explanation": "仮定形は名詞を修飾できず、この文の形に合わない。"}], "correct_form": "遅い", "base_form": "遅い", "form_label": "連体形（名詞の前）", "sentence_index": 1, "explanations": {"遅い": "「夜遅い時間」と名詞を修飾する連体形で、文に合う。", "遅く": "連用形は名詞を直接修飾できず、「時間」の前に置けない。", "遅さ": "名詞なので、「時間」の前に直接は続かず文が成り立たない。", "遅ければ": "仮定形は名詞を修飾できず、この文の形に合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aad67c8f-e9b3-403f-a0ec-20e528ef9731') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36239, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "今夜遅れの時間に電話をしてごめんなさい。", "corrected_sentence": "今夜遅い時間に電話をしてごめんなさい。", "error_description": "「時間」を修飾する形は「遅い」。「遅れ」は動詞「遅れる」の名詞形で、語が違う。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "遅かった", "is_correct": true, "explanation": "過去の出来事の理由を述べる過去形で、「雪が降るのが遅かった」に合う。"}, {"text": "遅くて", "is_correct": false, "explanation": "て形は「ので」の前に続かず、「降るのが遅くてので」は文が成り立たない。"}, {"text": "遅かろう", "is_correct": false, "explanation": "推量の形で、理由を表す「ので」の前には続かず文が成り立たない。"}, {"text": "遅まき", "is_correct": false, "explanation": "名詞なので、「降るのが遅まきので」と続けると文が成り立たない。"}], "correct_form": "遅かった", "base_form": "遅い", "form_label": "過去形", "sentence_index": 7, "explanations": {"遅かった": "過去の出来事の理由を述べる過去形で、「雪が降るのが遅かった」に合う。", "遅くて": "て形は「ので」の前に続かず、「降るのが遅くてので」は文が成り立たない。", "遅かろう": "推量の形で、理由を表す「ので」の前には続かず文が成り立たない。", "遅まき": "名詞なので、「降るのが遅まきので」と続けると文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aad67c8f-e9b3-403f-a0ec-20e528ef9731') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
