INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36240, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "まちがいがあっても、こまらないこと。", "primary_collocate": null, "pronunciation": "だいじょうぶ", "ipa": "daidʑoːbɯ", "syllable_count": 5, "sentences": [{"text": "間違えても大丈夫ですから、自分の考えを話してください。", "target_word": "大丈夫", "complexity_tier": "T3", "furigana": "間違[まちが]えても大丈夫[だいじょうぶ]ですから、自分[じぶん]の考[かんが]えを話[はな]してください。", "sentence_source": "generated"}, {"text": "失敗しても大丈夫だと言われて、安心して挑戦した。", "target_word": "大丈夫", "complexity_tier": "T3", "furigana": "失敗[しっぱい]しても大丈夫[だいじょうぶ]だと言[い]われて、安心[あんしん]して挑戦[ちょうせん]した。", "sentence_source": "generated"}, {"text": "多少遅れても大丈夫なので、慌てずに来てください。", "target_word": "大丈夫", "complexity_tier": "T3", "furigana": "多少[たしょう]遅[おく]れても大丈夫[だいじょうぶ]なので、慌[あわ]てずに来[き]てください。", "sentence_source": "generated"}, {"text": "字が汚くても大丈夫ですから、最後まで書いてください。", "target_word": "大丈夫", "complexity_tier": "T3", "furigana": "字[じ]が汚[きたな]くても大丈夫[だいじょうぶ]ですから、最後[さいご]まで書[か]いてください。", "sentence_source": "generated"}, {"text": "ちょっと失敗しても大丈夫な練習なので、気楽にやってみよう。", "target_word": "大丈夫", "complexity_tier": "T3", "furigana": "ちょっと失敗[しっぱい]しても大丈夫[だいじょうぶ]な練習[れんしゅう]なので、気楽[きらく]にやってみよう。", "sentence_source": "generated"}, {"text": "日本語が下手でも大丈夫だと思って、話しかけてみた。", "target_word": "大丈夫", "complexity_tier": "T3", "furigana": "日本語[にほんご]が下手[へた]でも大丈夫[だいじょうぶ]だと思[おも]って、話[はな]しかけてみた。", "sentence_source": "generated"}, {"text": "少しくらい間違っても大丈夫だから、大きな声で読んでみよう。", "target_word": "大丈夫", "complexity_tier": "T3", "furigana": "少[すこ]しくらい間違[まちが]っても大丈夫[だいじょうぶ]だから、大[おお]きな声[こえ]で読[よ]んでみよう。", "sentence_source": "generated"}, {"text": "全部わからなくても大丈夫で、大事なところだけ覚えればいい。", "target_word": "大丈夫", "complexity_tier": "T3", "furigana": "全部[ぜんぶ]わからなくても大丈夫[だいじょうぶ]で、大事[だいじ]なところだけ覚[おぼ]えればいい。", "sentence_source": "generated"}, {"text": "約束の時間に少し遅れても大丈夫だと、友達が言ってくれた。", "target_word": "大丈夫", "complexity_tier": "T3", "furigana": "約束[やくそく]の時間[じかん]に少[すこ]し遅[おく]れても大丈夫[だいじょうぶ]だと、友達[ともだち]が言[い]ってくれた。", "sentence_source": "generated"}, {"text": "答えを間違えたけれど、先生が笑ってくれたので大丈夫だった。", "target_word": "大丈夫", "complexity_tier": "T3", "furigana": "答[こた]えを間違[まちが]えたけれど、先生[せんせい]が笑[わら]ってくれたので大丈夫[だいじょうぶ]だった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "大丈夫だ", "label": "断定形"}, {"form": "大丈夫で", "label": "連用形（で）"}, {"form": "大丈夫な", "label": "連体形"}, {"form": "大丈夫だった", "label": "過去形"}, {"form": "大丈夫ではない", "label": "否定形"}], "register": "neutral", "sense_fingerprint": "間違いや失敗があっても困らない、許される", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5f6c10e-59f5-434b-8d2f-b32eae92b808') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36240, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "大丈夫", "is_correct": true, "explanation": "「問題がなく困らない」の意味で、間違えても困らないという文脈に合う。"}, {"text": "大切", "is_correct": false, "explanation": "「大切」は重要さを表す。間違えても困らない、という文脈には合わない。"}, {"text": "丈夫", "is_correct": false, "explanation": "「丈夫」は頑丈さや健康を表す。失敗しても平気という文脈には合わない。"}, {"text": "上手", "is_correct": false, "explanation": "「上手」は技能の巧みさを表す。間違えても困らないという意味にはならない。"}], "explanations": {"大丈夫": "「問題がなく困らない」の意味で、間違えても困らないという文脈に合う。", "大切": "「大切」は重要さを表す。間違えても困らない、という文脈には合わない。", "丈夫": "「丈夫」は頑丈さや健康を表す。失敗しても平気という文脈には合わない。", "上手": "「上手」は技能の巧みさを表す。間違えても困らないという意味にはならない。"}, "sentence_index": 0, "correct_answer": "大丈夫"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "昨夜の大丈夫な事故で、三時間も道路が止まった。", "explanation": "ここは〈ひどい〉（被害が大きい）の意味。大丈夫は「問題がないこと」なので、重大な事故には使えず「大きな事故」と言う。"}, {"text": "昨夜の大丈夫な地震で、家具がすべて倒れた。", "explanation": "ここは〈激しい〉（揺れが強い）の意味。大丈夫は「問題がないこと」なので、強い揺れには使えず「激しい地震」と言う。"}, {"text": "この写真は私にとって大丈夫な思い出だ。", "explanation": "ここは〈大事〉（大切で重要）の意味。大丈夫は「問題がないこと」なので、大切な思い出という意味では使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1aff041-8e12-4be2-95f9-036736301c3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36240, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "大丈夫", "is_correct": true, "explanation": "「間違っても問題ない」の意味で、「少しくらい間違っても…だから」に入る。"}, {"text": "派手", "is_correct": false, "explanation": "「派手」は目立つさまを表す。間違っても問題ないという文脈には合わない。"}, {"text": "静か", "is_correct": false, "explanation": "「静か」は音が少ない状態。間違えてもよいという意味にはならない。"}, {"text": "得意", "is_correct": false, "explanation": "「得意」は得意分野を表す。間違えても困らないという文脈には合わない。"}], "explanations": {"大丈夫": "「間違っても問題ない」の意味で、「少しくらい間違っても…だから」に入る。", "派手": "「派手」は目立つさまを表す。間違っても問題ないという文脈には合わない。", "静か": "「静か」は音が少ない状態。間違えてもよいという意味にはならない。", "得意": "「得意」は得意分野を表す。間違えても困らないという文脈には合わない。"}, "sentence_index": 6, "correct_answer": "大丈夫"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "試合は大丈夫な結果で、皆が悔しがった。", "explanation": "ここは〈残念〉（期待が外れて悔しい）の意味。大丈夫は「問題がないこと」なので、悔しい結果には使えず「残念な結果」と言う。"}, {"text": "この試合は大丈夫に勝てる。", "explanation": "ここは〈確実に〉（間違いなく）の副詞用法。大丈夫は副詞として使えず、「確実に勝てる」と言う。"}, {"text": "昨夜の大丈夫な被害で、町の半分が浸水した。", "explanation": "ここは〈深刻〉（被害が重い）の意味。大丈夫は「問題がないこと」なので、重い被害には使えず「深刻な被害」と言う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1aff041-8e12-4be2-95f9-036736301c3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36240, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "お金は足りているから、大丈夫なです。", "corrected_sentence": "お金は足りているから、大丈夫です。", "error_description": "形状詞「大丈夫」は「大丈夫です」の形で述語になる。「大丈夫なです」の「な」は連体形で、後ろに名詞がないので誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "大丈夫", "is_correct": true, "explanation": "「大丈夫だと」の語幹。「だ」の前に来る形で、ここに入る。"}, {"text": "大丈夫な", "is_correct": false, "explanation": "連体形で、後ろに名詞が続く形。「だと」の前には来ない。"}, {"text": "大丈夫で", "is_correct": false, "explanation": "連用形の「で」。「だと」とは続かないので入らない。"}, {"text": "大丈夫だった", "is_correct": false, "explanation": "過去の形。ここは過去ではなく、失敗しても問題がないという条件を述べている。"}], "correct_form": "大丈夫", "base_form": "大丈夫だ", "form_label": "語幹（「だ」の前）", "sentence_index": 1, "explanations": {"大丈夫": "「大丈夫だと」の語幹。「だ」の前に来る形で、ここに入る。", "大丈夫な": "連体形で、後ろに名詞が続く形。「だと」の前には来ない。", "大丈夫で": "連用形の「で」。「だと」とは続かないので入らない。", "大丈夫だった": "過去の形。ここは過去ではなく、失敗しても問題がないという条件を述べている。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1aff041-8e12-4be2-95f9-036736301c3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36240, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "暖房がよく効いているので、寒い日でも大丈夫なだ。", "corrected_sentence": "暖房がよく効いているので、寒い日でも大丈夫だ。", "error_description": "「大丈夫」の断定形は「大丈夫だ」。「大丈夫なだ」の「な」は連体形で、ここでは余分。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "大丈夫", "is_correct": true, "explanation": "「大丈夫で」の語幹。「で」の前に来る形で、ここに入る。"}, {"text": "大丈夫ではない", "is_correct": false, "explanation": "否定形。「大丈夫ではなくても」とはならないので入らない。"}, {"text": "大丈夫だろう", "is_correct": false, "explanation": "推量形。「で」が必要な位置には入らない。"}, {"text": "大丈夫じゃない", "is_correct": false, "explanation": "くだけた否定形。「で」と続かないので入らない。"}], "correct_form": "大丈夫", "base_form": "大丈夫だ", "form_label": "語幹（「で」の前）", "sentence_index": 7, "explanations": {"大丈夫": "「大丈夫で」の語幹。「で」の前に来る形で、ここに入る。", "大丈夫ではない": "否定形。「大丈夫ではなくても」とはならないので入らない。", "大丈夫だろう": "推量形。「で」が必要な位置には入らない。", "大丈夫じゃない": "くだけた否定形。「で」と続かないので入らない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1aff041-8e12-4be2-95f9-036736301c3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
