INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36241, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "問題がない状態。心配する必要がないこと。", "primary_collocate": null, "pronunciation": "だいじょうぶ", "ipa": "daidʑoːbɯ", "syllable_count": 5, "sentences": [{"text": "医者に診てもらったら、大丈夫だと言われて安心した。", "target_word": "大丈夫", "complexity_tier": "T3", "furigana": "医者[いしゃ]に診[み]てもらったら、大丈夫[だいじょうぶ]だと言[い]われて安心[あんしん]した。", "sentence_source": "generated"}, {"text": "傘を持ってきたから、雨が降っても大丈夫だ。", "target_word": "大丈夫", "complexity_tier": "T3", "furigana": "傘[かさ]を持[も]ってきたから、雨[あめ]が降[ふ]っても大丈夫[だいじょうぶ]だ。", "sentence_source": "generated"}, {"text": "この橋は新しいので、重い車が通っても大丈夫です。", "target_word": "大丈夫", "complexity_tier": "T3", "furigana": "この橋[はし]は新[あたら]しいので、重[おも]い車[くるま]が通[とお]っても大丈夫[だいじょうぶ]です。", "sentence_source": "generated"}, {"text": "熱は下がったので、もう大丈夫です。", "target_word": "大丈夫", "complexity_tier": "T3", "furigana": "熱[ねつ]は下[さ]がったので、もう大丈夫[だいじょうぶ]です。", "sentence_source": "generated"}, {"text": "重い荷物は私が持つから、大丈夫だよ。", "target_word": "大丈夫", "complexity_tier": "T3", "furigana": "重[おも]い荷物[にもつ]は私[わたし]が持[も]つから、大丈夫[だいじょうぶ]だよ。", "sentence_source": "generated"}, {"text": "忘れ物がないか調べたので、もう大丈夫だ。", "target_word": "大丈夫", "complexity_tier": "T3", "furigana": "忘[わす]れ物[もの]がないか調[しら]べたので、もう大丈夫[だいじょうぶ]だ。", "sentence_source": "generated"}, {"text": "地図があるから、初めての町でも大丈夫だと思う。", "target_word": "大丈夫", "complexity_tier": "T3", "furigana": "地図[ちず]があるから、初[はじ]めての町[まち]でも大丈夫[だいじょうぶ]だと思[おも]う。", "sentence_source": "generated"}, {"text": "この犬は優しいから、触っても大丈夫ですよ。", "target_word": "大丈夫", "complexity_tier": "T3", "furigana": "この犬[いぬ]は優[やさ]しいから、触[さわ]っても大丈夫[だいじょうぶ]ですよ。", "sentence_source": "generated"}, {"text": "薬を飲んだので、明日の試合に出ても大丈夫だろう。", "target_word": "大丈夫", "complexity_tier": "T3", "furigana": "薬[くすり]を飲[の]んだので、明日[あした]の試合[しあい]に出[で]ても大丈夫[だいじょうぶ]だろう。", "sentence_source": "generated"}, {"text": "彼女は「心配しなくても大丈夫」と笑って言った。", "target_word": "大丈夫", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は「心配[しんぱい]しなくても大丈夫[だいじょうぶ]」と笑[わら]って言[い]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "大丈夫だ", "label": "断定形"}, {"form": "大丈夫で", "label": "連用形（で）"}, {"form": "大丈夫な", "label": "連体形"}, {"form": "大丈夫だった", "label": "過去形"}, {"form": "大丈夫ではない", "label": "否定形"}], "register": "neutral", "sense_fingerprint": "問題がなく安全で、心配しなくてよい状態", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5f6c10e-59f5-434b-8d2f-b32eae92b808') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36241, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "大丈夫", "is_correct": true, "explanation": "「問題ない」の意味で、医者に診てもらった結果の判断として合う。"}, {"text": "派手", "is_correct": false, "explanation": "「派手」は見た目の華やかさを表す。医者の判断としては合わない。"}, {"text": "静か", "is_correct": false, "explanation": "「静か」は落ち着いた様子を表す。診断の言葉としては合わない。"}, {"text": "上手", "is_correct": false, "explanation": "「上手」は技能の巧みさを表す。診察の結果を言う文脈には合わない。"}], "explanations": {"大丈夫": "「問題ない」の意味で、医者に診てもらった結果の判断として合う。", "派手": "「派手」は見た目の華やかさを表す。医者の判断としては合わない。", "静か": "「静か」は落ち着いた様子を表す。診断の言葉としては合わない。", "上手": "「上手」は技能の巧みさを表す。診察の結果を言う文脈には合わない。"}, "sentence_index": 0, "correct_answer": "大丈夫"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夜中まで続く大丈夫な騒音に、ずっと眠れなかった。", "explanation": "ここは〈うるさい〉（音が大きく迷惑）の意味。大丈夫は「問題がないこと」なので、迷惑な騒音には使えず「うるさい」と言う。"}, {"text": "この薬は大丈夫な副作用が多く、飲むのをやめる人も多い。", "explanation": "ここは〈有害〉（体に悪い）の意味。大丈夫は「問題がないこと」なので、体に悪い副作用には使えず「有害な副作用」と言う。"}, {"text": "この橋は大丈夫な危険で、通る車はいつも事故を起こす。", "explanation": "ここは〈危険〉（危ない）の意味。大丈夫は「問題がないこと」なので、危ない状態には使えず「危険な橋」と言う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1aff041-8e12-4be2-95f9-036736301c3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36241, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "大丈夫", "is_correct": true, "explanation": "「問題なく心配ない」の意味で、「初めての町でも…だと思う」に入る。"}, {"text": "大切", "is_correct": false, "explanation": "「大切」は重要さを表す。初めての町に行けるかという判断には合わない。"}, {"text": "立派", "is_correct": false, "explanation": "「立派」は見事さを表す。行けるかどうかの判断には合わない。"}, {"text": "丁寧", "is_correct": false, "explanation": "「丁寧」は態度の細やかさを表す。町に行けるかという文脈には合わない。"}], "explanations": {"大丈夫": "「問題なく心配ない」の意味で、「初めての町でも…だと思う」に入る。", "大切": "「大切」は重要さを表す。初めての町に行けるかという判断には合わない。", "立派": "「立派」は見事さを表す。行けるかどうかの判断には合わない。", "丁寧": "「丁寧」は態度の細やかさを表す。町に行けるかという文脈には合わない。"}, "sentence_index": 6, "correct_answer": "大丈夫"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "昨夜の大丈夫な雨で、川が溢れた。", "explanation": "ここは〈ひどい〉（激しく悪い）の意味。大丈夫は「問題がないこと」なので、激しい雨には使えず「ひどい雨」と言う。"}, {"text": "この試合は大丈夫に勝てる。", "explanation": "ここは〈確実に〉（間違いなく）の副詞用法。大丈夫は副詞として使えない。"}, {"text": "この写真は私にとって大丈夫な思い出だ。", "explanation": "ここは〈大事〉（大切で重要）の意味。大丈夫は問題がないことを表すので、大切な思い出とは言えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1aff041-8e12-4be2-95f9-036736301c3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36241, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "寝不足だけれど、運転は大丈夫ではです。", "corrected_sentence": "寝不足だけれど、運転は大丈夫です。", "error_description": "「では」の後に「です」を重ねると二重の断定になり誤り。「では」を取った「大丈夫です」が正しい。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "大丈夫", "is_correct": true, "explanation": "「大丈夫だ」の語幹。「だ」の前に来る形で、ここに入る。"}, {"text": "大丈夫な", "is_correct": false, "explanation": "連体形。後ろに名詞が続く形で、文末には入らない。"}, {"text": "大丈夫で", "is_correct": false, "explanation": "連用形の「で」。文末の「だ」の位置には入らない。"}, {"text": "大丈夫だった", "is_correct": false, "explanation": "過去の形。ここは現在の見込みを述べている。"}], "correct_form": "大丈夫", "base_form": "大丈夫だ", "form_label": "語幹（「だ」の前）", "sentence_index": 1, "explanations": {"大丈夫": "「大丈夫だ」の語幹。「だ」の前に来る形で、ここに入る。", "大丈夫な": "連体形。後ろに名詞が続く形で、文末には入らない。", "大丈夫で": "連用形の「で」。文末の「だ」の位置には入らない。", "大丈夫だった": "過去の形。ここは現在の見込みを述べている。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1aff041-8e12-4be2-95f9-036736301c3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36241, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この子は人懐っこいから、触っても大丈夫くないです。", "corrected_sentence": "この子は人懐っこいから、触っても大丈夫です。", "error_description": "「大丈夫」の否定は「大丈夫ではない」「大丈夫じゃない」。「くない」は形容詞の否定形で、形状詞には続かない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "大丈夫", "is_correct": true, "explanation": "「大丈夫です」の語幹。「です」の前に来る形で、ここに入る。"}, {"text": "大丈夫だろう", "is_correct": false, "explanation": "推量形。断定の「です」の位置には入らない。"}, {"text": "大丈夫だ", "is_correct": false, "explanation": "「だ」は「です」と並ばないので、「です」の前には入らない。"}, {"text": "大丈夫なら", "is_correct": false, "explanation": "仮定形。「です」とは続かないので入らない。"}], "correct_form": "大丈夫", "base_form": "大丈夫だ", "form_label": "語幹（「です」の前）", "sentence_index": 7, "explanations": {"大丈夫": "「大丈夫です」の語幹。「です」の前に来る形で、ここに入る。", "大丈夫だろう": "推量形。断定の「です」の位置には入らない。", "大丈夫だ": "「だ」は「です」と並ばないので、「です」の前には入らない。", "大丈夫なら": "仮定形。「です」とは続かないので入らない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1aff041-8e12-4be2-95f9-036736301c3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36246, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "不味い", "is_correct": true, "explanation": "「味が悪い」の意味で、「旨い」の対義語。"}, {"text": "甘い", "is_correct": false, "explanation": "味の種類を表し、「旨い」の対義語ではない。"}, {"text": "辛い", "is_correct": false, "explanation": "味の種類を表し、「旨い」の対義語ではない。"}, {"text": "高い", "is_correct": false, "explanation": "値段の高さを表し、「旨い」の対義語ではない。"}], "correct_answer": "不味い", "explanations": {"不味い": "「味が悪い」の意味で、「旨い」の対義語。", "甘い": "味の種類を表し、「旨い」の対義語ではない。", "辛い": "味の種類を表し、「旨い」の対義語ではない。", "高い": "値段の高さを表し、「旨い」の対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1aff041-8e12-4be2-95f9-036736301c3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36246, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "不味い", "is_correct": true, "explanation": "「味が悪い」の意味で、「旨い」の対義語。"}, {"text": "冷たい", "is_correct": false, "explanation": "温度を表し、「旨い」の対義語ではない。"}, {"text": "太い", "is_correct": false, "explanation": "太さを表し、「旨い」の対義語ではない。"}, {"text": "広い", "is_correct": false, "explanation": "広さを表し、「旨い」の対義語ではない。"}], "correct_answer": "不味い", "explanations": {"不味い": "「味が悪い」の意味で、「旨い」の対義語。", "冷たい": "温度を表し、「旨い」の対義語ではない。", "太い": "太さを表し、「旨い」の対義語ではない。", "広い": "広さを表し、「旨い」の対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1aff041-8e12-4be2-95f9-036736301c3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36246, 3, 'prompt1_core', '{"pos": "形容詞", "semantic_class": "property", "definition": "たべもののあじがとてもいいこと。", "primary_collocate": null, "pronunciation": "うまい", "ipa": "ɯmai", "syllable_count": 3, "sentences": [{"text": "この店のラーメンは安くて旨い。", "target_word": "旨い", "complexity_tier": "T3", "furigana": "この店[みせ]のラーメンは安[やす]くて旨[うま]い。", "sentence_source": "generated"}, {"text": "仕事のあとに飲む冷たいビールは旨い。", "target_word": "旨い", "complexity_tier": "T3", "furigana": "仕事[しごと]のあとに飲[の]む冷[つめ]たいビールは旨[うま]い。", "sentence_source": "generated"}, {"text": "母が作った煮物は、どこの店より旨いと思う。", "target_word": "旨い", "complexity_tier": "T3", "furigana": "母[はは]が作[つく]った煮物[にもの]は、どこの店[みせ]より旨[うま]いと思[おも]う。", "sentence_source": "generated"}, {"text": "新しいお米は甘みがあって、おかずがなくても旨い。", "target_word": "旨い", "complexity_tier": "T3", "furigana": "新[あたら]しいお米[こめ]は甘[あま]みがあって、おかずがなくても旨[うま]い。", "sentence_source": "generated"}, {"text": "朝から何も食べていないので、おにぎりが旨かった。", "target_word": "旨かった", "complexity_tier": "T3", "furigana": "朝[あさ]から何[なに]も食[た]べていないので、おにぎりが旨[うま]かった。", "sentence_source": "generated"}, {"text": "焼きたてのパンは香りがよくて、とても旨い。", "target_word": "旨い", "complexity_tier": "T3", "furigana": "焼[や]きたてのパンは香[かお]りがよくて、とても旨[うま]い。", "sentence_source": "generated"}, {"text": "友達に教わった店の魚は、びっくりするほど旨かった。", "target_word": "旨かった", "complexity_tier": "T3", "furigana": "友達[ともだち]に教[おそ]わった店[みせ]の魚[さかな]は、びっくりするほど旨[うま]かった。", "sentence_source": "generated"}, {"text": "旨いものを食べると、疲れがすぐに取れる。", "target_word": "旨い", "complexity_tier": "T3", "furigana": "旨[うま]いものを食[た]べると、疲[つか]れがすぐに取[と]れる。", "sentence_source": "generated"}, {"text": "この水は冷たくて旨いから、もう一杯ください。", "target_word": "旨い", "complexity_tier": "T3", "furigana": "この水[みず]は冷[つめ]たくて旨[うま]いから、もう一杯[いっぱい]ください。", "sentence_source": "generated"}, {"text": "寒い日に食べる鍋は、体が温まって旨い。", "target_word": "旨い", "complexity_tier": "T3", "furigana": "寒[さむ]い日[ひ]に食[た]べる鍋[なべ]は、体[からだ]が温[あたた]まって旨[うま]い。", "sentence_source": "generated"}], "morphological_forms": [{"form": "旨い", "label": "終止形"}, {"form": "旨かった", "label": "過去形"}, {"form": "旨く", "label": "連用形"}, {"form": "旨くない", "label": "否定形"}, {"form": "旨ければ", "label": "仮定形"}], "register": "colloquial", "sense_fingerprint": "食べ物や飲み物の味が非常によい", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5f6c10e-59f5-434b-8d2f-b32eae92b808') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36246, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "旨い", "is_correct": true, "explanation": "「味がよい」の意味で、「安くて…」の後に味の評価として入る。"}, {"text": "硬い", "is_correct": false, "explanation": "「硬い」は食感や固さを表す。「安くて」の後に味の評価として続かない。"}, {"text": "重い", "is_correct": false, "explanation": "「重い」は重さを表す。料理の味の評価としては合わない。"}, {"text": "軽い", "is_correct": false, "explanation": "「軽い」は重さや軽やかさを表す。味の評価としては合わない。"}], "explanations": {"旨い": "「味がよい」の意味で、「安くて…」の後に味の評価として入る。", "硬い": "「硬い」は食感や固さを表す。「安くて」の後に味の評価として続かない。", "重い": "「重い」は重さを表す。料理の味の評価としては合わない。", "軽い": "「軽い」は重さや軽やかさを表す。味の評価としては合わない。"}, "sentence_index": 0, "correct_answer": "旨い"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この部屋は旨い広さで、四人で寝られる。", "explanation": "ここは〈広い〉（場所の面積が大きい）の意味。旨いは味がよいことなので、部屋の広さには使えず「広い」と言う。"}, {"text": "その薬は旨くて、子どもは毎日飲むのを嫌がる。", "explanation": "ここは〈苦い〉（味が苦く飲みにくい）の意味。旨いは味がよいことなので、苦い薬には使えず「苦い」と言う。"}, {"text": "この部屋の色は旨くて、とても明るい。", "explanation": "ここは〈明るい〉（光が多く色が鮮やか）の意味。旨いは味の評価なので、色の明るさには使えず「明るい」と言う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1aff041-8e12-4be2-95f9-036736301c3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36246, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "旨かった", "is_correct": true, "explanation": "過去の味の評価で、「びっくりするほど…」に入る。"}, {"text": "眠かった", "is_correct": false, "explanation": "「眠い」は眠気を表す。魚の味の評価には合わない。"}, {"text": "寂しかった", "is_correct": false, "explanation": "「寂しい」は気持ちを表す。魚の味の評価には合わない。"}, {"text": "うるさかった", "is_correct": false, "explanation": "「うるさい」は音の大きさを表す。魚の味や様子には合わない。"}], "explanations": {"旨かった": "過去の味の評価で、「びっくりするほど…」に入る。", "眠かった": "「眠い」は眠気を表す。魚の味の評価には合わない。", "寂しかった": "「寂しい」は気持ちを表す。魚の味の評価には合わない。", "うるさかった": "「うるさい」は音の大きさを表す。魚の味や様子には合わない。"}, "sentence_index": 6, "correct_answer": "旨かった"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "昨夜の旨い雨で、一晩中眠れなかった。", "explanation": "ここは〈ひどい〉（激しく悪い）の意味。旨いは味の評価なので、激しい雨の意味では使えない。"}, {"text": "旅行は旨かった。", "explanation": "ここは〈楽しい〉の意味。旨いは食べ物の味について言うので、旅の感想には使わない。"}, {"text": "先生は採点が旨い。", "explanation": "ここは〈甘い〉（評価が緩い）の意味。旨いは味の評価なので、採点の厳しさには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1aff041-8e12-4be2-95f9-036736301c3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36246, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "昨日食べた焼き鳥は、とても旨いった。", "corrected_sentence": "昨日食べた焼き鳥は、とても旨かった。", "error_description": "形容詞「旨い」の過去形は「旨かった」。「旨いった」は誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "旨い", "is_correct": true, "explanation": "「旨い」の終止形。文末の述語として入る。"}, {"text": "旨くて", "is_correct": false, "explanation": "て形。文を終わらせられないので入らない。"}, {"text": "旨く", "is_correct": false, "explanation": "連用形。文末の述語にはならない。"}, {"text": "旨ければ", "is_correct": false, "explanation": "仮定形。文末の述語にはならない。"}], "correct_form": "旨い", "base_form": "旨い", "form_label": "終止形", "sentence_index": 1, "explanations": {"旨い": "「旨い」の終止形。文末の述語として入る。", "旨くて": "て形。文を終わらせられないので入らない。", "旨く": "連用形。文末の述語にはならない。", "旨ければ": "仮定形。文末の述語にはならない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1aff041-8e12-4be2-95f9-036736301c3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36246, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "祖母が作った煮物は、とても旨いだった。", "corrected_sentence": "祖母が作った煮物は、とても旨かった。", "error_description": "形容詞「旨い」には「だ」は続かない。過去形は「旨かった」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "旨い", "is_correct": true, "explanation": "連体形。後ろの名詞「もの」を修飾する形で、ここに入る。"}, {"text": "旨そう", "is_correct": false, "explanation": "「そう」は形容動詞型で、名詞「もの」を修飾するには「旨そうな」が必要。"}, {"text": "旨み", "is_correct": false, "explanation": "名詞。「もの」を直接修飾できず、ここには入らない。"}, {"text": "旨かろう", "is_correct": false, "explanation": "推量形。名詞を修飾できないので入らない。"}], "correct_form": "旨い", "base_form": "旨い", "form_label": "連体形", "sentence_index": 7, "explanations": {"旨い": "連体形。後ろの名詞「もの」を修飾する形で、ここに入る。", "旨そう": "「そう」は形容動詞型で、名詞「もの」を修飾するには「旨そうな」が必要。", "旨み": "名詞。「もの」を直接修飾できず、ここには入らない。", "旨かろう": "推量形。名詞を修飾できないので入らない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1aff041-8e12-4be2-95f9-036736301c3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36248, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「広がる」の主語を示す「が」。「グローバリズムが広がって」と続くので正しい。"}, {"text": "を", "is_correct": false, "explanation": "「広がる」は自動詞なので、目的語の「を」とは組み合わない。"}, {"text": "へ", "is_correct": false, "explanation": "向かう先を示す「へ」は、「広がる」の主語にはならない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や相手を示すので、ここでは主語の役割を果たせない。"}], "correct_answer": "が", "explanations": {"が": "「広がる」の主語を示す「が」。「グローバリズムが広がって」と続くので正しい。", "を": "「広がる」は自動詞なので、目的語の「を」とは組み合わない。", "へ": "向かう先を示す「へ」は、「広がる」の主語にはならない。", "と": "「と」は並列や相手を示すので、ここでは主語の役割を果たせない。"}, "error_tags": {"を": "目的語", "へ": "方向", "と": "相手・並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ff88f66-a23a-43b4-812c-c0d92e99400c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36248, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「グローバリズムの考え」と続け、考えの内容を示す「の」。"}, {"text": "に", "is_correct": false, "explanation": "「グローバリズムに考え」とは続かず、「考えは」の前に置くと文が成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所を示す「で」は、名詞を修飾する「考え」の前には入らない。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」は「グローバリズムより」と比べる文になり、「考え」とつながらない。"}], "correct_answer": "の", "explanations": {"の": "「グローバリズムの考え」と続け、考えの内容を示す「の」。", "に": "「グローバリズムに考え」とは続かず、「考えは」の前に置くと文が成り立たない。", "で": "手段や場所を示す「で」は、名詞を修飾する「考え」の前には入らない。", "より": "比較の「より」は「グローバリズムより」と比べる文になり、「考え」とつながらない。"}, "error_tags": {"に": "方向・所在", "で": "手段・場所", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ff88f66-a23a-43b4-812c-c0d92e99400c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36248, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "世界の国々が、つながりを強くする考えです。", "primary_collocate": null, "pronunciation": "ぐろーばりずむ", "ipa": "ɡɯɾoːbaɾizɯmɯ", "syllable_count": 7, "sentences": [{"text": "グローバリズムは、世界の国々が仲よくつながろうという考えです。", "target_word": "グローバリズム", "complexity_tier": "T3", "furigana": "グローバリズムは、世界[せかい]の国々[くにぐに]が仲[なか]よくつながろうという考[かんが]えです。", "sentence_source": "generated"}, {"text": "グローバリズムが広がって、外国の食べものが身近になった。", "target_word": "グローバリズム", "complexity_tier": "T3", "furigana": "グローバリズムが広[ひろ]がって、外国[がいこく]の食[た]べものが身近[みぢか]になった。", "sentence_source": "generated"}, {"text": "グローバリズムのおかげで、遠い国の人ともすぐ話せる。", "target_word": "グローバリズム", "complexity_tier": "T3", "furigana": "グローバリズムのおかげで、遠[とお]い国[くに]の人[ひと]ともすぐ話[はな]せる。", "sentence_source": "generated"}, {"text": "学校の授業で、グローバリズムとは何かを調べた。", "target_word": "グローバリズム", "complexity_tier": "T3", "furigana": "学校[がっこう]の授業[じゅぎょう]で、グローバリズムとは何[なに]かを調[しら]べた。", "sentence_source": "generated"}, {"text": "グローバリズムを大切にする人は、国どうしの助け合いを重んじる。", "target_word": "グローバリズム", "complexity_tier": "T3", "furigana": "グローバリズムを大切[たいせつ]にする人[ひと]は、国[くに]どうしの助[たす]け合[あ]いを重[おも]んじる。", "sentence_source": "generated"}, {"text": "グローバリズムが進むと、世界のニュースが毎日すぐに届く。", "target_word": "グローバリズム", "complexity_tier": "T3", "furigana": "グローバリズムが進[すす]むと、世界[せかい]のニュースが毎日[まいにち]すぐに届[とど]く。", "sentence_source": "generated"}, {"text": "「グローバリズムは、国どうしの助け合いを大事にする考えだ」と、先生は話した。", "target_word": "グローバリズム", "complexity_tier": "T3", "furigana": "「グローバリズムは、国[くに]どうしの助[たす]け合[あ]いを大事[だいじ]にする考[かんが]えだ」と、先生[せんせい]は話[はな]した。", "sentence_source": "generated"}, {"text": "国を越えて協力するグローバリズムの考えは、環境を守るためにも必要だ。", "target_word": "グローバリズム", "complexity_tier": "T3", "furigana": "国[くに]を越[こ]えて協力[きょうりょく]するグローバリズムの考[かんが]えは、環境[かんきょう]を守[まも]るためにも必要[ひつよう]だ。", "sentence_source": "generated"}, {"text": "グローバリズムの流れで、外国から来て日本で働く人が増えた。", "target_word": "グローバリズム", "complexity_tier": "T3", "furigana": "グローバリズムの流[なが]れで、外国[がいこく]から来[き]て日本[にほん]で働[はたら]く人[ひと]が増[ふ]えた。", "sentence_source": "generated"}, {"text": "グローバリズムに反対する人は、自分たちの国の仕事が減るのを心配している。", "target_word": "グローバリズム", "complexity_tier": "T3", "furigana": "グローバリズムに反対[はんたい]する人[ひと]は、自分[じぶん]たちの国[くに]の仕事[しごと]が減[へ]るのを心配[しんぱい]している。", "sentence_source": "generated"}], "morphological_forms": [{"form": "グローバリズム", "label": "基本形"}], "register": "一般・やさしい説明", "sense_fingerprint": "世界の国々が結びつきを強めようとする考え（やさしい説明）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa11b1da-6a01-497b-ba17-85963d2f0c23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36248, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ナショナリズム", "is_correct": false, "explanation": "自国を優先する考えで、世界の国々が仲よくつながろうとする内容と逆になるので合わない。"}, {"text": "グローバリズム", "is_correct": true, "explanation": "世界の国々が仲よくつながろうという考えを指す語なので、ここに入る。"}, {"text": "ニヒリズム", "is_correct": false, "explanation": "何の価値も認めない考えで、「仲よくつながる」という肯定的な内容と合わない。"}, {"text": "ミニマリズム", "is_correct": false, "explanation": "物を少なくして暮らす考え方で、国どうしのつながりの説明には当てはまらない。"}], "explanations": {"ナショナリズム": "自国を優先する考えで、世界の国々が仲よくつながろうとする内容と逆になるので合わない。", "グローバリズム": "世界の国々が仲よくつながろうという考えを指す語なので、ここに入る。", "ニヒリズム": "何の価値も認めない考えで、「仲よくつながる」という肯定的な内容と合わない。", "ミニマリズム": "物を少なくして暮らす考え方で、国どうしのつながりの説明には当てはまらない。"}, "sentence_index": 0, "correct_answer": "グローバリズム"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "野球の試合で、グローバリズムを忘れて取りに帰った。", "explanation": "〈グローブ〉（手袋）と混同した文。グローバリズムは思想を表す語で、野球の道具には使わない。"}, {"text": "地理の授業で、グローバリズムを回して国の場所を確かめた。", "explanation": "〈地球儀〉と混同した文。グローバリズムは回して見る物ではなく、思想を表す語なので合わない。"}, {"text": "昼ごはんのあと、グローバリズムを洗った。", "explanation": "〈弁当箱〉の意味の文。グローバリズムは洗える物ではないので、この使い方はしない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ff88f66-a23a-43b4-812c-c0d92e99400c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36248, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "アナーキズム", "is_correct": false, "explanation": "国家や権力を否定する思想で、先生が「大事だ」と話す対象としては文脈に合わない。"}, {"text": "グローバリズム", "is_correct": true, "explanation": "国境を越えた結びつきを指す語で、「大事だ」と話された内容に当たる。"}, {"text": "ダダイズム", "is_correct": false, "explanation": "既成の価値を否定した芸術運動の名で、「大事だ」と話される理念としては合わない。"}, {"text": "ロマンチシズム", "is_correct": false, "explanation": "感情や美を重んじる考えで、ここで話題になっている内容とは結びつかない。"}], "explanations": {"アナーキズム": "国家や権力を否定する思想で、先生が「大事だ」と話す対象としては文脈に合わない。", "グローバリズム": "国境を越えた結びつきを指す語で、「大事だ」と話された内容に当たる。", "ダダイズム": "既成の価値を否定した芸術運動の名で、「大事だ」と話される理念としては合わない。", "ロマンチシズム": "感情や美を重んじる考えで、ここで話題になっている内容とは結びつかない。"}, "sentence_index": 6, "correct_answer": "グローバリズム"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "うちの店には、腕のいいグローバリズムがいる。", "explanation": "〈美容師〉（人）の意味。グローバリズムは思想を表す語で、店で働く人にはならない。"}, {"text": "夏休みには、グローバリズムに泊まりに行った。", "explanation": "〈祖母の家〉のような場所の意味。グローバリズムは泊まれる場所ではないので合わない。"}, {"text": "三時間目の授業は、グローバリズムだった。", "explanation": "〈国語〉（教科）の意味。グローバリズムは授業の科目にはならないので、この使い方はしない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ff88f66-a23a-43b4-812c-c0d92e99400c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36248, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "グローバリズムを進んで、世界の国々が仲よくなった。", "corrected_sentence": "グローバリズムが進んで、世界の国々が仲よくなった。", "error_description": "「進む」は自動詞なので、主語は「が」で示す。「を」は他動詞の目的語に使う助詞なので誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ff88f66-a23a-43b4-812c-c0d92e99400c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36248, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "グローバリズムが進めて、どの国でも似た商品が売られるようになった。", "corrected_sentence": "グローバリズムが進んで、どの国でも似た商品が売られるようになった。", "error_description": "「進める」は他動詞なので、主語が「グローバリズム」では合わない。正しくは自動詞の「進んで」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ff88f66-a23a-43b4-812c-c0d92e99400c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36249, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「グローバリズムの流れ」と続けて名詞をつなぐ「の」。"}, {"text": "に", "is_correct": false, "explanation": "「流れに乗る」の対象を示す「に」。「グローバリズムに流れ」では文が成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "手段を示す「で」は、「流れ」を修飾する位置には入らない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や相手を示すため、「流れ」を修飾するこの位置では不自然になる。"}], "correct_answer": "の", "explanations": {"の": "「グローバリズムの流れ」と続けて名詞をつなぐ「の」。", "に": "「流れに乗る」の対象を示す「に」。「グローバリズムに流れ」では文が成り立たない。", "で": "手段を示す「で」は、「流れ」を修飾する位置には入らない。", "と": "「と」は並列や相手を示すため、「流れ」を修飾するこの位置では不自然になる。"}, "error_tags": {"に": "方向・相手", "で": "手段", "と": "相手・並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ff88f66-a23a-43b4-812c-c0d92e99400c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36249, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「格差を広げた」の主語を示す「が」。「グローバリズムが格差を広げた」と続くので正しい。"}, {"text": "を", "is_correct": false, "explanation": "「グローバリズムを格差を」と目的語が二つ重なり、不自然になる。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す「へ」は、「広げた」の主語にはならない。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」は「グローバリズムより」と比べる文になり、主語を表せない。"}], "correct_answer": "が", "explanations": {"が": "「格差を広げた」の主語を示す「が」。「グローバリズムが格差を広げた」と続くので正しい。", "を": "「グローバリズムを格差を」と目的語が二つ重なり、不自然になる。", "へ": "方向を示す「へ」は、「広げた」の主語にはならない。", "より": "比較の「より」は「グローバリズムより」と比べる文になり、主語を表せない。"}, "error_tags": {"を": "目的語", "へ": "方向", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ff88f66-a23a-43b4-812c-c0d92e99400c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36249, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "グローバリズムとは、経済や文化など、国境を越えて世界全体がひとつに統合されていく考え方や動きのことです。", "primary_collocate": null, "pronunciation": "ぐろーばりずむ", "ipa": "ɡɯɾoːbaɾizɯmɯ", "syllable_count": 7, "sentences": [{"text": "グローバリズムは、経済や文化が国境を越えて結びつく動きを指す。", "target_word": "グローバリズム", "complexity_tier": "T3", "furigana": "グローバリズムは、経済[けいざい]や文化[ぶんか]が国境[こっきょう]を越[こ]えて結[むす]びつく動[うご]きを指[さ]す。", "sentence_source": "generated"}, {"text": "企業は、グローバリズムの流れに乗って、海外に工場を建てた。", "target_word": "グローバリズム", "complexity_tier": "T3", "furigana": "企業[きぎょう]は、グローバリズムの流[なが]れに乗[の]って、海外[かいがい]に工場[こうじょう]を建[た]てた。", "sentence_source": "generated"}, {"text": "行き過ぎたグローバリズムは、地域の産業を弱くするという批判がある。", "target_word": "グローバリズム", "complexity_tier": "T3", "furigana": "行[い]き過[す]ぎたグローバリズムは、地域[ちいき]の産業[さんぎょう]を弱[よわ]くするという批判[ひはん]がある。", "sentence_source": "generated"}, {"text": "グローバリズムが進むほど、一国の景気が世界中に影響を与える。", "target_word": "グローバリズム", "complexity_tier": "T3", "furigana": "グローバリズムが進[すす]むほど、一国[いっこく]の景気[けいき]が世界中[せかいじゅう]に影響[えいきょう]を与[あた]える。", "sentence_source": "generated"}, {"text": "保護主義とは反対に、グローバリズムは自由な貿易を重んじる。", "target_word": "グローバリズム", "complexity_tier": "T3", "furigana": "保護[ほご]主義[しゅぎ]とは反対[はんたい]に、グローバリズムは自由[じゆう]な貿易[ぼうえき]を重[おも]んじる。", "sentence_source": "generated"}, {"text": "この政治家は、グローバリズムよりも国内の雇用を守ると主張した。", "target_word": "グローバリズム", "complexity_tier": "T3", "furigana": "この政治家[せいじか]は、グローバリズムよりも国内[こくない]の雇用[こよう]を守[まも]ると主張[しゅちょう]した。", "sentence_source": "generated"}, {"text": "グローバリズムのもとで、各地の文化が混ざり合っている。", "target_word": "グローバリズム", "complexity_tier": "T3", "furigana": "グローバリズムのもとで、各地[かくち]の文化[ぶんか]が混[ま]ざり合[あ]っている。", "sentence_source": "generated"}, {"text": "経済学者は、グローバリズムが格差を広げたかどうかを議論している。", "target_word": "グローバリズム", "complexity_tier": "T3", "furigana": "経済[けいざい]学者[がくしゃ]は、グローバリズムが格差[かくさ]を広[ひろ]げたかどうかを議論[ぎろん]している。", "sentence_source": "generated"}, {"text": "若者の間で、グローバリズムに対する見方が大きく分かれている。", "target_word": "グローバリズム", "complexity_tier": "T3", "furigana": "若者[わかもの]の間[あいだ]で、グローバリズムに対[たい]する見方[みかた]が大[おお]きく分[わ]かれている。", "sentence_source": "generated"}, {"text": "グローバリズムを背景に、国際的な会議が頻繁に開かれるようになった。", "target_word": "グローバリズム", "complexity_tier": "T3", "furigana": "グローバリズムを背景[はいけい]に、国際的[こくさいてき]な会議[かいぎ]が頻繁[ひんぱん]に開[ひら]かれるようになった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "グローバリズム", "label": "基本形"}], "register": "論説・報道の文体", "sense_fingerprint": "経済・文化が国境を越えて世界規模で統合されていく考え方や動き（論説用法）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa11b1da-6a01-497b-ba17-85963d2f0c23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36249, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ナショナリズム", "is_correct": false, "explanation": "国家の利益を優先する考えで、国境を越えて結びつく動きの説明には当たらない。"}, {"text": "ヒューマニズム", "is_correct": false, "explanation": "人間の尊厳を重んじる考えで、経済や文化の動きを指す文脈とは合わない。"}, {"text": "グローバリズム", "is_correct": true, "explanation": "経済や文化が国境を越えて結びつく動きを指す語なので、ここに入る。"}, {"text": "プラグマティズム", "is_correct": false, "explanation": "実際の結果を重んじる考え方で、国境を越えた結びつきの動きを指す語ではない。"}], "explanations": {"ナショナリズム": "国家の利益を優先する考えで、国境を越えて結びつく動きの説明には当たらない。", "ヒューマニズム": "人間の尊厳を重んじる考えで、経済や文化の動きを指す文脈とは合わない。", "グローバリズム": "経済や文化が国境を越えて結びつく動きを指す語なので、ここに入る。", "プラグマティズム": "実際の結果を重んじる考え方で、国境を越えた結びつきの動きを指す語ではない。"}, "sentence_index": 0, "correct_answer": "グローバリズム"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "週末の大掃除で、グローバリズムをふいた。", "explanation": "〈窓ガラス〉の意味の文。ふくのは窓ガラスなどの物で、思想を表す語は合わない。"}, {"text": "夜の部屋で、グローバリズムに火をともした。", "explanation": "〈ろうそく〉の意味の文。火をともせるのは物で、グローバリズムには当てはまらない。"}, {"text": "公園の木にグローバリズムを吊るして昼寝した。", "explanation": "〈ハンモック〉の意味の文。吊るせるのは物で、思想を吊るすことはできない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ff88f66-a23a-43b4-812c-c0d92e99400c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36249, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "シニシズム", "is_correct": false, "explanation": "世の中の理想を冷笑する考えで、文化が混ざり合うという現象の説明には合わない。"}, {"text": "グローバリズム", "is_correct": true, "explanation": "国境を越えて文化が混ざり合う動きを背景に持つ語なので、ここに入る。"}, {"text": "パターナリズム", "is_correct": false, "explanation": "相手の利益を理由に介入する考えで、文化が混ざり合う様子とは結びつかない。"}, {"text": "ナショナリズム", "is_correct": false, "explanation": "自国の文化や利益を重んじる考えで、文化が混ざり合う状況とは逆になる。"}], "explanations": {"シニシズム": "世の中の理想を冷笑する考えで、文化が混ざり合うという現象の説明には合わない。", "グローバリズム": "国境を越えて文化が混ざり合う動きを背景に持つ語なので、ここに入る。", "パターナリズム": "相手の利益を理由に介入する考えで、文化が混ざり合う様子とは結びつかない。", "ナショナリズム": "自国の文化や利益を重んじる考えで、文化が混ざり合う状況とは逆になる。"}, "sentence_index": 6, "correct_answer": "グローバリズム"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "祖父は、昔から村一番のグローバリズムだった。", "explanation": "〈大工〉（人の職業）の意味。思想を表す語では、人の職業を表せない。"}, {"text": "友だちと、グローバリズムで待ち合わせた。", "explanation": "〈喫茶店〉のような場所の意味。グローバリズムは待ち合わせの場所にはならない。"}, {"text": "来週の火曜日は、グローバリズムだ。", "explanation": "〈祝日〉の意味。日付の種類を表す語で、思想の名前はここに当てはまらない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ff88f66-a23a-43b4-812c-c0d92e99400c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36249, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "グローバリズムを進むと、各国の政策が似てくる。", "corrected_sentence": "グローバリズムが進むと、各国の政策が似てくる。", "error_description": "「進む」は自動詞なので、主語には「が」を使う。「を」は他動詞の目的語に使うため誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ff88f66-a23a-43b4-812c-c0d92e99400c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36249, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "グローバリズムが広げて、どの国の食文化も少しずつ混ざり合った。", "corrected_sentence": "グローバリズムが広がって、どの国の食文化も少しずつ混ざり合った。", "error_description": "「広げる」は他動詞なので、主語が「グローバリズム」では合わない。正しくは自動詞の「広がって」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ff88f66-a23a-43b4-812c-c0d92e99400c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36254, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「すること」の後に入り、「多い」の主語を示す。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示すので、「多い」の主語にはならない。"}, {"text": "に", "is_correct": false, "explanation": "方向や対象を示すので、ここでは文が成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "場所や手段を示すので、ここでは文が成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「すること」の後に入り、「多い」の主語を示す。", "を": "目的語を示すので、「多い」の主語にはならない。", "に": "方向や対象を示すので、ここでは文が成り立たない。", "で": "場所や手段を示すので、ここでは文が成り立たない。"}, "error_tags": {"を": "目的語を示す", "に": "方向・対象を示す", "で": "場所・手段を示す"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1aff041-8e12-4be2-95f9-036736301c3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36254, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「すること」の後に入り、「好きだ」の主語を示す。"}, {"text": "と", "is_correct": false, "explanation": "引用や並列を示すので、「好きだ」の主語にはならない。"}, {"text": "から", "is_correct": false, "explanation": "起点や理由を示すので、ここでは文が成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "比較を示すので、ここでは文が成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「すること」の後に入り、「好きだ」の主語を示す。", "と": "引用や並列を示すので、「好きだ」の主語にはならない。", "から": "起点や理由を示すので、ここでは文が成り立たない。", "より": "比較を示すので、ここでは文が成り立たない。"}, "error_tags": {"と": "引用・並列を示す", "から": "起点・理由を示す", "より": "比較を示す"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1aff041-8e12-4be2-95f9-036736301c3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36254, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "何かを行うこと。動作や行為を名詞として言う。", "primary_collocate": null, "pronunciation": "すること", "ipa": "sɯɾɯkoto", "syllable_count": 4, "sentences": [{"text": "毎日少しずつ勉強することが大切だ。", "target_word": "すること", "complexity_tier": "T3", "furigana": "毎日[まいにち]少[すこ]しずつ勉強[べんきょう]することが大切[たいせつ]だ。", "sentence_source": "generated"}, {"text": "休みの日は、ゆっくりすることが多い。", "target_word": "すること", "complexity_tier": "T3", "furigana": "休[やす]みの日[ひ]は、ゆっくりすることが多[おお]い。", "sentence_source": "generated"}, {"text": "宿題をすることを忘れて、先生に注意された。", "target_word": "すること", "complexity_tier": "T3", "furigana": "宿題[しゅくだい]をすることを忘[わす]れて、先生[せんせい]に注意[ちゅうい]された。", "sentence_source": "generated"}, {"text": "困っている人に親切にすることは、誰にでもできる。", "target_word": "すること", "complexity_tier": "T3", "furigana": "困[こま]っている人[ひと]に親切[しんせつ]にすることは、誰[だれ]にでもできる。", "sentence_source": "generated"}, {"text": "朝早く散歩することが、私の楽しみです。", "target_word": "すること", "complexity_tier": "T3", "furigana": "朝早[あさはや]く散歩[さんぽ]することが、私[わたし]の楽[たの]しみです。", "sentence_source": "generated"}, {"text": "初めて会う人にあいさつをすることは、大事なマナーだ。", "target_word": "すること", "complexity_tier": "T3", "furigana": "初[はじ]めて会[あ]う人[ひと]にあいさつをすることは、大事[だいじ]なマナーだ。", "sentence_source": "generated"}, {"text": "今日することをメモに書いておくと、忘れない。", "target_word": "すること", "complexity_tier": "T3", "furigana": "今日[きょう]することをメモに書[か]いておくと、忘[わす]れない。", "sentence_source": "generated"}, {"text": "兄は夜遅くまでゲームをすることが好きだ。", "target_word": "すること", "complexity_tier": "T3", "furigana": "兄[あに]は夜遅[よるおそ]くまでゲームをすることが好[す]きだ。", "sentence_source": "generated"}, {"text": "電車の中で大きな声で電話をすることは、よくない。", "target_word": "すること", "complexity_tier": "T3", "furigana": "電車[でんしゃ]の中[なか]で大[おお]きな声[こえ]で電話[でんわ]をすることは、よくない。", "sentence_source": "generated"}, {"text": "試験の前にすることを、紙に書いて整理した。", "target_word": "すること", "complexity_tier": "T3", "furigana": "試験[しけん]の前[まえ]にすることを、紙[かみ]に書[か]いて整理[せいり]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "すること", "label": "連体形+こと"}, {"form": "したこと", "label": "過去形+こと"}, {"form": "しないこと", "label": "否定形+こと"}, {"form": "することが", "label": "主格"}, {"form": "することを", "label": "目的格"}], "register": "neutral", "sense_fingerprint": "何かを行う、動作や行為を名詞的に言う「すること」", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5f6c10e-59f5-434b-8d2f-b32eae92b808') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36254, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "すること", "is_correct": true, "explanation": "「勉強すること」の形で、「大切だ」の主語になる。"}, {"text": "食べること", "is_correct": false, "explanation": "「勉強食べること」は文として成り立たない。"}, {"text": "眠ること", "is_correct": false, "explanation": "「勉強眠ること」は文として成り立たない。"}, {"text": "歌うこと", "is_correct": false, "explanation": "「勉強歌うこと」は文として成り立たない。"}], "explanations": {"すること": "「勉強すること」の形で、「大切だ」の主語になる。", "食べること": "「勉強食べること」は文として成り立たない。", "眠ること": "「勉強眠ること」は文として成り立たない。", "歌うこと": "「勉強歌うこと」は文として成り立たない。"}, "sentence_index": 0, "correct_answer": "すること"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "机の上に、することを置いた。", "explanation": "ここは〈物〉の意味。「すること」は動作を指す名詞で、物として置くことはできない。"}, {"text": "今朝は、することが晴れた。", "explanation": "ここは〈天気〉の意味。「すること」は行為を表すので、晴れるという天気の状態には使えない。"}, {"text": "この箱には、することが三つ入っている。", "explanation": "ここは〈物〉を数える意味。「すること」は行為を表すので、物の数え方には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1aff041-8e12-4be2-95f9-036736301c3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36254, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "すること", "is_correct": true, "explanation": "「今日すること」の形で、メモに書く予定を指す。"}, {"text": "天気", "is_correct": false, "explanation": "「天気をメモに書く」は文として不自然で、ここには入らない。"}, {"text": "気温", "is_correct": false, "explanation": "「気温をメモに書く」は文として不自然で、ここには入らない。"}, {"text": "眠気", "is_correct": false, "explanation": "「眠気をメモに書く」は文として不自然で、ここには入らない。"}], "explanations": {"すること": "「今日すること」の形で、メモに書く予定を指す。", "天気": "「天気をメモに書く」は文として不自然で、ここには入らない。", "気温": "「気温をメモに書く」は文として不自然で、ここには入らない。", "眠気": "「眠気をメモに書く」は文として不自然で、ここには入らない。"}, "sentence_index": 6, "correct_answer": "すること"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "その本は、することが三十ページある。", "explanation": "ここは〈物〉の意味。「すること」は行為を表すので、ページ数の説明には使えない。"}, {"text": "彼は夏に、することにかかって寝込んだ。", "explanation": "ここは〈病気〉の意味。「すること」は行為を表すので、病気のように「かかる」ものとしては使えない。"}, {"text": "台所から、することの匂いがする。", "explanation": "ここは〈匂い〉の意味。「すること」は行為を表すので、においとしては使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1aff041-8e12-4be2-95f9-036736301c3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36254, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "少しずつ練習することを上達のコツだ。", "corrected_sentence": "少しずつ練習することが上達のコツだ。", "error_description": "「上達のコツだ」の主語には「が」が必要。「を」は目的語を表すので誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "すること", "is_correct": true, "explanation": "「すること」の連体形＋こと。ここでは「ゆっくりすることが多い」の主語。"}, {"text": "すれば", "is_correct": false, "explanation": "仮定形。名詞「こと」には続かないので入らない。"}, {"text": "しよう", "is_correct": false, "explanation": "意志形。名詞を修飾できないので入らない。"}, {"text": "することを", "is_correct": false, "explanation": "目的格。「多い」の主語にはならないので入らない。"}], "correct_form": "すること", "base_form": "すること", "form_label": "連体形＋こと", "sentence_index": 1, "explanations": {"すること": "「すること」の連体形＋こと。ここでは「ゆっくりすることが多い」の主語。", "すれば": "仮定形。名詞「こと」には続かないので入らない。", "しよう": "意志形。名詞を修飾できないので入らない。", "することを": "目的格。「多い」の主語にはならないので入らない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1aff041-8e12-4be2-95f9-036736301c3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36254, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "毎朝ジョギングをすることに習慣になった。", "corrected_sentence": "毎朝ジョギングをすることが習慣になった。", "error_description": "「習慣になった」の主語には「が」が必要。「に」は文の主語を示せないので誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "すること", "is_correct": true, "explanation": "「すること」の連体形＋こと。ここでは「好きだ」の対象として入る。"}, {"text": "すると", "is_correct": false, "explanation": "接続の形。名詞として「が好きだ」の主語にはならないので入らない。"}, {"text": "して", "is_correct": false, "explanation": "て形。名詞を修飾できないので入らない。"}, {"text": "させる", "is_correct": false, "explanation": "使役の形。名詞にならず、「が好きだ」の前には入らない。"}], "correct_form": "すること", "base_form": "すること", "form_label": "連体形＋こと", "sentence_index": 7, "explanations": {"すること": "「すること」の連体形＋こと。ここでは「好きだ」の対象として入る。", "すると": "接続の形。名詞として「が好きだ」の主語にはならないので入らない。", "して": "て形。名詞を修飾できないので入らない。", "させる": "使役の形。名詞にならず、「が好きだ」の前には入らない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1aff041-8e12-4be2-95f9-036736301c3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
