INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36260, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "「さまざま」は、いろいろなものやことがあるという意味です。一つだけではなく、たくさんの種類があることをあらわします。", "primary_collocate": null, "pronunciation": "さまざま", "ipa": "samazama", "syllable_count": 4, "sentences": [{"text": "この店には、様々な国のお茶がそろっている。", "target_word": "様々", "complexity_tier": "T3", "furigana": "この店[みせ]には、様々[さまざま]な国[くに]のお茶[ちゃ]がそろっている。", "sentence_source": "generated"}, {"text": "人にはそれぞれ、様々な考え方がある。", "target_word": "様々", "complexity_tier": "T3", "furigana": "人[ひと]にはそれぞれ、様々[さまざま]な考[かんが]え方[かた]がある。", "sentence_source": "generated"}, {"text": "駅前の広場には、様々な年齢の人が集まっていた。", "target_word": "様々", "complexity_tier": "T3", "furigana": "駅前[えきまえ]の広場[ひろば]には、様々[さまざま]な年齢[ねんれい]の人[ひと]が集[あつ]まっていた。", "sentence_source": "generated"}, {"text": "祭りでは、様々な色の花火が夜空に上がった。", "target_word": "様々", "complexity_tier": "T3", "furigana": "祭[まつ]りでは、様々[さまざま]な色[いろ]の花火[はなび]が夜空[よぞら]に上[あ]がった。", "sentence_source": "generated"}, {"text": "仕事を辞めた理由は人によって様々だ。", "target_word": "様々", "complexity_tier": "T3", "furigana": "仕事[しごと]を辞[や]めた理由[りゆう]は人[ひと]によって様々[さまざま]だ。", "sentence_source": "generated"}, {"text": "旅行で、様々な人と出会うことができた。", "target_word": "様々", "complexity_tier": "T3", "furigana": "旅行[りょこう]で、様々[さまざま]な人[ひと]と出会[であ]うことができた。", "sentence_source": "generated"}, {"text": "図書館で、様々な種類の本を借りた。", "target_word": "様々", "complexity_tier": "T3", "furigana": "図書館[としょかん]で、様々[さまざま]な種類[しゅるい]の本[ほん]を借[か]りた。", "sentence_source": "generated"}, {"text": "春になると、様々な花が一斉に咲く。", "target_word": "様々", "complexity_tier": "T3", "furigana": "春[はる]になると、様々[さまざま]な花[はな]が一斉[いっせい]に咲[さ]く。", "sentence_source": "generated"}, {"text": "この町には、様々な文化が混ざり合っている。", "target_word": "様々", "complexity_tier": "T3", "furigana": "この町[まち]には、様々[さまざま]な文化[ぶんか]が混[ま]ざり合[あ]っている。", "sentence_source": "generated"}, {"text": "意見は様々に分かれたが、最後は一つにまとまった。", "target_word": "様々", "complexity_tier": "T3", "furigana": "意見[いけん]は様々[さまざま]に分[わ]かれたが、最後[さいご]は一[ひと]つにまとまった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "様々", "label": "基本形"}, {"form": "様々な", "label": "連体形"}, {"form": "様々に", "label": "連用形"}, {"form": "様々だ", "label": "終止形"}, {"form": "様々で", "label": "中止形"}], "register": "neutral", "sense_fingerprint": "一つではなく、たくさんの種類があるいろいろな様子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '867e6da7-b7bb-4db0-b05a-8fbe2c1dbaea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36260, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "様々", "is_correct": true, "explanation": "国のお茶がいろいろあるという意味で、「様々な国」と文意に合う。"}, {"text": "不便", "is_correct": false, "explanation": "不便は使いにくさを表し、お茶の種類がそろっている文には合わない。"}, {"text": "清潔", "is_correct": false, "explanation": "清潔は汚れがないことで、国の種類を示す文には合わない。"}, {"text": "確実", "is_correct": false, "explanation": "確実は間違いがないことで、お茶の種類の多さを示す文には合わない。"}], "explanations": {"様々": "国のお茶がいろいろあるという意味で、「様々な国」と文意に合う。", "不便": "不便は使いにくさを表し、お茶の種類がそろっている文には合わない。", "清潔": "清潔は汚れがないことで、国の種類を示す文には合わない。", "確実": "確実は間違いがないことで、お茶の種類の多さを示す文には合わない。"}, "sentence_index": 0, "correct_answer": "様々"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "祭りでは、様々な色の花火が全部同じ色で上がった。", "explanation": "ここは〈同じ〉の場面。様々は種類がいろいろであることを表すので、全部同じ色の花火には合わない。"}, {"text": "祭りでは、様々に白い花火が夜空に上がった。", "explanation": "ここは〈一様〉（同じように）の意味。様々は種類が多様なことなので、そろった白い花火には合わない。"}, {"text": "祭りでは、様々な花火が一発だけ夜空に上がった。", "explanation": "ここは〈単一〉（数が一つだけ）の意味。様々は種類の多さを表すので、一発だけ上がった場面には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb5f2262-c6a2-494a-bf81-41eac77c9c52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36260, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "様々", "is_correct": true, "explanation": "図書館で多くの種類の本を借りたという意味で、「様々な種類」と文意に合う。"}, {"text": "不正", "is_correct": false, "explanation": "不正は正しくないことで、本の種類を表す語としては合わない。"}, {"text": "無断", "is_correct": false, "explanation": "無断は許可を得ないことで、本の種類を示す文には合わない。"}, {"text": "乱雑", "is_correct": false, "explanation": "乱雑は散らかっていることで、本の種類を表す文には合わない。"}], "explanations": {"様々": "図書館で多くの種類の本を借りたという意味で、「様々な種類」と文意に合う。", "不正": "不正は正しくないことで、本の種類を表す語としては合わない。", "無断": "無断は許可を得ないことで、本の種類を示す文には合わない。", "乱雑": "乱雑は散らかっていることで、本の種類を表す文には合わない。"}, "sentence_index": 6, "correct_answer": "様々"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "意見は様々に一致したので、すぐに決まった。", "explanation": "ここは〈一致〉（全員が同じになる）の意味。様々は種類が多いことなので、意見がそろった場面には合わない。"}, {"text": "最後に意見を出したのは、様々な一人だった。", "explanation": "ここは〈特定〉（一人に絞る）の意味。様々は種類の多さを表すので、一人を指す場面には合わない。"}, {"text": "参加者の立場は、様々に同じだった。", "explanation": "ここは〈同じ〉（均一である）の意味。様々は種類の違いを表すので、立場がそろった場面には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb5f2262-c6a2-494a-bf81-41eac77c9c52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36260, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この店には、様々だ国の紅茶がそろっている。", "corrected_sentence": "この店には、様々な国の紅茶がそろっている。", "error_description": "「様々」は名詞を修飾するとき「様々な＋名詞」になる。「様々だ」は述語用法なので、名詞の前では「な」にする。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "様々な", "is_correct": true, "explanation": "名詞の前に置く連体形で、「様々な考え方」と文意に合う。"}, {"text": "様々だ", "is_correct": false, "explanation": "述語の終止形で、名詞の前には直接置けない。"}, {"text": "様々に", "is_correct": false, "explanation": "連用形で動詞や形容詞を修飾する形。名詞の前には使えない。"}, {"text": "様々で", "is_correct": false, "explanation": "中止形で文を区切る役割があり、名詞の前には置けない。"}], "correct_form": "様々な", "base_form": "様々", "form_label": "連体形", "sentence_index": 1, "explanations": {"様々な": "名詞の前に置く連体形で、「様々な考え方」と文意に合う。", "様々だ": "述語の終止形で、名詞の前には直接置けない。", "様々に": "連用形で動詞や形容詞を修飾する形。名詞の前には使えない。", "様々で": "中止形で文を区切る役割があり、名詞の前には置けない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb5f2262-c6a2-494a-bf81-41eac77c9c52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36260, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "図書館で、様々に種類の雑誌を借りた。", "corrected_sentence": "図書館で、様々な種類の雑誌を借りた。", "error_description": "「様々」は名詞「種類」を修飾するので「様々な」にする。「様々に種類」は副詞用法の「に」になるので誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "様々な", "is_correct": true, "explanation": "名詞「花」の前に置く連体形で、「様々な花」と文意に合う。"}, {"text": "様々です", "is_correct": false, "explanation": "丁寧な述語の形。名詞「花」の前には直接置けず、「花」を修飾できない。"}, {"text": "様々だった", "is_correct": false, "explanation": "過去の述語の形。名詞「花」を修飾できず、習慣を表す「咲く」の文の時制とも合わない。"}, {"text": "様々では", "is_correct": false, "explanation": "否定を含む述語の形で、名詞「花」の前には置けない。"}], "correct_form": "様々な", "base_form": "様々", "form_label": "連体形", "sentence_index": 7, "explanations": {"様々な": "名詞「花」の前に置く連体形で、「様々な花」と文意に合う。", "様々です": "丁寧な述語の形。名詞「花」の前には直接置けず、「花」を修飾できない。", "様々だった": "過去の述語の形。名詞「花」を修飾できず、習慣を表す「咲く」の文の時制とも合わない。", "様々では": "否定を含む述語の形で、名詞「花」の前には置けない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb5f2262-c6a2-494a-bf81-41eac77c9c52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
