INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36261, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "「さまざま」は、種類や状態が多く、それぞれ異なっていることを表す形容動詞です。「様々な」の形で名詞を修飾したり、「様々だ」で述語になります。", "primary_collocate": null, "pronunciation": "さまざま", "ipa": "samazama", "syllable_count": 4, "sentences": [{"text": "この店には様々な国のお茶があります。", "target_word": "様々", "complexity_tier": "T3", "furigana": "この店[みせ]には様々[さまざま]な国[くに]のお茶[ちゃ]があります。", "sentence_source": "generated"}, {"text": "人によって、好きな食べ物は様々です。", "target_word": "様々", "complexity_tier": "T3", "furigana": "人[ひと]によって、好[す]きな食[た]べ物[もの]は様々[さまざま]です。", "sentence_source": "generated"}, {"text": "駅前の広場では、様々な人が行き来しています。", "target_word": "様々", "complexity_tier": "T3", "furigana": "駅前[えきまえ]の広場[ひろば]では、様々[さまざま]な人[ひと]が行[い]き来[き]しています。", "sentence_source": "generated"}, {"text": "先生に様々な質問をしましたが、全部わかりやすく答えてくれました。", "target_word": "様々", "complexity_tier": "T3", "furigana": "先生[せんせい]に様々[さまざま]な質問[しつもん]をしましたが、全部[ぜんぶ]わかりやすく答[こた]えてくれました。", "sentence_source": "generated"}, {"text": "考え方は様々なので、みんなの意見を聞きましょう。", "target_word": "様々", "complexity_tier": "T3", "furigana": "考[かんが]え方[かた]は様々[さまざま]なので、みんなの意見[いけん]を聞[き]きましょう。", "sentence_source": "generated"}, {"text": "週末は友達と様々な場所へ出かけました。", "target_word": "様々", "complexity_tier": "T3", "furigana": "週末[しゅうまつ]は友達[ともだち]と様々[さまざま]な場所[ばしょ]へ出[で]かけました。", "sentence_source": "generated"}, {"text": "祭りでは様々な色の服を着た人たちが踊っていました。", "target_word": "様々", "complexity_tier": "T3", "furigana": "祭[まつ]りでは様々[さまざま]な色[いろ]の服[ふく]を着[き]た人[ひと]たちが踊[おど]っていました。", "sentence_source": "generated"}, {"text": "理由は様々で、一つに決めることはできません。", "target_word": "様々", "complexity_tier": "T3", "furigana": "理由[りゆう]は様々[さまざま]で、一[ひと]つに決[き]めることはできません。", "sentence_source": "generated"}, {"text": "この本には様々な動物の写真がのっています。", "target_word": "様々", "complexity_tier": "T3", "furigana": "この本[ほん]には様々[さまざま]な動物[どうぶつ]の写真[しゃしん]がのっています。", "sentence_source": "generated"}, {"text": "日本には地方ごとに様々な方言があります。", "target_word": "様々", "complexity_tier": "T3", "furigana": "日本[にほん]には地方[ちほう]ごとに様々[さまざま]な方言[ほうげん]があります。", "sentence_source": "generated"}], "morphological_forms": [{"form": "様々な", "label": "連体形"}, {"form": "様々だ", "label": "終止形"}, {"form": "様々です", "label": "丁寧形"}, {"form": "様々で", "label": "連用形（で）"}, {"form": "様々に", "label": "連用形（に）"}], "register": "neutral", "sense_fingerprint": "形状詞。種類や状態が多様で、それぞれ違うこと。「様々な+名詞」「様々だ/です」の形で使う。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '867e6da7-b7bb-4db0-b05a-8fbe2c1dbaea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36261, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "様々", "is_correct": true, "explanation": "お茶の国がいろいろあるという意味で、「様々な国」と文意に合う。"}, {"text": "過激", "is_correct": false, "explanation": "過激は度を越えた激しさを表し、お茶の国の種類を示す文には合わない。"}, {"text": "孤独", "is_correct": false, "explanation": "孤独は一人でいることで、お茶の国の種類を示す文には合わない。"}, {"text": "不快", "is_correct": false, "explanation": "不快は気持ちがよくないことで、お茶の国の種類を示す文には合わない。"}], "explanations": {"様々": "お茶の国がいろいろあるという意味で、「様々な国」と文意に合う。", "過激": "過激は度を越えた激しさを表し、お茶の国の種類を示す文には合わない。", "孤独": "孤独は一人でいることで、お茶の国の種類を示す文には合わない。", "不快": "不快は気持ちがよくないことで、お茶の国の種類を示す文には合わない。"}, "sentence_index": 0, "correct_answer": "様々"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "先生に様々な質問をしましたが、全部同じ分野の質問でした。", "explanation": "ここは〈同種〉（同じ種類）の意味。様々は種類がいろいろという意味なので、全部同じ分野の質問だった場面には合わない。"}, {"text": "先生に様々な質問を一つだけしましたが、全部わかりやすく答えてくれました。", "explanation": "ここは〈単一〉（一つだけ）の意味。様々は多くの種類があることなので、一つだけの質問には合わない。"}, {"text": "先生に様々な質問をしましたが、どれも同じ一問でした。", "explanation": "ここは〈同一〉（全部同じ）の意味。様々は種類がいろいろという意味なので、どれも同じ一問だった場面には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb5f2262-c6a2-494a-bf81-41eac77c9c52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36261, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "様々", "is_correct": true, "explanation": "祭りで多くの色の服を着た人たちがいたという意味で、「様々な色」と文意に合う。"}, {"text": "冷静", "is_correct": false, "explanation": "冷静は落ち着いていることで、服の色を修飾する文には合わない。"}, {"text": "静粛", "is_correct": false, "explanation": "静粛は静かにすることで、服の色を示す文には合わない。"}, {"text": "不要", "is_correct": false, "explanation": "不要は必要ないことで、服の色を示す文には合わない。"}], "explanations": {"様々": "祭りで多くの色の服を着た人たちがいたという意味で、「様々な色」と文意に合う。", "冷静": "冷静は落ち着いていることで、服の色を修飾する文には合わない。", "静粛": "静粛は静かにすることで、服の色を示す文には合わない。", "不要": "不要は必要ないことで、服の色を示す文には合わない。"}, "sentence_index": 6, "correct_answer": "様々"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "日本には地方ごとに様々な方言の辞書が一冊だけあります。", "explanation": "ここは〈単一〉（一つだけ）の意味。様々は種類が多いことなので、一冊だけの辞書には合わない。"}, {"text": "日本には全国で様々な標準語が使われています。", "explanation": "ここは〈標準〉（一つにそろえた基準）の意味。様々は種類が多いことなので、一つにまとまった標準語には合わない。"}, {"text": "日本の方言は、どの地方でも様々に同じ発音をしています。", "explanation": "ここは〈同じ〉（均一である）の意味。様々は種類の違いを表すので、どの地方でも同じ発音をする場面には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb5f2262-c6a2-494a-bf81-41eac77c9c52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36261, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この店には様々国の紅茶があります。", "corrected_sentence": "この店には様々な国の紅茶があります。", "error_description": "「様々」は名詞を修飾するとき「な」が必要。「様々国」は「様々な国」と言う。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "様々", "is_correct": true, "explanation": "「です」の前に置く述語の形で、「好きな食べ物は様々です」と文意が通る。"}, {"text": "様々な", "is_correct": false, "explanation": "名詞の前で使う連体形で、「です」の前には置けない。"}, {"text": "様々だ", "is_correct": false, "explanation": "「です」と重ねると「だです」となり、文法的に誤り。"}, {"text": "様々に", "is_correct": false, "explanation": "連用形で、「です」の前には使えない。"}], "correct_form": "様々", "base_form": "様々", "form_label": "述語（です）の前", "sentence_index": 1, "explanations": {"様々": "「です」の前に置く述語の形で、「好きな食べ物は様々です」と文意が通る。", "様々な": "名詞の前で使う連体形で、「です」の前には置けない。", "様々だ": "「です」と重ねると「だです」となり、文法的に誤り。", "様々に": "連用形で、「です」の前には使えない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb5f2262-c6a2-494a-bf81-41eac77c9c52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36261, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この図鑑には様々に動物の写真がのっています。", "corrected_sentence": "この図鑑には様々な動物の写真がのっています。", "error_description": "「様々」は名詞「動物」を修飾するので「様々な」にする。「様々に動物」は副詞用法の「に」になるので誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "様々", "is_correct": true, "explanation": "基本形。語の見出しの形で、文中の『様々で』の語幹にあたる。"}, {"text": "様々くて", "is_correct": false, "explanation": "「くて」は形容詞の活用形で、形状詞の「様々」には付かず、文法的に誤り。"}, {"text": "様々くない", "is_correct": false, "explanation": "「くない」は形容詞の否定形で、形状詞の「様々」には付かず、文法的に誤り。"}, {"text": "様々では", "is_correct": false, "explanation": "「ではない」の形で後ろに否定が続く述語。ここでは続く否定がないので文と合わない。"}], "correct_form": "様々", "base_form": "様々", "form_label": "基本形", "sentence_index": 7, "explanations": {"様々": "基本形。語の見出しの形で、文中の『様々で』の語幹にあたる。", "様々くて": "「くて」は形容詞の活用形で、形状詞の「様々」には付かず、文法的に誤り。", "様々くない": "「くない」は形容詞の否定形で、形状詞の「様々」には付かず、文法的に誤り。", "様々では": "「ではない」の形で後ろに否定が続く述語。ここでは続く否定がないので文と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb5f2262-c6a2-494a-bf81-41eac77c9c52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36264, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb5f2262-c6a2-494a-bf81-41eac77c9c52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36264, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「約束を守る」の「を」で、守る対象を示す。"}, {"text": "が", "is_correct": false, "explanation": "「守る」は目的語を取る動詞なので、約束を主語にする「が」は文が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "守る対象は「に」では示せず、「約束に守る」は不自然。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を示すので、守る対象には合わない。"}], "correct_answer": "を", "explanations": {"を": "「約束を守る」の「を」で、守る対象を示す。", "が": "「守る」は目的語を取る動詞なので、約束を主語にする「が」は文が成り立たない。", "に": "守る対象は「に」では示せず、「約束に守る」は不自然。", "で": "「で」は手段や場所を示すので、守る対象には合わない。"}, "error_tags": {"が": "主語", "に": "対象・場所", "で": "手段・場所"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb5f2262-c6a2-494a-bf81-41eac77c9c52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36264, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "これからすることを、ちゃんと守ることです。", "primary_collocate": null, "pronunciation": "やくそく", "ipa": "jakɯsokɯ", "syllable_count": 4, "sentences": [{"text": "父は、毎日一緒に宿題をすると約束してくれました。", "target_word": "約束", "complexity_tier": "T3", "furigana": "父[ちち]は、毎日[まいにち]一緒[いっしょ]に宿題[しゅくだい]をすると約束[やくそく]してくれました。", "sentence_source": "generated"}, {"text": "約束は必ず守らなければなりません。", "target_word": "約束", "complexity_tier": "T3", "furigana": "約束[やくそく]は必[かなら]ず守[まも]らなければなりません。", "sentence_source": "generated"}, {"text": "彼は約束を破ったので、妹はとても怒っています。", "target_word": "約束", "complexity_tier": "T3", "furigana": "彼[かれ]は約束[やくそく]を破[やぶ]ったので、妹[いもうと]はとても怒[おこ]っています。", "sentence_source": "generated"}, {"text": "先生と、もう遅刻しないという約束をしました。", "target_word": "約束", "complexity_tier": "T3", "furigana": "先生[せんせい]と、もう遅刻[ちこく]しないという約束[やくそく]をしました。", "sentence_source": "generated"}, {"text": "小さな約束でも、守る人は信頼されます。", "target_word": "約束", "complexity_tier": "T3", "furigana": "小[ちい]さな約束[やくそく]でも、守[まも]る人[ひと]は信頼[しんらい]されます。", "sentence_source": "generated"}, {"text": "「うそはつかない」と母に約束した。", "target_word": "約束", "complexity_tier": "T3", "furigana": "「うそはつかない」と母[はは]に約束[やくそく]した。", "sentence_source": "generated"}, {"text": "約束したことを忘れてしまい、友達に謝りました。", "target_word": "約束", "complexity_tier": "T3", "furigana": "約束[やくそく]したことを忘[わす]れてしまい、友達[ともだち]に謝[あやま]りました。", "sentence_source": "generated"}, {"text": "彼女は約束を守る人なので、みんなが安心して仕事をまかせます。", "target_word": "約束", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は約束[やくそく]を守[まも]る人[ひと]なので、みんなが安心[あんしん]して仕事[しごと]をまかせます。", "sentence_source": "generated"}, {"text": "子どもとの約束は、忙しくても大切にしたいです。", "target_word": "約束", "complexity_tier": "T3", "furigana": "子[こ]どもとの約束[やくそく]は、忙[いそが]しくても大切[たいせつ]にしたいです。", "sentence_source": "generated"}, {"text": "約束を守らない人には、もう何も頼みたくない。", "target_word": "約束", "complexity_tier": "T3", "furigana": "約束[やくそく]を守[まも]らない人[ひと]には、もう何[なに]も頼[たの]みたくない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "約束する", "label": "終止形"}, {"form": "約束します", "label": "丁寧形"}, {"form": "約束した", "label": "過去形"}, {"form": "約束して", "label": "て形"}, {"form": "約束しない", "label": "否定形"}], "register": "neutral", "sense_fingerprint": "名詞（サ変）。これからすると言ったことを必ず守るという誓い。「約束を守る／破る」「〜と約束する」。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '867e6da7-b7bb-4db0-b05a-8fbe2c1dbaea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36264, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "約束", "is_correct": true, "explanation": "「毎日一緒に宿題をすると約束してくれた」と、これからの行動を誓う意味で文に合う。"}, {"text": "放棄", "is_correct": false, "explanation": "放棄は手放すことで、「宿題をすると放棄してくれた」では意味が通らない。"}, {"text": "脱線", "is_correct": false, "explanation": "脱線は話が本題から外れることで、宿題をすると言う文には合わない。"}, {"text": "反論", "is_correct": false, "explanation": "反論は相手の意見に言い返すことで、宿題をすると言う文には合わない。"}], "explanations": {"約束": "「毎日一緒に宿題をすると約束してくれた」と、これからの行動を誓う意味で文に合う。", "放棄": "放棄は手放すことで、「宿題をすると放棄してくれた」では意味が通らない。", "脱線": "脱線は話が本題から外れることで、宿題をすると言う文には合わない。", "反論": "反論は相手の意見に言い返すことで、宿題をすると言う文には合わない。"}, "sentence_index": 0, "correct_answer": "約束"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "昨日の天気は、雨が降る約束だった。", "explanation": "ここは〈予想〉（まだ起きていない天気を見込む）の意味。約束は人が誓って守る行為なので、天気の見込みには合わない。"}, {"text": "テレビの天気予報は、明日の雨を約束した。", "explanation": "ここは〈予報〉の意味。約束は人が誓って守る行為なので、天気を予測する場面には合わない。"}, {"text": "ホテルの部屋を約束して、旅行へ行った。", "explanation": "ここは〈予約〉（先に取っておく）の意味。約束は人と誓い合う行為なので、部屋を先に押さえる場面には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb5f2262-c6a2-494a-bf81-41eac77c9c52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36264, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "約束", "is_correct": true, "explanation": "友達に謝ったのは、したことを忘れた場面で、約束を忘れたという意味で文に合う。"}, {"text": "停電", "is_correct": false, "explanation": "停電は電気が止まることで、忘れたことを謝る文には合わない。"}, {"text": "熱中", "is_correct": false, "explanation": "熱中は夢中になることで、忘れたことを謝る文には合わない。"}, {"text": "渋滞", "is_correct": false, "explanation": "渋滞は車が進まなくなることで、忘れたことを謝る文には合わない。"}], "explanations": {"約束": "友達に謝ったのは、したことを忘れた場面で、約束を忘れたという意味で文に合う。", "停電": "停電は電気が止まることで、忘れたことを謝る文には合わない。", "熱中": "熱中は夢中になることで、忘れたことを謝る文には合わない。", "渋滞": "渋滞は車が進まなくなることで、忘れたことを謝る文には合わない。"}, "sentence_index": 6, "correct_answer": "約束"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この箱の中には、大切な約束が入っている。", "explanation": "ここは〈品物〉（箱に入れる物）の意味。約束は人同士が誓うことなので、箱に入れられる物の意味では使わない。"}, {"text": "彼は犯人の名前を約束した。", "explanation": "ここは〈名乗る〉の場面。約束は未来の行動を誓うことなので、名前を示す場面には合わない。"}, {"text": "彼は宿題の答えを約束して、先生に出した。", "explanation": "ここは〈提出〉（書いたものを渡す）の意味。約束は人と誓い合うことなので、答えを先生に渡す場面には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb5f2262-c6a2-494a-bf81-41eac77c9c52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36264, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "母は、毎日一緒に散歩をすると約束しくれました。", "corrected_sentence": "母は、毎日一緒に散歩をすると約束してくれました。", "error_description": "「約束してくれました」の「て」が抜けている。「約束しくれました」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb5f2262-c6a2-494a-bf81-41eac77c9c52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36264, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼は約束が守る人なので、家族も安心します。", "corrected_sentence": "彼は約束を守る人なので、家族も安心します。", "error_description": "「守る」は目的語に「を」を取るので、「約束を守る」とする。「約束が守る」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb5f2262-c6a2-494a-bf81-41eac77c9c52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36265, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「約束の時間」の「の」。約束と時間を結ぶ連体修飾の助詞で、文に合う。"}, {"text": "が", "is_correct": false, "explanation": "「約束が時間」では約束が主語になるが、時間と結びつかず不自然。"}, {"text": "を", "is_correct": false, "explanation": "「約束を時間」は目的語として時間につながらず不自然。"}, {"text": "で", "is_correct": false, "explanation": "「約束で時間」は手段や場所の意味にならず不自然。"}], "correct_answer": "の", "explanations": {"の": "「約束の時間」の「の」。約束と時間を結ぶ連体修飾の助詞で、文に合う。", "が": "「約束が時間」では約束が主語になるが、時間と結びつかず不自然。", "を": "「約束を時間」は目的語として時間につながらず不自然。", "で": "「約束で時間」は手段や場所の意味にならず不自然。"}, "error_tags": {"が": "主語", "を": "目的語", "で": "場所・手段"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb5f2262-c6a2-494a-bf81-41eac77c9c52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36265, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb5f2262-c6a2-494a-bf81-41eac77c9c52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36265, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "前もって決めたことや、取り決めた内容。特に、会う日時や場所などを互いに決めること。", "primary_collocate": null, "pronunciation": "やくそく", "ipa": "jakɯsokɯ", "syllable_count": 4, "sentences": [{"text": "今日は友達と六時に駅で会う約束があります。", "target_word": "約束", "complexity_tier": "T3", "furigana": "今日[きょう]は友達[ともだち]と六時[ろくじ]に駅[えき]で会[あ]う約束[やくそく]があります。", "sentence_source": "generated"}, {"text": "約束の時間に遅れないように、早く家を出ました。", "target_word": "約束", "complexity_tier": "T3", "furigana": "約束[やくそく]の時間[じかん]に遅[おく]れないように、早[はや]く家[いえ]を出[で]ました。", "sentence_source": "generated"}, {"text": "来週の金曜日は、先生と会う約束が入っています。", "target_word": "約束", "complexity_tier": "T3", "furigana": "来週[らいしゅう]の金曜日[きんようび]は、先生[せんせい]と会[あ]う約束[やくそく]が入[はい]っています。", "sentence_source": "generated"}, {"text": "約束の場所に行ったが、友達はまだ来ていなかった。", "target_word": "約束", "complexity_tier": "T3", "furigana": "約束[やくそく]の場所[ばしょ]に行[い]ったが、友達[ともだち]はまだ来[き]ていなかった。", "sentence_source": "generated"}, {"text": "すみません、その日はほかの約束があって行けません。", "target_word": "約束", "complexity_tier": "T3", "furigana": "すみません、その日[ひ]はほかの約束[やくそく]があって行[い]けません。", "sentence_source": "generated"}, {"text": "約束の日を間違えて、一日早く店に着いてしまった。", "target_word": "約束", "complexity_tier": "T3", "furigana": "約束[やくそく]の日[ひ]を間違[まちが]えて、一日[いちにち]早[はや]く店[みせ]に着[つ]いてしまった。", "sentence_source": "generated"}, {"text": "母と買い物に行く約束を、雨のため来週に変えました。", "target_word": "約束", "complexity_tier": "T3", "furigana": "母[はは]と買[か]い物[もの]に行[い]く約束[やくそく]を、雨[あめ]のため来週[らいしゅう]に変[か]えました。", "sentence_source": "generated"}, {"text": "社長との約束は午後三時なので、昼ごはんは早めに食べます。", "target_word": "約束", "complexity_tier": "T3", "furigana": "社長[しゃちょう]との約束[やくそく]は午後[ごご]三時[さんじ]なので、昼[ひる]ごはんは早[はや]めに食[た]べます。", "sentence_source": "generated"}, {"text": "約束なしで来たのに、部長は会ってくれた。", "target_word": "約束", "complexity_tier": "T3", "furigana": "約束[やくそく]なしで来[き]たのに、部長[ぶちょう]は会[あ]ってくれた。", "sentence_source": "generated"}, {"text": "彼とは、駅前の喫茶店で会う約束になっています。", "target_word": "約束", "complexity_tier": "T3", "furigana": "彼[かれ]とは、駅前[えきまえ]の喫茶店[きっさてん]で会[あ]う約束[やくそく]になっています。", "sentence_source": "generated"}], "morphological_forms": [{"form": "約束する", "label": "終止形"}, {"form": "約束します", "label": "丁寧形"}, {"form": "約束した", "label": "過去形"}, {"form": "約束して", "label": "て形"}, {"form": "約束の", "label": "連体修飾（の）"}], "register": "neutral", "sense_fingerprint": "名詞。人と会う日時や場所などを前もって決めた取り決め。「約束がある」「約束の時間／場所」。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '867e6da7-b7bb-4db0-b05a-8fbe2c1dbaea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36265, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "約束", "is_correct": true, "explanation": "「会う約束があります」の形で、会う日時を前もって決めたことを表し、文に合う。"}, {"text": "返事", "is_correct": false, "explanation": "「会う返事がある」は意味が通らない。返事は相手への応答で、予定を表さない。"}, {"text": "遠慮", "is_correct": false, "explanation": "「会う遠慮がある」は不自然。遠慮は控えめにすることで、予定の内容を表さない。"}, {"text": "自慢", "is_correct": false, "explanation": "「会う自慢がある」は意味が通らない。自慢は誇ることで、予定を表さない。"}], "explanations": {"約束": "「会う約束があります」の形で、会う日時を前もって決めたことを表し、文に合う。", "返事": "「会う返事がある」は意味が通らない。返事は相手への応答で、予定を表さない。", "遠慮": "「会う遠慮がある」は不自然。遠慮は控えめにすることで、予定の内容を表さない。", "自慢": "「会う自慢がある」は意味が通らない。自慢は誇ることで、予定を表さない。"}, "sentence_index": 0, "correct_answer": "約束"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "レストランの窓側の席を約束しておいた。", "explanation": "ここは〈予約〉の意味。席を前もって取っておくことは予約で、約束は人との取り決めを指すので合わない。"}, {"text": "店員に料理を約束した。", "explanation": "ここは〈注文〉の意味。料理を頼むことは注文で、約束は人と取り決めた内容を指すので合わない。"}, {"text": "来週の試験に向けて、毎日二時間の約束を立てている。", "explanation": "ここは〈計画〉の意味。勉強の見通しは計画で、「約束を立てる」とは言わない。約束は人との取り決めを指すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb5f2262-c6a2-494a-bf81-41eac77c9c52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36265, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "約束", "is_correct": true, "explanation": "「母と買い物に行く約束」を来週に変えたという文脈に合う。"}, {"text": "注意", "is_correct": false, "explanation": "「買い物に行く注意」は意味が通らない。注意は気をつけることで、変える対象にならない。"}, {"text": "勇気", "is_correct": false, "explanation": "「買い物に行く勇気」は意味が通らない。勇気は行動を支える気持ちで、日程を変える対象ではない。"}, {"text": "感想", "is_correct": false, "explanation": "「買い物に行く感想」は意味が通らない。感想は感じたことで、日程を変える対象ではない。"}], "explanations": {"約束": "「母と買い物に行く約束」を来週に変えたという文脈に合う。", "注意": "「買い物に行く注意」は意味が通らない。注意は気をつけることで、変える対象にならない。", "勇気": "「買い物に行く勇気」は意味が通らない。勇気は行動を支える気持ちで、日程を変える対象ではない。", "感想": "「買い物に行く感想」は意味が通らない。感想は感じたことで、日程を変える対象ではない。"}, "sentence_index": 6, "correct_answer": "約束"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は接客の約束が豊富で、どんな客にも慣れている。", "explanation": "ここは〈経験〉の意味。積み重ねた実績は「経験が豊富」と言い、「約束が豊富」とは言わない。"}, {"text": "問題の約束を書き終えたので、先生に提出した。", "explanation": "ここは〈解答〉の意味。問題に書く答えは解答で、約束は人との取り決めなので合わない。"}, {"text": "彼女は料理の約束が上手で、友人にも評判がいい。", "explanation": "ここは〈得意〉の意味。料理の腕前は「料理が上手」「得意」と言い、約束は人との取り決めを指すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb5f2262-c6a2-494a-bf81-41eac77c9c52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36265, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "明日は母と買い物に行く約束がしました。", "corrected_sentence": "明日は母と買い物に行く約束をしました。", "error_description": "「約束をする」の「約束」は目的語なので助詞「を」を使う。「が」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb5f2262-c6a2-494a-bf81-41eac77c9c52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36265, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼は私との約束を守れった。", "corrected_sentence": "彼は私との約束を守った。", "error_description": "「守る」の過去形は「守った」。「守れった」は活用の誤りで、正しくは「守った」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb5f2262-c6a2-494a-bf81-41eac77c9c52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
