INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36266, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "決まった時間よりもあとになること。", "primary_collocate": null, "pronunciation": "おくれる", "ipa": "okɯɾeɾɯ", "syllable_count": 4, "sentences": [{"text": "大雪のため、電車が十分遅れています。", "target_word": "遅れています", "complexity_tier": "T3", "furigana": "大雪[おおゆき]のため、電車[でんしゃ]が十分[じゅっぷん]遅[おく]れています。", "sentence_source": "generated"}, {"text": "バスが十五分遅れたので、みんなで待っていた。", "target_word": "遅れた", "complexity_tier": "T3", "furigana": "バスが十五分[じゅうごふん]遅[おく]れたので、みんなで待[ま]っていた。", "sentence_source": "generated"}, {"text": "雨で工事が遅れて、道が使えるのは来月になる。", "target_word": "遅れて", "complexity_tier": "T3", "furigana": "雨[あめ]で工事[こうじ]が遅[おく]れて、道[みち]が使[つか]えるのは来月[らいげつ]になる。", "sentence_source": "generated"}, {"text": "飛行機の出発が一時間遅れるそうです。", "target_word": "遅れる", "complexity_tier": "T3", "furigana": "飛行機[ひこうき]の出発[しゅっぱつ]が一時間[いちじかん]遅[おく]れるそうです。", "sentence_source": "generated"}, {"text": "荷物の到着が遅れる場合は、お店から連絡があります。", "target_word": "遅れる", "complexity_tier": "T3", "furigana": "荷物[にもつ]の到着[とうちゃく]が遅[おく]れる場合[ばあい]は、お店[みせ]から連絡[れんらく]があります。", "sentence_source": "generated"}, {"text": "朝の会議は、社長が来ないため少し遅れて始まった。", "target_word": "遅れて", "complexity_tier": "T3", "furigana": "朝[あさ]の会議[かいぎ]は、社長[しゃちょう]が来[こ]ないため少[すこ]し遅[おく]れて始[はじ]まった。", "sentence_source": "generated"}, {"text": "風のせいで、船が予定より遅れて港に着きました。", "target_word": "遅れて", "complexity_tier": "T3", "furigana": "風[かぜ]のせいで、船[ふね]が予定[よてい]より遅[おく]れて港[みなと]に着[つ]きました。", "sentence_source": "generated"}, {"text": "工場の機械が止まり、商品の発送が遅れています。", "target_word": "遅れています", "complexity_tier": "T3", "furigana": "工場[こうじょう]の機械[きかい]が止[と]まり、商品[しょうひん]の発送[はっそう]が遅[おく]れています。", "sentence_source": "generated"}, {"text": "天気が悪くて、運動会の開始が遅れました。", "target_word": "遅れました", "complexity_tier": "T3", "furigana": "天気[てんき]が悪[わる]くて、運動会[うんどうかい]の開始[かいし]が遅[おく]れました。", "sentence_source": "generated"}, {"text": "事故の影響で、新幹線が遅れるかもしれません。", "target_word": "遅れる", "complexity_tier": "T3", "furigana": "事故[じこ]の影響[えいきょう]で、新幹線[しんかんせん]が遅[おく]れるかもしれません。", "sentence_source": "generated"}], "morphological_forms": [{"form": "遅れる", "label": "終止形"}, {"form": "遅れます", "label": "丁寧形"}, {"form": "遅れた", "label": "過去形"}, {"form": "遅れて", "label": "て形"}, {"form": "遅れない", "label": "否定形"}, {"form": "遅れれば", "label": "仮定形"}], "register": "neutral", "sense_fingerprint": "下一段動詞。電車・工事・出発など、物事が予定や決まった時刻より後ろにずれること。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '867e6da7-b7bb-4db0-b05a-8fbe2c1dbaea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36266, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "遅れています", "is_correct": true, "explanation": "「十分遅れています」で電車の遅延を表し、大雪のため遅れている文脈に合う。"}, {"text": "壊れています", "is_correct": false, "explanation": "「電車が壊れている」は遅延の意味にならず、大雪の文脈に合わない。"}, {"text": "眠っています", "is_correct": false, "explanation": "「電車が眠っている」は不自然で、遅延とは無関係。"}, {"text": "消えています", "is_correct": false, "explanation": "「電車が消えている」は遅延とは無関係で、文に合わない。"}], "explanations": {"遅れています": "「十分遅れています」で電車の遅延を表し、大雪のため遅れている文脈に合う。", "壊れています": "「電車が壊れている」は遅延の意味にならず、大雪の文脈に合わない。", "眠っています": "「電車が眠っている」は不自然で、遅延とは無関係。", "消えています": "「電車が消えている」は遅延とは無関係で、文に合わない。"}, "sentence_index": 0, "correct_answer": "遅れています"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は足が遅れて、徒競走で最後になってしまった。", "explanation": "ここは〈足が遅い〉の意味。走る速さの遅さは「足が遅い」と言い、「足が遅れる」とは言わないので合わない。"}, {"text": "この道は朝から遅れていて、車が進まない。", "explanation": "ここは〈混む〉の意味。道路の渋滞は「混んでいる」と言い、道路が時刻に遅れるとは言わないので合わない。"}, {"text": "昨夜は仕事が終わらず、遅れて寝た。", "explanation": "ここは〈遅く〉の意味。就寝が遅いことは「遅く寝た」と言い、「遅れて寝た」とは言わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb5f2262-c6a2-494a-bf81-41eac77c9c52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36266, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "遅れて", "is_correct": true, "explanation": "「予定より遅れて港に着きました」で、予定より遅く着いたことを表し、文に合う。"}, {"text": "沈んで", "is_correct": false, "explanation": "「船が沈んで港に着く」は意味が通らない。"}, {"text": "覚えて", "is_correct": false, "explanation": "「船が覚えて港に着く」は意味が通らない。"}, {"text": "集めて", "is_correct": false, "explanation": "「船が集めて港に着く」は意味が通らず、風のせいで着いた文脈にも合わない。"}], "explanations": {"遅れて": "「予定より遅れて港に着きました」で、予定より遅く着いたことを表し、文に合う。", "沈んで": "「船が沈んで港に着く」は意味が通らない。", "覚えて": "「船が覚えて港に着く」は意味が通らない。", "集めて": "「船が集めて港に着く」は意味が通らず、風のせいで着いた文脈にも合わない。"}, "sentence_index": 6, "correct_answer": "遅れて"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は性格が遅れていて、人の話についていけない。", "explanation": "ここは〈理解が鈍い〉の意味。理解の鈍さは「鈍い」と言い、「遅れている」は時刻や進みの話なので合わない。"}, {"text": "今朝の気温は三度遅れている。", "explanation": "ここは〈低い〉の意味。気温の低さは「低い」と言い、「遅れている」とは言わないので合わない。"}, {"text": "彼女は走るのが遅れる。", "explanation": "ここは〈足が遅い〉の意味で、「走るのが遅い」と言う。「遅れる」は予定時刻に後れることで、速さの遅さは表さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb5f2262-c6a2-494a-bf81-41eac77c9c52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36266, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "先ほどの地震で、列車が三十分遅れるています。", "corrected_sentence": "先ほどの地震で、列車が三十分遅れています。", "error_description": "「遅れる」は「遅れて＋います」の形で使う。「遅れるています」は誤りで、正しくは「遅れています」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "遅れた", "is_correct": true, "explanation": "過去形で、バスが遅れたという既に起きた出来事を表し、文に合う。"}, {"text": "遅れて", "is_correct": false, "explanation": "て形は後ろに続けるための形で、「遅れた」という過去の出来事を言い切る文の形ではない。"}, {"text": "遅れない", "is_correct": false, "explanation": "否定形なので「遅れなかった」という意味になり、実際にバスが遅れた事実と逆になる。"}, {"text": "遅れたり", "is_correct": false, "explanation": "「たり」は並べる形で、「ので」に続けると文が成り立たない。"}], "correct_form": "遅れた", "base_form": "遅れる", "form_label": "過去形", "sentence_index": 1, "explanations": {"遅れた": "過去形で、バスが遅れたという既に起きた出来事を表し、文に合う。", "遅れて": "て形は後ろに続けるための形で、「遅れた」という過去の出来事を言い切る文の形ではない。", "遅れない": "否定形なので「遅れなかった」という意味になり、実際にバスが遅れた事実と逆になる。", "遅れたり": "「たり」は並べる形で、「ので」に続けると文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb5f2262-c6a2-494a-bf81-41eac77c9c52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36266, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "明日の会議を、三十分遅れます。", "corrected_sentence": "明日の会議に、三十分遅れます。", "error_description": "「会議に遅れる」のように、遅れる対象には助詞「に」を使う。「を」は誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "遅れています", "is_correct": true, "explanation": "丁寧な進行・結果の形で、発送が遅れている現在の状態を表し、文に合う。"}, {"text": "遅れられています", "is_correct": false, "explanation": "「遅れる」には受身の形がなく、「遅れられています」は不自然で誤り。"}, {"text": "遅れていない", "is_correct": false, "explanation": "否定になり、発送が遅れていないという意味になるので文と逆。"}, {"text": "遅れなかった", "is_correct": false, "explanation": "過去の否定で、遅れなかったという意味になり、文の内容と逆。"}], "correct_form": "遅れています", "base_form": "遅れる", "form_label": "ている形（丁寧）", "sentence_index": 7, "explanations": {"遅れています": "丁寧な進行・結果の形で、発送が遅れている現在の状態を表し、文に合う。", "遅れられています": "「遅れる」には受身の形がなく、「遅れられています」は不自然で誤り。", "遅れていない": "否定になり、発送が遅れていないという意味になるので文と逆。", "遅れなかった": "過去の否定で、遅れなかったという意味になり、文の内容と逆。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb5f2262-c6a2-494a-bf81-41eac77c9c52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
