INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36267, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "予定された時刻や期限に間に合わないこと。", "primary_collocate": null, "pronunciation": "おくれる", "ipa": "okɯɾeɾɯ", "syllable_count": 4, "sentences": [{"text": "朝寝坊をして、学校に遅れてしまいました。", "target_word": "遅れて", "complexity_tier": "T3", "furigana": "朝寝坊[あさねぼう]をして、学校[がっこう]に遅[おく]れてしまいました。", "sentence_source": "generated"}, {"text": "宿題を出すのが遅れて、先生に注意された。", "target_word": "遅れて", "complexity_tier": "T3", "furigana": "宿題[しゅくだい]を出[だ]すのが遅[おく]れて、先生[せんせい]に注意[ちゅうい]された。", "sentence_source": "generated"}, {"text": "締め切りに遅れないように、今夜のうちに報告書を書きます。", "target_word": "遅れない", "complexity_tier": "T3", "furigana": "締[し]め切[き]りに遅[おく]れないように、今夜[こんや]のうちに報告書[ほうこくしょ]を書[か]きます。", "sentence_source": "generated"}, {"text": "道が混んでいて、会議に遅れそうです。", "target_word": "遅れそう", "complexity_tier": "T3", "furigana": "道[みち]が混[こ]んでいて、会議[かいぎ]に遅[おく]れそうです。", "sentence_source": "generated"}, {"text": "家賃の支払いが遅れると、手数料がかかります。", "target_word": "遅れる", "complexity_tier": "T3", "furigana": "家賃[やちん]の支払[しはら]いが遅[おく]れると、手数料[てすうりょう]がかかります。", "sentence_source": "generated"}, {"text": "授業に五分遅れたら、教室に入れてもらえなかった。", "target_word": "遅れたら", "complexity_tier": "T3", "furigana": "授業[じゅぎょう]に五分[ごふん]遅[おく]れたら、教室[きょうしつ]に入[はい]れてもらえなかった。", "sentence_source": "generated"}, {"text": "申し込みが遅れたため、人気の講座は満員だった。", "target_word": "遅れた", "complexity_tier": "T3", "furigana": "申[もう]し込[こ]みが遅[おく]れたため、人気[にんき]の講座[こうざ]は満員[まんいん]だった。", "sentence_source": "generated"}, {"text": "父は仕事が終わらず、夕食の時間に遅れて帰ってきた。", "target_word": "遅れて", "complexity_tier": "T3", "furigana": "父[ちち]は仕事[しごと]が終[お]わらず、夕食[ゆうしょく]の時間[じかん]に遅[おく]れて帰[かえ]ってきた。", "sentence_source": "generated"}, {"text": "遅れてすみません、道に迷ってしまって。", "target_word": "遅れて", "complexity_tier": "T3", "furigana": "遅[おく]れてすみません、道[みち]に迷[まよ]ってしまって。", "sentence_source": "generated"}, {"text": "彼女は一度も試験の時間に遅れたことがない。", "target_word": "遅れた", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は一度[いちど]も試験[しけん]の時間[じかん]に遅[おく]れたことがない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "遅れる", "label": "終止形"}, {"form": "遅れます", "label": "丁寧形"}, {"form": "遅れた", "label": "過去形"}, {"form": "遅れて", "label": "て形"}, {"form": "遅れない", "label": "否定形"}, {"form": "遅れたら", "label": "たら形"}], "register": "neutral", "sense_fingerprint": "下一段動詞。授業・会議・締め切り・支払いなど、予定の時刻や期限に間に合わないこと。「〜に遅れる」。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '867e6da7-b7bb-4db0-b05a-8fbe2c1dbaea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36267, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "遅れて", "is_correct": true, "explanation": "「学校に遅れてしまいました」で、遅刻してしまった残念な気持ちを表し、文に合う。"}, {"text": "驚いて", "is_correct": false, "explanation": "「学校に驚いてしまいました」は意味が通らない。驚くのは出来事に対する気持ちで、場所には結びつかない。"}, {"text": "喜んで", "is_correct": false, "explanation": "「学校に喜んでしまいました」は意味が通らず、朝寝坊の文脈にも合わない。"}, {"text": "悩んで", "is_correct": false, "explanation": "「学校に悩んでしまいました」は意味が通らず、朝寝坊の文脈にも合わない。"}], "explanations": {"遅れて": "「学校に遅れてしまいました」で、遅刻してしまった残念な気持ちを表し、文に合う。", "驚いて": "「学校に驚いてしまいました」は意味が通らない。驚くのは出来事に対する気持ちで、場所には結びつかない。", "喜んで": "「学校に喜んでしまいました」は意味が通らず、朝寝坊の文脈にも合わない。", "悩んで": "「学校に悩んでしまいました」は意味が通らず、朝寝坊の文脈にも合わない。"}, "sentence_index": 0, "correct_answer": "遅れて"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼女は食事をするのがいつも遅れる。", "explanation": "ここは〈食べるのが遅い〉の意味。食べる速さの遅さは「遅い」と言い、「遅れる」とは言わないので合わない。"}, {"text": "その店は値段が遅れていて、安く買える。", "explanation": "ここは〈安い〉の意味。値段の安さは「安い」と言い、「値段が遅れる」とは言わないので合わない。"}, {"text": "彼女は計算がいつも遅れる。", "explanation": "ここは〈計算が速くない〉の意味で、「計算が遅い」と言う。「遅れる」は期限や時刻に間に合わないことで、速さの遅さは表さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb5f2262-c6a2-494a-bf81-41eac77c9c52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36267, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "遅れた", "is_correct": true, "explanation": "「申し込みが遅れたため」で、申し込みの時期がずれた理由を表し、文の「ため」に合う。"}, {"text": "止まった", "is_correct": false, "explanation": "「申し込みが止まった」は理由として満員に結びつかず、不自然。"}, {"text": "眠った", "is_correct": false, "explanation": "「申し込みが眠った」は意味が通らない。"}, {"text": "叫んだ", "is_correct": false, "explanation": "「申し込みが叫んだ」は意味が通らない。"}], "explanations": {"遅れた": "「申し込みが遅れたため」で、申し込みの時期がずれた理由を表し、文の「ため」に合う。", "止まった": "「申し込みが止まった」は理由として満員に結びつかず、不自然。", "眠った": "「申し込みが眠った」は意味が通らない。", "叫んだ": "「申し込みが叫んだ」は意味が通らない。"}, "sentence_index": 6, "correct_answer": "遅れた"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は夜、遅れて寝た。", "explanation": "ここは〈遅く〉の意味。就寝が夜更けであることは「夜遅く寝た」と言い、「遅れて寝た」とは言わないので合わない。"}, {"text": "彼の声は、画面の映像に遅れて響いた。", "explanation": "ここは〈少し後になって届く〉の意味。音の遅れは「遅れて届く」とは言うが、ここは声の響き方を表す文として不自然で、時刻に間に合わない意味とは合わない。"}, {"text": "仕事が終わらず、夜遅れて帰った。", "explanation": "ここは〈遅く〉の意味。帰宅が夜更けであることは「夜遅く帰った」と言い、「遅れて帰った」は時刻に間に合わないことになり合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb5f2262-c6a2-494a-bf81-41eac77c9c52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36267, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "締め切りで遅れたので、申請は受理されなかった。", "corrected_sentence": "締め切りに遅れたので、申請は受理されなかった。", "error_description": "期限に遅れる場合は「締め切りに遅れる」と「に」を使う。「で」は誤りで、正しくは「に」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "遅れて", "is_correct": true, "explanation": "て形で「遅れて、注意された」と続けると、遅れた結果注意されたという因果関係に合う。"}, {"text": "遅れる", "is_correct": false, "explanation": "終止形は文を言い切る形で、「遅れて注意された」という因果の続きには合わない。"}, {"text": "遅れない", "is_correct": false, "explanation": "否定形なので遅れなかったという意味になり、注意された理由と逆になる。"}, {"text": "遅れなかった", "is_correct": false, "explanation": "否定の過去で、遅れなかったのに注意されたことになり、因果が成り立たない。"}], "correct_form": "遅れて", "base_form": "遅れる", "form_label": "て形", "sentence_index": 1, "explanations": {"遅れて": "て形で「遅れて、注意された」と続けると、遅れた結果注意されたという因果関係に合う。", "遅れる": "終止形は文を言い切る形で、「遅れて注意された」という因果の続きには合わない。", "遅れない": "否定形なので遅れなかったという意味になり、注意された理由と逆になる。", "遅れなかった": "否定の過去で、遅れなかったのに注意されたことになり、因果が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb5f2262-c6a2-494a-bf81-41eac77c9c52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36267, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "次の授業に遅れなくように、急ぎます。", "corrected_sentence": "次の授業に遅れないように、急ぎます。", "error_description": "「遅れる」の否定形は「遅れない」。「遅れなく」は誤りで、「ように」と続けるなら「遅れないように」とする。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "遅れて", "is_correct": true, "explanation": "て形で「遅れて帰ってきた」と続けると、夕食の時間に遅れて帰宅した事実に合う。"}, {"text": "遅れます", "is_correct": false, "explanation": "丁寧形は文を言い切る形で、「帰ってきた」と続く文には合わない。"}, {"text": "遅れている", "is_correct": false, "explanation": "継続中の状態を表すので、帰ってきたという完了した出来事と合わない。"}, {"text": "遅れたら", "is_correct": false, "explanation": "仮定の条件を表すので、実際に帰宅した事実を述べる文と合わない。"}], "correct_form": "遅れて", "base_form": "遅れる", "form_label": "て形", "sentence_index": 7, "explanations": {"遅れて": "て形で「遅れて帰ってきた」と続けると、夕食の時間に遅れて帰宅した事実に合う。", "遅れます": "丁寧形は文を言い切る形で、「帰ってきた」と続く文には合わない。", "遅れている": "継続中の状態を表すので、帰ってきたという完了した出来事と合わない。", "遅れたら": "仮定の条件を表すので、実際に帰宅した事実を述べる文と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb5f2262-c6a2-494a-bf81-41eac77c9c52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36268, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "話題を示す「は」で、「兄は努力している」となる。"}, {"text": "を", "is_correct": false, "explanation": "「兄をいつも努力している」は努力する人を目的語にしてしまい非文法的。"}, {"text": "に", "is_correct": false, "explanation": "「兄にいつも努力している」では文が成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「兄でいつも努力している」は非文法的。"}], "correct_answer": "は", "explanations": {"は": "話題を示す「は」で、「兄は努力している」となる。", "を": "「兄をいつも努力している」は努力する人を目的語にしてしまい非文法的。", "に": "「兄にいつも努力している」では文が成り立たない。", "で": "「兄でいつも努力している」は非文法的。"}, "error_tags": {"を": "object", "に": "target", "で": "means"}, "sentence_index": 3}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "怠け", "is_correct": true, "explanation": "がんばらずになまけることで、努力の反対。"}, {"text": "辛抱", "is_correct": false, "explanation": "耐えることで、努力に近く反対ではない。"}, {"text": "熱意", "is_correct": false, "explanation": "強い気持ちで、努力の反対ではない。"}, {"text": "運動", "is_correct": false, "explanation": "体を動かすことで、努力の反対ではない。"}], "correct_answer": "怠け", "explanations": {"怠け": "がんばらずになまけることで、努力の反対。", "辛抱": "耐えることで、努力に近く反対ではない。", "熱意": "強い気持ちで、努力の反対ではない。", "運動": "体を動かすことで、努力の反対ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '861d1c7d-3753-4885-8f4d-62b03829a50d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36268, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「続ける」の目的語を示す「を」で、「努力を続ける」となる。"}, {"text": "が", "is_correct": false, "explanation": "「努力が続ける」は他動詞の目的語に合わず非文法的。"}, {"text": "に", "is_correct": false, "explanation": "「努力に続ける」は「続ける」の目的語を表せず非文法的。"}, {"text": "と", "is_correct": false, "explanation": "「努力と続ける」は意味が通らず非文法的。"}], "correct_answer": "を", "explanations": {"を": "「続ける」の目的語を示す「を」で、「努力を続ける」となる。", "が": "「努力が続ける」は他動詞の目的語に合わず非文法的。", "に": "「努力に続ける」は「続ける」の目的語を表せず非文法的。", "と": "「努力と続ける」は意味が通らず非文法的。"}, "error_tags": {"が": "subject", "に": "target", "と": "comitative"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "怠惰", "is_correct": true, "explanation": "がんばらずになまけることで、努力の反対。"}, {"text": "忍耐", "is_correct": false, "explanation": "耐えることで、努力に近く反対ではない。"}, {"text": "根性", "is_correct": false, "explanation": "粘り強い気持ちで、努力の反対ではない。"}, {"text": "成果", "is_correct": false, "explanation": "努力の結果で、反対の関係ではない。"}], "correct_answer": "怠惰", "explanations": {"怠惰": "がんばらずになまけることで、努力の反対。", "忍耐": "耐えることで、努力に近く反対ではない。", "根性": "粘り強い気持ちで、努力の反対ではない。", "成果": "努力の結果で、反対の関係ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '861d1c7d-3753-4885-8f4d-62b03829a50d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36268, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "あきらめずにがんばること", "primary_collocate": null, "pronunciation": "どりょく", "ipa": "doɾʲokɯ", "syllable_count": 3, "sentences": [{"text": "努力する。", "target_word": "努力", "complexity_tier": "T1", "furigana": "努力[どりょく]する。", "sentence_source": "generated"}, {"text": "毎日努力します。", "target_word": "努力", "complexity_tier": "T2", "furigana": "毎日[まいにち]努力[どりょく]します。", "sentence_source": "generated"}, {"text": "努力が大切だ。", "target_word": "努力", "complexity_tier": "T1", "furigana": "努力[どりょく]が大切[たいせつ]だ。", "sentence_source": "generated"}, {"text": "兄はいつも努力している。", "target_word": "努力", "complexity_tier": "T3", "furigana": "兄[あに]はいつも努力[どりょく]している。", "sentence_source": "generated"}, {"text": "あきらめずに努力しました。", "target_word": "努力", "complexity_tier": "T2", "furigana": "あきらめずに努力[どりょく]しました。", "sentence_source": "generated"}, {"text": "努力のおかげで、一位になれた。", "target_word": "努力", "complexity_tier": "T3", "furigana": "努力[どりょく]のおかげで、一位[いちい]になれた。", "sentence_source": "generated"}, {"text": "彼の努力をみんなが見ている。", "target_word": "努力", "complexity_tier": "T3", "furigana": "彼[かれ]の努力[どりょく]をみんなが見[み]ている。", "sentence_source": "generated"}, {"text": "練習で努力を続けると、上手になる。", "target_word": "努力", "complexity_tier": "T3", "furigana": "練習[れんしゅう]で努力[どりょく]を続[つづ]けると、上手[じょうず]になる。", "sentence_source": "generated"}, {"text": "試合に勝つために、みんなで努力した。", "target_word": "努力", "complexity_tier": "T3", "furigana": "試合[しあい]に勝[か]つために、みんなで努力[どりょく]した。", "sentence_source": "generated"}, {"text": "努力しても、まだ足りないと思う。", "target_word": "努力", "complexity_tier": "T3", "furigana": "努力[どりょく]しても、まだ足[た]りないと思[おも]う。", "sentence_source": "generated"}], "morphological_forms": [{"form": "努力する", "label": "活用"}, {"form": "努力した", "label": "活用"}, {"form": "努力家", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 