INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36268, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "努力", "is_correct": true, "explanation": "「どりょく」で、聞こえた語と一致する。"}, {"text": "魅力", "is_correct": false, "explanation": "「みりょく」で、最初の音が「ど」ではなく「み」。"}, {"text": "視力", "is_correct": false, "explanation": "「しりょく」で、最初の音が「ど」ではなく「し」。"}, {"text": "武力", "is_correct": false, "explanation": "「ぶりょく」で、最初の音が「ど」ではなく「ぶ」。"}, {"text": "度量", "is_correct": false, "explanation": "「どりょう」で、最後の音が「く」ではなく「う」。"}], "explanations": {"努力": "「どりょく」で、聞こえた語と一致する。", "魅力": "「みりょく」で、最初の音が「ど」ではなく「み」。", "視力": "「しりょく」で、最初の音が「ど」ではなく「し」。", "武力": "「ぶりょく」で、最初の音が「ど」ではなく「ぶ」。", "度量": "「どりょう」で、最後の音が「く」ではなく「う」。"}, "sentence_index": null, "correct_answer": "努力"}, "level_3": {"options": [{"text": "努力", "is_correct": true, "explanation": "「努力する」は自然な動詞の形。"}, {"text": "机", "is_correct": false, "explanation": "「机する」という言い方はなく、「する」と結びつかない。"}, {"text": "海", "is_correct": false, "explanation": "「海する」という言い方はなく、「する」と結びつかない。"}, {"text": "帽子", "is_correct": false, "explanation": "「帽子する」はこの意味では使えず、「する」と結びつかない。"}], "explanations": {"努力": "「努力する」は自然な動詞の形。", "机": "「机する」という言い方はなく、「する」と結びつかない。", "海": "「海する」という言い方はなく、「する」と結びつかない。", "帽子": "「帽子する」はこの意味では使えず、「する」と結びつかない。"}, "sentence_index": 0, "correct_answer": "努力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "兄は努力を二つ買ってきた。", "explanation": "努力は買える物ではないので、「買う」の目的語にならない。"}, {"text": "兄はすぐにあきらめるので、いつも努力している。", "explanation": "努力はあきらめずにがんばることなので、すぐあきらめることと矛盾する。"}, {"text": "今朝は努力が降っています。", "explanation": "努力は天気の現象ではないので、「降る」の主語にならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '861d1c7d-3753-4885-8f4d-62b03829a50d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36268, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "努力", "is_correct": true, "explanation": "「どりょく」で、聞こえた語と一致する。"}, {"text": "知力", "is_correct": false, "explanation": "「ちりょく」で、最初の音が「ど」ではなく「ち」。"}, {"text": "浮力", "is_correct": false, "explanation": "「ふりょく」で、最初の音が「ど」ではなく「ふ」。"}, {"text": "磁力", "is_correct": false, "explanation": "「じりょく」で、最初の音が「ど」ではなく「じ」。"}, {"text": "火力", "is_correct": false, "explanation": "「かりょく」で、最初の音が「ど」ではなく「か」。"}], "explanations": {"努力": "「どりょく」で、聞こえた語と一致する。", "知力": "「ちりょく」で、最初の音が「ど」ではなく「ち」。", "浮力": "「ふりょく」で、最初の音が「ど」ではなく「ふ」。", "磁力": "「じりょく」で、最初の音が「ど」ではなく「じ」。", "火力": "「かりょく」で、最初の音が「ど」ではなく「か」。"}, "sentence_index": null, "correct_answer": "努力"}, "level_3": {"options": [{"text": "努力", "is_correct": true, "explanation": "みんなが見ているのは、彼の努力の様子なので意味が合う。"}, {"text": "声", "is_correct": false, "explanation": "形は合うが、声は「見る」ものではないので意味が合わない。"}, {"text": "音", "is_correct": false, "explanation": "形は合うが、音は「見る」ものではないので意味が合わない。"}, {"text": "味", "is_correct": false, "explanation": "形は合うが、味は「見る」ものではないので意味が合わない。"}], "explanations": {"努力": "みんなが見ているのは、彼の努力の様子なので意味が合う。", "声": "形は合うが、声は「見る」ものではないので意味が合わない。", "音": "形は合うが、音は「見る」ものではないので意味が合わない。", "味": "形は合うが、味は「見る」ものではないので意味が合わない。"}, "sentence_index": 6, "correct_answer": "努力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "努力に電話をかけて、約束を決めた。", "explanation": "努力は人や場所ではないので、電話をかける相手にならない。"}, {"text": "毎日寝てばかりいて、何もしないで、とても努力した。", "explanation": "努力はあきらめずにがんばることなので、何もしないことと矛盾する。"}, {"text": "努力を着て、寒い外へ出かけた。", "explanation": "努力は服ではないので、「着る」の目的語にならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '861d1c7d-3753-4885-8f4d-62b03829a50d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLU