INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36269, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「少年の努力」と、努力する人を表す「の」。"}, {"text": "を", "is_correct": false, "explanation": "「少年を努力は」では文が成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「少年で努力は」では名詞をつなげない。"}, {"text": "へ", "is_correct": false, "explanation": "「少年へ努力は」は方向を表す語で、ここでは非文法的。"}], "correct_answer": "の", "explanations": {"の": "「少年の努力」と、努力する人を表す「の」。", "を": "「少年を努力は」では文が成り立たない。", "で": "「少年で努力は」では名詞をつなげない。", "へ": "「少年へ努力は」は方向を表す語で、ここでは非文法的。"}, "error_tags": {"を": "object", "で": "means", "へ": "direction"}, "sentence_index": 0}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "怠惰", "is_correct": true, "explanation": "努力せずになまけることで、努力の反対。"}, {"text": "苦労", "is_correct": false, "explanation": "努力に伴うつらさで、反対ではない。"}, {"text": "我慢", "is_correct": false, "explanation": "耐えることで、努力の反対ではない。"}, {"text": "練習", "is_correct": false, "explanation": "努力の一つの形で、反対ではない。"}], "correct_answer": "怠惰", "explanations": {"怠惰": "努力せずになまけることで、努力の反対。", "苦労": "努力に伴うつらさで、反対ではない。", "我慢": "耐えることで、努力の反対ではない。", "練習": "努力の一つの形で、反対ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '861d1c7d-3753-4885-8f4d-62b03829a50d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36269, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "と", "options": [{"text": "と", "is_correct": true, "explanation": "「かなうと信じる」と、信じる内容を示す「と」。"}, {"text": "を", "is_correct": false, "explanation": "「かなうを信じている」は文として成り立たない。"}, {"text": "が", "is_correct": false, "explanation": "「かなうが信じている」では意味が通らない。"}, {"text": "で", "is_correct": false, "explanation": "「かなうで信じている」は非文法的。"}], "correct_answer": "と", "explanations": {"と": "「かなうと信じる」と、信じる内容を示す「と」。", "を": "「かなうを信じている」は文として成り立たない。", "が": "「かなうが信じている」では意味が通らない。", "で": "「かなうで信じている」は非文法的。"}, "error_tags": {"を": "object", "が": "subject", "で": "means"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "怠慢", "is_correct": true, "explanation": "努力せずになまけることで、努力の反対。"}, {"text": "勤勉", "is_correct": false, "explanation": "まじめに働くことで、努力に近い意味。"}, {"text": "熱心", "is_correct": false, "explanation": "一生懸命なことで、努力に近い意味。"}, {"text": "成功", "is_correct": false, "explanation": "努力の結果で、反対の関係ではない。"}], "correct_answer": "怠慢", "explanations": {"怠慢": "努力せずになまけることで、努力の反対。", "勤勉": "まじめに働くことで、努力に近い意味。", "熱心": "一生懸命なことで、努力に近い意味。", "成功": "努力の結果で、反対の関係ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '861d1c7d-3753-4885-8f4d-62b03829a50d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36269, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "目的を達成するために、一生懸命に取り組むこと。", "primary_collocate": null, "pronunciation": "どりょく", "ipa": "doɾʲokɯ", "syllable_count": 3, "sentences": [{"text": "冷たくて甘いレモネードは、暑さに疲れた人々の喉を潤し、少年の努力は小さな売上となって確実に実を結んでいった。", "target_word": "努力", "complexity_tier": "T6", "furigana": "冷[つめ]たくて甘[あま]いレモネードは、暑[あつ]さに疲[つか]れた人々[ひとびと]の喉[のど]を潤[うるお]し、少年[しょうねん]の努力[どりょく]は小[ちい]さな売上[うりあげ]となって確実[かくじつ]に実[み]を結[むす]んでいった。", "sentence_source": "mined"}, {"text": "努力は大切です。", "target_word": "努力", "complexity_tier": "T2", "furigana": "努力[どりょく]は大切[たいせつ]です。", "sentence_source": "generated"}, {"text": "毎日努力を続けている。", "target_word": "努力", "complexity_tier": "T3", "furigana": "毎日[まいにち]努力[どりょく]を続[つづ]けている。", "sentence_source": "generated"}, {"text": "彼の努力が実って、試験に受かった。", "target_word": "努力", "complexity_tier": "T3", "furigana": "彼[かれ]の努力[どりょく]が実[みの]って、試験[しけん]に受[う]かった。", "sentence_source": "generated"}, {"text": "私は日本語を上手に話せるように努力している。", "target_word": "努力", "complexity_tier": "T3", "furigana": "私[わたし]は日本語[にほんご]を上手[じょうず]に話[はな]せるように努力[どりょく]している。", "sentence_source": "generated"}, {"text": "努力しても、結果が出ないときもある。", "target_word": "努力", "complexity_tier": "T3", "furigana": "努力[どりょく]しても、結果[けっか]が出[で]ないときもある。", "sentence_source": "generated"}, {"text": "先生は生徒の努力をほめた。", "target_word": "努力", "complexity_tier": "T3", "furigana": "先生[せんせい]は生徒[せいと]の努力[どりょく]をほめた。", "sentence_source": "generated"}, {"text": "努力すれば、夢はきっとかなうと信じている。", "target_word": "努力", "complexity_tier": "T4", "furigana": "努力[どりょく]すれば、夢[ゆめ]はきっとかなうと信[しん]じている。", "sentence_source": "generated"}, {"text": "彼女は努力の人で、休まず練習した。", "target_word": "努力", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は努力[どりょく]の人[ひと]で、休[やす]まず練習[れんしゅう]した。", "sentence_source": "generated"}, {"text": "長い間の努力が認められて、賞をもらった。", "target_word": "努力", "complexity_tier": "T4", "furigana": "長[なが]い間[あいだ]の努力[どりょく]が認[みと]められて、賞[しょう]をもらった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "努力する", "label": "活用"}, {"form": "努力した", "label": "活用"}, {"form": "努力家", "label": "派生"}, {"form": "努力目標", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 目的のために懸命に取り組むこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e809459e-112d-418e-b65d-24a3fcd1f3e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36269, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "努力", "is_correct": true, "explanation": "「どりょく」で、聞こえた語と一致する。"}, {"text": "魅力", "is_correct": false, "explanation": "「みりょく」で、最初の音が「ど」ではなく「み」。"}, {"text": "視力", "is_correct": false, "explanation": "「しりょく」で、最初の音が「ど」ではなく「し」。"}, {"text": "武力", "is_correct": false, "explanation": "「ぶりょく」で、最初の音が「ど」ではなく「ぶ」。"}, {"text": "度量", "is_correct": false, "explanation": "「どりょう」で、最後の音が「く」ではなく「う」。"}], "explanations": {"努力": "「どりょく」で、聞こえた語と一致する。", "魅力": "「みりょく」で、最初の音が「ど」ではなく「み」。", "視力": "「しりょく」で、最初の音が「ど」ではなく「し」。", "武力": "「ぶりょく」で、最初の音が「ど」ではなく「ぶ」。", "度量": "「どりょう」で、最後の音が「く」ではなく「う」。"}, "sentence_index": null, "correct_answer": "努力"}, "level_3": {"options": [{"text": "努力", "is_correct": true, "explanation": "売上という実を結ぶのは、少年の努力なので意味が合う。"}, {"text": "身長", "is_correct": false, "explanation": "形は合うが、身長が売上になって実を結ぶのは意味が合わない。"}, {"text": "帽子", "is_correct": false, "explanation": "形は合うが、帽子が売上になって実を結ぶのは意味が合わない。"}, {"text": "年齢", "is_correct": false, "explanation": "形は合うが、年齢が売上になって実を結ぶのは意味が合わない。"}], "explanations": {"努力": "売上という実を結ぶのは、少年の努力なので意味が合う。", "身長": "形は合うが、身長が売上になって実を結ぶのは意味が合わない。", "帽子": "形は合うが、帽子が売上になって実を結ぶのは意味が合わない。", "年齢": "形は合うが、年齢が売上になって実を結ぶのは意味が合わない。"}, "sentence_index": 0, "correct_answer": "努力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "朝ごはんに努力を食べて、体が大きくなった。", "explanation": "努力は取り組むことで食べ物ではないので、「食べる」の目的語にならない。"}, {"text": "彼は何もしないで、ずっと努力している。", "explanation": "努力は懸命に取り組むことなので、何もしないことと矛盾する。"}, {"text": "机の上に努力が置いてあります。", "explanation": "努力は目に見える物ではないので、「置いてある」と合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '861d1c7d-3753-4885-8f4d-62b03829a50d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36269, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "努力", "is_correct": true, "explanation": "「どりょく」で、聞こえた語と一致する。"}, {"text": "知力", "is_correct": false, "explanation": "「ちりょく」で、最初の音が「ど」ではなく「ち」。"}, {"text": "浮力", "is_correct": false, "explanation": "「ふりょく」で、最初の音が「ど」ではなく「ふ」。"}, {"text": "磁力", "is_correct": false, "explanation": "「じりょく」で、最初の音が「ど」ではなく「じ」。"}, {"text": "火力", "is_correct": false, "explanation": "「かりょく」で、最初の音が「ど」ではなく「か」。"}], "explanations": {"努力": "「どりょく」で、聞こえた語と一致する。", "知力": "「ちりょく」で、最初の音が「ど」ではなく「ち」。", "浮力": "「ふりょく」で、最初の音が「ど」ではなく「ふ」。", "磁力": "「じりょく」で、最初の音が「ど」ではなく「じ」。", "火力": "「かりょく」で、最初の音が「ど」ではなく「か」。"}, "sentence_index": null, "correct_answer": "努力"}, "level_3": {"options": [{"text": "努力", "is_correct": true, "explanation": "先生がほめるのは、生徒の努力なので意味が合う。"}, {"text": "遅刻", "is_correct": false, "explanation": "形は合うが、遅刻をほめるのは意味が合わない。"}, {"text": "病気", "is_correct": false, "explanation": "形は合うが、病気をほめるのは意味が合わない。"}, {"text": "喧嘩", "is_correct": false, "explanation": "形は合うが、喧嘩をほめるのは意味が合わない。"}], "explanations": {"努力": "先生がほめるのは、生徒の努力なので意味が合う。", "遅刻": "形は合うが、遅刻をほめるのは意味が合わない。", "病気": "形は合うが、病気をほめるのは意味が合わない。", "喧嘩": "形は合うが、喧嘩をほめるのは意味が合わない。"}, "sentence_index": 6, "correct_answer": "努力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "昨日の夜、公園で努力を拾った。", "explanation": "努力は目に見える物ではないので、「拾う」の目的語にならない。"}, {"text": "彼は遊んでばかりで、毎日とても努力している。", "explanation": "努力は懸命に取り組むことなので、遊んでばかりと矛盾する。"}, {"text": "努力を一杯飲んで、元気になった。", "explanation": "努力は飲み物ではないので、「飲む」の目的語にならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '861d1c7d-3753-4885-8f4d-62b03829a50d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36269, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼は試験に合格するために努力に続けていた。", "corrected_sentence": "彼は試験に合格するために努力を続けていた。", "error_description": "「続ける」の目的語を表すので、「に」ではなく「を」を使う。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '861d1c7d-3753-4885-8f4d-62b03829a50d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36269, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼は何もしなかったので、努力が実って成功した。", "corrected_sentence": "彼は毎日練習したので、努力が実って成功した。", "error_description": "何もしなかったのに「努力が実る」では意味が合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '861d1c7d-3753-4885-8f4d-62b03829a50d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36270, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "正解。「電車が止まった」で、電車を主語にして止まった様子を表す。"}, {"text": "を", "is_correct": false, "explanation": "「止まる」は目的語をとらないため、「電車を止まった」は不自然。"}, {"text": "に", "is_correct": false, "explanation": "「電車に止まる」とは言わない。止まるのは電車自身なので、位置を示す「に」は合わない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は相手や並列を示すが、「電車と止まった」では意味が通らない。"}], "correct_answer": "が", "explanations": {"が": "正解。「電車が止まった」で、電車を主語にして止まった様子を表す。", "を": "「止まる」は目的語をとらないため、「電車を止まった」は不自然。", "に": "「電車に止まる」とは言わない。止まるのは電車自身なので、位置を示す「に」は合わない。", "と": "「と」は相手や並列を示すが、「電車と止まった」では意味が通らない。"}, "error_tags": {"を": "目的語", "に": "位置・相手", "と": "共同・並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a849add-9c71-470c-b7c7-5f19af1c26f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36270, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "正解。「電車の窓」と、窓が電車に属することを示す「の」が必要。"}, {"text": "が", "is_correct": false, "explanation": "「電車が窓から」では電車自身が見ているような文になり、窓の所属を示せない。"}, {"text": "を", "is_correct": false, "explanation": "「電車を窓から」では目的語になり、文の構造が合わない。"}, {"text": "に", "is_correct": false, "explanation": "「電車に窓から」は位置や相手を示すが、窓の所属を表す文脈には合わない。"}], "correct_answer": "の", "explanations": {"の": "正解。「電車の窓」と、窓が電車に属することを示す「の」が必要。", "が": "「電車が窓から」では電車自身が見ているような文になり、窓の所属を示せない。", "を": "「電車を窓から」では目的語になり、文の構造が合わない。", "に": "「電車に窓から」は位置や相手を示すが、窓の所属を表す文脈には合わない。"}, "error_tags": {"が": "主語", "を": "目的語", "に": "位置・相手"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a849add-9c71-470c-b7c7-5f19af1c26f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36270, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "電車とは、電気で走る、線路の上の乗り物です。", "primary_collocate": null, "pronunciation": "でんしゃ", "ipa": "deɲɕa", "syllable_count": 3, "sentences": [{"text": "朝は電車がこんでいて、座れなかった。", "target_word": "電車", "complexity_tier": "T3", "furigana": "朝[あさ]は電車[でんしゃ]がこんでいて、座[すわ]れなかった。", "sentence_source": "generated"}, {"text": "雨で電車が止まったので、会社に遅れた。", "target_word": "電車", "complexity_tier": "T3", "furigana": "雨[あめ]で電車[でんしゃ]が止[と]まったので、会社[かいしゃ]に遅[おく]れた。", "sentence_source": "generated"}, {"text": "駅で電車を待っている間に、本を読んだ。", "target_word": "電車", "complexity_tier": "T3", "furigana": "駅[えき]で電車[でんしゃ]を待[ま]っている間[あいだ]に、本[ほん]を読[よ]んだ。", "sentence_source": "generated"}, {"text": "私は毎日電車で学校へ行きます。", "target_word": "電車", "complexity_tier": "T3", "furigana": "私[わたし]は毎日[まいにち]電車[でんしゃ]で学校[がっこう]へ行[い]きます。", "sentence_source": "generated"}, {"text": "電車の中では、大きな声で話さないでください。", "target_word": "電車", "complexity_tier": "T3", "furigana": "電車[でんしゃ]の中[なか]では、大[おお]きな声[こえ]で話[はな]さないでください。", "sentence_source": "generated"}, {"text": "最後の電車に間に合って、ほっとした。", "target_word": "電車", "complexity_tier": "T3", "furigana": "最後[さいご]の電車[でんしゃ]に間[ま]に合[あ]って、ほっとした。", "sentence_source": "generated"}, {"text": "この電車は東京駅まで行きますか。", "target_word": "電車", "complexity_tier": "T3", "furigana": "この電車[でんしゃ]は東京駅[とうきょうえき]まで行[い]きますか。", "sentence_source": "generated"}, {"text": "電車の窓から、きれいな海が見えた。", "target_word": "電車", "complexity_tier": "T3", "furigana": "電車[でんしゃ]の窓[まど]から、きれいな海[うみ]が見[み]えた。", "sentence_source": "generated"}, {"text": "電車がゆれて、荷物が床に落ちた。", "target_word": "電車", "complexity_tier": "T3", "furigana": "電車[でんしゃ]がゆれて、荷物[にもつ]が床[ゆか]に落[お]ちた。", "sentence_source": "generated"}, {"text": "電車は電気で走るので、バスより静かだ。", "target_word": "電車", "complexity_tier": "T3", "furigana": "電車[でんしゃ]は電気[でんき]で走[はし]るので、バスより静[しず]かだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "電車", "label": "基本形"}], "register": "中立", "sense_fingerprint": "電気で線路の上を走る乗り物（鉄道の車両）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11236ac4-32a0-4c53-9d4d-00c4116c6282') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36270, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "電車", "is_correct": true, "explanation": "正解。「こんでいて」は乗り物の混雑を表し、電車に合う。"}, {"text": "辞書", "is_correct": false, "explanation": "辞書は混みあうものではないので、「朝はこんでいて」と合わない。"}, {"text": "時刻表", "is_correct": false, "explanation": "時刻表は紙に書かれた表なので、「こんでいて」と組み合わない。"}, {"text": "切符", "is_correct": false, "explanation": "切符は一枚ずつ売買するもので、混雑して主語になる言い方はしない。"}], "explanations": {"電車": "正解。「こんでいて」は乗り物の混雑を表し、電車に合う。", "辞書": "辞書は混みあうものではないので、「朝はこんでいて」と合わない。", "時刻表": "時刻表は紙に書かれた表なので、「こんでいて」と組み合わない。", "切符": "切符は一枚ずつ売買するもので、混雑して主語になる言い方はしない。"}, "sentence_index": 0, "correct_answer": "電車"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "昔は電車が石炭を燃やし、煙をあげながら走っていた。", "explanation": "ここは〈汽車〉の意味。電車は電気で走るので、石炭を燃やす蒸気機関の列車には合わない。"}, {"text": "父は週末、電車にガソリンを入れて遠くまでドライブした。", "explanation": "ここは〈車〉の意味。電車は電気で走るのでガソリンは使わず、自動車の文脈になっている。"}, {"text": "この村では、電車を馬が引いて客を町まで運ぶ。", "explanation": "ここは〈馬車〉の意味。電車は電気で走るもので、馬が引く乗り物には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a849add-9c71-470c-b7c7-5f19af1c26f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36270, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "電車", "is_correct": true, "explanation": "正解。「この___は東京駅まで行きますか」の主語として、行き先を尋ねる乗り物に合う。"}, {"text": "地図", "is_correct": false, "explanation": "地図は行き先を尋ねる対象ではなく、「東京駅まで行く」の主語にはならない。"}, {"text": "時刻表", "is_correct": false, "explanation": "時刻表は自分で行くものではないので、「東京駅まで行きますか」と合わない。"}, {"text": "財布", "is_correct": false, "explanation": "財布は移動する主体ではないので、「東京駅まで行きますか」と合わない。"}], "explanations": {"電車": "正解。「この___は東京駅まで行きますか」の主語として、行き先を尋ねる乗り物に合う。", "地図": "地図は行き先を尋ねる対象ではなく、「東京駅まで行く」の主語にはならない。", "時刻表": "時刻表は自分で行くものではないので、「東京駅まで行きますか」と合わない。", "財布": "財布は移動する主体ではないので、「東京駅まで行きますか」と合わない。"}, "sentence_index": 6, "correct_answer": "電車"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この小さな電車は、電気で川を静かに進む。", "explanation": "ここは〈船〉の意味。電車は線路の上を走るもので、川を進むことはできないので合わない。"}, {"text": "弟は電車をこぐのが大好きで、毎朝ペダルを踏んで学校へ行く。", "explanation": "ここは〈自転車〉の意味。電車はペダルを踏んで進むものではないので、「こぐ」「ペダル」と合わない。"}, {"text": "この町では、電車を人が引いて観光客を乗せて走る。", "explanation": "ここは〈人力車〉の意味。電車は電気で走るので、人が引く乗り物には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a849add-9c71-470c-b7c7-5f19af1c26f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36270, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "駅のホームで電車を乗り遅れた。", "corrected_sentence": "駅のホームで電車に乗り遅れた。", "error_description": "「乗り遅れる」の相手は「に」で示す。「電車を」は誤りで、正しくは「電車に乗り遅れた」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a849add-9c71-470c-b7c7-5f19af1c26f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36270, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "昨日は電車を遅れたので、待ち合わせに遅刻した。", "corrected_sentence": "昨日は電車が遅れたので、待ち合わせに遅刻した。", "error_description": "「遅れる」は自動詞で、主語は「電車が」になる。「電車を」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a849add-9c71-470c-b7c7-5f19af1c26f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36271, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "正解。「新しい電車が走り始める」で、電車を主語にして走り始めることを表す。"}, {"text": "を", "is_correct": false, "explanation": "「走り始める」は目的語をとらないため、「電車を走り始める」は不自然。"}, {"text": "に", "is_correct": false, "explanation": "「電車に走り始める」は文として成り立たず、位置を示す「に」は合わない。"}, {"text": "と", "is_correct": false, "explanation": "「電車と走り始める」は並列の意味になり、文の主語が決まらない。"}], "correct_answer": "が", "explanations": {"が": "正解。「新しい電車が走り始める」で、電車を主語にして走り始めることを表す。", "を": "「走り始める」は目的語をとらないため、「電車を走り始める」は不自然。", "に": "「電車に走り始める」は文として成り立たず、位置を示す「に」は合わない。", "と": "「電車と走り始める」は並列の意味になり、文の主語が決まらない。"}, "error_tags": {"を": "目的語", "に": "位置・相手", "と": "共同・並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a849add-9c71-470c-b7c7-5f19af1c26f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
