INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36271, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "電車は、電気を動力として線路上を走る鉄道車両です。", "primary_collocate": null, "pronunciation": "でんしゃ", "ipa": "deɲɕa", "syllable_count": 3, "sentences": [{"text": "電車は電気の力で線路の上を走る。", "target_word": "電車", "complexity_tier": "T3", "furigana": "電車[でんしゃ]は電気[でんき]の力[ちから]で線路[せんろ]の上[うえ]を走[はし]る。", "sentence_source": "generated"}, {"text": "新しい電車が来年から走り始める。", "target_word": "電車", "complexity_tier": "T3", "furigana": "新[あたら]しい電車[でんしゃ]が来年[らいねん]から走[はし]り始[はじ]める。", "sentence_source": "generated"}, {"text": "電車の運転士は、時間どおりに駅へ着くよう気をつけている。", "target_word": "電車", "complexity_tier": "T3", "furigana": "電車[でんしゃ]の運転士[うんてんし]は、時間[じかん]どおりに駅[えき]へ着[つ]くよう気[き]をつけている。", "sentence_source": "generated"}, {"text": "都会では電車が発達していて、車がなくても便利だ。", "target_word": "電車", "complexity_tier": "T3", "furigana": "都会[とかい]では電車[でんしゃ]が発達[はったつ]していて、車[くるま]がなくても便利[べんり]だ。", "sentence_source": "generated"}, {"text": "子どものころ、家の近くを走る電車を見るのが好きだった。", "target_word": "電車", "complexity_tier": "T3", "furigana": "子[こ]どものころ、家[いえ]の近[ちか]くを走[はし]る電[でん]車[しゃ]を見[み]るのが好[す]きだった。", "sentence_source": "generated"}, {"text": "電車の本数が少ない町なので、時刻表をよく見る。", "target_word": "電車", "complexity_tier": "T3", "furigana": "電車[でんしゃ]の本数[ほんすう]が少[すく]ない町[まち]なので、時刻表[じこくひょう]をよく見[み]る。", "sentence_source": "generated"}, {"text": "電車が駅にとまると、たくさんの人がおりた。", "target_word": "電車", "complexity_tier": "T3", "furigana": "電車[でんしゃ]が駅[えき]にとまると、たくさんの人[ひと]がおりた。", "sentence_source": "generated"}, {"text": "事故のため、電車は三十分ほどおくれて着いた。", "target_word": "電車", "complexity_tier": "T3", "furigana": "事故[じこ]のため、電車[でんしゃ]は三十分[さんじゅっぷん]ほどおくれて着[つ]いた。", "sentence_source": "generated"}, {"text": "弟は電車が大好きで、毎週写真を撮りに行く。", "target_word": "電車", "complexity_tier": "T3", "furigana": "弟[おとうと]は電車[でんしゃ]が大好[だいす]きで、毎週[まいしゅう]写真[しゃしん]を撮[と]りに行[い]く。", "sentence_source": "generated"}, {"text": "電車の音が聞こえたので、急いで改札を通った。", "target_word": "電車", "complexity_tier": "T3", "furigana": "電車[でんしゃ]の音[おと]が聞[き]こえたので、急[いそ]いで改札[かいさつ]を通[とお]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "電車", "label": "基本形"}], "register": "中立", "sense_fingerprint": "電気を動力に線路上を走る鉄道車両", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11236ac4-32a0-4c53-9d4d-00c4116c6282') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36271, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "電車", "is_correct": true, "explanation": "正解。電気の力で線路の上を走る乗り物として、文の主語に合う。"}, {"text": "飛行機", "is_correct": false, "explanation": "飛行機は空を飛ぶもので、線路の上を走ることはないので合わない。"}, {"text": "船", "is_correct": false, "explanation": "船は水上を進むもので、線路の上を走ることはないので合わない。"}, {"text": "自転車", "is_correct": false, "explanation": "自転車は線路を走らず、電気の力で動くものでもないので合わない。"}], "explanations": {"電車": "正解。電気の力で線路の上を走る乗り物として、文の主語に合う。", "飛行機": "飛行機は空を飛ぶもので、線路の上を走ることはないので合わない。", "船": "船は水上を進むもので、線路の上を走ることはないので合わない。", "自転車": "自転車は線路を走らず、電気の力で動くものでもないので合わない。"}, "sentence_index": 0, "correct_answer": "電車"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "弟は毎朝、電車のペダルを踏んで学校へ行く。", "explanation": "ここは〈自転車〉の意味。電車にはペダルがなく、踏んで進む乗り物ではないので合わない。"}, {"text": "電車の帆が風を受けて、川を進んだ。", "explanation": "ここは〈船〉の意味。電車には帆がなく、風の力では進まないので合わない。"}, {"text": "昔の電車は石炭を燃やし、煙をあげながら走った。", "explanation": "ここは〈汽車〉の意味。電車は電気で走るので、石炭を燃やす乗り物には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a849add-9c71-470c-b7c7-5f19af1c26f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36271, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "電車", "is_correct": true, "explanation": "正解。電車が駅に止まって人が降りる、という流れの主語に合う。"}, {"text": "時刻表", "is_correct": false, "explanation": "時刻表は駅に止まる乗り物ではないので、「駅にとまる」と合わない。"}, {"text": "切符", "is_correct": false, "explanation": "切符は駅に止まって人が降りる動作をしないので、この文の主語にならない。"}, {"text": "荷物", "is_correct": false, "explanation": "荷物は自分で駅に止まらないので、「駅にとまると」と合わない。"}], "explanations": {"電車": "正解。電車が駅に止まって人が降りる、という流れの主語に合う。", "時刻表": "時刻表は駅に止まる乗り物ではないので、「駅にとまる」と合わない。", "切符": "切符は駅に止まって人が降りる動作をしないので、この文の主語にならない。", "荷物": "荷物は自分で駅に止まらないので、「駅にとまると」と合わない。"}, "sentence_index": 6, "correct_answer": "電車"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "電車で空を飛んで、急いで空港の出口を通った。", "explanation": "ここは〈飛行機〉の意味。電車は線路を走る乗り物で空は飛ばないので合わない。"}, {"text": "電車のガソリンが切れたので、急いで改札を通った。", "explanation": "ここは〈自動車〉の意味。電車はガソリンでは走らず、電気で動くので合わない。"}, {"text": "電車を人が引いて、観光客を乗せて走った。", "explanation": "ここは〈人力車〉の意味。電車は電気で走るので、人が引く乗り物には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a849add-9c71-470c-b7c7-5f19af1c26f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36271, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "駅から電車で乗って、会社へ向かった。", "corrected_sentence": "駅から電車に乗って、会社へ向かった。", "error_description": "「乗る」の相手は「に」で示す。「電車で乗る」は誤りで、正しくは「電車に乗って」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a849add-9c71-470c-b7c7-5f19af1c26f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36271, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "電車を止まったので、待ち合わせに間に合わなかった。", "corrected_sentence": "電車が止まったので、待ち合わせに間に合わなかった。", "error_description": "「止まる」は自動詞で、主語は「電車が」になる。「電車を止まった」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a849add-9c71-470c-b7c7-5f19af1c26f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36272, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "正解。「会議が長引く」で、会議を主語にして長引いたことを表す。"}, {"text": "を", "is_correct": false, "explanation": "「長引く」は自動詞なので目的語をとらず、「会議を長引いて」は不自然。"}, {"text": "に", "is_correct": false, "explanation": "「会議に長引いて」は成り立たず、位置や相手を示す「に」は合わない。"}, {"text": "と", "is_correct": false, "explanation": "「会議と長引いて」は並列の意味になり、文の主語が決まらない。"}], "correct_answer": "が", "explanations": {"が": "正解。「会議が長引く」で、会議を主語にして長引いたことを表す。", "を": "「長引く」は自動詞なので目的語をとらず、「会議を長引いて」は不自然。", "に": "「会議に長引いて」は成り立たず、位置や相手を示す「に」は合わない。", "と": "「会議と長引いて」は並列の意味になり、文の主語が決まらない。"}, "error_tags": {"を": "目的語", "に": "位置・相手", "と": "共同・並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a849add-9c71-470c-b7c7-5f19af1c26f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36272, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "正解。「会議に出席する」で、出席する先を示す「に」が正しい。"}, {"text": "を", "is_correct": false, "explanation": "「出席する」は目的語をとらないため、「会議を出席する」は誤り。"}, {"text": "が", "is_correct": false, "explanation": "「会議が出席する」では会議自体が出席するような文になり、意味が合わない。"}, {"text": "の", "is_correct": false, "explanation": "「の」を重ねると「会議のは」となり、文として成り立たない。"}], "correct_answer": "に", "explanations": {"に": "正解。「会議に出席する」で、出席する先を示す「に」が正しい。", "を": "「出席する」は目的語をとらないため、「会議を出席する」は誤り。", "が": "「会議が出席する」では会議自体が出席するような文になり、意味が合わない。", "の": "「の」を重ねると「会議のは」となり、文として成り立たない。"}, "error_tags": {"を": "目的語", "が": "主語", "の": "所属・連体"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a849add-9c71-470c-b7c7-5f19af1c26f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36272, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "会議とは、みんなが集まって話し合うことです。", "primary_collocate": null, "pronunciation": "かいぎ", "ipa": "kaiɡi", "syllable_count": 3, "sentences": [{"text": "明日の朝九時から会議があります。", "target_word": "会議", "complexity_tier": "T3", "furigana": "明日[あした]の朝[あさ]九時[くじ]から会議[かいぎ]があります。", "sentence_source": "generated"}, {"text": "会議が長引いて、昼ご飯を食べる時間がなかった。", "target_word": "会議", "complexity_tier": "T3", "furigana": "会議[かいぎ]が長引[ながび]いて、昼[ひる]ご飯[はん]を食[た]べる時間[じかん]がなかった。", "sentence_source": "generated"}, {"text": "会議で、新しい計画についてみんなで話した。", "target_word": "会議", "complexity_tier": "T3", "furigana": "会議[かいぎ]で、新[あたら]しい計画[けいかく]についてみんなで話[はな]した。", "sentence_source": "generated"}, {"text": "先生たちは今、会議をしているので、教室にいない。", "target_word": "会議", "complexity_tier": "T3", "furigana": "先生[せんせい]たちは今[いま]、会議[かいぎ]をしているので、教室[きょうしつ]にいない。", "sentence_source": "generated"}, {"text": "会議の前に、資料をコピーしておいてください。", "target_word": "会議", "complexity_tier": "T3", "furigana": "会議[かいぎ]の前[まえ]に、資料[しりょう]をコピーしておいてください。", "sentence_source": "generated"}, {"text": "私は会議で意見を言うのが少し苦手だ。", "target_word": "会議", "complexity_tier": "T3", "furigana": "私[わたし]は会議[かいぎ]で意見[いけん]を言[い]うのが少[すこ]し苦手[にがて]だ。", "sentence_source": "generated"}, {"text": "会議が終わったあと、みんなでお茶を飲んだ。", "target_word": "会議", "complexity_tier": "T3", "furigana": "会議[かいぎ]が終[お]わったあと、みんなでお茶[ちゃ]を飲[の]んだ。", "sentence_source": "generated"}, {"text": "来週の会議には、社長も出席するそうだ。", "target_word": "会議", "complexity_tier": "T3", "furigana": "来週[らいしゅう]の会議[かいぎ]には、社長[しゃちょう]も出席[しゅっせき]するそうだ。", "sentence_source": "generated"}, {"text": "町の会議で、公園を作ることが決まった。", "target_word": "会議", "complexity_tier": "T3", "furigana": "町[まち]の会議[かいぎ]で、公園[こうえん]を作[つく]ることが決[き]まった。", "sentence_source": "generated"}, {"text": "今日は会議があるので、早く帰れない。", "target_word": "会議", "complexity_tier": "T3", "furigana": "今日[きょう]は会議[かいぎ]があるので、早[はや]く帰[かえ]れない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "会議", "label": "基本形"}], "register": "中立", "sense_fingerprint": "みんなが集まって話し合うこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11236ac4-32a0-4c53-9d4d-00c4116c6282') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36272, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "会議", "is_correct": true, "explanation": "正解。「明日の朝九時から会議があります」と、予定の内容として自然に合う。"}, {"text": "眠気", "is_correct": false, "explanation": "眠気は予定として「あります」と並ばないので、「明日の朝九時から」と合わない。"}, {"text": "湿度", "is_correct": false, "explanation": "湿度は予定の内容にならないので、「明日の朝九時からあります」と合わない。"}, {"text": "味", "is_correct": false, "explanation": "味は予定の対象にならないので、「明日の朝九時からあります」と合わない。"}], "explanations": {"会議": "正解。「明日の朝九時から会議があります」と、予定の内容として自然に合う。", "眠気": "眠気は予定として「あります」と並ばないので、「明日の朝九時から」と合わない。", "湿度": "湿度は予定の内容にならないので、「明日の朝九時からあります」と合わない。", "味": "味は予定の対象にならないので、「明日の朝九時からあります」と合わない。"}, "sentence_index": 0, "correct_answer": "会議"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "私は毎朝、会議で歯を磨いてから出かける。", "explanation": "ここは〈洗面所〉の意味。会議は話し合いの集まりで、歯を磨く場所ではないので合わない。"}, {"text": "会議で、志望動機を三つ聞かれた。", "explanation": "ここは〈面接〉の意味。会議は複数の人が話し合う場で、志望動機を個別に問われる面接とは違うので合わない。"}, {"text": "会議に予定を貼っておいた。", "explanation": "ここは〈掲示板〉の意味。会議は予定を貼る場所ではなく、「貼る」と合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a849add-9c71-470c-b7c7-5f19af1c26f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36272, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "会議", "is_correct": true, "explanation": "正解。「会議が終わったあと」で、終わる出来事の主語に合う。"}, {"text": "財布", "is_correct": false, "explanation": "財布は持ち歩く物で、終わる出来事の主語にならないので、「が終わったあと」と合わない。"}, {"text": "窓", "is_correct": false, "explanation": "窓は開け閉めする物で、終わる出来事の主語にならないので、「が終わったあと」と合わない。"}, {"text": "熱意", "is_correct": false, "explanation": "熱意は終わる出来事の主語として不自然なので、この文には合わない。"}], "explanations": {"会議": "正解。「会議が終わったあと」で、終わる出来事の主語に合う。", "財布": "財布は持ち歩く物で、終わる出来事の主語にならないので、「が終わったあと」と合わない。", "窓": "窓は開け閉めする物で、終わる出来事の主語にならないので、「が終わったあと」と合わない。", "熱意": "熱意は終わる出来事の主語として不自然なので、この文には合わない。"}, "sentence_index": 6, "correct_answer": "会議"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今日は会議に並んでいるので、早く帰れない。", "explanation": "ここは〈行列〉の意味。会議は並んで順番を待つものではないので、「並ぶ」と合わない。"}, {"text": "今日は会議を教えるので、早く帰れない。", "explanation": "ここは〈授業〉の意味。会議は教える対象ではないので、「教える」と合わない。"}, {"text": "今日は会議を出すので、早く帰れない。", "explanation": "ここは〈宿題〉の意味。会議は提出するものではないので、「出す」と合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a849add-9c71-470c-b7c7-5f19af1c26f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36272, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "会議を参加するため、早めに会社へ行った。", "corrected_sentence": "会議に参加するため、早めに会社へ行った。", "error_description": "「参加する」の相手は「に」で示す。「会議を参加する」は誤りで、正しくは「会議に参加する」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a849add-9c71-470c-b7c7-5f19af1c26f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36272, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "急な会議を入ったので、夕方の約束を変えた。", "corrected_sentence": "急な会議が入ったので、夕方の約束を変えた。", "error_description": "「入る」は自動詞で、主語は「会議が」になる。「会議を入った」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a849add-9c71-470c-b7c7-5f19af1c26f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36273, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "正解。「会議には集まり」で、集まる場所を示す「に」が正しい。"}, {"text": "を", "is_correct": false, "explanation": "「集まる」は目的語をとらないため、「会議を集まり」は不自然。"}, {"text": "が", "is_correct": false, "explanation": "「会議が集まり」では会議自体が集まるような文になり、場所を示せない。"}, {"text": "と", "is_correct": false, "explanation": "「会議と集まり」は並列の意味になり、集まる場所を示せない。"}], "correct_answer": "に", "explanations": {"に": "正解。「会議には集まり」で、集まる場所を示す「に」が正しい。", "を": "「集まる」は目的語をとらないため、「会議を集まり」は不自然。", "が": "「会議が集まり」では会議自体が集まるような文になり、場所を示せない。", "と": "「会議と集まり」は並列の意味になり、集まる場所を示せない。"}, "error_tags": {"を": "目的語", "が": "主語", "と": "共同・並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a849add-9c71-470c-b7c7-5f19af1c26f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
