INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36273, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "複数の人が集まって、意見を交換したり、決定をしたりする集まり。", "primary_collocate": null, "pronunciation": "かいぎ", "ipa": "kaiɡi", "syllable_count": 3, "sentences": [{"text": "部長は会議で、各部署の意見を聞いてから決定した。", "target_word": "会議", "complexity_tier": "T3", "furigana": "部長[ぶちょう]は会議[かいぎ]で、各部署[かくぶしょ]の意見[いけん]を聞[き]いてから決定[けってい]した。", "sentence_source": "generated"}, {"text": "会議には十人の代表が集まり、予算について話し合った。", "target_word": "会議", "complexity_tier": "T3", "furigana": "会議[かいぎ]には十人[じゅうにん]の代表[だいひょう]が集[あつ]まり、予算[よさん]について話[はな]し合[あ]った。", "sentence_source": "generated"}, {"text": "会議はオンラインで行われ、遠くにいる人も参加できた。", "target_word": "会議", "complexity_tier": "T3", "furigana": "会議[かいぎ]はオンラインで行[おこな]われ、遠[とお]くにいる人[ひと]も参加[さんか]できた。", "sentence_source": "generated"}, {"text": "会議で意見が分かれたため、結論は次回に持ち越された。", "target_word": "会議", "complexity_tier": "T3", "furigana": "会議[かいぎ]で意見[いけん]が分[わ]かれたため、結論[けつろん]は次回[じかい]に持[も]ち越[こ]された。", "sentence_source": "generated"}, {"text": "緊急の会議が開かれ、対策が話し合われた。", "target_word": "会議", "complexity_tier": "T3", "furigana": "緊急[きんきゅう]の会議[かいぎ]が開[ひら]かれ、対策[たいさく]が話[はな]し合[あ]われた。", "sentence_source": "generated"}, {"text": "会議の議事録は、新人の田中さんが書くことになっている。", "target_word": "会議", "complexity_tier": "T3", "furigana": "会議[かいぎ]の議事録[ぎじろく]は、新人[しんじん]の田中[たなか]さんが書[か]くことになっている。", "sentence_source": "generated"}, {"text": "会議が始まる前に、司会者が今日の議題を説明した。", "target_word": "会議", "complexity_tier": "T3", "furigana": "会議[かいぎ]が始[はじ]まる前[まえ]に、司会者[しかいしゃ]が今日[きょう]の議題[ぎだい]を説明[せつめい]した。", "sentence_source": "generated"}, {"text": "全員が賛成したので、会議はすぐに終わった。", "target_word": "会議", "complexity_tier": "T3", "furigana": "全員[ぜんいん]が賛成[さんせい]したので、会議[かいぎ]はすぐに終[お]わった。", "sentence_source": "generated"}, {"text": "国々の代表が集まる会議で、環境問題が取り上げられた。", "target_word": "会議", "complexity_tier": "T3", "furigana": "国々[くにぐに]の代表[だいひょう]が集[あつ]まる会議[かいぎ]で、環境問題[かんきょうもんだい]が取[と]り上[あ]げられた。", "sentence_source": "generated"}, {"text": "会議で決まったことは、メールで全員に伝えます。", "target_word": "会議", "complexity_tier": "T3", "furigana": "会議[かいぎ]で決[き]まったことは、メールで全員[ぜんいん]に伝[つた]えます。", "sentence_source": "generated"}], "morphological_forms": [{"form": "会議", "label": "基本形"}], "register": "中立", "sense_fingerprint": "複数の人が集まり、意見を交わしたり物事を決めたりする公式な集まり", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 3 above tier T2: contains vocabulary far above tier T2: 持ち越さ (Zipf 2.28)']::text[], '11236ac4-32a0-4c53-9d4d-00c4116c6282') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36273, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "会議", "is_correct": true, "explanation": "正解。「部長は会議で、意見を聞いてから決定した」と、決定の場として合う。"}, {"text": "眠気", "is_correct": false, "explanation": "眠気は意見を聞く場所にならないので、「部長は眠気で」と合わない。"}, {"text": "雨", "is_correct": false, "explanation": "雨は決定の場所にならないので、「部長は雨で」と合わない。"}, {"text": "味", "is_correct": false, "explanation": "味は決定の場所にならないので、「部長は味で」と合わない。"}], "explanations": {"会議": "正解。「部長は会議で、意見を聞いてから決定した」と、決定の場として合う。", "眠気": "眠気は意見を聞く場所にならないので、「部長は眠気で」と合わない。", "雨": "雨は決定の場所にならないので、「部長は雨で」と合わない。", "味": "味は決定の場所にならないので、「部長は味で」と合わない。"}, "sentence_index": 0, "correct_answer": "会議"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夏の会議で、大きな花火が三十発上がった。", "explanation": "ここは〈花火大会〉の意味。会議は話し合いの集まりで、花火が上がる催しではないので合わない。"}, {"text": "会議でゴールを決めて、チームが勝った。", "explanation": "ここは〈試合〉の意味。会議はゴールを決める場ではないので、「ゴールを決める」と合わない。"}, {"text": "会議で、足の骨をつないだ。", "explanation": "ここは〈手術〉の意味。会議は話し合いの集まりで、骨をつなぐ治療の場ではないので、「つないだ」と合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a849add-9c71-470c-b7c7-5f19af1c26f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36273, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "会議", "is_correct": true, "explanation": "正解。「会議が始まる前に」で、始まる出来事の主語に合う。"}, {"text": "湿度", "is_correct": false, "explanation": "湿度は始まる出来事ではないので、「が始まる前に」と合わない。"}, {"text": "味", "is_correct": false, "explanation": "味は始まる出来事ではないので、「が始まる前に」と合わない。"}, {"text": "年齢", "is_correct": false, "explanation": "年齢は始まる出来事ではないので、「が始まる前に」と合わない。"}], "explanations": {"会議": "正解。「会議が始まる前に」で、始まる出来事の主語に合う。", "湿度": "湿度は始まる出来事ではないので、「が始まる前に」と合わない。", "味": "味は始まる出来事ではないので、「が始まる前に」と合わない。", "年齢": "年齢は始まる出来事ではないので、「が始まる前に」と合わない。"}, "sentence_index": 6, "correct_answer": "会議"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "会議で、みんなでお酒を飲んで盛り上がった。", "explanation": "ここは〈宴会〉の意味。会議は議題について話し合う場で、飲んで盛り上がる集まりではない。"}, {"text": "会議で、玉ねぎを炒めてから、スープを作った。", "explanation": "ここは〈料理〉の意味。会議は料理をする場ではないので、「炒める」「作る」と合わない。"}, {"text": "会議で、大学の志望理由を聞かれた。", "explanation": "ここは〈面接〉の意味。会議は志望理由を聞く場ではないので、「聞かれた」と合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a849add-9c71-470c-b7c7-5f19af1c26f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36273, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "新しい会議を出席するため、午前中は予定を空けた。", "corrected_sentence": "新しい会議に出席するため、午前中は予定を空けた。", "error_description": "「出席する」の相手は「に」で示す。「会議を出席する」は誤りで、正しくは「会議に出席する」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a849add-9c71-470c-b7c7-5f19af1c26f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36273, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "会議を遅刻したので、社長に謝った。", "corrected_sentence": "会議に遅刻したので、社長に謝った。", "error_description": "「遅刻する」の相手は「に」で示す。「会議を遅刻する」は誤りで、正しくは「会議に遅刻する」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a849add-9c71-470c-b7c7-5f19af1c26f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36274, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「最後の一点で決まる」の基準・手段を示す「で」が正しい。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語で、「決まる」には取らない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向で、「一点へ決まる」は合わない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較で、ここでは比べる文脈がない。"}], "correct_answer": "で", "explanations": {"で": "「最後の一点で決まる」の基準・手段を示す「で」が正しい。", "を": "「を」は目的語で、「決まる」には取らない。", "へ": "「へ」は方向で、「一点へ決まる」は合わない。", "より": "「より」は比較で、ここでは比べる文脈がない。"}, "error_tags": {"を": "目的語", "へ": "方向", "より": "比較"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '616496e4-4d0a-47ad-b093-14a19d5697f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36274, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "主題の「は」で、「方針は」と話題を示す。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞をつなぐ助詞で、「方針の自然に」は続かない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列・相手で、「方針と決まる」は意味が合わない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は結果を示すが、ここでは「自然に」と続かず不自然。"}], "correct_answer": "は", "explanations": {"は": "主題の「は」で、「方針は」と話題を示す。", "の": "「の」は名詞をつなぐ助詞で、「方針の自然に」は続かない。", "と": "「と」は並列・相手で、「方針と決まる」は意味が合わない。", "に": "「に」は結果を示すが、ここでは「自然に」と続かず不自然。"}, "error_tags": {"の": "連体", "と": "並列・相手", "に": "結果・対象"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '616496e4-4d0a-47ad-b093-14a19d5697f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36274, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "試合の結果・日程・順番などが、成り行きや条件によって定まり、変わらなくなること。", "primary_collocate": null, "pronunciation": "きまる", "ipa": "kimaɾɯ", "syllable_count": 3, "sentences": [{"text": "来週の会議の日程は、月曜日に決まる予定だ。", "target_word": "決まる", "complexity_tier": "T3", "furigana": "来週[らいしゅう]の会議[かいぎ]の日程[にってい]は、月曜日[げつようび]に決[き]まる予定[よてい]だ。", "sentence_source": "generated"}, {"text": "試合の結果は、最後の一点で決まる。", "target_word": "決まる", "complexity_tier": "T3", "furigana": "試合[しあい]の結果[けっか]は、最後[さいご]の一点[いってん]で決[き]まる。", "sentence_source": "generated"}, {"text": "行き先が決まるまで、切符は買わないでおこう。", "target_word": "決まる", "complexity_tier": "T3", "furigana": "行[い]き先[さき]が決[き]まるまで、切符[きっぷ]は買[か]わないでおこう。", "sentence_source": "generated"}, {"text": "席は番号で決まるので、好きな場所には座れない。", "target_word": "決まる", "complexity_tier": "T3", "furigana": "席[せき]は番号[ばんごう]で決[き]まるので、好[す]きな場所[ばしょ]には座[すわ]れない。", "sentence_source": "generated"}, {"text": "優勝チームが決まる瞬間を、全員が息をのんで見守った。", "target_word": "決まる", "complexity_tier": "T3", "furigana": "優勝[ゆうしょう]チームが決[き]まる瞬間[しゅんかん]を、全員[ぜんいん]が息[いき]をのんで見守[みまも]った。", "sentence_source": "generated"}, {"text": "就職先が決まる前は、毎日とても不安だった。", "target_word": "決まる", "complexity_tier": "T3", "furigana": "就職先[しゅうしょくさき]が決[き]まる前[まえ]は、毎日[まいにち]とても不安[ふあん]だった。", "sentence_source": "generated"}, {"text": "部屋の広さで家賃が決まるのは、どの町でも同じだ。", "target_word": "決まる", "complexity_tier": "T3", "furigana": "部屋[へや]の広[ひろ]さで家賃[やちん]が決[き]まるのは、どの町[まち]でも同[おな]じだ。", "sentence_source": "generated"}, {"text": "全員の意見がそろえば、方針は自然に決まる。", "target_word": "決まる", "complexity_tier": "T3", "furigana": "全員[ぜんいん]の意見[いけん]がそろえば、方針[ほうしん]は自然[しぜん]に決[き]まる。", "sentence_source": "generated"}, {"text": "順番がくじで決まる場合、文句は言えない。", "target_word": "決まる", "complexity_tier": "T3", "furigana": "順番[じゅんばん]がくじで決[き]まる場合[ばあい]、文句[もんく]は言[い]えない。", "sentence_source": "generated"}, {"text": "引っ越しの日が決まる前に、荷物を少しずつ整理した。", "target_word": "決まる", "complexity_tier": "T3", "furigana": "引[ひ]っ越[こ]しの日[ひ]が決[き]まる前[まえ]に、荷物[にもつ]を少[すこ]しずつ整理[せいり]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "決まる", "label": "辞書形"}, {"form": "決まらない", "label": "否定形"}, {"form": "決まった", "label": "過去形"}, {"form": "決まって", "label": "て形"}, {"form": "決まれば", "label": "仮定形"}], "register": "neutral", "sense_fingerprint": "決まる: intransitive; a schedule, result or order gets fixed and no longer changes (日程・結果・順番が決まる)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e19b2205-6e13-41a2-a86e-2a42bff0feea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36274, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "決まる", "is_correct": true, "explanation": "「月曜日に決まる予定」と、日程が定まる意味で合う。"}, {"text": "燃える", "is_correct": false, "explanation": "会議の日程は燃えるものではないので合わない。"}, {"text": "冷える", "is_correct": false, "explanation": "会議の日程は冷えるものではないので合わない。"}, {"text": "濡れる", "is_correct": false, "explanation": "会議の日程は濡れるものではないので合わない。"}], "explanations": {"決まる": "「月曜日に決まる予定」と、日程が定まる意味で合う。", "燃える": "会議の日程は燃えるものではないので合わない。", "冷える": "会議の日程は冷えるものではないので合わない。", "濡れる": "会議の日程は濡れるものではないので合わない。"}, "sentence_index": 0, "correct_answer": "決まる"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "来週の天気は、月曜日に決まる予定だ。", "explanation": "ここは〈予報が出る〉の意味。天気は定めるものではないので、決まるは合わない。"}, {"text": "セメントが決まって、壁は一晩でしっかりした。", "explanation": "ここは〈固まる〉の意味。決まるは結論や順序が定まる意味で、物質の硬化には使わない。"}, {"text": "午後には雨が決まり、外は明るくなった。", "explanation": "ここは〈止まる〉の意味。決まるは結論や順序が定まる意味で、雨がやむ意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '616496e4-4d0a-47ad-b093-14a19d5697f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36274, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "決まる", "is_correct": true, "explanation": "「家賃が決まる」は条件で定まる意味で合う。"}, {"text": "壊れる", "is_correct": false, "explanation": "家賃は壊れるものではないので合わない。"}, {"text": "光る", "is_correct": false, "explanation": "家賃は光るものではないので合わない。"}, {"text": "凍る", "is_correct": false, "explanation": "家賃は凍るものではないので合わない。"}], "explanations": {"決まる": "「家賃が決まる」は条件で定まる意味で合う。", "壊れる": "家賃は壊れるものではないので合わない。", "光る": "家賃は光るものではないので合わない。", "凍る": "家賃は凍るものではないので合わない。"}, "sentence_index": 6, "correct_answer": "決まる"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "雪が決まる前に、道路の雪かきを少しずつ進めた。", "explanation": "ここは〈溶ける〉の意味。決まるは結論や順序が定まる意味で、雪が溶ける意味では使わない。"}, {"text": "パンが決まる前に、部屋の準備を少しずつ進めた。", "explanation": "ここは〈焼ける〉の意味。決まるは定まる意味で、パンが焼ける意味では使わない。"}, {"text": "荷物が決まる前に、届いた箱を開けた。", "explanation": "ここは〈届く〉の意味。決まるは定まる意味で、荷物が届く意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '616496e4-4d0a-47ad-b093-14a19d5697f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36274, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "その試合の結果は、最後の一点を決まる。", "corrected_sentence": "その試合の結果は、最後の一点で決まる。", "error_description": "「決まる」は手段・基準を「で」で示す。「一点を決まる」は「を」が誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "決まる", "is_correct": true, "explanation": "文の述語になる辞書形で、「決まる。」と言い切るのに正しい。"}, {"text": "決まら", "is_correct": false, "explanation": "未然形で、文末に置くと言い切れない。"}, {"text": "決まれ", "is_correct": false, "explanation": "命令形で、結果を述べる文には合わない。"}, {"text": "決まって", "is_correct": false, "explanation": "て形で、文を言い切れない。"}], "correct_form": "決まる", "base_form": "決まる", "form_label": "辞書形", "sentence_index": 1, "explanations": {"決まる": "文の述語になる辞書形で、「決まる。」と言い切るのに正しい。", "決まら": "未然形で、文末に置くと言い切れない。", "決まれ": "命令形で、結果を述べる文には合わない。", "決まって": "て形で、文を言い切れない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '616496e4-4d0a-47ad-b093-14a19d5697f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36274, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "部屋の広さで家賃が決まりるのは、ほとんどの町でも同じだ。", "corrected_sentence": "部屋の広さで家賃が決まるのは、ほとんどの町でも同じだ。", "error_description": "「決まる」は辞書形。「決まりる」は活用が誤りで、「決まる」が正しい。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "決まる", "is_correct": true, "explanation": "文末の辞書形で、「決まる。」と言い切るのに正しい。"}, {"text": "決まり", "is_correct": false, "explanation": "連用形で、文末に置くと文が途切れる。"}, {"text": "決まらず", "is_correct": false, "explanation": "連用形の否定で、文を言い切れない。"}, {"text": "決まるまい", "is_correct": false, "explanation": "否定の意志形で、「方針は自然に」の述語として意味が合わない。"}], "correct_form": "決まる", "base_form": "決まる", "form_label": "辞書形", "sentence_index": 7, "explanations": {"決まる": "文末の辞書形で、「決まる。」と言い切るのに正しい。", "決まり": "連用形で、文末に置くと文が途切れる。", "決まらず": "連用形の否定で、文を言い切れない。", "決まるまい": "否定の意志形で、「方針は自然に」の述語として意味が合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '616496e4-4d0a-47ad-b093-14a19d5697f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
