INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36275, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "物事がはっきりと決められて、変わらなくなること。", "primary_collocate": null, "pronunciation": "きまる", "ipa": "kimaɾɯ", "syllable_count": 3, "sentences": [{"text": "話し合いの結果、新しい規則が正式に決まる。", "target_word": "決まる", "complexity_tier": "T3", "furigana": "話[はな]し合[あ]いの結果[けっか]、新[あたら]しい規則[きそく]が正式[せいしき]に決[き]まる。", "sentence_source": "generated"}, {"text": "担当者が決まると、仕事は一気に進み始めた。", "target_word": "決まる", "complexity_tier": "T3", "furigana": "担当者[たんとうしゃ]が決[き]まると、仕事[しごと]は一気[いっき]に進[すす]み始[はじ]めた。", "sentence_source": "generated"}, {"text": "結婚式の場所が決まる前に、予算をはっきりさせておくべきだ。", "target_word": "決まる", "complexity_tier": "T3", "furigana": "結婚式[けっこんしき]の場所[ばしょ]が決[き]まる前[まえ]に、予算[よさん]をはっきりさせておくべきだ。", "sentence_source": "generated"}, {"text": "一度正式に決まるとなると、日程はもう動かせない。", "target_word": "決まる", "complexity_tier": "T3", "furigana": "一度[いちど]正式[せいしき]に決[き]まるとなると、日程[にってい]はもう動[うご]かせない。", "sentence_source": "generated"}, {"text": "値段が決まるまで、店の人は商品を並べなかった。", "target_word": "決まる", "complexity_tier": "T3", "furigana": "値段[ねだん]が決[き]まるまで、店[みせ]の人[ひと]は商品[しょうひん]を並[なら]べなかった。", "sentence_source": "generated"}, {"text": "議長の一言で、会の方針がはっきり決まる。", "target_word": "決まる", "complexity_tier": "T3", "furigana": "議長[ぎちょう]の一言[ひとこと]で、会[かい]の方針[ほうしん]がはっきり決[き]まる。", "sentence_source": "generated"}, {"text": "合格者が決まるのは、来月の十日だ。", "target_word": "決まる", "complexity_tier": "T3", "furigana": "合格者[ごうかくしゃ]が決[き]まるのは、来月[らいげつ]の十日[とおか]だ。", "sentence_source": "generated"}, {"text": "進学先が決まる日まで、家族みんなで待った。", "target_word": "決まる", "complexity_tier": "T3", "furigana": "進学先[しんがくさき]が決[き]まる日[ひ]まで、家族[かぞく]みんなで待[ま]った。", "sentence_source": "generated"}, {"text": "新しい社長が決まるというニュースが、朝から流れた。", "target_word": "決まる", "complexity_tier": "T3", "furigana": "新[あたら]しい社長[しゃちょう]が決[き]まるというニュースが、朝[あさ]から流[なが]れた。", "sentence_source": "generated"}, {"text": "ルールが決まるたびに、子どもたちは真剣に確かめた。", "target_word": "決まる", "complexity_tier": "T3", "furigana": "ルールが決[き]まるたびに、子[こ]どもたちは真剣[しんけん]に確[たし]かめた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "決まる", "label": "辞書形"}, {"form": "決まらない", "label": "否定形"}, {"form": "決まった", "label": "過去形"}, {"form": "決まって", "label": "て形"}, {"form": "決まれば", "label": "仮定形"}], "register": "neutral", "sense_fingerprint": "決まる: intransitive; a matter, policy or person is clearly settled and becomes firm (方針・担当者・値段が決まる)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e19b2205-6e13-41a2-a86e-2a42bff0feea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36275, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "決まる", "is_correct": true, "explanation": "文末の述語になる自動詞の終止形。「新しい規則が正式に決まる」と自然につながる。"}, {"text": "決める", "is_correct": false, "explanation": "他動詞なので「規則を決める」になる。「規則が」と続けると文が成り立たない。"}, {"text": "決まって", "is_correct": false, "explanation": "て形は文末で述語になれないので、この位置では文を終えられない。"}, {"text": "決まり", "is_correct": false, "explanation": "名詞の「決まり」は文を終える述語にならない。「正式に決まり」で文が切れてしまう。"}], "explanations": {"決まる": "文末の述語になる自動詞の終止形。「新しい規則が正式に決まる」と自然につながる。", "決める": "他動詞なので「規則を決める」になる。「規則が」と続けると文が成り立たない。", "決まって": "て形は文末で述語になれないので、この位置では文を終えられない。", "決まり": "名詞の「決まり」は文を終える述語にならない。「正式に決まり」で文が切れてしまう。"}, "sentence_index": 0, "correct_answer": "決まる"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼の怒りは決まって、声が出なくなった。", "explanation": "ここは〈極まる〉（これ以上ないほど程度が強まる）の意味。〈決まる〉は物事が定まることで、感情の程度が強まる意味にはならない。"}, {"text": "ゼリーがよく決まって、きれいに切れた。", "explanation": "ここは「固まる」の意味。「決まる」は方針・人・値段などが定まることで、物質が固まる意味はない。"}, {"text": "子どもの泣き声が、ようやく決まった。", "explanation": "ここは〈収まる〉（静まる）の意味。〈決まる〉は物事が定まることで、泣き声が静まる意味にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '616496e4-4d0a-47ad-b093-14a19d5697f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36275, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "決まる", "is_correct": true, "explanation": "「決まるのは」と名詞節を作る辞書形。「合格者が決まるのは来月の十日だ」と自然に続く。"}, {"text": "決まって", "is_correct": false, "explanation": "て形は「のは」の前に置けず、名詞節が成り立たない。"}, {"text": "決まれ", "is_correct": false, "explanation": "命令形は名詞節の述語にならず、「のは」と続かない。"}, {"text": "決まろう", "is_correct": false, "explanation": "意向形は「のは」の前に続かず、文の主語として成り立たない。"}], "explanations": {"決まる": "「決まるのは」と名詞節を作る辞書形。「合格者が決まるのは来月の十日だ」と自然に続く。", "決まって": "て形は「のは」の前に置けず、名詞節が成り立たない。", "決まれ": "命令形は名詞節の述語にならず、「のは」と続かない。", "決まろう": "意向形は「のは」の前に続かず、文の主語として成り立たない。"}, "sentence_index": 6, "correct_answer": "決まる"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この習慣は、ようやく社会に決まった。", "explanation": "ここは〈定着する〉（習慣が広く根づく）の意味。〈決まる〉は物事が定まることで、習慣が社会に根づく意味にはならない。"}, {"text": "朝から足が決まって、少し疲れた。", "explanation": "ここは〈つる〉（筋肉がけいれんする）の意味。〈決まる〉は物事が定まることで、足がけいれんする意味にはならない。"}, {"text": "夜空の星が、みんな一つに決まった。", "explanation": "ここは星がまとまるという意味。「決まる」は決定や方針がはっきりすることで、星の配置が一つに決まるという言い方はしない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '616496e4-4d0a-47ad-b093-14a19d5697f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36275, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "会議で新しい規則が正式に決める。", "corrected_sentence": "会議で新しい規則が正式に決まる。", "error_description": "正しくは「決まる」。「決める」は他動詞で「規則を決める」と使うため、「規則が」とは続かない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "決まる", "is_correct": true, "explanation": "「〜と」の前に置く辞書形。「担当者が決まると」は自然な条件になる。"}, {"text": "決まって", "is_correct": false, "explanation": "て形は「〜と」の前に置けないので、文が成り立たない。"}, {"text": "決まらない", "is_correct": false, "explanation": "否定形だと「決まらないと仕事は進まない」という逆の意味になり、ここの流れに合わない。"}, {"text": "決まれ", "is_correct": false, "explanation": "命令形で、「と」で続けても条件の文にならず、文として成り立たない。"}], "correct_form": "決まる", "base_form": "決まる", "form_label": "辞書形", "sentence_index": 1, "explanations": {"決まる": "「〜と」の前に置く辞書形。「担当者が決まると」は自然な条件になる。", "決まって": "て形は「〜と」の前に置けないので、文が成り立たない。", "決まらない": "否定形だと「決まらないと仕事は進まない」という逆の意味になり、ここの流れに合わない。", "決まれ": "命令形で、「と」で続けても条件の文にならず、文として成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '616496e4-4d0a-47ad-b093-14a19d5697f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36275, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "試験の合格者が決まるのに、来月の十日です。", "corrected_sentence": "試験の合格者が決まるのは、来月の十日です。", "error_description": "正しくは「決まるのは」。「のに」は逆接なので、「来月の十日です」と続けると文が成り立たない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "決まる", "is_correct": true, "explanation": "連体形で、名詞「日」を修飾している。「決まる日まで」は決まるまでの期間を示す。"}, {"text": "決まり", "is_correct": false, "explanation": "連用形または名詞で、名詞「日」を直接修飾できず「決まり日まで」は成り立たない。"}, {"text": "決まれ", "is_correct": false, "explanation": "命令形で、名詞「日」を修飾できず「決まれ日まで」は文の流れに合わない。"}, {"text": "決まろう", "is_correct": false, "explanation": "意向形で、名詞「日」を修飾できず「決まろう日まで」は文が成り立たない。"}], "correct_form": "決まる", "base_form": "決まる", "form_label": "連体形", "sentence_index": 7, "explanations": {"決まる": "連体形で、名詞「日」を修飾している。「決まる日まで」は決まるまでの期間を示す。", "決まり": "連用形または名詞で、名詞「日」を直接修飾できず「決まり日まで」は成り立たない。", "決まれ": "命令形で、名詞「日」を修飾できず「決まれ日まで」は文の流れに合わない。", "決まろう": "意向形で、名詞「日」を修飾できず「決まろう日まで」は文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '616496e4-4d0a-47ad-b093-14a19d5697f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36276, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「十時に始まる」で、開始の時刻を示す。"}, {"text": "を", "is_correct": false, "explanation": "「十時を始まる」では十時が動作の対象になり、自動詞の始まるとは合わない。"}, {"text": "で", "is_correct": false, "explanation": "「十時で始まる」は手段や範囲を示し、時刻を示す文脈と合わない。"}, {"text": "の", "is_correct": false, "explanation": "「十時の始まる」は名詞を修飾する形で、述語として成立しない。"}], "correct_answer": "に", "explanations": {"に": "「十時に始まる」で、開始の時刻を示す。", "を": "「十時を始まる」では十時が動作の対象になり、自動詞の始まるとは合わない。", "で": "「十時で始まる」は手段や範囲を示し、時刻を示す文脈と合わない。", "の": "「十時の始まる」は名詞を修飾する形で、述語として成立しない。"}, "error_tags": {"を": "対象", "で": "手段・範囲", "の": "修飾"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "終わる", "is_correct": true, "explanation": "「始まる」と対になり、工事が終わる意味。"}, {"text": "話す", "is_correct": false, "explanation": "言葉を発する動作で、始まるの対義語ではない。"}, {"text": "通う", "is_correct": false, "explanation": "決まった場所へ繰り返し行く意味で、対義語ではない。"}, {"text": "泣く", "is_correct": false, "explanation": "涙を流して声を出す動作で、対義語ではない。"}], "correct_answer": "終わる", "explanations": {"終わる": "「始まる」と対になり、工事が終わる意味。", "話す": "言葉を発する動作で、始まるの対義語ではない。", "通う": "決まった場所へ繰り返し行く意味で、対義語ではない。", "泣く": "涙を流して声を出す動作で、対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68c6077d-e2cf-408b-a25f-99af80ba644b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36276, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "から", "options": [{"text": "から", "is_correct": true, "explanation": "「場面から始まる」で、物事の起点を示す。"}, {"text": "と", "is_correct": false, "explanation": "「場面と始まる」では並列の形になり、起点を示せない。"}, {"text": "より", "is_correct": false, "explanation": "比べる基準を示すので、「場面より始まる」は起点の意味にならない。"}, {"text": "へ", "is_correct": false, "explanation": "移動の方向を示すため、「場面へ始まる」は物語の起点を表せない。"}], "correct_answer": "から", "explanations": {"から": "「場面から始まる」で、物事の起点を示す。", "と": "「場面と始まる」では並列の形になり、起点を示せない。", "より": "比べる基準を示すので、「場面より始まる」は起点の意味にならない。", "へ": "移動の方向を示すため、「場面へ始まる」は物語の起点を表せない。"}, "error_tags": {"と": "並列・引用", "より": "比較", "へ": "方向"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "終わる", "is_correct": true, "explanation": "「始まる」と対になり、新しい仕事が終わる意味。"}, {"text": "歩く", "is_correct": false, "explanation": "足を動かして進む動作で、対義語ではない。"}, {"text": "眠る", "is_correct": false, "explanation": "目を閉じて休む状態で、対義語ではない。"}, {"text": "並ぶ", "is_correct": false, "explanation": "順番に横に揃う意味で、対義語ではない。"}], "correct_answer": "終わる", "explanations": {"終わる": "「始まる」と対になり、新しい仕事が終わる意味。", "歩く": "足を動かして進む動作で、対義語ではない。", "眠る": "目を閉じて休む状態で、対義語ではない。", "並ぶ": "順番に横に揃う意味で、対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68c6077d-e2cf-408b-a25f-99af80ba644b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36276, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "何かが新しく動き出します。", "primary_collocate": null, "pronunciation": "はじまる", "ipa": "hadʑimaɾɯ", "syllable_count": 4, "sentences": [{"text": "テレビのドラマが始まる時間なので、家族が居間に集まった。", "target_word": "始まる", "complexity_tier": "T3", "furigana": "テレビのドラマが始[はじ]まる時間[じかん]なので、家族[かぞく]が居間[いま]に集[あつ]まった。", "sentence_source": "generated"}, {"text": "運動会は十時に始まるから、早く寝よう。", "target_word": "始まる", "complexity_tier": "T3", "furigana": "運動会[うんどうかい]は十時[じゅうじ]に始[はじ]まるから、早[はや]く寝[ね]よう。", "sentence_source": "generated"}, {"text": "コンサートが始まると、会場の電気が消えた。", "target_word": "始まる", "complexity_tier": "T3", "furigana": "コンサートが始[はじ]まると、会場[かいじょう]の電気[でんき]が消[き]えた。", "sentence_source": "generated"}, {"text": "工事が始まって、毎日朝から大きな音がするようになった。", "target_word": "始まって", "complexity_tier": "T3", "furigana": "工事[こうじ]が始[はじ]まって、毎日[まいにち]朝[あさ]から大[おお]きな音[おと]がするようになった。", "sentence_source": "generated"}, {"text": "学校が始まる日の朝、弟は緊張して何も食べられなかった。", "target_word": "始まる", "complexity_tier": "T3", "furigana": "学校[がっこう]が始[はじ]まる日[ひ]の朝[あさ]、弟[おとうと]は緊張[きんちょう]して何[なに]も食[た]べられなかった。", "sentence_source": "generated"}, {"text": "夏休みが始まって、子どもたちは毎日プールへ行っている。", "target_word": "始まって", "complexity_tier": "T3", "furigana": "夏休[なつやす]みが始[はじ]まって、子[こ]どもたちは毎日[まいにち]プールへ行[い]っている。", "sentence_source": "generated"}, {"text": "授業が始まったばかりなのに、もう眠くなってしまった。", "target_word": "始まった", "complexity_tier": "T3", "furigana": "授業[じゅぎょう]が始[はじ]まったばかりなのに、もう眠[ねむ]くなってしまった。", "sentence_source": "generated"}, {"text": "この物語は、一人の少年が村を出る場面から始まる。", "target_word": "始まる", "complexity_tier": "T3", "furigana": "この物語[ものがたり]は、一人[ひとり]の少年[しょうねん]が村[むら]を出[で]る場面[ばめん]から始[はじ]まる。", "sentence_source": "generated"}, {"text": "試験が始まる直前、教室はとても静かだった。", "target_word": "始まる", "complexity_tier": "T3", "furigana": "試験[しけん]が始[はじ]まる直前[ちょくぜん]、教室[きょうしつ]はとても静[しず]かだった。", "sentence_source": "generated"}, {"text": "新しい仕事が始まる日は、いつもより早く家を出た。", "target_word": "始まる", "complexity_tier": "T3", "furigana": "新[あたら]しい仕事[しごと]が始[はじ]まる日[ひ]は、いつもより早[はや]く家[いえ]を出[で]た。", "sentence_source": "generated"}], "morphological_forms": [{"form": "始まる", "label": "終止形"}, {"form": "始まり", "label": "連用形"}, {"form": "始まって", "label": "て形"}, {"form": "始まった", "label": "過去形"}, {"form": "始まらない", "label": "否定形"}, {"form": "始まります", "label": "丁寧形"}], "register": "neutral", "sense_fingerprint": "番組・行事・工事・学校などが新しく動き出す、日常的な自動詞", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d0a981c-3ffd-4367-ac70-36156b437484') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36276, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "始まる", "is_correct": true, "explanation": "ドラマが始まる時間の意味で、「時間」を修飾する連体形として自然。"}, {"text": "届く", "is_correct": false, "explanation": "物や知らせが到着する意味で、ドラマには使えず合わない。"}, {"text": "冷める", "is_correct": false, "explanation": "温かいものが冷える意味で、ドラマの放送時刻には合わない。"}, {"text": "乾く", "is_correct": false, "explanation": "水分がなくなる意味で、ドラマが始まる時間の文とは合わない。"}], "explanations": {"始まる": "ドラマが始まる時間の意味で、「時間」を修飾する連体形として自然。", "届く": "物や知らせが到着する意味で、ドラマには使えず合わない。", "冷める": "温かいものが冷える意味で、ドラマの放送時刻には合わない。", "乾く": "水分がなくなる意味で、ドラマが始まる時間の文とは合わない。"}, "sentence_index": 0, "correct_answer": "始まる"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "停電で、家中の電気が始まった。", "explanation": "ここは〈消える〉の意味。明かりが消えることは〈消える〉で、〈始まる〉は物事が動き出す意味なので合わない。"}, {"text": "交通事故が始まって、道路が渋滞した。", "explanation": "ここは〈起こる〉の意味。事故のように突然生じる出来事は〈起こる〉で、〈始まる〉は催しや活動が動き出す場合に使う。"}, {"text": "強風で、窓ガラスが始まった。", "explanation": "ここは〈割れる〉の意味。ガラスにひびが入り砕けることは〈割れる〉で、〈始まる〉とは意味が違う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68c6077d-e2cf-408b-a25f-99af80ba644b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36276, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "始まった", "is_correct": true, "explanation": "「始まったばかり」で、始まって間もないことを示し、文脈に合う。"}, {"text": "降った", "is_correct": false, "explanation": "雨や雪が降る意味で、授業には使えず合わない。"}, {"text": "凍った", "is_correct": false, "explanation": "水などが固まる意味で、授業を主語にできず合わない。"}, {"text": "壊れた", "is_correct": false, "explanation": "物が故障する意味で、授業が始まったという文脈と合わない。"}], "explanations": {"始まった": "「始まったばかり」で、始まって間もないことを示し、文脈に合う。", "降った": "雨や雪が降る意味で、授業には使えず合わない。", "凍った": "水などが固まる意味で、授業を主語にできず合わない。", "壊れた": "物が故障する意味で、授業が始まったという文脈と合わない。"}, "sentence_index": 6, "correct_answer": "始まった"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "春になって、庭の草むらに芽が始まった。", "explanation": "ここは〈生える〉の意味。芽や草が伸び出すことは〈生える〉で、〈始まる〉は物事が動き出す意味なので合わない。"}, {"text": "急に電話が始まって、話せなくなった。", "explanation": "ここは〈切れる〉の意味。通話がつながりを失うことは〈切れる〉で、〈始まる〉とは意味が違うので合わない。"}, {"text": "煙が始まって、火事かと思った。", "explanation": "ここは〈上がる〉の意味。煙が立ち上ることは〈上がる〉で、〈始まる〉は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68c6077d-e2cf-408b-a25f-99af80ba644b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36276, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "来月から駅前の工事を始まる。", "corrected_sentence": "来月から駅前の工事が始まる。", "error_description": "「始まる」は自動詞なので、動作の主体は「が」で示す。「を」は誤りで、「工事が始まる」が正しい。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "始まる", "is_correct": true, "explanation": "「始まるから」と続く終止形で、理由を述べる文の述語になる。"}, {"text": "始まり", "is_correct": false, "explanation": "連用形で、「十時に始まりから」では述語にならない。"}, {"text": "始まれ", "is_correct": false, "explanation": "命令形で、「から」に続けて理由を述べる文にならない。"}, {"text": "始まります", "is_correct": false, "explanation": "丁寧形で、「始まるから」の普通体と文体が合わない。"}], "correct_form": "始まる", "base_form": "始まる", "form_label": "終止形", "sentence_index": 1, "explanations": {"始まる": "「始まるから」と続く終止形で、理由を述べる文の述語になる。", "始まり": "連用形で、「十時に始まりから」では述語にならない。", "始まれ": "命令形で、「から」に続けて理由を述べる文にならない。", "始まります": "丁寧形で、「始まるから」の普通体と文体が合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68c6077d-e2cf-408b-a25f-99af80ba644b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36276, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "窓口の受付は午前九時を始まる。", "corrected_sentence": "窓口の受付は午前九時から始まる。", "error_description": "「始まる」は開始の時点を「から」で示す。「を」は誤りで、「午前九時から始まる」が正しい。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "始まる", "is_correct": true, "explanation": "「始まる。」と文末で言い切る終止形で、物語の書き出しを述べる述語になる。"}, {"text": "始まらない", "is_correct": false, "explanation": "否定形で、物語が始まらないという内容になり文の意味と合わない。"}, {"text": "始まれば", "is_correct": false, "explanation": "仮定形で条件を表し、文末では言い切れない。"}, {"text": "始まろう", "is_correct": false, "explanation": "意志形で、物語が始まる事実を述べる文と合わない。"}], "correct_form": "始まる", "base_form": "始まる", "form_label": "終止形", "sentence_index": 7, "explanations": {"始まる": "「始まる。」と文末で言い切る終止形で、物語の書き出しを述べる述語になる。", "始まらない": "否定形で、物語が始まらないという内容になり文の意味と合わない。", "始まれば": "仮定形で条件を表し、文末では言い切れない。", "始まろう": "意志形で、物語が始まる事実を述べる文と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68c6077d-e2cf-408b-a25f-99af80ba644b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36277, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「四月に始まる」で、始まる時期を示す。"}, {"text": "を", "is_correct": false, "explanation": "「四月を始まる」では四月が動作の対象になり、自動詞の始まるとは合わない。"}, {"text": "で", "is_correct": false, "explanation": "「四月で始まる」は手段や範囲を示し、時期を示す文脈と合わない。"}, {"text": "と", "is_correct": false, "explanation": "「四月と始まる」は並列や引用の形で、ここでは不自然。"}], "correct_answer": "に", "explanations": {"に": "「四月に始まる」で、始まる時期を示す。", "を": "「四月を始まる」では四月が動作の対象になり、自動詞の始まるとは合わない。", "で": "「四月で始まる」は手段や範囲を示し、時期を示す文脈と合わない。", "と": "「四月と始まる」は並列や引用の形で、ここでは不自然。"}, "error_tags": {"を": "対象", "で": "手段・範囲", "と": "並列・引用"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "終わる", "is_correct": true, "explanation": "「始まる」と対になり、物事が終わる意味。映画が始まる場面の反対語。"}, {"text": "話す", "is_correct": false, "explanation": "言葉を発する動作で、始まるの対義語ではない。"}, {"text": "通う", "is_correct": false, "explanation": "決まった場所へ繰り返し行く意味で、対義語ではない。"}, {"text": "泣く", "is_correct": false, "explanation": "涙を流して声を出す動作で、対義語ではない。"}], "correct_answer": "終わる", "explanations": {"終わる": "「始まる」と対になり、物事が終わる意味。映画が始まる場面の反対語。", "話す": "言葉を発する動作で、始まるの対義語ではない。", "通う": "決まった場所へ繰り返し行く意味で、対義語ではない。", "泣く": "涙を流して声を出す動作で、対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68c6077d-e2cf-408b-a25f-99af80ba644b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36277, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "終わる", "is_correct": true, "explanation": "「始まって」の反対で、生活が終わる意味。"}, {"text": "歩く", "is_correct": false, "explanation": "足を動かして進む動作で、対義語ではない。"}, {"text": "眠る", "is_correct": false, "explanation": "目を閉じて休む状態で、対義語ではない。"}, {"text": "並ぶ", "is_correct": false, "explanation": "順番に横に揃う意味で、対義語ではない。"}], "correct_answer": "終わる", "explanations": {"終わる": "「始まって」の反対で、生活が終わる意味。", "歩く": "足を動かして進む動作で、対義語ではない。", "眠る": "目を閉じて休む状態で、対義語ではない。", "並ぶ": "順番に横に揃う意味で、対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68c6077d-e2cf-408b-a25f-99af80ba644b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36277, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "物事が新たに動き出したり、行われるようになること。", "primary_collocate": null, "pronunciation": "はじまる", "ipa": "hadʑimaɾɯ", "syllable_count": 4, "sentences": [{"text": "その過程は、微生物を培養する「種起こし」から始まります。", "target_word": "始まります", "complexity_tier": "T3", "furigana": "その過程[かてい]は、微生物[びせいぶつ]を培養[ばいよう]する「種起[たねお]こし」から始[はじ]まります。", "sentence_source": "mined"}, {"text": "新学期は四月に始まるが、準備は三月から行われる。", "target_word": "始まる", "complexity_tier": "T3", "furigana": "新学期[しんがっき]は四月[しがつ]に始[はじ]まるが、準備[じゅんび]は三月[さんがつ]から行[おこな]われる。", "sentence_source": "generated"}, {"text": "授業が始まる前に、先生は出席をとった。", "target_word": "始まる", "complexity_tier": "T3", "furigana": "授業[じゅぎょう]が始[はじ]まる前[まえ]に、先生[せんせい]は出席[しゅっせき]をとった。", "sentence_source": "generated"}, {"text": "映画が始まったので、私たちは話すのをやめた。", "target_word": "始まった", "complexity_tier": "T3", "furigana": "映画[えいが]が始[はじ]まったので、私[わたし]たちは話[はな]すのをやめた。", "sentence_source": "generated"}, {"text": "夏休みが終われば、また忙しい毎日が始まる。", "target_word": "始まる", "complexity_tier": "T3", "furigana": "夏休[なつやす]みが終[お]われば、また忙[いそが]しい毎日[まいにち]が始[はじ]まる。", "sentence_source": "generated"}, {"text": "会議は九時の予定だったが、社長が遅れたため、実際に始まったのは九時十分だった。", "target_word": "始まった", "complexity_tier": "T3", "furigana": "会議[かいぎ]は九時[くじ]の予定[よてい]だったが、社長[しゃちょう]が遅[おく]れたため、実際[じっさい]に始[はじ]まったのは九時十分[くじじゅっぷん]だった。", "sentence_source": "generated"}, {"text": "この町の祭りは、大きな太鼓の音から始まります。", "target_word": "始まります", "complexity_tier": "T3", "furigana": "この町[まち]の祭[まつ]りは、大[おお]きな太鼓[たいこ]の音[おと]から始[はじ]まります。", "sentence_source": "generated"}, {"text": "雨でグラウンドが使えないから、試合はまだ始まらない。", "target_word": "始まらない", "complexity_tier": "T3", "furigana": "雨[あめ]でグラウンドが使[つか]えないから、試合[しあい]はまだ始[はじ]まらない。", "sentence_source": "generated"}, {"text": "二人の友情は、小さなあいさつから始まった。", "target_word": "始まった", "complexity_tier": "T3", "furigana": "二人[ふたり]の友情[ゆうじょう]は、小[ちい]さなあいさつから始[はじ]まった。", "sentence_source": "generated"}, {"text": "新しい生活が始まって、毎朝早く起きるようになった。", "target_word": "始まって", "complexity_tier": "T3", "furigana": "新[あたら]しい生活[せいかつ]が始[はじ]まって、毎朝[まいあさ]早[はや]く起[お]きるようになった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "始まる", "label": "終止形"}, {"form": "始まり", "label": "連用形"}, {"form": "始まって", "label": "て形"}, {"form": "始まった", "label": "過去形"}, {"form": "始まらない", "label": "否定形"}, {"form": "始まります", "label": "丁寧形"}], "register": "neutral", "sense_fingerprint": "授業・会議・行事・関係などの物事が新たに動き出して行われるようになる自動詞", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d0a981c-3ffd-4367-ac70-36156b437484') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36277, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "始まります", "is_correct": true, "explanation": "「種起こしから始まります」で、過程の出発点を丁寧に述べる。文脈に合う。"}, {"text": "終わります", "is_correct": false, "explanation": "物事が終わる意味になり、過程の出発点を示す「〜から」の文と合わない。"}, {"text": "届きます", "is_correct": false, "explanation": "物や知らせが到着する意味で、過程が始まる文脈とは違う。"}, {"text": "冷めます", "is_correct": false, "explanation": "温かいものが温度を失う意味で、過程の開始を表せない。"}], "explanations": {"始まります": "「種起こしから始まります」で、過程の出発点を丁寧に述べる。文脈に合う。", "終わります": "物事が終わる意味になり、過程の出発点を示す「〜から」の文と合わない。", "届きます": "物や知らせが到着する意味で、過程が始まる文脈とは違う。", "冷めます": "温かいものが温度を失う意味で、過程の開始を表せない。"}, "sentence_index": 0, "correct_answer": "始まります"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "お湯が始まったので、ボタンを押した。", "explanation": "ここは〈沸く〉の意味。お湯が熱くなって泡立つ変化は〈沸く〉で、〈始まる〉は物事が動き出す意味なので合わない。"}, {"text": "山の麓で、きれいな水が始まった。", "explanation": "ここは〈湧く〉の意味。地面から水がわき出すことは〈湧く〉で、〈始まる〉は物事が動き出す意味なので合わない。"}, {"text": "夜空に新しい星が始まった。", "explanation": "ここは〈出現する〉の意味。星が新たに現れることは〈出現する〉で、〈始まる〉は物事が動き出す意味なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68c6077d-e2cf-408b-a25f-99af80ba644b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36277, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "始まります", "is_correct": true, "explanation": "「太鼓の音から始まります」で、祭りの始まりを述べる。"}, {"text": "閉まります", "is_correct": false, "explanation": "戸や蓋が閉じる意味で、祭りの始まりを表す文と合わない。"}, {"text": "見えます", "is_correct": false, "explanation": "視界に入る意味で、祭りの開始を示す文脈と合わない。"}, {"text": "戻ります", "is_correct": false, "explanation": "元の場所へ帰る意味で、太鼓の音から祭りが始まる文とは合わない。"}], "explanations": {"始まります": "「太鼓の音から始まります」で、祭りの始まりを述べる。", "閉まります": "戸や蓋が閉じる意味で、祭りの始まりを表す文と合わない。", "見えます": "視界に入る意味で、祭りの開始を示す文脈と合わない。", "戻ります": "元の場所へ帰る意味で、太鼓の音から祭りが始まる文とは合わない。"}, "sentence_index": 6, "correct_answer": "始まります"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "スイッチを入れると、部屋の電気が始まった。", "explanation": "ここは〈点く〉の意味。明かりがつく変化は〈点く〉で、〈始まる〉は物事が動き出す意味なので合わない。"}, {"text": "急にストーブが始まって、部屋が寒いままだ。", "explanation": "ここは〈壊れる〉の意味。機械が故障して動かなくなることは〈壊れる〉で、〈始まる〉とは意味が違うので合わない。"}, {"text": "庭の木の下に、芽が始まった。", "explanation": "ここは〈生える〉の意味。草や芽が地面から伸び出すことは〈生える〉で、〈始まる〉は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68c6077d-e2cf-408b-a25f-99af80ba644b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36277, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "来週から新しいコースを始まる。", "corrected_sentence": "来週から新しいコースが始まる。", "error_description": "「始まる」は自動詞なので主語には「が」を使う。「を」は誤りで、「コースが始まる」が正しい。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "始まる", "is_correct": true, "explanation": "「始まるが」と続く終止形で、文の述語になる。"}, {"text": "始まり", "is_correct": false, "explanation": "連用形で、「四月に始まりが」では述語にならない。"}, {"text": "始まって", "is_correct": false, "explanation": "て形で、「が」で文を続けられない。"}, {"text": "始まります", "is_correct": false, "explanation": "丁寧形で、普通体の「始まるが」と文体が合わない。"}], "correct_form": "始まる", "base_form": "始まる", "form_label": "終止形", "sentence_index": 1, "explanations": {"始まる": "「始まるが」と続く終止形で、文の述語になる。", "始まり": "連用形で、「四月に始まりが」では述語にならない。", "始まって": "て形で、「が」で文を続けられない。", "始まります": "丁寧形で、普通体の「始まるが」と文体が合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68c6077d-e2cf-408b-a25f-99af80ba644b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36277, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "研修会は九時を始まる。", "corrected_sentence": "研修会は九時から始まる。", "error_description": "「始まる」は開始の時点を「から」で示す。「を」は誤りで、「九時から始まる」が正しい。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "始まらない", "is_correct": true, "explanation": "否定形で、「まだ始まらない」と述語になる。"}, {"text": "始まらず", "is_correct": false, "explanation": "連用中止形で、文を終えられず「まだ始まらず」の述語にならない。"}, {"text": "始まれば", "is_correct": false, "explanation": "仮定形で条件を表し、文末の述語にならない。"}, {"text": "始まろう", "is_correct": false, "explanation": "意志形で、グラウンドが使えないという事実を述べる文と合わない。"}], "correct_form": "始まらない", "base_form": "始まる", "form_label": "否定形", "sentence_index": 7, "explanations": {"始まらない": "否定形で、「まだ始まらない」と述語になる。", "始まらず": "連用中止形で、文を終えられず「まだ始まらず」の述語にならない。", "始まれば": "仮定形で条件を表し、文末の述語にならない。", "始まろう": "意志形で、グラウンドが使えないという事実を述べる文と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68c6077d-e2cf-408b-a25f-99af80ba644b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
