INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36278, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "function", "definition": "何かと何かをくらべるときに使うことば。", "primary_collocate": null, "pronunciation": "たいする", "ipa": "taisɯɾɯ", "syllable_count": 4, "sentences": [{"text": "兄は肉が好きなのに対して、妹は魚が好きだ。", "target_word": "対して", "complexity_tier": "T3", "furigana": "兄[あに]は肉[にく]が好[す]きなのに対[たい]して、妹[いもうと]は魚[さかな]が好[す]きだ。", "sentence_source": "generated"}, {"text": "去年の夏は暑かったのに対して、今年の夏は雨が多い。", "target_word": "対して", "complexity_tier": "T3", "furigana": "去年[きょねん]の夏[なつ]は暑[あつ]かったのに対[たい]して、今年[ことし]の夏[なつ]は雨[あめ]が多[おお]い。", "sentence_source": "generated"}, {"text": "都会は人が多いのに対して、田舎は静かでゆっくりしている。", "target_word": "対して", "complexity_tier": "T3", "furigana": "都会[とかい]は人[ひと]が多[おお]いのに対[たい]して、田舎[いなか]は静[しず]かでゆっくりしている。", "sentence_source": "generated"}, {"text": "姉は社交的なのに対して、私は人見知りだ。", "target_word": "対して", "complexity_tier": "T3", "furigana": "姉[あね]は社交的[しゃこうてき]なのに対[たい]して、私[わたし]は人見知[ひとみし]りだ。", "sentence_source": "generated"}, {"text": "東京の冬は暖かいのに対して、北海道の冬は寒い。", "target_word": "対して", "complexity_tier": "T3", "furigana": "東京[とうきょう]の冬[ふゆ]は暖[あたた]かいのに対[たい]して、北海道[ほっかいどう]の冬[ふゆ]は寒[さむ]い。", "sentence_source": "generated"}, {"text": "賛成が六十人だったのに対して、反対は二十人だった。", "target_word": "対して", "complexity_tier": "T3", "furigana": "賛成[さんせい]が六十人[ろくじゅうにん]だったのに対[たい]して、反対[はんたい]は二十人[にじゅうにん]だった。", "sentence_source": "generated"}, {"text": "日本語は動詞が最後に来るのに対して、英語は主語のすぐあとに動詞が来る。", "target_word": "対して", "complexity_tier": "T3", "furigana": "日本語[にほんご]は動詞[どうし]が最後[さいご]に来[く]るのに対[たい]して、英語[えいご]は主語[しゅご]のすぐあとに動詞[どうし]が来[く]る。", "sentence_source": "generated"}, {"text": "午前の部は参加者が少なかったのに対し、午後の部は満員だった。", "target_word": "対し", "complexity_tier": "T3", "furigana": "午前[ごぜん]の部[ぶ]は参加者[さんかしゃ]が少[すく]なかったのに対[たい]し、午後[ごご]の部[ぶ]は満員[まんいん]だった。", "sentence_source": "generated"}, {"text": "父は新しい物が好きなのに対して、母は古い物を大切にする。", "target_word": "対して", "complexity_tier": "T3", "furigana": "父[ちち]は新[あたら]しい物[もの]が好[す]きなのに対[たい]して、母[はは]は古[ふる]い物[もの]を大切[たいせつ]にする。", "sentence_source": "generated"}, {"text": "駅前の店は高いのに対して、少し離れた店は安い。", "target_word": "対して", "complexity_tier": "T3", "furigana": "駅前[えきまえ]の店[みせ]は高[たか]いのに対[たい]して、少[すこ]し離[はな]れた店[みせ]は安[やす]い。", "sentence_source": "generated"}], "morphological_forms": [{"form": "対する", "label": "終止形"}, {"form": "対して", "label": "て形"}, {"form": "対し", "label": "連用形"}, {"form": "対した", "label": "過去形"}, {"form": "対しない", "label": "否定形"}], "register": "中立", "sense_fingerprint": "「AにたいしてB」の形で、二つの物事を対比させて述べる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11236ac4-32a0-4c53-9d4d-00c4116c6282') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36278, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "対して", "is_correct": true, "explanation": "「〜のに対して」の形で、兄と妹の好みを対比している。この文の正解。"}, {"text": "通じて", "is_correct": false, "explanation": "「〜を通じて」は手段や媒介を表すため、「好きなのに通じて」は文として成り立たない。"}, {"text": "応じて", "is_correct": false, "explanation": "「〜に応じて」は状況に合わせる意味で、「好きなのに応じて」は対比の文に入らない。"}, {"text": "基づいて", "is_correct": false, "explanation": "「〜に基づいて」は根拠を表すため、「好きなのに基づいて」は意味が通らない。"}], "explanations": {"対して": "「〜のに対して」の形で、兄と妹の好みを対比している。この文の正解。", "通じて": "「〜を通じて」は手段や媒介を表すため、「好きなのに通じて」は文として成り立たない。", "応じて": "「〜に応じて」は状況に合わせる意味で、「好きなのに応じて」は対比の文に入らない。", "基づいて": "「〜に基づいて」は根拠を表すため、「好きなのに基づいて」は意味が通らない。"}, "sentence_index": 0, "correct_answer": "対して"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夏休みに対して、宿題はもう終わった。", "explanation": "ここは〈〜より前に〉の意味の「前に」と混同した例。「対して」は時期の前後関係を表せないので、この文では合わない。"}, {"text": "資格取得に対して、毎日勉強した。", "explanation": "ここは〈目標に向けて〉の意味の「向けて」と混同した例。「対して」は相手や対象を指すので、目標に向かう意味にはならない。"}, {"text": "説明書に対して、組み立てた。", "explanation": "ここは〈説明書に従って〉の意味の「従って」と混同した例。「対して」では従う意味は出ないので、この文では合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a849add-9c71-470c-b7c7-5f19af1c26f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36278, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "対して", "is_correct": true, "explanation": "「〜のに対して」の形で、日本語と英語の語順を対比している。この文の正解。"}, {"text": "伴って", "is_correct": false, "explanation": "「〜に伴って」は変化が同時に起きることを表すため、「来るのに伴って」は不自然。"}, {"text": "込めて", "is_correct": false, "explanation": "「〜を込めて」は気持ちを込める意味で、「来るのに込めて」は文が成り立たない。"}, {"text": "取って", "is_correct": false, "explanation": "「〜を取って」は除去や獲得の意味で、「来るのに取って」は意味が通らない。"}], "explanations": {"対して": "「〜のに対して」の形で、日本語と英語の語順を対比している。この文の正解。", "伴って": "「〜に伴って」は変化が同時に起きることを表すため、「来るのに伴って」は不自然。", "込めて": "「〜を込めて」は気持ちを込める意味で、「来るのに込めて」は文が成り立たない。", "取って": "「〜を取って」は除去や獲得の意味で、「来るのに取って」は意味が通らない。"}, "sentence_index": 6, "correct_answer": "対して"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "肉に対して、野菜を食べた。", "explanation": "ここは〈〜の代わりに〉の意味の「代わりに」と混同した例。「対して」では代用の意味は出ないので、この文では合わない。"}, {"text": "季節に対して服装を選ぶ。", "explanation": "ここは〈季節に合わせて〉の意味の「合わせて」と混同した例。「対して」は向かう対象を表すので、合わせる意味にはならない。"}, {"text": "データに対して、結論を出した。", "explanation": "ここは〈データをもとに〉の意味の「もとに」と混同した例。「対して」では根拠を示せないので、この文では合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a849add-9c71-470c-b7c7-5f19af1c26f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36278, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "今年の春は寒かったのに対する、夏は暑い。", "corrected_sentence": "今年の春は寒かったのに対して、夏は暑い。", "error_description": "誤りは「対する」。「のに」に続けて文を接続するときは、て形の「対して」を使う。連体形の「対する」は名詞を修飾する形なので、ここでは不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a849add-9c71-470c-b7c7-5f19af1c26f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36278, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夏は海が混むのに対しない、冬は静かだ。", "corrected_sentence": "夏は海が混むのに対して、冬は静かだ。", "error_description": "誤りは「対しない」。対比の用法では「のに対して」の形を使う。否定形の「対しない」は対比の文に合わないため、て形の「対して」に直す必要がある。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a849add-9c71-470c-b7c7-5f19af1c26f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
