INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36280, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「別の方法」の「の」。「別」と「方法」を結んで名詞を修飾する。この問題の正解。"}, {"text": "へ", "is_correct": false, "explanation": "「別へ方法で」では方向の関係が成り立たず、文が壊れる。"}, {"text": "から", "is_correct": false, "explanation": "「別から方法で」では起点の関係が成り立たず、不自然になる。"}, {"text": "より", "is_correct": false, "explanation": "「別より方法で」では比較の関係が成り立たず、文が通らない。"}], "correct_answer": "の", "explanations": {"の": "「別の方法」の「の」。「別」と「方法」を結んで名詞を修飾する。この問題の正解。", "へ": "「別へ方法で」では方向の関係が成り立たず、文が壊れる。", "から": "「別から方法で」では起点の関係が成り立たず、不自然になる。", "より": "「別より方法で」では比較の関係が成り立たず、文が通らない。"}, "error_tags": {"へ": "方向", "から": "起点", "より": "比較・起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a849add-9c71-470c-b7c7-5f19af1c26f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36280, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "べつのこと。", "primary_collocate": null, "pronunciation": "べつ", "ipa": "betsɯ", "syllable_count": 2, "sentences": [{"text": "それとこれとは別の話だ。", "target_word": "別", "complexity_tier": "T3", "furigana": "それとこれとは別[べつ]の話[はなし]だ。", "sentence_source": "generated"}, {"text": "この店は高いので、別の店に行こう。", "target_word": "別", "complexity_tier": "T3", "furigana": "この店[みせ]は高[たか]いので、別[べつ]の店[みせ]に行[い]こう。", "sentence_source": "generated"}, {"text": "仕事と趣味は別だと考えている。", "target_word": "別", "complexity_tier": "T3", "furigana": "仕事[しごと]と趣味[しゅみ]は別[べつ]だと考[かんが]えている。", "sentence_source": "generated"}, {"text": "傘をなくしたので、別の傘を買った。", "target_word": "別", "complexity_tier": "T3", "furigana": "傘[かさ]をなくしたので、別[べつ]の傘[かさ]を買[か]った。", "sentence_source": "generated"}, {"text": "今日の話は、先週の件とは別の問題だ。", "target_word": "別", "complexity_tier": "T3", "furigana": "今日[きょう]の話[はなし]は、先週[せんしゅう]の件[けん]とは別[べつ]の問題[もんだい]だ。", "sentence_source": "generated"}, {"text": "都合が悪いなら、別の日に会いましょう。", "target_word": "別", "complexity_tier": "T3", "furigana": "都合[つごう]が悪[わる]いなら、別[べつ]の日[ひ]に会[あ]いましょう。", "sentence_source": "generated"}, {"text": "道がこんでいたので、別の道を通って帰った。", "target_word": "別", "complexity_tier": "T3", "furigana": "道[みち]がこんでいたので、別[べつ]の道[みち]を通[とお]って帰[かえ]った。", "sentence_source": "generated"}, {"text": "この問題は、別の方法で解いてみてください。", "target_word": "別", "complexity_tier": "T3", "furigana": "この問題[もんだい]は、別[べつ]の方法[ほうほう]で解[と]いてみてください。", "sentence_source": "generated"}, {"text": "兄と私は同じ家に住んでいるが、財布は別だ。", "target_word": "別", "complexity_tier": "T3", "furigana": "兄[あに]と私[わたし]は同[おな]じ家[いえ]に住[す]んでいるが、財布[さいふ]は別[べつ]だ。", "sentence_source": "generated"}, {"text": "その人は別の学校に行って、会えなくなった。", "target_word": "別", "complexity_tier": "T3", "furigana": "その人[ひと]は別[べつ]の学校[がっこう]に行[い]って、会[あ]えなくなった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "別", "label": "基本形"}], "register": "中立", "sense_fingerprint": "それとは違う、ほかのもの・こと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11236ac4-32a0-4c53-9d4d-00c4116c6282') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36280, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "別", "is_correct": true, "explanation": "「それとこれとは別の話だ」で、違うことを表す。この文の正解。"}, {"text": "余計", "is_correct": false, "explanation": "「余計な」の形で名詞を修飾するため、「余計の話」は文が成り立たない。"}, {"text": "必要", "is_correct": false, "explanation": "「必要な」の形で使うため、「必要の話」は誤り。"}, {"text": "静か", "is_correct": false, "explanation": "「静かな」の形で使うため、「静かの話」は誤り。"}], "explanations": {"別": "「それとこれとは別の話だ」で、違うことを表す。この文の正解。", "余計": "「余計な」の形で名詞を修飾するため、「余計の話」は文が成り立たない。", "必要": "「必要な」の形で使うため、「必要の話」は誤り。", "静か": "「静かな」の形で使うため、「静かの話」は誤り。"}, "sentence_index": 0, "correct_answer": "別"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夏は山の別荘で過ごす。", "explanation": "ここは〈避暑用の住まい〉を表す「別荘」。〈べつのこと〉の意味ではないので、この語義では合わない。"}, {"text": "この建物の別館で会議をする。", "explanation": "ここは〈本館とは別の建物〉を表す「別館」。〈べつのこと〉の意味ではないので、この語義では合わない。"}, {"text": "ケーキは別腹だ。", "explanation": "ここは〈食事の満腹感とは別の胃〉を表す慣用句「別腹」。〈べつのこと〉の意味ではないので、この語義では合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a849add-9c71-470c-b7c7-5f19af1c26f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36280, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "別", "is_correct": true, "explanation": "「別の道を通って帰った」で、通ったのが普段と違う道であることを表す。この文の正解。"}, {"text": "無効", "is_correct": false, "explanation": "「無効な」の形で修飾するため、「無効の道」は文が成り立たない。"}, {"text": "静か", "is_correct": false, "explanation": "「静かな」の形で使うため、「静かの道」は誤り。"}, {"text": "不要", "is_correct": false, "explanation": "「不要な」の形で使うため、「不要の道」は誤り。"}], "explanations": {"別": "「別の道を通って帰った」で、通ったのが普段と違う道であることを表す。この文の正解。", "無効": "「無効な」の形で修飾するため、「無効の道」は文が成り立たない。", "静か": "「静かな」の形で使うため、「静かの道」は誤り。", "不要": "「不要な」の形で使うため、「不要の道」は誤り。"}, "sentence_index": 6, "correct_answer": "別"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "その人は別格の存在で、今では会えない。", "explanation": "ここは〈特別な地位〉を表す複合語「別格」。〈べつのこと〉の意味の「別」ではないので、この語義では合わない。"}, {"text": "その人とは一年前に別れてから、会えなくなった。", "explanation": "ここは動詞「別れる」の形で、名詞「別」の〈べつのこと〉の意味ではない。この語義では合わない。"}, {"text": "その人は別名で活動していて、会えなくなった。", "explanation": "ここは〈本名とは別の呼び名〉を表す「別名」。〈べつのこと〉の意味ではないので、この語義では合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a849add-9c71-470c-b7c7-5f19af1c26f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36280, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "家賃は別のです。", "corrected_sentence": "家賃は別です。", "error_description": "「別」は名詞・形容動詞として「別です」「別だ」の形で述語になる。「別の」は名詞を修飾する形なので、「です」の前に置くと誤り。誤りは「の」の付け加え。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a849add-9c71-470c-b7c7-5f19af1c26f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36280, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "その店は別のだった。", "corrected_sentence": "その店は別だった。", "error_description": "「別」は名詞・形容動詞なので「別だった」の形で述語になる。「別の」は連体形で、「だった」の前には置けない。誤りは余分な「の」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a849add-9c71-470c-b7c7-5f19af1c26f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
