INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36281, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "他のものと違っていること。また、それとは異なるもの。", "primary_collocate": null, "pronunciation": "べつ", "ipa": "betsɯ", "syllable_count": 2, "sentences": [{"text": "このシャツは小さいので、別のシャツを見せてください。", "target_word": "別", "complexity_tier": "T3", "furigana": "このシャツは小[ちい]さいので、別[べつ]のシャツを見[み]せてください。", "sentence_source": "generated"}, {"text": "今日は忙しいので、別の日に会いましょう。", "target_word": "別", "complexity_tier": "T3", "furigana": "今日[きょう]は忙[いそが]しいので、別[べつ]の日[ひ]に会[あ]いましょう。", "sentence_source": "generated"}, {"text": "仕事の話と私生活は別です。", "target_word": "別", "complexity_tier": "T3", "furigana": "仕事[しごと]の話[はなし]と私生活[しせいかつ]は別[べつ]です。", "sentence_source": "generated"}, {"text": "見た目は似ていますが、中身は別のものです。", "target_word": "別", "complexity_tier": "T3", "furigana": "見[み]た目[め]は似[に]ていますが、中身[なかみ]は別[べつ]のものです。", "sentence_source": "generated"}, {"text": "この問題は別の方法で解いてみます。", "target_word": "別", "complexity_tier": "T3", "furigana": "この問題[もんだい]は別[べつ]の方法[ほうほう]で解[と]いてみます。", "sentence_source": "generated"}, {"text": "双子ですが、性格は全く別です。", "target_word": "別", "complexity_tier": "T3", "furigana": "双子[ふたご]ですが、性格[せいかく]は全[まった]く別[べつ]です。", "sentence_source": "generated"}, {"text": "好き嫌いと上手下手は別の話です。", "target_word": "別", "complexity_tier": "T3", "furigana": "好[す]き嫌[きら]いと上手[じょうず]下手[へた]は別[べつ]の話[はなし]です。", "sentence_source": "generated"}, {"text": "この店は混んでいるので、別の支店に行きたいです。", "target_word": "別", "complexity_tier": "T3", "furigana": "この店[みせ]は混[こ]んでいるので、別[べつ]の支店[してん]に行[い]きたいです。", "sentence_source": "generated"}, {"text": "もっと大きい別の部屋を借りたいです。", "target_word": "別", "complexity_tier": "T3", "furigana": "もっと大[おお]きい別[べつ]の部屋[へや]を借[か]りたいです。", "sentence_source": "generated"}, {"text": "このパンは食べ終わったので、別のパンを買います。", "target_word": "別", "complexity_tier": "T3", "furigana": "このパンは食[た]べ終[お]わったので、別[べつ]のパンを買[か]います。", "sentence_source": "generated"}], "morphological_forms": [{"form": "別", "label": "基本形"}, {"form": "別の", "label": "連体形"}, {"form": "別だ", "label": "断定形"}, {"form": "別です", "label": "丁寧形"}], "register": "neutral", "sense_fingerprint": "別(べつ): 他と違うこと、また異なるもの。「別の〜」「〜は別だ」の形で使う名詞", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11236ac4-32a0-4c53-9d4d-00c4116c6282') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36281, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "別", "is_correct": true, "explanation": "「別のシャツを見せてください」で、今のシャツとは違うシャツを指す。この文の正解。"}, {"text": "不要", "is_correct": false, "explanation": "「不要な」の形で使うため、「不要のシャツ」は文が成り立たない。"}, {"text": "余計", "is_correct": false, "explanation": "「余計な」の形で名詞を修飾するため、「余計のシャツ」は誤り。"}, {"text": "静か", "is_correct": false, "explanation": "「静かな」の形で使うため、「静かのシャツ」は誤り。"}], "explanations": {"別": "「別のシャツを見せてください」で、今のシャツとは違うシャツを指す。この文の正解。", "不要": "「不要な」の形で使うため、「不要のシャツ」は文が成り立たない。", "余計": "「余計な」の形で名詞を修飾するため、「余計のシャツ」は誤り。", "静か": "「静かな」の形で使うため、「静かのシャツ」は誤り。"}, "sentence_index": 0, "correct_answer": "別"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夏は湖畔の別荘で過ごす。", "explanation": "ここは〈避暑用の住まい〉を表す「別荘」。〈異なるもの〉の意味ではないので、この文では合わない。"}, {"text": "ケーキは別腹だ。", "explanation": "ここは〈食事の満腹感とは別の胃〉を表す慣用句「別腹」。〈異なるもの〉の意味ではないので、この文では合わない。"}, {"text": "この建物の別館で会議をする。", "explanation": "ここは〈本館とは別の建物〉を表す「別館」。〈異なるもの〉の意味ではないので、この文では合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a849add-9c71-470c-b7c7-5f19af1c26f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36281, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "別", "is_correct": true, "explanation": "「好き嫌いと上手下手は別の話です」で、二つが無関係であることを表す。この文の正解。"}, {"text": "必要", "is_correct": false, "explanation": "「必要な」の形で使うため、「必要の話」は文が成り立たない。"}, {"text": "静か", "is_correct": false, "explanation": "「静かな」の形で使うため、「静かの話」は誤り。"}, {"text": "不利", "is_correct": false, "explanation": "「不利な」の形で使うため、「不利の話」は誤り。"}], "explanations": {"別": "「好き嫌いと上手下手は別の話です」で、二つが無関係であることを表す。この文の正解。", "必要": "「必要な」の形で使うため、「必要の話」は文が成り立たない。", "静か": "「静かな」の形で使うため、「静かの話」は誤り。", "不利": "「不利な」の形で使うため、「不利の話」は誤り。"}, "sentence_index": 6, "correct_answer": "別"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼女とは一年前に別れたので、今は一人で暮らしている。", "explanation": "ここは動詞「別れる」の形。〈異なるもの〉を表す名詞「別」ではないので、この語義では合わない。"}, {"text": "このパンは別格のおいしさだ。", "explanation": "ここは〈特に優れている〉の意味の「別格」。〈べつのパン〉という語義ではないので合わない。"}, {"text": "このパンは別名で売られている。", "explanation": "ここは〈本来の名前とは別の呼び名〉を表す「別名」。〈異なるもの〉の語義ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a849add-9c71-470c-b7c7-5f19af1c26f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36281, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "会費は別のでお支払いください。", "corrected_sentence": "会費は別にお支払いください。", "error_description": "副詞「別に」の形で動詞「支払う」に続ける。「別の」に「で」を付けるのは誤り。誤りは「ので」の部分で、正しくは「に」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a849add-9c71-470c-b7c7-5f19af1c26f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36281, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この件は別のです。", "corrected_sentence": "この件は別です。", "error_description": "「別」は名詞・形容動詞なので「別です」の形で述語になる。「別の」は連体形で「です」の前には置けない。誤りは余分な「の」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a849add-9c71-470c-b7c7-5f19af1c26f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
