INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36282, 3, 'prompt1_core', '{"pos": "副詞", "semantic_class": "function", "definition": "「もっと」は、今よりもっと大きいことを言いたいときに使う言葉です。", "primary_collocate": null, "pronunciation": "もっと", "ipa": "motto", "syllable_count": 3, "sentences": [{"text": "このスープは少し薄いので、塩をもっと入れてください。", "target_word": "もっと", "complexity_tier": "T3", "furigana": "このスープは少[すこ]し薄[うす]いので、塩[しお]をもっと入[い]れてください。", "sentence_source": "generated"}, {"text": "後ろの席まで聞こえないので、もっと大きな声で話してください。", "target_word": "もっと", "complexity_tier": "T3", "furigana": "後[うし]ろの席[せき]まで聞[き]こえないので、もっと大[おお]きな声[こえ]で話[はな]してください。", "sentence_source": "generated"}, {"text": "昨日より今日のほうが、もっと寒く感じる。", "target_word": "もっと", "complexity_tier": "T3", "furigana": "昨日[きのう]より今日[きょう]のほうが、もっと寒[さむ]く感[かん]じる。", "sentence_source": "generated"}, {"text": "日本語がもっと上手になりたくて、毎日練習している。", "target_word": "もっと", "complexity_tier": "T3", "furigana": "日本語[にほんご]がもっと上手[じょうず]になりたくて、毎日[まいにち]練習[れんしゅう]している。", "sentence_source": "generated"}, {"text": "この部屋が今よりもっと広ければいいのに。", "target_word": "もっと", "complexity_tier": "T3", "furigana": "この部屋[へや]が今[いま]よりもっと広[ひろ]ければいいのに。", "sentence_source": "generated"}, {"text": "兄は父よりもっと背が高い。", "target_word": "もっと", "complexity_tier": "T3", "furigana": "兄[あに]は父[ちち]よりもっと背[せ]が高[たか]い。", "sentence_source": "generated"}, {"text": "時間があるなら、展示をもっとゆっくり見ていこう。", "target_word": "もっと", "complexity_tier": "T3", "furigana": "時間[じかん]があるなら、展示[てんじ]をもっとゆっくり見[み]ていこう。", "sentence_source": "generated"}, {"text": "今でも十分おいしいが、砂糖を足せばもっと甘くなる。", "target_word": "もっと", "complexity_tier": "T3", "furigana": "今[いま]でも十分[じゅうぶん]おいしいが、砂糖[さとう]を足[た]せばもっと甘[あま]くなる。", "sentence_source": "generated"}, {"text": "試合に勝ったあと、選手たちはもっと強くなりたいと話した。", "target_word": "もっと", "complexity_tier": "T3", "furigana": "試合[しあい]に勝[か]ったあと、選手[せんしゅ]たちはもっと強[つよ]くなりたいと話[はな]した。", "sentence_source": "generated"}, {"text": "先生は「もっと本を読んだほうがいい」と言った。", "target_word": "もっと", "complexity_tier": "T3", "furigana": "先生[せんせい]は「もっと本[ほん]を読[よ]んだほうがいい」と言[い]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "もっと", "label": "副詞（不変化）"}], "register": "neutral", "sense_fingerprint": "現状よりさらに程度や量が大きいことを表す副詞", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 4 above tier T1: contains vocabulary far above tier T1: 広けれ (Zipf 1.64)']::text[], 'f5f6c10e-59f5-434b-8d2f-b32eae92b808') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36282, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "もっと", "is_correct": true, "explanation": "正解。「塩をもっと入れてください」で、今より量を増やす意味になる。"}, {"text": "ぜんぜん", "is_correct": false, "explanation": "「ぜんぜん」は否定の文で使う副詞なので、肯定の「入れてください」とは続かない。"}, {"text": "とても", "is_correct": false, "explanation": "「とても」は程度の強さを表すが、「塩を〜入れる」の量を直接修飾する使い方は不自然。"}, {"text": "あまり", "is_correct": false, "explanation": "「あまり」は「〜ない」の否定と組む副詞なので、肯定の「入れてください」とは合わない。"}], "explanations": {"もっと": "正解。「塩をもっと入れてください」で、今より量を増やす意味になる。", "ぜんぜん": "「ぜんぜん」は否定の文で使う副詞なので、肯定の「入れてください」とは続かない。", "とても": "「とても」は程度の強さを表すが、「塩を〜入れる」の量を直接修飾する使い方は不自然。", "あまり": "「あまり」は「〜ない」の否定と組む副詞なので、肯定の「入れてください」とは合わない。"}, "sentence_index": 0, "correct_answer": "もっと"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "もっと夜中の十二時になった。", "explanation": "ここは〈もう〉（すでに時刻が来た）の意味。もっとは今より程度や量が増すことなので、時刻の到達は表せない。"}, {"text": "もっと三分で駅に着く。", "explanation": "ここは〈あと〉（残りの時間）の意味。もっとは増加を表すので、残り時間を示す文には合わない。"}, {"text": "もっと試験が終わって、ほっとした。", "explanation": "ここは〈やっと〉（長く待った末に）の意味。もっとは程度の増加で、待った末の到達や安堵は表せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1aff041-8e12-4be2-95f9-036736301c3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36282, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "もっと", "is_correct": true, "explanation": "正解。「展示をもっとゆっくり見ていこう」で、より時間をかけて見るという程度の増加を表す。"}, {"text": "ほとんど", "is_correct": false, "explanation": "「ほとんど」は大部分を表し、否定と結びつくことが多いので、肯定の「ゆっくり見ていこう」には合わない。"}, {"text": "まったく", "is_correct": false, "explanation": "「まったく」は後ろに否定が来るのが普通で、肯定の「ゆっくり見ていこう」とは続かない。"}, {"text": "なかなか", "is_correct": false, "explanation": "「なかなか」は「なかなか〜ない」と否定で使うので、肯定の「見ていこう」とは続かない。"}], "explanations": {"もっと": "正解。「展示をもっとゆっくり見ていこう」で、より時間をかけて見るという程度の増加を表す。", "ほとんど": "「ほとんど」は大部分を表し、否定と結びつくことが多いので、肯定の「ゆっくり見ていこう」には合わない。", "まったく": "「まったく」は後ろに否定が来るのが普通で、肯定の「ゆっくり見ていこう」とは続かない。", "なかなか": "「なかなか」は「なかなか〜ない」と否定で使うので、肯定の「見ていこう」とは続かない。"}, "sentence_index": 6, "correct_answer": "もっと"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "もっと気がつくと、雨が降っていた。", "explanation": "ここは〈いつの間にか〉（気づかないうちに）の意味。もっとは程度の増加なので、気づかないうちに起きた変化は表せない。"}, {"text": "もっと夜が明ける。", "explanation": "ここは〈まもなく〉（間もなく）の意味。もっとは今より程度が増すことで、時が近づくことは表せない。"}, {"text": "もっとぎりぎり、電車に乗った。", "explanation": "ここは〈ぎりぎり〉（かろうじて間に合う）の意味。もっとは程度の増加なので、ぎりぎりの成立は表せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1aff041-8e12-4be2-95f9-036736301c3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36282, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "明日はもっとに早く起きよう。", "corrected_sentence": "明日はもっと早く起きよう。", "error_description": "助詞の誤り。副詞「もっと」には格助詞「に」を付けず、直後に「早く」を続ける。「もっとに」が誤りで、正しくは「もっと早く」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1aff041-8e12-4be2-95f9-036736301c3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36282, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "先週より寒いので、もっと厚いに服を着よう。", "corrected_sentence": "先週より寒いので、もっと厚い服を着よう。", "error_description": "活用形の誤り。形容詞「厚い」は名詞「服」を直接修飾する連体形の形で使い、「厚いに」は形容詞に「に」を付けた誤った形。正しくは「もっと厚い服」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1aff041-8e12-4be2-95f9-036736301c3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36284, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "から", "options": [{"text": "から", "is_correct": true, "explanation": "「会ってから」の「から」。会ったあとに次の行動へ移ることを表す。この文の正解。"}, {"text": "で", "is_correct": false, "explanation": "「会ってで」では接続が成り立たず、文が壊れる。"}, {"text": "に", "is_correct": false, "explanation": "「会ってに」は接続として成り立たず、不自然になる。"}, {"text": "と", "is_correct": false, "explanation": "「会ってと」は接続として成り立たず、文が通らない。"}], "correct_answer": "から", "explanations": {"から": "「会ってから」の「から」。会ったあとに次の行動へ移ることを表す。この文の正解。", "で": "「会ってで」では接続が成り立たず、文が壊れる。", "に": "「会ってに」は接続として成り立たず、不自然になる。", "と": "「会ってと」は接続として成り立たず、文が通らない。"}, "error_tags": {"で": "手段・場所", "に": "方向・時点", "と": "並列・相手"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a849add-9c71-470c-b7c7-5f19af1c26f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36284, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a849add-9c71-470c-b7c7-5f19af1c26f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36284, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "人といっしょにその場所に行くことです。", "primary_collocate": null, "pronunciation": "あう", "ipa": "aɯ", "syllable_count": 2, "sentences": [{"text": "駅の前で友達と会って、いっしょに映画館へ行きました。", "target_word": "会って", "complexity_tier": "T3", "furigana": "駅[えき]の前[まえ]で友達[ともだち]と会[あ]って、いっしょに映画館[えいがかん]へ行[い]きました。", "sentence_source": "generated"}, {"text": "明日は九時に学校の門で会ってから、みんなで博物館に行きます。", "target_word": "会って", "complexity_tier": "T3", "furigana": "明日[あした]は九時[くじ]に学校[がっこう]の門[もん]で会[あ]ってから、みんなで博物館[はくぶつかん]に行[い]きます。", "sentence_source": "generated"}, {"text": "母と駅で会って、いっしょに病院へ行きました。", "target_word": "会って", "complexity_tier": "T3", "furigana": "母[はは]と駅[えき]で会[あ]って、いっしょに病院[びょういん]へ行[い]きました。", "sentence_source": "generated"}, {"text": "先生とバス停で会って、いっしょに学校へ行きます。", "target_word": "会って", "complexity_tier": "T3", "furigana": "先生[せんせい]とバス停[てい]で会[あ]って、いっしょに学校[がっこう]へ行[い]きます。", "sentence_source": "generated"}, {"text": "友達とホテルの前で会って、いっしょに空港へ行きました。", "target_word": "会って", "complexity_tier": "T3", "furigana": "友達[ともだち]とホテルの前[まえ]で会[あ]って、いっしょに空港[くうこう]へ行[い]きました。", "sentence_source": "generated"}, {"text": "兄と会ってから、二人で買い物に行きます。", "target_word": "会って", "complexity_tier": "T3", "furigana": "兄[あに]と会[あ]ってから、二人[ふたり]で買い物[かいもの]に行[い]きます。", "sentence_source": "generated"}, {"text": "日曜日に姉と会って、いっしょに海へ行く予定です。", "target_word": "会って", "complexity_tier": "T3", "furigana": "日曜日[にちようび]に姉[あね]と会[あ]って、いっしょに海[うみ]へ行[い]く予定[よてい]です。", "sentence_source": "generated"}, {"text": "会社の前で田中さんと会って、いっしょに会議室へ行きました。", "target_word": "会って", "complexity_tier": "T3", "furigana": "会社[かいしゃ]の前[まえ]で田中[たなか]さんと会[あ]って、いっしょに会議室[かいぎしつ]へ行[い]きました。", "sentence_source": "generated"}, {"text": "約束の時間に彼女と会って、いっしょにお店へ行きます。", "target_word": "会って", "complexity_tier": "T3", "furigana": "約束[やくそく]の時間[じかん]に彼女[かのじょ]と会[あ]って、いっしょにお店[みせ]へ行[い]きます。", "sentence_source": "generated"}, {"text": "駅で先輩と会って、いっしょに球場へ行きました。", "target_word": "会って", "complexity_tier": "T3", "furigana": "駅[えき]で先輩[せんぱい]と会[あ]って、いっしょに球場[きゅうじょう]へ行[い]きました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "会う", "label": "基本形"}, {"form": "会います", "label": "丁寧形"}, {"form": "会って", "label": "て形"}, {"form": "会った", "label": "過去形"}, {"form": "会わない", "label": "否定形"}, {"form": "会える", "label": "可能形"}], "register": "neutral", "sense_fingerprint": "会う(あう): 人とある場所で落ち合い、いっしょにその場所や目的地へ行く", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11236ac4-32a0-4c53-9d4d-00c4116c6282') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36284, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "会って", "is_correct": true, "explanation": "「友達と会って、いっしょに映画館へ行った」で、待ち合わせて合流する意味になる。この文の正解。"}, {"text": "消して", "is_correct": false, "explanation": "「消す」は〈消去する〉意味で、「友達と消して」は文が成り立たない。"}, {"text": "焦げて", "is_correct": false, "explanation": "「焦げる」は物が焼けすぎる意味で、「友達と焦げて」は意味が通らない。"}, {"text": "砕けて", "is_correct": false, "explanation": "「砕ける」は物が細かく割れる意味で、「友達と砕けて」は文が成り立たない。"}], "explanations": {"会って": "「友達と会って、いっしょに映画館へ行った」で、待ち合わせて合流する意味になる。この文の正解。", "消して": "「消す」は〈消去する〉意味で、「友達と消して」は文が成り立たない。", "焦げて": "「焦げる」は物が焼けすぎる意味で、「友達と焦げて」は意味が通らない。", "砕けて": "「砕ける」は物が細かく割れる意味で、「友達と砕けて」は文が成り立たない。"}, "sentence_index": 0, "correct_answer": "会って"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "来週、会議の資料を社長に会って渡す。", "explanation": "ここは〈人と顔を合わせる〉の意味。〈いっしょに場所へ行く〉の語義ではなく、資料の受け渡しと結びつけると不自然なので、この語義では合わない。"}, {"text": "道で昔の友達に会う。", "explanation": "ここは〈偶然出会う〉の意味。〈いっしょに場所へ行く〉の語義ではないので、この語義では合わない。"}, {"text": "事故に会って、入院した。", "explanation": "ここは〈不運に遭う〉の意味。〈いっしょに場所へ行く〉の語義ではないので、この文では合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a849add-9c71-470c-b7c7-5f19af1c26f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36284, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "会って", "is_correct": true, "explanation": "「姉と会って、いっしょに海へ行く予定」で、待ち合わせて合流する意味になる。この文の正解。"}, {"text": "眠って", "is_correct": false, "explanation": "「眠る」は寝る意味で、「姉と眠って、いっしょに海へ行く」は文の意味が成り立たない。"}, {"text": "凍って", "is_correct": false, "explanation": "「凍る」は固まる意味で、「姉と凍って」は文が成り立たない。"}, {"text": "割れて", "is_correct": false, "explanation": "「割れる」は物が壊れる意味で、「姉と割れて」は文が成り立たない。"}], "explanations": {"会って": "「姉と会って、いっしょに海へ行く予定」で、待ち合わせて合流する意味になる。この文の正解。", "眠って": "「眠る」は寝る意味で、「姉と眠って、いっしょに海へ行く」は文の意味が成り立たない。", "凍って": "「凍る」は固まる意味で、「姉と凍って」は文が成り立たない。", "割れて": "「割れる」は物が壊れる意味で、「姉と割れて」は文が成り立たない。"}, "sentence_index": 6, "correct_answer": "会って"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "計算が会って、ほっとした。", "explanation": "ここは〈合う（一致する）〉の意味。「会う」は人と会うことで、数字が一致する意味には使わない。"}, {"text": "この答えは正しい数字と会っている。", "explanation": "ここは〈正解と一致する〉の意味の「合う」と混同した例。「会う」は人と顔を合わせる意味で、数字の一致には使わない。"}, {"text": "このサイズの服は体に会わない。", "explanation": "ここは〈合わない（ぴったり合わない）〉の意味。〈いっしょに行く〉の意味ではないので、ここでは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a849add-9c71-470c-b7c7-5f19af1c26f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36284, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "週末に先輩と会ってで、いっしょに買い物に行きました。", "corrected_sentence": "週末に先輩と会って、いっしょに買い物に行きました。", "error_description": "「会って」の後ろに「で」は続かない。誤りは余分な「で」で、これを外すと正しい文になる。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "会って", "is_correct": true, "explanation": "て形で「会ってから」と続け、会ってから次の行動に移る意味になる。この文の正解。"}, {"text": "会わず", "is_correct": false, "explanation": "連用形の否定で「会わず」は「から」に続かず、文が成り立たない。"}, {"text": "会えば", "is_correct": false, "explanation": "仮定形で「会えばから」は接続が成り立たず、文が壊れる。"}, {"text": "会いましょう", "is_correct": false, "explanation": "勧誘の形で、後ろの「から」に続かず文の流れに合わない。"}], "correct_form": "会って", "base_form": "会う", "form_label": "て形", "sentence_index": 1, "explanations": {"会って": "て形で「会ってから」と続け、会ってから次の行動に移る意味になる。この文の正解。", "会わず": "連用形の否定で「会わず」は「から」に続かず、文が成り立たない。", "会えば": "仮定形で「会えばから」は接続が成り立たず、文が壊れる。", "会いましょう": "勧誘の形で、後ろの「から」に続かず文の流れに合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a849add-9c71-470c-b7c7-5f19af1c26f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36284, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "明日は先輩と会いて、いっしょに球場へ行きます。", "corrected_sentence": "明日は先輩と会って、いっしょに球場へ行きます。", "error_description": "「会う」のて形は「会って」。「会いて」は連用形「会い」に「て」を付けた誤りで、正しくはて形の「会って」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "会って", "is_correct": true, "explanation": "て形で「田中さんと会って、いっしょに会議室へ行った」と続く。この文の正解。"}, {"text": "会おう", "is_correct": false, "explanation": "意志形で「会おう、いっしょに〜」と続かず、文が成り立たない。"}, {"text": "会います", "is_correct": false, "explanation": "丁寧な現在形で、て形ではないため「行きました」と続く形にならない。"}, {"text": "会え", "is_correct": false, "explanation": "命令形で「会え、いっしょに〜」と続かず、文が成り立たない。"}], "correct_form": "会って", "base_form": "会う", "form_label": "て形", "sentence_index": 7, "explanations": {"会って": "て形で「田中さんと会って、いっしょに会議室へ行った」と続く。この文の正解。", "会おう": "意志形で「会おう、いっしょに〜」と続かず、文が成り立たない。", "会います": "丁寧な現在形で、て形ではないため「行きました」と続く形にならない。", "会え": "命令形で「会え、いっしょに〜」と続かず、文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a849add-9c71-470c-b7c7-5f19af1c26f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36285, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "と", "options": [{"text": "と", "is_correct": true, "explanation": "会う相手を示す「と」。「姉と会いました」で、会う相手を正しく表す。"}, {"text": "を", "is_correct": false, "explanation": "「会う」は「を」を取らない。対象は「と」か「に」で示す。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す助詞で、会う相手を示すには使えない。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾の助詞。動詞の直前に置いて相手を示すことはできない。"}], "correct_answer": "と", "explanations": {"と": "会う相手を示す「と」。「姉と会いました」で、会う相手を正しく表す。", "を": "「会う」は「を」を取らない。対象は「と」か「に」で示す。", "へ": "方向を表す助詞で、会う相手を示すには使えない。", "の": "連体修飾の助詞。動詞の直前に置いて相手を示すことはできない。"}, "error_tags": {"を": "格不一致", "へ": "方向", "の": "連体修飾"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "別れる", "is_correct": true, "explanation": "〈会う〉の対義語。顔を合わせることの反対で、それぞれ離れることを表す。"}, {"text": "集まる", "is_correct": false, "explanation": "人が一か所に寄る意味。〈会う〉の対義語ではない。"}, {"text": "待つ", "is_correct": false, "explanation": "相手や時間が来るのを待つ意味。対義語ではない。"}, {"text": "話す", "is_correct": false, "explanation": "言葉を交わす意味。対義語ではない。"}], "correct_answer": "別れる", "explanations": {"別れる": "〈会う〉の対義語。顔を合わせることの反対で、それぞれ離れることを表す。", "集まる": "人が一か所に寄る意味。〈会う〉の対義語ではない。", "待つ": "相手や時間が来るのを待つ意味。対義語ではない。", "話す": "言葉を交わす意味。対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a849add-9c71-470c-b7c7-5f19af1c26f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36285, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "場所を表す「で」。「公園で会って」で、会った場所を示す。"}, {"text": "が", "is_correct": false, "explanation": "主語を示す「が」。「公園が会って」では場所が主語になり、意味をなさない。"}, {"text": "から", "is_correct": false, "explanation": "起点を示す「から」。「公園から会って」では場所で会うという意味にならない。"}, {"text": "より", "is_correct": false, "explanation": "比較を示す「より」。比べる文脈がなく、「公園より会って」は成立しない。"}], "correct_answer": "で", "explanations": {"で": "場所を表す「で」。「公園で会って」で、会った場所を示す。", "が": "主語を示す「が」。「公園が会って」では場所が主語になり、意味をなさない。", "から": "起点を示す「から」。「公園から会って」では場所で会うという意味にならない。", "より": "比較を示す「より」。比べる文脈がなく、「公園より会って」は成立しない。"}, "error_tags": {"が": "主語", "から": "起点", "より": "比較"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "別れる", "is_correct": true, "explanation": "〈会う〉の対義語。顔を合わせることの反対で、それぞれ離れることを表す。"}, {"text": "訪ねる", "is_correct": false, "explanation": "相手の家や場所を尋ねて行く意味。対義語ではない。"}, {"text": "出かける", "is_correct": false, "explanation": "家などから外へ行く意味。対義語ではない。"}, {"text": "誘う", "is_correct": false, "explanation": "相手に一緒に行くよう声をかける意味。対義語ではない。"}], "correct_answer": "別れる", "explanations": {"別れる": "〈会う〉の対義語。顔を合わせることの反対で、それぞれ離れることを表す。", "訪ねる": "相手の家や場所を尋ねて行く意味。対義語ではない。", "出かける": "家などから外へ行く意味。対義語ではない。", "誘う": "相手に一緒に行くよう声をかける意味。対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a849add-9c71-470c-b7c7-5f19af1c26f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36285, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "ある人が他の人と同じ場所にいて、お互いに顔を合わせること。たとえば、約束して公園で一緒に過ごすこと。", "primary_collocate": null, "pronunciation": "あう", "ipa": "aɯ", "syllable_count": 2, "sentences": [{"text": "日曜日に公園で友達と会います。", "target_word": "会います", "complexity_tier": "T3", "furigana": "日曜日[にちようび]に公園[こうえん]で友達[ともだち]と会[あ]います。", "sentence_source": "generated"}, {"text": "昨日、約束して公園で姉と会いました。", "target_word": "会いました", "complexity_tier": "T3", "furigana": "昨日[きのう]、約束[やくそく]して公園[こうえん]で姉[あね]と会[あ]いました。", "sentence_source": "generated"}, {"text": "久しぶりに祖母に会って、一日ゆっくり話しました。", "target_word": "会って", "complexity_tier": "T3", "furigana": "久[ひさ]しぶりに祖母[そぼ]に会[あ]って、一日[いちにち]ゆっくり話[はな]しました。", "sentence_source": "generated"}, {"text": "来週、公園で会う約束をしました。", "target_word": "会う", "complexity_tier": "T3", "furigana": "来週[らいしゅう]、公園[こうえん]で会[あ]う約束[やくそく]をしました。", "sentence_source": "generated"}, {"text": "毎週土曜日、公園で友達と会って遊びます。", "target_word": "会って", "complexity_tier": "T3", "furigana": "毎週[まいしゅう]土曜日[どようび]、公園[こうえん]で友達[ともだち]と会[あ]って遊[あそ]びます。", "sentence_source": "generated"}, {"text": "雨だったので、友達と公園で会う約束をやめて、家で遊びました。", "target_word": "会う", "complexity_tier": "T3", "furigana": "雨[あめ]だったので、友達[ともだち]と公園[こうえん]で会[あ]う約束[やくそく]をやめて、家[いえ]で遊[あそ]びました。", "sentence_source": "generated"}, {"text": "友達と公園で会って、お弁当を食べました。", "target_word": "会って", "complexity_tier": "T3", "furigana": "友達[ともだち]と公園[こうえん]で会[あ]って、お弁当[べんとう]を食[た]べました。", "sentence_source": "generated"}, {"text": "彼とは公園で会って、いっしょに犬を散歩させました。", "target_word": "会って", "complexity_tier": "T3", "furigana": "彼[かれ]とは公園[こうえん]で会[あ]って、いっしょに犬[いぬ]を散歩[さんぽ]させました。", "sentence_source": "generated"}, {"text": "子どもの時の友達と公園で会うのが楽しみです。", "target_word": "会う", "complexity_tier": "T3", "furigana": "子[こ]どもの時[とき]の友達[ともだち]と公園[こうえん]で会[あ]うのが楽[たの]しみです。", "sentence_source": "generated"}, {"text": "週末に公園で恋人と会って、のんびり過ごしました。", "target_word": "会って", "complexity_tier": "T3", "furigana": "週末[しゅうまつ]に公園[こうえん]で恋人[こいびと]と会[あ]って、のんびり過[す]ごしました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "会う", "label": "基本形"}, {"form": "会います", "label": "丁寧形"}, {"form": "会って", "label": "て形"}, {"form": "会った", "label": "過去形"}, {"form": "会わない", "label": "否定形"}, {"form": "会える", "label": "可能形"}], "register": "neutral", "sense_fingerprint": "会う(あう): 人と同じ場所で顔を合わせ、いっしょに時間を過ごす。約束して人と対面する", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11236ac4-32a0-4c53-9d4d-00c4116c6282') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36285, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "会います", "is_correct": true, "explanation": "文中の形そのもの。「日曜日に公園で友達と〜」の空欄に、丁寧な現在・未来形の「会います」が入る。"}, {"text": "沸かします", "is_correct": false, "explanation": "湯や水を熱する動詞で、人を対象にできない。「友達と沸かします」は意味をなさない。"}, {"text": "凍らせます", "is_correct": false, "explanation": "物を凍らせる動詞。人には使えず、「友達と凍らせます」は不自然。"}, {"text": "焦がします", "is_correct": false, "explanation": "食べ物などを焼いて焦がす動詞。人には使えず、文が成立しない。"}], "explanations": {"会います": "文中の形そのもの。「日曜日に公園で友達と〜」の空欄に、丁寧な現在・未来形の「会います」が入る。", "沸かします": "湯や水を熱する動詞で、人を対象にできない。「友達と沸かします」は意味をなさない。", "凍らせます": "物を凍らせる動詞。人には使えず、「友達と凍らせます」は不自然。", "焦がします": "食べ物などを焼いて焦がす動詞。人には使えず、文が成立しない。"}, "sentence_index": 0, "correct_answer": "会います"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "昨日、宝くじに会いました。", "explanation": "ここは〈当たる〉（宝くじが当たる）の意味。〈会う〉は人と顔を合わせることなので、宝くじには使えない。"}, {"text": "その本に会って、人生が変わりました。", "explanation": "ここは〈出会う〉の意味。〈会う〉は人と対面する意味なので、本には使えない。"}, {"text": "この靴はサイズが会いました。", "explanation": "ここは〈合う〉（ぴったり合う）の意味。〈会う〉は人と顔を合わせる意味なので、サイズには使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a849add-9c71-470c-b7c7-5f19af1c26f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36285, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "会って", "is_correct": true, "explanation": "文中の形そのもの。「友達と公園で〜、お弁当を食べました」の空欄に、て形の「会って」が入る。"}, {"text": "割って", "is_correct": false, "explanation": "物を割る動詞。人を対象にできず、「友達と割って」は意味をなさない。"}, {"text": "煮詰めて", "is_correct": false, "explanation": "液体を煮て濃くする動詞。人には使えず、文が成立しない。"}, {"text": "砕いて", "is_correct": false, "explanation": "固い物を細かくする動詞。人には使えず、「友達と砕いて」は不自然。"}], "explanations": {"会って": "文中の形そのもの。「友達と公園で〜、お弁当を食べました」の空欄に、て形の「会って」が入る。", "割って": "物を割る動詞。人を対象にできず、「友達と割って」は意味をなさない。", "煮詰めて": "液体を煮て濃くする動詞。人には使えず、文が成立しない。", "砕いて": "固い物を細かくする動詞。人には使えず、「友達と砕いて」は不自然。"}, "sentence_index": 6, "correct_answer": "会って"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "週末に恋人と電話で会って、のんびり過ごしました。", "explanation": "ここは〈話す〉の意味。電話で言葉を交わすことは〈会う〉とは言わない。〈会う〉は顔を合わせることなので、電話には使えない。"}, {"text": "週末に恋人と映画に会って、のんびり過ごしました。", "explanation": "ここは〈見る〉の意味。映画は見るものなので〈会う〉は使えない。〈会う〉は人に対して使う。"}, {"text": "週末に恋人の声に会って、のんびり過ごしました。", "explanation": "ここは〈聞く〉の意味。声は聞くものなので、〈会う〉は使えない。〈会う〉は人と対面することを表す。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a849add-9c71-470c-b7c7-5f19af1c26f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36285, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "先週、駅で先生に会うて、話しました。", "corrected_sentence": "先週、駅で先生に会って、話しました。", "error_description": "て形の誤り。「会う」のて形は「会って」で、「会うて」は誤り（う→っ）。正しくは「会って」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "会いました", "is_correct": true, "explanation": "丁寧形の過去。昨日の出来事を丁寧に述べる文に合う正しい形。"}, {"text": "会って", "is_correct": false, "explanation": "て形。文を言い切れず、文末には使えない。"}, {"text": "会わない", "is_correct": false, "explanation": "否定形。「会った」という肯定の事実を述べる文には合わない。"}, {"text": "会います", "is_correct": false, "explanation": "丁寧形の現在・未来。昨日の出来事を述べる文では過去の形が必要。"}], "correct_form": "会いました", "base_form": "会う", "form_label": "丁寧形（過去）", "sentence_index": 1, "explanations": {"会いました": "丁寧形の過去。昨日の出来事を丁寧に述べる文に合う正しい形。", "会って": "て形。文を言い切れず、文末には使えない。", "会わない": "否定形。「会った」という肯定の事実を述べる文には合わない。", "会います": "丁寧形の現在・未来。昨日の出来事を述べる文では過去の形が必要。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a849add-9c71-470c-b7c7-5f19af1c26f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36285, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "先週、カフェで同僚を会いました。", "corrected_sentence": "先週、カフェで同僚と会いました。", "error_description": "助詞の誤り。「会う」は「と」で相手を示す。「を」は誤りで、正しくは「同僚と会いました」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "会って", "is_correct": true, "explanation": "て形。「彼とは公園で会って、〜させました」のように、後に動作が続く形として正しい。"}, {"text": "会わせ", "is_correct": false, "explanation": "使役の語幹で、単独では文を続けも言い切りもできず、成立しない。"}, {"text": "会おう", "is_correct": false, "explanation": "意向形。話し手の意思を表す形で、過去の出来事の文には合わない。"}, {"text": "会える", "is_correct": false, "explanation": "可能形。「会うことができる」の意味になり、実際に会った事実を述べられない。"}], "correct_form": "会って", "base_form": "会う", "form_label": "て形", "sentence_index": 7, "explanations": {"会って": "て形。「彼とは公園で会って、〜させました」のように、後に動作が続く形として正しい。", "会わせ": "使役の語幹で、単独では文を続けも言い切りもできず、成立しない。", "会おう": "意向形。話し手の意思を表す形で、過去の出来事の文には合わない。", "会える": "可能形。「会うことができる」の意味になり、実際に会った事実を述べられない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a849add-9c71-470c-b7c7-5f19af1c26f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
