INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36288, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "十が三つ集まった数。", "primary_collocate": null, "pronunciation": "さんじゅう", "ipa": "sandʑɯː", "syllable_count": 4, "sentences": [{"text": "10を三つ集めると「30」になります。", "target_word": "30", "complexity_tier": "T3", "furigana": "10を三[みっ]つ集[あつ]めると「30」になります。", "sentence_source": "generated"}, {"text": "10と10と10をたすと、「30」です。", "target_word": "30", "complexity_tier": "T3", "furigana": "10と10と10をたすと、「30」です。", "sentence_source": "generated"}, {"text": "10個ずつ三つの箱に入れると、合計は「30」です。", "target_word": "30", "complexity_tier": "T3", "furigana": "10個[こ]ずつ三[みっ]つの箱[はこ]に入[い]れると、合計[ごうけい]は「30」です。", "sentence_source": "generated"}, {"text": "10が三つ集まった数は「30」です。", "target_word": "30", "complexity_tier": "T3", "furigana": "10が三[みっ]つ集[あつ]まった数[かず]は「30」です。", "sentence_source": "generated"}, {"text": "20に10を足すと「30」になります。", "target_word": "30", "complexity_tier": "T3", "furigana": "20に10を足[た]すと「30」になります。", "sentence_source": "generated"}, {"text": "10を三回足すと、答えは「30」です。", "target_word": "30", "complexity_tier": "T3", "furigana": "10を三回[さんかい]足[た]すと、答[こた]えは「30」です。", "sentence_source": "generated"}, {"text": "赤と青と白の玉が10ずつあるので、玉は全部で「30」です。", "target_word": "30", "complexity_tier": "T3", "furigana": "赤[あか]と青[あお]と白[しろ]の玉[たま]が10ずつあるので、玉[たま]は全部[ぜんぶ]で「30」です。", "sentence_source": "generated"}, {"text": "先生は黒板に10を三つ書いて、合計は「30」だと説明しました。", "target_word": "30", "complexity_tier": "T3", "furigana": "先生[せんせい]は黒板[こくばん]に10を三[みっ]つ書[か]いて、合計[ごうけい]は「30」だと説明[せつめい]しました。", "sentence_source": "generated"}, {"text": "10の束が三つあれば、数えなくても「30」だと分かります。", "target_word": "30", "complexity_tier": "T3", "furigana": "10の束[たば]が三[みっ]つあれば、数[かぞ]えなくても「30」だと分[わ]かります。", "sentence_source": "generated"}, {"text": "10ずつ三つに分けられる数は「30」です。", "target_word": "30", "complexity_tier": "T3", "furigana": "10ずつ三[みっ]つに分[わ]けられる数[かず]は「30」です。", "sentence_source": "generated"}], "morphological_forms": [{"form": "30", "label": "基本形"}, {"form": "三十", "label": "漢数字表記"}, {"form": "30の", "label": "連体形"}, {"form": "30です", "label": "丁寧形"}], "register": "neutral", "sense_fingerprint": "30(さんじゅう): 十が三つ集まってできる数。合計や足し算の結果としての数", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11236ac4-32a0-4c53-9d4d-00c4116c6282') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36288, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "30", "is_correct": true, "explanation": "文中の形そのもの。「10を三つ集めると「〜」になります」の空欄に、数の「30」が入る。"}, {"text": "三角", "is_correct": false, "explanation": "図形の名前。数を集めた結果にはならず、文が成立しない。"}, {"text": "正方形", "is_correct": false, "explanation": "図形の名前。10を集めて正方形になるという意味にならず、不自然。"}, {"text": "円", "is_correct": false, "explanation": "図形の名前。集めた結果が円になるという意味にならない。"}], "explanations": {"30": "文中の形そのもの。「10を三つ集めると「〜」になります」の空欄に、数の「30」が入る。", "三角": "図形の名前。数を集めた結果にはならず、文が成立しない。", "正方形": "図形の名前。10を集めて正方形になるという意味にならず、不自然。", "円": "図形の名前。集めた結果が円になるという意味にならない。"}, "sentence_index": 0, "correct_answer": "30"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この薬は30の効果を持っています。", "explanation": "「三重の効果」の「三」は30に置き換えられない。30は数であり、重なりを表す語にはならない。"}, {"text": "彼は30苦を背負いながら夢を追いかけた。", "explanation": "「三重苦」の「三」は30に置き換えられない。数の30は苦しみの重なりを表さない。"}, {"text": "この曲は30奏で演奏されます。", "explanation": "「三重奏」の「三」は30に置き換えられない。数の30は演奏形態を表す語にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a849add-9c71-470c-b7c7-5f19af1c26f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
