INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36290, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "違いを主題として示す「は」。「違いは、すぐにわかりました」と続く。"}, {"text": "の", "is_correct": false, "explanation": "「違いの、すぐにわかりました」とは続かない。違いの後には主題の「は」が入る。"}, {"text": "へ", "is_correct": false, "explanation": "「違いへ」と方向は示せず、この文では不自然。"}, {"text": "と", "is_correct": false, "explanation": "「違いと」は並列や相手を示すが、主題を示す文にならない。"}], "correct_answer": "は", "explanations": {"は": "違いを主題として示す「は」。「違いは、すぐにわかりました」と続く。", "の": "「違いの、すぐにわかりました」とは続かない。違いの後には主題の「は」が入る。", "へ": "「違いへ」と方向は示せず、この文では不自然。", "と": "「違いと」は並列や相手を示すが、主題を示す文にならない。"}, "error_tags": {"の": "所有", "へ": "方向", "と": "並列"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "一致", "is_correct": true, "explanation": "「同じではないこと」の対義語は「一致」。同じか異なるかで対立する。"}, {"text": "増加", "is_correct": false, "explanation": "数量が増えることで、同じかどうかの対義語ではない。"}, {"text": "完成", "is_correct": false, "explanation": "物事がなし遂げられることで、違いとは対立しない。"}, {"text": "進歩", "is_correct": false, "explanation": "よい方向へ進むことで、違いの対義語ではない。"}], "correct_answer": "一致", "explanations": {"一致": "「同じではないこと」の対義語は「一致」。同じか異なるかで対立する。", "増加": "数量が増えることで、同じかどうかの対義語ではない。", "完成": "物事がなし遂げられることで、違いとは対立しない。", "進歩": "よい方向へ進むことで、違いの対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '37a00a04-4613-4ed0-8714-b43ebbccdc29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36290, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「結果に違いが出る」の「が」。違いが現れる主語を示す。"}, {"text": "を", "is_correct": false, "explanation": "「違いを出ます」とは続かない。「出ます」は目的語を取らず、違いは主語として「が」で示す。"}, {"text": "で", "is_correct": false, "explanation": "「結果で違い」と手段は示せず、「出ます」の主語にならない。"}, {"text": "より", "is_correct": false, "explanation": "「結果より違い」は比較の意味になり、「出ます」と続かない。"}], "correct_answer": "が", "explanations": {"が": "「結果に違いが出る」の「が」。違いが現れる主語を示す。", "を": "「違いを出ます」とは続かない。「出ます」は目的語を取らず、違いは主語として「が」で示す。", "で": "「結果で違い」と手段は示せず、「出ます」の主語にならない。", "より": "「結果より違い」は比較の意味になり、「出ます」と続かない。"}, "error_tags": {"を": "目的語", "で": "手段", "より": "比較"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "同一", "is_correct": true, "explanation": "「同じではないこと」の対義語は「同一（同じであること）」。"}, {"text": "混乱", "is_correct": false, "explanation": "乱れて分からなくなることで、違いの対義語ではない。"}, {"text": "成長", "is_correct": false, "explanation": "大きくなることで、違いと対立する関係にない。"}, {"text": "報告", "is_correct": false, "explanation": "知らせることで、対義語ではない。"}], "correct_answer": "同一", "explanations": {"同一": "「同じではないこと」の対義語は「同一（同じであること）」。", "混乱": "乱れて分からなくなることで、違いの対義語ではない。", "成長": "大きくなることで、違いと対立する関係にない。", "報告": "知らせることで、対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '37a00a04-4613-4ed0-8714-b43ebbccdc29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36290, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ふたつのものが、同じではないこと。", "primary_collocate": null, "pronunciation": "ちがい", "ipa": "tɕiɡai", "syllable_count": 3, "sentences": [{"text": "兄と弟では、性格に大きな違いがあります。", "target_word": "違い", "complexity_tier": "T3", "furigana": "兄[あに]と弟[おとうと]では、性格[せいかく]に大[おお]きな違[ちが]いがあります。", "sentence_source": "generated"}, {"text": "新しい車と古い車の違いは、すぐにわかりました。", "target_word": "違い", "complexity_tier": "T3", "furigana": "新[あたら]しい車[くるま]と古[ふる]い車[くるま]の違[ちが]いは、すぐにわかりました。", "sentence_source": "generated"}, {"text": "年齢の違いは、二人の友情に関係ありません。", "target_word": "違い", "complexity_tier": "T3", "furigana": "年齢[ねんれい]の違[ちが]いは、二人[ふたり]の友情[ゆうじょう]に関係[かんけい]ありません。", "sentence_source": "generated"}, {"text": "日本と私の国では、文化の違いが多くて驚きました。", "target_word": "違い", "complexity_tier": "T3", "furigana": "日本[にほん]と私[わたし]の国[くに]では、文化[ぶんか]の違[ちが]いが多[おお]くて驚[おどろ]きました。", "sentence_source": "generated"}, {"text": "値段に違いがないなら、安全なほうを選びます。", "target_word": "違い", "complexity_tier": "T3", "furigana": "値段[ねだん]に違[ちが]いがないなら、安全[あんぜん]なほうを選[えら]びます。", "sentence_source": "generated"}, {"text": "双子なのに、二人の違いははっきりしています。", "target_word": "違い", "complexity_tier": "T3", "furigana": "双子[ふたご]なのに、二人[ふたり]の違[ちが]いははっきりしています。", "sentence_source": "generated"}, {"text": "昨日と今日では、気温の違いが十度もあります。", "target_word": "違い", "complexity_tier": "T3", "furigana": "昨日[きのう]と今日[きょう]では、気温[きおん]の違[ちが]いが十度[じゅうど]もあります。", "sentence_source": "generated"}, {"text": "練習した人としていない人では、結果に違いが出ます。", "target_word": "違い", "complexity_tier": "T3", "furigana": "練習[れんしゅう]した人[ひと]としていない人[ひと]では、結果[けっか]に違[ちが]いが出[で]ます。", "sentence_source": "generated"}, {"text": "先生の説明と本の内容に違いがあって、困りました。", "target_word": "違い", "complexity_tier": "T3", "furigana": "先生[せんせい]の説明[せつめい]と本[ほん]の内容[ないよう]に違[ちが]いがあって、困[こま]りました。", "sentence_source": "generated"}, {"text": "この二つの水は、味の違いがまったくわかりません。", "target_word": "違い", "complexity_tier": "T3", "furigana": "この二[ふた]つの水[みず]は、味[あじ]の違[ちが]いがまったくわかりません。", "sentence_source": "generated"}], "morphological_forms": [{"form": "違い", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "二つのものが同じでない状態。差があること。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01b68666-ebe4-44b0-8208-b74bdbb1eb7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36290, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "違い", "is_correct": true, "explanation": "「性格に大きな違いがある」で、二人の性格の差を表す。空欄に入る正解。"}, {"text": "記憶", "is_correct": false, "explanation": "「性格に大きな記憶がある」は意味が通らず、空欄に入らない。"}, {"text": "音量", "is_correct": false, "explanation": "「性格に大きな音量がある」は性格の説明として成り立たない。"}, {"text": "天気", "is_correct": false, "explanation": "「性格に大きな天気がある」は言わず、文脈に合わない。"}], "explanations": {"違い": "「性格に大きな違いがある」で、二人の性格の差を表す。空欄に入る正解。", "記憶": "「性格に大きな記憶がある」は意味が通らず、空欄に入らない。", "音量": "「性格に大きな音量がある」は性格の説明として成り立たない。", "天気": "「性格に大きな天気がある」は言わず、文脈に合わない。"}, "sentence_index": 0, "correct_answer": "違い"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼女は驚いて、思わず違いを上げた。", "explanation": "違いは「上げる」とは組まないので不自然。"}, {"text": "仕事のつらさを、同僚に違いをこぼした。", "explanation": "違いは「こぼす」とは組まないので不自然。"}, {"text": "彼に大きな違いをかけてしまい、申し訳なかった。", "explanation": "違いは「かける」とは組まないので不自然。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '37a00a04-4613-4ed0-8714-b43ebbccdc29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36290, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "違い", "is_correct": true, "explanation": "「気温の違い」で、昨日と今日の温度の差を表す。空欄に入る正解。"}, {"text": "手紙", "is_correct": false, "explanation": "「気温の手紙」は意味が通らず、空欄に入らない。"}, {"text": "音楽", "is_correct": false, "explanation": "「気温の音楽」は成り立たず、文脈に合わない。"}, {"text": "経験", "is_correct": false, "explanation": "「気温の経験」は言わず、この文では不自然。"}], "explanations": {"違い": "「気温の違い」で、昨日と今日の温度の差を表す。空欄に入る正解。", "手紙": "「気温の手紙」は意味が通らず、空欄に入らない。", "音楽": "「気温の音楽」は成り立たず、文脈に合わない。", "経験": "「気温の経験」は言わず、この文では不自然。"}, "sentence_index": 6, "correct_answer": "違い"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼女は違いを断ち切れず、なかなか答えを出せなかった。", "explanation": "違いは「断ち切る」とは組まないので不自然。"}, {"text": "人前で違いをかいてしまい、とても恥ずかしかった。", "explanation": "違いは「かく」とは組まないので不自然。"}, {"text": "その知らせに、違いを隠せないほど驚いた。", "explanation": "違いは「隠す」とは組まないので不自然。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '37a00a04-4613-4ed0-8714-b43ebbccdc29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36290, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "二つの色の違いを、はっきり決めます。", "corrected_sentence": "二つの色の違いを、はっきり見分けます。", "error_description": "正しくは「違いを見分ける」。「違いを決める」とは言わない。違いに続く動詞「決めます」が誤りで、正しくは「見分けます」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '37a00a04-4613-4ed0-8714-b43ebbccdc29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36290, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夏と冬では、気温を違いが大きい。", "corrected_sentence": "夏と冬では、気温の違いが大きい。", "error_description": "正しくは「気温の違い」。「違い」の前は「の」で続ける。「を」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '37a00a04-4613-4ed0-8714-b43ebbccdc29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36291, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "共通", "is_correct": true, "explanation": "「違う点」の対義語は「共通点（同じ点）」。"}, {"text": "変化", "is_correct": false, "explanation": "変わることで、違いの対義語ではない。"}, {"text": "発見", "is_correct": false, "explanation": "見つけることで、対義語ではない。"}, {"text": "印象", "is_correct": false, "explanation": "受けた感じのことで、対義語ではない。"}], "correct_answer": "共通", "explanations": {"共通": "「違う点」の対義語は「共通点（同じ点）」。", "変化": "変わることで、違いの対義語ではない。", "発見": "見つけることで、対義語ではない。", "印象": "受けた感じのことで、対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '37a00a04-4613-4ed0-8714-b43ebbccdc29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36291, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「中身の違い」の「の」。違いの前に名詞を続けて、何の違いかを示す。"}, {"text": "を", "is_correct": false, "explanation": "「中身を違い」は目的語にならず、違いの前に置けない。"}, {"text": "へ", "is_correct": false, "explanation": "「中身へ違い」と方向は示せず、不自然。"}, {"text": "か", "is_correct": false, "explanation": "「中身か違い」では「か」が並列を表す形にならず、違いの前に置けない。"}], "correct_answer": "の", "explanations": {"の": "「中身の違い」の「の」。違いの前に名詞を続けて、何の違いかを示す。", "を": "「中身を違い」は目的語にならず、違いの前に置けない。", "へ": "「中身へ違い」と方向は示せず、不自然。", "か": "「中身か違い」では「か」が並列を表す形にならず、違いの前に置けない。"}, "error_tags": {"を": "object", "へ": "direction", "か": "alternative"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "共通", "is_correct": true, "explanation": "「違う点」の対義語は「共通点（同じ点）」。"}, {"text": "機会", "is_correct": false, "explanation": "物事をする好機のことで、対義語ではない。"}, {"text": "努力", "is_correct": false, "explanation": "力を尽くすことで、対義語ではない。"}, {"text": "責任", "is_correct": false, "explanation": "引き受けるべき務めで、対義語ではない。"}], "correct_answer": "共通", "explanations": {"共通": "「違う点」の対義語は「共通点（同じ点）」。", "機会": "物事をする好機のことで、対義語ではない。", "努力": "力を尽くすことで、対義語ではない。", "責任": "引き受けるべき務めで、対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '37a00a04-4613-4ed0-8714-b43ebbccdc29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36291, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "二つの物事の間に見られる、異なる点。相違。", "primary_collocate": null, "pronunciation": "ちがい", "ipa": "tɕiɡai", "syllable_count": 3, "sentences": [{"text": "二つの写真の違いを三つ探してください。", "target_word": "違い", "complexity_tier": "T3", "furigana": "二[ふた]つの写真[しゃしん]の違[ちが]いを三[みっ]つ探[さが]してください。", "sentence_source": "generated"}, {"text": "この二つの言葉の違いを、辞書で調べました。", "target_word": "違い", "complexity_tier": "T3", "furigana": "この二[ふた]つの言葉[ことば]の違[ちが]いを、辞書[じしょ]で調[しら]べました。", "sentence_source": "generated"}, {"text": "兄と私の違いは、背の高さだけです。", "target_word": "違い", "complexity_tier": "T3", "furigana": "兄[あに]と私[わたし]の違[ちが]いは、背[せ]の高[たか]さだけです。", "sentence_source": "generated"}, {"text": "表を見ると、A案とB案の違いがよくわかります。", "target_word": "違い", "complexity_tier": "T3", "furigana": "表[ひょう]を見[み]ると、A案[えー あん]とB案[びー あん]の違[ちが]いがよくわかります。", "sentence_source": "generated"}, {"text": "日本語の「は」と「が」の違いを、先生に質問しました。", "target_word": "違い", "complexity_tier": "T3", "furigana": "日本語[にほんご]の「は」と「が」の違[ちが]いを、先生[せんせい]に質問[しつもん]しました。", "sentence_source": "generated"}, {"text": "二つの会社の違いは、給料と休みの日数です。", "target_word": "違い", "complexity_tier": "T3", "furigana": "二[ふた]つの会社[かいしゃ]の違[ちが]いは、給料[きゅうりょう]と休[やす]みの日数[にっすう]です。", "sentence_source": "generated"}, {"text": "男女の違いを、グラフで比べてみました。", "target_word": "違い", "complexity_tier": "T3", "furigana": "男女[だんじょ]の違[ちが]いを、グラフで比[くら]べてみました。", "sentence_source": "generated"}, {"text": "見た目はそっくりだが、中身の違いは大きい。", "target_word": "違い", "complexity_tier": "T3", "furigana": "見[み]た目[め]はそっくりだが、中身[なかみ]の違[ちが]いは大[おお]きい。", "sentence_source": "generated"}, {"text": "本物とにせ物の違いを見分ける方法を教わりました。", "target_word": "違い", "complexity_tier": "T3", "furigana": "本物[ほんもの]とにせ物[もの]の違[ちが]いを見分[みわ]ける方法[ほうほう]を教[おそ]わりました。", "sentence_source": "generated"}, {"text": "関東と関西では、味つけの違いがあります。", "target_word": "違い", "complexity_tier": "T3", "furigana": "関東[かんとう]と関西[かんさい]では、味[あじ]つけの違[ちが]いがあります。", "sentence_source": "generated"}], "morphological_forms": [{"form": "違い", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "比べたときに見つかる、具体的な異なる点。相違点。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 9 above tier T1: contains vocabulary far above tier T1: 味つけ (Zipf 2.13)']::text[], '01b68666-ebe4-44b0-8208-b74bdbb1eb7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36291, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "違い", "is_correct": true, "explanation": "「写真の違い」を三つ探す文。二枚の写真の異なる点を指す。空欄に入る正解。"}, {"text": "予定", "is_correct": false, "explanation": "「写真の予定」を探すとは言わず、文脈に合わない。"}, {"text": "注文", "is_correct": false, "explanation": "「写真の注文」を探す、という意味にならない。"}, {"text": "手順", "is_correct": false, "explanation": "「写真の手順」を三つ探すとは言わない。"}], "explanations": {"違い": "「写真の違い」を三つ探す文。二枚の写真の異なる点を指す。空欄に入る正解。", "予定": "「写真の予定」を探すとは言わず、文脈に合わない。", "注文": "「写真の注文」を探す、という意味にならない。", "手順": "「写真の手順」を三つ探すとは言わない。"}, "sentence_index": 0, "correct_answer": "違い"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "昼過ぎに違いがやんで、外に出られた。", "explanation": "ここは〈雨〉の意味。雨はやむもの（雨がやむ）だが、違いがやむとは言わないので合わない。"}, {"text": "パソコンの違いを直してもらいました。", "explanation": "ここは〈故障〉の意味。故障は直すものだが、違いは直すものではないので合わない。"}, {"text": "窓の違いを拭いて、部屋をきれいにしました。", "explanation": "ここは〈汚れ〉の意味。汚れは拭くものだが、違いは拭けないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '37a00a04-4613-4ed0-8714-b43ebbccdc29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36291, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "違い", "is_correct": true, "explanation": "「男女の違い」を比べる文。性別による異なる点を指す。空欄に入る正解。"}, {"text": "宿題", "is_correct": false, "explanation": "「男女の宿題」は意味が通らず、空欄に入らない。"}, {"text": "電池", "is_correct": false, "explanation": "「男女の電池」は成り立たず、文脈に合わない。"}, {"text": "季節", "is_correct": false, "explanation": "「男女の季節」は言わず、グラフで比べる文に合わない。"}], "explanations": {"違い": "「男女の違い」を比べる文。性別による異なる点を指す。空欄に入る正解。", "宿題": "「男女の宿題」は意味が通らず、空欄に入らない。", "電池": "「男女の電池」は成り立たず、文脈に合わない。", "季節": "「男女の季節」は言わず、グラフで比べる文に合わない。"}, "sentence_index": 6, "correct_answer": "違い"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は先輩への違いを抱き、毎日練習を続けた。", "explanation": "ここは〈憧れ〉の意味。憧れは抱くものだが、違いを抱くとは言わないので合わない。"}, {"text": "運動のあと、違いをかいてのどが渇いた。", "explanation": "ここは〈汗〉の意味。汗はかくもの（汗をかく）だが、違いをかくとは言わないので合わない。"}, {"text": "彼は違いを決めて、会社を辞めた。", "explanation": "ここは〈覚悟〉の意味。覚悟は決めるものだが、違いを決めるとは言わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '37a00a04-4613-4ed0-8714-b43ebbccdc29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36291, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "二つの絵の違いが三つ探してください。", "corrected_sentence": "二つの絵の違いを三つ探してください。", "error_description": "「探す」の目的語は「を」で示す。「違いが」は誤りで、「違いを」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '37a00a04-4613-4ed0-8714-b43ebbccdc29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36291, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "兄と私の違いが、表で比べました。", "corrected_sentence": "兄と私の違いを、表で比べました。", "error_description": "正しくは「違いを比べる」。「比べる」の目的語は「を」で示す。「が」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '37a00a04-4613-4ed0-8714-b43ebbccdc29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36292, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "過去", "is_correct": true, "explanation": "「未来」の対義語。時間の前後で対になる。"}, {"text": "鉛筆", "is_correct": false, "explanation": "鉛筆は筆記具で、時間の対義語にならない。"}, {"text": "雨", "is_correct": false, "explanation": "雨は天気で、未来の対義語とは言えない。"}, {"text": "階段", "is_correct": false, "explanation": "階段は建築の部位で、時間の反対語ではない。"}], "correct_answer": "過去", "explanations": {"過去": "「未来」の対義語。時間の前後で対になる。", "鉛筆": "鉛筆は筆記具で、時間の対義語にならない。", "雨": "雨は天気で、未来の対義語とは言えない。", "階段": "階段は建築の部位で、時間の反対語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '147fd2e2-5122-4bc2-bae3-4a55a30696a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36292, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「未来の自分」の「の」。未来を連体修飾する。"}, {"text": "を", "is_correct": false, "explanation": "「未来を自分に」は目的語にならず、文が続かない。"}, {"text": "に", "is_correct": false, "explanation": "「未来に自分に」と「に」が二つ続き、不自然になる。"}, {"text": "は", "is_correct": false, "explanation": "「未来は」と「手紙は」で主題が二つ重なり、不自然になる。"}], "correct_answer": "の", "explanations": {"の": "「未来の自分」の「の」。未来を連体修飾する。", "を": "「未来を自分に」は目的語にならず、文が続かない。", "に": "「未来に自分に」と「に」が二つ続き、不自然になる。", "は": "「未来は」と「手紙は」で主題が二つ重なり、不自然になる。"}, "error_tags": {"を": "目的語", "に": "二重の格", "は": "主題の重複"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "過去", "is_correct": true, "explanation": "「未来」の対義語。時間の前後で対になる。"}, {"text": "机", "is_correct": false, "explanation": "机は家具で、時間の対義語にならない。"}, {"text": "花", "is_correct": false, "explanation": "花は植物で、未来の対義語とは言えない。"}, {"text": "皿", "is_correct": false, "explanation": "皿は食器で、時間の反対語ではない。"}], "correct_answer": "過去", "explanations": {"過去": "「未来」の対義語。時間の前後で対になる。", "机": "机は家具で、時間の対義語にならない。", "花": "花は植物で、未来の対義語とは言えない。", "皿": "皿は食器で、時間の反対語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '147fd2e2-5122-4bc2-bae3-4a55a30696a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36292, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "これから来る時間のこと。今ではない、あとの時間。", "primary_collocate": null, "pronunciation": "みらい", "ipa": "miɾai", "syllable_count": 3, "sentences": [{"text": "過去を悔やむより、未来のことを考えたほうがいい。", "target_word": "未来", "complexity_tier": "T3", "furigana": "過去(かこ)を悔(く)やむより、未来(みらい)のことを考(かんが)えたほうがいい。", "sentence_source": "generated"}, {"text": "祖父は「未来は誰にも見えないものだ」とよく言っていた。", "target_word": "未来", "complexity_tier": "T3", "furigana": "祖父(そふ)は「未来(みらい)は誰(だれ)にも見(み)えないものだ」とよく言(い)っていた。", "sentence_source": "generated"}, {"text": "未来に向かって、一歩ずつ進んでいこう。", "target_word": "未来", "complexity_tier": "T3", "furigana": "未来(みらい)に向(む)かって、一歩(いっぽ)ずつ進(すす)んでいこう。", "sentence_source": "generated"}, {"text": "昨日の失敗は忘れて、未来を見て生きていきたい。", "target_word": "未来", "complexity_tier": "T3", "furigana": "昨日(きのう)の失敗(しっぱい)は忘(わす)れて、未来(みらい)を見(み)て生(い)きていきたい。", "sentence_source": "generated"}, {"text": "この町の未来を、住民みんなで話し合った。", "target_word": "未来", "complexity_tier": "T3", "furigana": "この町(まち)の未来(みらい)を、住民(じゅうみん)みんなで話(はな)し合(あ)った。", "sentence_source": "generated"}, {"text": "彼女は自分の未来に不安を感じていた。", "target_word": "未来", "complexity_tier": "T3", "furigana": "彼女(かのじょ)は自分(じぶん)の未来(みらい)に不安(ふあん)を感(かん)じていた。", "sentence_source": "generated"}, {"text": "科学者たちは、地球の未来について研究している。", "target_word": "未来", "complexity_tier": "T3", "furigana": "科学者[かがくしゃ]たちは、地球[ちきゅう]の未来[みらい]について研究[けんきゅう]している。", "sentence_source": "generated"}, {"text": "手紙は、未来の自分に宛てて書いた。", "target_word": "未来", "complexity_tier": "T3", "furigana": "手紙[てがみ]は、未来[みらい]の自分[じぶん]に宛[あ]てて書[か]いた。", "sentence_source": "generated"}, {"text": "未来の私へ、元気でいますか。", "target_word": "未来", "complexity_tier": "T3", "furigana": "未来(みらい)の私(わたし)へ、元気(げんき)でいますか。", "sentence_source": "generated"}, {"text": "タイムマシンで未来へ行ってみたいと思う。", "target_word": "未来", "complexity_tier": "T3", "furigana": "タイムマシンで未来(みらい)へ行(い)ってみたいと思(おも)う。", "sentence_source": "generated"}], "morphological_forms": [{"form": "未来", "label": "基本形"}, {"form": "未来の", "label": "連体修飾"}, {"form": "未来へ", "label": "方向"}], "register": "neutral", "sense_fingerprint": "未来: time that is still to come, not now but later (future)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '229fb64a-60c4-458a-8173-9276c7aa12bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36292, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "未来", "is_correct": true, "explanation": "「未来のこと」で、今ではないあとの時間を指す。文脈に合う唯一の語。"}, {"text": "財布", "is_correct": false, "explanation": "財布は持ち物で、考える対象の時間としては意味が通らない。"}, {"text": "玄関", "is_correct": false, "explanation": "玄関は建物の出入口で、時間を表さない。"}, {"text": "花瓶", "is_correct": false, "explanation": "花瓶は容器で、考える対象の時間として成り立たない。"}], "explanations": {"未来": "「未来のこと」で、今ではないあとの時間を指す。文脈に合う唯一の語。", "財布": "財布は持ち物で、考える対象の時間としては意味が通らない。", "玄関": "玄関は建物の出入口で、時間を表さない。", "花瓶": "花瓶は容器で、考える対象の時間として成り立たない。"}, "sentence_index": 0, "correct_answer": "未来"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "財布の中に、未来を入れている。", "explanation": "〈物〉の意味。未来は時間を指すので、財布に入れる物にはならない。"}, {"text": "夏休みの楽しい思い出が、もう未来になってしまった。", "explanation": "〈過ぎ去ったこと〉の意味。既に起きた思い出を未来とすると、時間の向きが逆になる。"}, {"text": "昨日の試合は、未来の夜に行われた。", "explanation": "〈過ぎた時間〉の意味。既に過ぎた昨日の試合を未来の時間に置くと、順序が矛盾する。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '147fd2e2-5122-4bc2-bae3-4a55a30696a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36292, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "未来", "is_correct": true, "explanation": "「未来について」で、これから来る時代を指し、研究の対象として自然。"}, {"text": "窓", "is_correct": false, "explanation": "窓は建物の部位で、研究の対象として「地球の窓」の意味が通らない。"}, {"text": "財布", "is_correct": false, "explanation": "財布は持ち物で、研究の対象として「地球の財布」の意味が通らない。"}, {"text": "靴下", "is_correct": false, "explanation": "靴下は衣類で、「地球の靴下について研究」は成り立たない。"}], "explanations": {"未来": "「未来について」で、これから来る時代を指し、研究の対象として自然。", "窓": "窓は建物の部位で、研究の対象として「地球の窓」の意味が通らない。", "財布": "財布は持ち物で、研究の対象として「地球の財布」の意味が通らない。", "靴下": "靴下は衣類で、「地球の靴下について研究」は成り立たない。"}, "sentence_index": 6, "correct_answer": "未来"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今この瞬間は、もう未来だ。", "explanation": "〈現在〉の意味。今を未来と呼ぶと、現在と未来の区別が崩れる。"}, {"text": "この町の歴史は、まだ未来のことだ。", "explanation": "〈過去〉の意味。既に起きた出来事を、まだ来ていない時間とすると矛盾する。"}, {"text": "前回の大会で、未来に優勝した。", "explanation": "〈次回〉の意味。次回の大会なら未来の話だが、既に終わった出来事に使うと矛盾する。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '147fd2e2-5122-4bc2-bae3-4a55a30696a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36292, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "次の世代の未来に、真剣に考えたい。", "corrected_sentence": "次の世代の未来を、真剣に考えたい。", "error_description": "「考えたい」の対象は「未来を」と目的語で示す。「未来に」は誤り（に→を）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '147fd2e2-5122-4bc2-bae3-4a55a30696a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36292, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "地球の未来を破るために、努力したい。", "corrected_sentence": "地球の未来を築くために、努力したい。", "error_description": "「未来を」に続く動詞は「築く」。「破る」は未来とのコロケーションとして誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '147fd2e2-5122-4bc2-bae3-4a55a30696a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36293, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「未来の」で、後ろの「ために」に続く連体修飾の「の」。文が自然に続く。"}, {"text": "を", "is_correct": false, "explanation": "「未来を」では「ために」に続かず、文が成り立たない。"}, {"text": "が", "is_correct": false, "explanation": "「未来が」では主語になり、「ために」に続かない。"}, {"text": "で", "is_correct": false, "explanation": "「未来で」は場所や手段を示し、「ために」に続く修飾にならない。"}], "correct_answer": "の", "explanations": {"の": "「未来の」で、後ろの「ために」に続く連体修飾の「の」。文が自然に続く。", "を": "「未来を」では「ために」に続かず、文が成り立たない。", "が": "「未来が」では主語になり、「ために」に続かない。", "で": "「未来で」は場所や手段を示し、「ために」に続く修飾にならない。"}, "error_tags": {"を": "目的語", "が": "主語", "で": "場所・手段"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "過去", "is_correct": true, "explanation": "「未来」の対義語。時間の前後で対になる。"}, {"text": "鉛筆", "is_correct": false, "explanation": "鉛筆は筆記具で、時間の対義語にならない。"}, {"text": "雨", "is_correct": false, "explanation": "雨は天気で、未来の対義語とは言えない。"}, {"text": "階段", "is_correct": false, "explanation": "階段は建築の部位で、時間の反対語ではない。"}], "correct_answer": "過去", "explanations": {"過去": "「未来」の対義語。時間の前後で対になる。", "鉛筆": "鉛筆は筆記具で、時間の対義語にならない。", "雨": "雨は天気で、未来の対義語とは言えない。", "階段": "階段は建築の部位で、時間の反対語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '147fd2e2-5122-4bc2-bae3-4a55a30696a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36293, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「未来では」の「で」。場面を示す形で、「では」として自然に続く。"}, {"text": "を", "is_correct": false, "explanation": "「未来を」と「は」は続かず、文が成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「未来とでは」は相手や共同の意味になり、場面を示せない。"}, {"text": "へ", "is_correct": false, "explanation": "「未来へでは」は方向の意味になり、場面にならない。"}], "correct_answer": "で", "explanations": {"で": "「未来では」の「で」。場面を示す形で、「では」として自然に続く。", "を": "「未来を」と「は」は続かず、文が成り立たない。", "と": "「未来とでは」は相手や共同の意味になり、場面を示せない。", "へ": "「未来へでは」は方向の意味になり、場面にならない。"}, "error_tags": {"を": "目的語", "と": "相手・共同", "へ": "方向"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "過去", "is_correct": true, "explanation": "「未来」の対義語。時間の前後で対になる。"}, {"text": "皿", "is_correct": false, "explanation": "皿は食器で、時間の対義語にならない。"}, {"text": "花", "is_correct": false, "explanation": "花は植物で、未来の対義語とは言えない。"}, {"text": "石", "is_correct": false, "explanation": "石は鉱物で、時間の反対語ではない。"}], "correct_answer": "過去", "explanations": {"過去": "「未来」の対義語。時間の前後で対になる。", "皿": "皿は食器で、時間の対義語にならない。", "花": "花は植物で、未来の対義語とは言えない。", "石": "石は鉱物で、時間の反対語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '147fd2e2-5122-4bc2-bae3-4a55a30696a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36293, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "これからやってくる、まだ来ていない時間や時期。現在よりも後のことを指す。", "primary_collocate": null, "pronunciation": "みらい", "ipa": "miɾai", "syllable_count": 3, "sentences": [{"text": "まさに、大地と対話するその姿勢こそが、未来を担う魂の育成に他ならないのだろう。", "target_word": "未来", "complexity_tier": "T4", "furigana": "まさに、大地(だいち)と対話(たいわ)するその姿勢(しせい)こそが、未来(みらい)を担(にな)う魂(たましい)の育成(いくせい)に他(ほか)ならないのだろう。", "sentence_source": "mined"}, {"text": "子どもたちの未来のために、この森を守り続けたい。", "target_word": "未来", "complexity_tier": "T3", "furigana": "子(こ)どもたちの未来(みらい)のために、この森(もり)を守(まも)り続(つづ)けたい。", "sentence_source": "generated"}, {"text": "この国の未来を想像して、日記に書いてみた。", "target_word": "未来", "complexity_tier": "T3", "furigana": "この国[くに]の未来[みらい]を想像[そうぞう]して、日記[にっき]に書[か]いてみた。", "sentence_source": "generated"}, {"text": "過去は変えられないが、未来は自分の行動で変えられる。", "target_word": "未来", "complexity_tier": "T3", "furigana": "過去(かこ)は変(か)えられないが、未来(みらい)は自分(じぶん)の行動(こうどう)で変(か)えられる。", "sentence_source": "generated"}, {"text": "彼は明るい未来を信じて、毎日遅くまで勉強している。", "target_word": "未来", "complexity_tier": "T3", "furigana": "彼(かれ)は明(あか)るい未来(みらい)を信(しん)じて、毎日(まいにち)遅(おそ)くまで勉強(べんきょう)している。", "sentence_source": "generated"}, {"text": "この技術は、私たちの未来を大きく変えるかもしれない。", "target_word": "未来", "complexity_tier": "T3", "furigana": "この技術(ぎじゅつ)は、私(わたし)たちの未来(みらい)を大(おお)きく変(か)えるかもしれない。", "sentence_source": "generated"}, {"text": "未来のことは誰にも分からないから、今日できることをやろう。", "target_word": "未来", "complexity_tier": "T3", "furigana": "未来(みらい)のことは誰(だれ)にも分(わ)からないから、今日(きょう)できることをやろう。", "sentence_source": "generated"}, {"text": "映画の中の未来では、車が空を飛んでいた。", "target_word": "未来", "complexity_tier": "T3", "furigana": "映画(えいが)の中(なか)の未来(みらい)では、車(くるま)が空(そら)を飛(と)んでいた。", "sentence_source": "generated"}, {"text": "環境問題を放置すれば、未来の世代が困ることになる。", "target_word": "未来", "complexity_tier": "T3", "furigana": "環境問題(かんきょうもんだい)を放置(ほうち)すれば、未来(みらい)の世代(せだい)が困(こま)ることになる。", "sentence_source": "generated"}, {"text": "占い師は私の未来について、いくつか助言をくれた。", "target_word": "未来", "complexity_tier": "T3", "furigana": "占(うらな)い師(し)は私(わたし)の未来(みらい)について、いくつか助言(じょげん)をくれた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "未来", "label": "基本形"}, {"form": "未来の", "label": "連体修飾"}, {"form": "未来へ", "label": "方向"}], "register": "neutral", "sense_fingerprint": "未来: the time yet to come, after the present (future)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '229fb64a-60c4-458a-8173-9276c7aa12bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36293, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "未来", "is_correct": true, "explanation": "「未来を担う」で、これから来る時代を背負うという意味。文脈に合う唯一の語。"}, {"text": "窓", "is_correct": false, "explanation": "窓は建物の開口部で、「担う」の対象にならない。"}, {"text": "湖", "is_correct": false, "explanation": "湖は地形を指し、「未来を担う魂」の意味が通らない。"}, {"text": "机", "is_correct": false, "explanation": "机は家具で、時代や使命を担う対象にはならない。"}], "explanations": {"未来": "「未来を担う」で、これから来る時代を背負うという意味。文脈に合う唯一の語。", "窓": "窓は建物の開口部で、「担う」の対象にならない。", "湖": "湖は地形を指し、「未来を担う魂」の意味が通らない。", "机": "机は家具で、時代や使命を担う対象にはならない。"}, "sentence_index": 0, "correct_answer": "未来"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "引っ越しの荷物に、未来を詰め込んだ。", "explanation": "〈中身〉の意味。未来は時間を指すので、箱に詰める中身にはならない。"}, {"text": "夏休みの楽しい思い出が、もう未来になってしまった。", "explanation": "〈過去〉の意味。既に起きた思い出を未来とすると、時間の向きが逆になる。"}, {"text": "昨日の会議は、未来の午後に開かれた。", "explanation": "〈過ぎた時間〉の意味。既に過ぎた昨日の会議を未来の時間に置くと、時間の順序が矛盾する。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '147fd2e2-5122-4bc2-bae3-4a55a30696a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36293, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "未来", "is_correct": true, "explanation": "「未来のこと」で、まだ来ていない時間を指す。文脈に合う唯一の語。"}, {"text": "天井", "is_correct": false, "explanation": "天井は建物の部位で、分からない対象としての「未来のこと」にはならない。"}, {"text": "床", "is_correct": false, "explanation": "床は建物の部位で、誰にも分からない対象として意味が通らない。"}, {"text": "紙", "is_correct": false, "explanation": "紙は材料や道具で、「誰にも分からない」対象として成り立たない。"}], "explanations": {"未来": "「未来のこと」で、まだ来ていない時間を指す。文脈に合う唯一の語。", "天井": "天井は建物の部位で、分からない対象としての「未来のこと」にはならない。", "床": "床は建物の部位で、誰にも分からない対象として意味が通らない。", "紙": "紙は材料や道具で、「誰にも分からない」対象として成り立たない。"}, "sentence_index": 6, "correct_answer": "未来"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今この瞬間は、もう未来になっている。", "explanation": "〈現在〉の意味。今を未来と呼ぶと、現在と未来の区別が崩れる。"}, {"text": "その事件は、もう未来のこととして記録に残っている。", "explanation": "〈過去〉の意味。既に起きた事件を未来のこととすると、時間の向きが逆になる。"}, {"text": "この靴の未来を履いて、出かけた。", "explanation": "〈履き物〉の意味。未来は時間を指すので、靴のように履く物にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '147fd2e2-5122-4bc2-bae3-4a55a30696a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36293, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この町の未来に想像して、日記に書いてみた。", "corrected_sentence": "この町の未来を想像して、日記に書いてみた。", "error_description": "「想像する」の対象は「未来を」と目的語の「を」で示す。「未来に」は誤り（に→を）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '147fd2e2-5122-4bc2-bae3-4a55a30696a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36293, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この村の未来で、みんなで考えた。", "corrected_sentence": "この村の未来を、みんなで考えた。", "error_description": "「考える」の対象は「未来を」と目的語で示す。「未来で」は格助詞の誤り（で→を）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '147fd2e2-5122-4bc2-bae3-4a55a30696a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36294, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1aff041-8e12-4be2-95f9-036736301c3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
