INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36294, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "前と違うようになる。", "primary_collocate": null, "pronunciation": "かわる", "ipa": "kawaɾɯ", "syllable_count": 3, "sentences": [{"text": "引っ越してから、彼の生活は大きく変わった。", "target_word": "変わった", "complexity_tier": "T3", "furigana": "ひっこしてから、かれのせいかつはおおきくかわった。", "sentence_source": "generated"}, {"text": "町は十年前とはすっかり変わってしまった。", "target_word": "変わって", "complexity_tier": "T3", "furigana": "まちはじゅうねんまえとはすっかりかわってしまった。", "sentence_source": "generated"}, {"text": "彼は結婚して、性格が変わったと言われる。", "target_word": "変わった", "complexity_tier": "T3", "furigana": "かれはけっこんして、せいかくがかわったといわれる。", "sentence_source": "generated"}, {"text": "髪型を変えたら、印象が変わった。", "target_word": "変わった", "complexity_tier": "T3", "furigana": "かみがたをかえたら、いんしょうがかわった。", "sentence_source": "generated"}, {"text": "昔と変わらない味で、懐かしくなった。", "target_word": "変わらない", "complexity_tier": "T3", "furigana": "むかしとかわらないあじで、なつかしくなった。", "sentence_source": "generated"}, {"text": "考えが変わったので、旅行には行かないことにした。", "target_word": "変わった", "complexity_tier": "T3", "furigana": "かんがえがかわったので、りょこうにはいかないことにした。", "sentence_source": "generated"}, {"text": "新しい店長になって、店の雰囲気が変わった。", "target_word": "変わった", "complexity_tier": "T3", "furigana": "あたらしいてんちょうになって、みせのふんいきがかわった。", "sentence_source": "generated"}, {"text": "久しぶりに会った友達は、少しも変わっていなかった。", "target_word": "変わって", "complexity_tier": "T3", "furigana": "ひさしぶりにあったともだちは、すこしもかわっていなかった。", "sentence_source": "generated"}, {"text": "国が変われば、習慣も変わる。", "target_word": "変われば", "complexity_tier": "T3", "furigana": "くにがかわれば、しゅうかんもかわる。", "sentence_source": "generated"}, {"text": "転職して仕事が変わると、毎日の過ごし方も変わる。", "target_word": "変わる", "complexity_tier": "T3", "furigana": "てんしょくしてしごとがかわると、まいにちのすごしかたもかわる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "変わる", "label": "終止形"}, {"form": "変わった", "label": "過去形"}, {"form": "変わらない", "label": "否定形"}, {"form": "変わって", "label": "て形"}, {"form": "変われば", "label": "仮定形"}], "register": "neutral", "sense_fingerprint": "人・場所・考えなどが以前とは違う様子になる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5f6c10e-59f5-434b-8d2f-b32eae92b808') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36294, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "変わった", "is_correct": true, "explanation": "正解。「生活は大きく変わった」で、前と違う状態になったことを過去形で述べる。"}, {"text": "変えた", "is_correct": false, "explanation": "他動詞なので、「生活は」を主語にして状態の変化を述べる文には合わない（「生活を変えた」の形になる）。"}, {"text": "変わって", "is_correct": false, "explanation": "て形なので文を終えられず、「大きく変わって。」では文が成立しない。"}, {"text": "変われ", "is_correct": false, "explanation": "命令形なので、事実を述べる文の終わりには使えない。"}], "explanations": {"変わった": "正解。「生活は大きく変わった」で、前と違う状態になったことを過去形で述べる。", "変えた": "他動詞なので、「生活は」を主語にして状態の変化を述べる文には合わない（「生活を変えた」の形になる）。", "変わって": "て形なので文を終えられず、「大きく変わって。」では文が成立しない。", "変われ": "命令形なので、事実を述べる文の終わりには使えない。"}, "sentence_index": 0, "correct_answer": "変わった"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "新しい研究で、彼はノーベル賞に変わった。", "explanation": "ここは〈受賞する〉（賞を受ける）の意味。変わるは状態が別になることで、賞を受けることは表せない。"}, {"text": "今日は私が運転を代わります。", "explanation": "ここは〈代わる〉（役目を引き継ぐ）の意味。変わるは性質や状態が別になることで、役目の交代は代わるで表す。"}, {"text": "元の場所に変わった。", "explanation": "ここは〈戻る〉（元の位置に返る）の意味。変わるは状態が別になることで、元の位置に返ることは表せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1aff041-8e12-4be2-95f9-036736301c3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36294, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "変わった", "is_correct": true, "explanation": "正解。「店の雰囲気が変わった」で、前と違う状態になったことを過去形で述べる。"}, {"text": "変えろ", "is_correct": false, "explanation": "命令形の他動詞なので、「雰囲気が」を主語にする文には合わない。"}, {"text": "変わろう", "is_correct": false, "explanation": "意向形なので、「雰囲気が」の変化を事実として述べる文とは合わない。"}, {"text": "変われば", "is_correct": false, "explanation": "仮定形なので文を終えられず、条件節で終わってしまう。"}], "explanations": {"変わった": "正解。「店の雰囲気が変わった」で、前と違う状態になったことを過去形で述べる。", "変えろ": "命令形の他動詞なので、「雰囲気が」を主語にする文には合わない。", "変わろう": "意向形なので、「雰囲気が」の変化を事実として述べる文とは合わない。", "変われば": "仮定形なので文を終えられず、条件節で終わってしまう。"}, "sentence_index": 6, "correct_answer": "変わった"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "故障したパソコンが変わった。", "explanation": "ここは〈直る〉（修理されて元どおりになる）の意味。変わるは状態が別になることで、故障の回復は表せない。"}, {"text": "貯金が一年で二倍に変わった。", "explanation": "ここは〈増える〉（数量が多くなる）の意味。変わるは性質や状態が別になることで、数量が増えることは表せない。"}, {"text": "うわさが町中に変わった。", "explanation": "ここは〈広がる〉（範囲が広がる）の意味。変わるは状態が別になることで、範囲の拡大は表せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1aff041-8e12-4be2-95f9-036736301c3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36294, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "最近、彼は性格を変わった。", "corrected_sentence": "最近、彼は性格が変わった。", "error_description": "助詞の誤り。「変わる」は主語の状態が変わる自動詞なので、「性格を」ではなく「性格が」を使う。「性格を変わった」が誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "変わって", "is_correct": true, "explanation": "正解。「てしまった」に続く て形で、変化の結果を強調する。"}, {"text": "変わった", "is_correct": false, "explanation": "過去形なので「てしまった」に続かず、文が成立しない。"}, {"text": "変わらない", "is_correct": false, "explanation": "否定形なので「てしまった」に続かず、変化していないという意味になる。"}, {"text": "変われば", "is_correct": false, "explanation": "仮定形なので「てしまった」に続かず、条件節で終わってしまう。"}], "correct_form": "変わって", "base_form": "変わる", "form_label": "て形", "sentence_index": 1, "explanations": {"変わって": "正解。「てしまった」に続く て形で、変化の結果を強調する。", "変わった": "過去形なので「てしまった」に続かず、文が成立しない。", "変わらない": "否定形なので「てしまった」に続かず、変化していないという意味になる。", "変われば": "仮定形なので「てしまった」に続かず、条件節で終わってしまう。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1aff041-8e12-4be2-95f9-036736301c3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36294, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この会社は来年から方針が変わりる。", "corrected_sentence": "この会社は来年から方針が変わる。", "error_description": "活用の誤り。「変わる」は五段活用の動詞で、終止形は「変わる」。「変わりる」は誤った活用形。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "変わって", "is_correct": true, "explanation": "正解。「ていなかった」に続く て形で、変化していない状態を表す。"}, {"text": "変わります", "is_correct": false, "explanation": "丁寧な非過去形なので「ていなかった」に続かず、文が成立しない。"}, {"text": "変わろう", "is_correct": false, "explanation": "意向形なので「ていなかった」に続かず、文が成立しない。"}, {"text": "変わる", "is_correct": false, "explanation": "終止形なので「ていなかった」に続かず、「少しも」と組むと文が崩れる。"}], "correct_form": "変わって", "base_form": "変わる", "form_label": "て形", "sentence_index": 7, "explanations": {"変わって": "正解。「ていなかった」に続く て形で、変化していない状態を表す。", "変わります": "丁寧な非過去形なので「ていなかった」に続かず、文が成立しない。", "変わろう": "意向形なので「ていなかった」に続かず、文が成立しない。", "変わる": "終止形なので「ていなかった」に続かず、「少しも」と組むと文が崩れる。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1aff041-8e12-4be2-95f9-036736301c3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
