INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36295, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "物事が他の状態になる。変化する。", "primary_collocate": null, "pronunciation": "かわる", "ipa": "kawaɾɯ", "syllable_count": 3, "sentences": [{"text": "信号が赤から青に変わったので、歩き出した。", "target_word": "変わった", "complexity_tier": "T3", "furigana": "しんごうがあかからあおにかわったので、あるきだした。", "sentence_source": "generated"}, {"text": "水は零度以下になると氷に変わる。", "target_word": "変わる", "complexity_tier": "T3", "furigana": "みずはれいどいかになるとこおりにかわる。", "sentence_source": "generated"}, {"text": "秋になると、木の葉の色が緑から赤に変わる。", "target_word": "変わる", "complexity_tier": "T3", "furigana": "あきになると、このはのいろがみどりからあかにかわる。", "sentence_source": "generated"}, {"text": "雨はやがて雪に変わった。", "target_word": "変わった", "complexity_tier": "T3", "furigana": "あめはやがてゆきにかわった。", "sentence_source": "generated"}, {"text": "試合の途中で、天気が急に晴れから雨に変わった。", "target_word": "変わった", "complexity_tier": "T3", "furigana": "しあいのとちゅうで、てんきがきゅうにはれからあめにかわった。", "sentence_source": "generated"}, {"text": "夕方になって、空の色が赤からだんだん紫に変わっていく。", "target_word": "変わっていく", "complexity_tier": "T3", "furigana": "ゆうがたになって、そらのいろがあかからだんだんむらさきにかわっていく。", "sentence_source": "generated"}, {"text": "青虫はさなぎを経て、きれいなチョウに変わる。", "target_word": "変わる", "complexity_tier": "T3", "furigana": "あおむしはさなぎをへて、きれいなチョウにかわる。", "sentence_source": "generated"}, {"text": "喜びの声は、すぐに悲鳴に変わった。", "target_word": "変わった", "complexity_tier": "T3", "furigana": "よろこびのこえは、すぐにひめいにかわった。", "sentence_source": "generated"}, {"text": "氷がとけて水に変わるのを、じっと見ていた。", "target_word": "変わる", "complexity_tier": "T3", "furigana": "こおりがとけてみずにかわるのを、じっとみていた。", "sentence_source": "generated"}, {"text": "話し合いの空気が、笑いから真剣なものに変わった。", "target_word": "変わった", "complexity_tier": "T3", "furigana": "はなしあいのくうきが、わらいからしんけんなものにかわった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "変わる", "label": "終止形"}, {"form": "変わった", "label": "過去形"}, {"form": "変わって", "label": "て形"}, {"form": "変わっていく", "label": "継続変化"}], "register": "neutral", "sense_fingerprint": "物事が別の状態・別のものへ移り変わる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 6 above tier T2: contains vocabulary far above tier T2: 青虫 (Zipf 2.03)']::text[], 'f5f6c10e-59f5-434b-8d2f-b32eae92b808') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36295, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "変わった", "is_correct": true, "explanation": "正解。「信号が〜に変わったので」で、状態が移った過去を表し、「ので」に続く。"}, {"text": "変えた", "is_correct": false, "explanation": "他動詞なので、「信号が」が変化する主語になる文では使えない。"}, {"text": "変わって", "is_correct": false, "explanation": "て形なので「ので」に続かず、文が成立しない。"}, {"text": "変われ", "is_correct": false, "explanation": "命令形なので「ので」に続かず、文が成立しない。"}], "explanations": {"変わった": "正解。「信号が〜に変わったので」で、状態が移った過去を表し、「ので」に続く。", "変えた": "他動詞なので、「信号が」が変化する主語になる文では使えない。", "変わって": "て形なので「ので」に続かず、文が成立しない。", "変われ": "命令形なので「ので」に続かず、文が成立しない。"}, "sentence_index": 0, "correct_answer": "変わった"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は並んでいた列の前に、そっと変わった。", "explanation": "ここは〈割り込む〉（順番を飛ばして入る）の意味。変わるは状態が別になることで、順番を飛ばして入ることは表せない。"}, {"text": "謎がようやく変わった。", "explanation": "ここは〈解ける〉（謎が明らかになる）の意味。変わるは別の状態に移るだけで、謎の解明は表せない。"}, {"text": "お茶が変わった。", "explanation": "ここは〈冷める〉（温度が下がる）の意味。変わるは状態が別になることで、温度が下がることは表せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1aff041-8e12-4be2-95f9-036736301c3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36295, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "変わる", "is_correct": true, "explanation": "正解。「チョウに変わる」で、状態が別のものに移る変化を表す。"}, {"text": "変えろ", "is_correct": false, "explanation": "命令形の他動詞なので、「青虫は」を主語とする変化の文には合わない。"}, {"text": "変わろう", "is_correct": false, "explanation": "意向形なので、事実として変化を述べる文とは合わない。"}, {"text": "変われば", "is_correct": false, "explanation": "仮定形なので文を終えられず、条件節で終わってしまう。"}], "explanations": {"変わる": "正解。「チョウに変わる」で、状態が別のものに移る変化を表す。", "変えろ": "命令形の他動詞なので、「青虫は」を主語とする変化の文には合わない。", "変わろう": "意向形なので、事実として変化を述べる文とは合わない。", "変われば": "仮定形なので文を終えられず、条件節で終わってしまう。"}, "sentence_index": 6, "correct_answer": "変わる"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夜明けの霧が変わった。", "explanation": "ここは〈消える〉（なくなる）の意味。変わるは別の状態に移ることで、消滅は表せない。"}, {"text": "列車が駅に変わった。", "explanation": "ここは〈着く〉（目的地に到達する）の意味。変わるは状態が別になることで、到着は表せない。"}, {"text": "インクが紙に変わった。", "explanation": "ここは〈広がる〉（面積が広がる）の意味。変わるは状態が別になることで、広がる意味は表せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1aff041-8e12-4be2-95f9-036736301c3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36295, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "会議の途中で、議題を急に変わった。", "corrected_sentence": "会議の途中で、議題が急に変わった。", "error_description": "助詞の誤り。「変わる」は自動詞なので、「議題を」ではなく「議題が」を使う。「議題を変わった」が誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "変わる", "is_correct": true, "explanation": "正解。「なると」に続く終止形で、一般的な変化を表す。"}, {"text": "変わった", "is_correct": false, "explanation": "過去形なので、「なると」と組む一般的な法則の文には合わない。"}, {"text": "変わって", "is_correct": false, "explanation": "て形なので文を終えられず、「氷に変わって。」では文が成立しない。"}, {"text": "変われば", "is_correct": false, "explanation": "仮定形なので「なると」と重なり、条件が二重になって主節がない。"}], "correct_form": "変わる", "base_form": "変わる", "form_label": "終止形", "sentence_index": 1, "explanations": {"変わる": "正解。「なると」に続く終止形で、一般的な変化を表す。", "変わった": "過去形なので、「なると」と組む一般的な法則の文には合わない。", "変わって": "て形なので文を終えられず、「氷に変わって。」では文が成立しない。", "変われば": "仮定形なので「なると」と重なり、条件が二重になって主節がない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1aff041-8e12-4be2-95f9-036736301c3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36295, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夜になると、空の色が赤から紫に変わりる。", "corrected_sentence": "夜になると、空の色が赤から紫に変わる。", "error_description": "活用の誤り。「変わる」の終止形は「変わる」で、「変わりる」は誤った活用形。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "変わった", "is_correct": true, "explanation": "正解。「すぐに悲鳴に変わった」で、過去の出来事として述べる過去形。"}, {"text": "変わらない", "is_correct": false, "explanation": "否定形なので、変化が起きたという文脈と合わない。"}, {"text": "変わろう", "is_correct": false, "explanation": "意向形なので、「喜びの声」を主語にして事実を述べる文には合わない。"}, {"text": "変わるな", "is_correct": false, "explanation": "禁止の形なので、事実を述べる文には合わない。"}], "correct_form": "変わった", "base_form": "変わる", "form_label": "過去形", "sentence_index": 7, "explanations": {"変わった": "正解。「すぐに悲鳴に変わった」で、過去の出来事として述べる過去形。", "変わらない": "否定形なので、変化が起きたという文脈と合わない。", "変わろう": "意向形なので、「喜びの声」を主語にして事実を述べる文には合わない。", "変わるな": "禁止の形なので、事実を述べる文には合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1aff041-8e12-4be2-95f9-036736301c3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36296, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「計画を変える」の「計画」は変えられる対象なので、目的語を示す「を」が入る。"}, {"text": "が", "is_correct": false, "explanation": "「計画が変えて」は主語を示す「が」になり、変える対象を表せない。"}, {"text": "で", "is_correct": false, "explanation": "「計画で変えて」は場所や手段の「で」になり、変える対象の文型に合わない。"}, {"text": "と", "is_correct": false, "explanation": "「計画と変えて」は共同や引用の「と」になり、対象を示す文型に合わない。"}], "correct_answer": "を", "explanations": {"を": "「計画を変える」の「計画」は変えられる対象なので、目的語を示す「を」が入る。", "が": "「計画が変えて」は主語を示す「が」になり、変える対象を表せない。", "で": "「計画で変えて」は場所や手段の「で」になり、変える対象の文型に合わない。", "と": "「計画と変えて」は共同や引用の「と」になり、対象を示す文型に合わない。"}, "error_tags": {"が": "主格（主語）", "で": "場所・手段", "と": "共同・引用"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1aff041-8e12-4be2-95f9-036736301c3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36296, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「計画は」で主題を示す。「完ぺきだった」の主題になる。"}, {"text": "に", "is_correct": false, "explanation": "「計画に完ぺきだった」は位置や相手の「に」になり、述語の「完ぺきだ」に合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「計画へ完ぺきだった」は方向の「へ」になり、意味が通らない。"}, {"text": "の", "is_correct": false, "explanation": "「計画の完ぺきだった」は連体の「の」になり、文の述語が成り立たない。"}], "correct_answer": "は", "explanations": {"は": "「計画は」で主題を示す。「完ぺきだった」の主題になる。", "に": "「計画に完ぺきだった」は位置や相手の「に」になり、述語の「完ぺきだ」に合わない。", "へ": "「計画へ完ぺきだった」は方向の「へ」になり、意味が通らない。", "の": "「計画の完ぺきだった」は連体の「の」になり、文の述語が成り立たない。"}, "error_tags": {"に": "位置・相手", "へ": "方向", "の": "連体（所属）"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1aff041-8e12-4be2-95f9-036736301c3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36296, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "何かをする前に、やり方を考えること。", "primary_collocate": null, "pronunciation": "けいかく", "ipa": "keːkakɯ", "syllable_count": 4, "sentences": [{"text": "夏休みの旅行の計画を、家族で立てた。", "target_word": "計画", "complexity_tier": "T3", "furigana": "なつやすみのりょこうのけいかくを、かぞくでたてた。", "sentence_source": "generated"}, {"text": "雨が降ったので、計画を変えて家で過ごした。", "target_word": "計画", "complexity_tier": "T3", "furigana": "あめがふったので、けいかくをかえていえですごした。", "sentence_source": "generated"}, {"text": "彼は計画どおりに、毎月五万円ずつ貯金している。", "target_word": "計画", "complexity_tier": "T3", "furigana": "かれはけいかくどおりに、まいつきごまんえんずつちょきんしている。", "sentence_source": "generated"}, {"text": "計画が甘かったから、準備が間に合わなかった。", "target_word": "計画", "complexity_tier": "T3", "furigana": "けいかくがあまかったから、じゅんびがまにあわなかった。", "sentence_source": "generated"}, {"text": "新しい店を開く計画について、友達に相談した。", "target_word": "計画", "complexity_tier": "T3", "furigana": "あたらしいみせをひらくけいかくについて、ともだちにそうだんした。", "sentence_source": "generated"}, {"text": "大きな計画ほど、細かい準備が大切だ。", "target_word": "計画", "complexity_tier": "T3", "furigana": "おおきなけいかくほど、こまかいじゅんびがたいせつだ。", "sentence_source": "generated"}, {"text": "計画していた花見は、台風で中止になった。", "target_word": "計画", "complexity_tier": "T3", "furigana": "けいかくしていたはなみは、たいふうでちゅうしになった。", "sentence_source": "generated"}, {"text": "計画は完ぺきだったのに、実行する人がいなかった。", "target_word": "計画", "complexity_tier": "T3", "furigana": "けいかくはかんぺきだったのに、じっこうするひとがいなかった。", "sentence_source": "generated"}, {"text": "来年の海外留学を計画している。", "target_word": "計画", "complexity_tier": "T3", "furigana": "らいねんのかいがいりゅうがくをけいかくしている。", "sentence_source": "generated"}, {"text": "この計画にはお金がかかりすぎるので、反対だ。", "target_word": "計画", "complexity_tier": "T3", "furigana": "このけいかくにはおかねがかかりすぎるので、はんたいだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "計画", "label": "基本形"}, {"form": "計画する", "label": "する動詞"}, {"form": "計画した", "label": "過去形"}, {"form": "計画している", "label": "進行形"}], "register": "neutral", "sense_fingerprint": "事を行う前に手順や方法を考えて決めること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5f6c10e-59f5-434b-8d2f-b32eae92b808') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36296, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "計画", "is_correct": true, "explanation": "「旅行の計画を立てる」は自然な組み合わせで、旅行の準備の意味になる。"}, {"text": "反省", "is_correct": false, "explanation": "「反省を立てる」とは言わない。反省は過去を振り返ることで、旅行の準備には合わない。"}, {"text": "相談", "is_correct": false, "explanation": "「相談を立てる」は不自然。相談は話し合いのことで、立てる対象にはならない。"}, {"text": "批判", "is_correct": false, "explanation": "「批判を立てる」は言わない。批判は欠点を指摘することで、ここには合わない。"}], "explanations": {"計画": "「旅行の計画を立てる」は自然な組み合わせで、旅行の準備の意味になる。", "反省": "「反省を立てる」とは言わない。反省は過去を振り返ることで、旅行の準備には合わない。", "相談": "「相談を立てる」は不自然。相談は話し合いのことで、立てる対象にはならない。", "批判": "「批判を立てる」は言わない。批判は欠点を指摘することで、ここには合わない。"}, "sentence_index": 0, "correct_answer": "計画"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "明日の天気は、計画どおりに昼から晴れるでしょう。", "explanation": "ここは〈予想〉の意味。計画は人が前もって行動の手順を決めることで、天気の移り変わりには使わない（予想どおりと言う）。"}, {"text": "彼は計画が明るくて、みんなに好かれている。", "explanation": "ここは〈性格〉の意味。計画は行動の手順を指すので、人の明るさや性格には使わない。"}, {"text": "データを計画して、故障の原因を突き止めた。", "explanation": "ここは〈分析〉の意味。データを調べて読み解くことは分析で、計画（前もって手順を考えること）とは合わないので、データには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1aff041-8e12-4be2-95f9-036736301c3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36296, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "計画", "is_correct": true, "explanation": "「計画していた花見」は、前もって準備していた行事という意味になる。"}, {"text": "挑戦", "is_correct": false, "explanation": "「挑戦していた花見」は意味が通らない。挑戦は難しいことに向かう行為で、花見には使わない。"}, {"text": "感謝", "is_correct": false, "explanation": "「感謝していた花見」は不自然。感謝は気持ちを表す語で、行事を修飾しない。"}, {"text": "歓迎", "is_correct": false, "explanation": "「歓迎していた花見」は意味が通らない。歓迎は人を迎える行為で、行事を修飾しない。"}], "explanations": {"計画": "「計画していた花見」は、前もって準備していた行事という意味になる。", "挑戦": "「挑戦していた花見」は意味が通らない。挑戦は難しいことに向かう行為で、花見には使わない。", "感謝": "「感謝していた花見」は不自然。感謝は気持ちを表す語で、行事を修飾しない。", "歓迎": "「歓迎していた花見」は意味が通らない。歓迎は人を迎える行為で、行事を修飾しない。"}, "sentence_index": 6, "correct_answer": "計画"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "このスープは計画が濃くておいしい。", "explanation": "ここは〈味〉の意味。計画は行動の手順を指すので、料理の味の濃さには使わない。"}, {"text": "試合の計画は三対一で、私たちが勝った。", "explanation": "ここは〈結果〉の意味。計画は前もって決めた手順で、試合の得点の結果には使わない。"}, {"text": "私の計画は百六十センチだ。", "explanation": "ここは〈身長〉の意味。計画は行動の手順なので、身長という数値には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1aff041-8e12-4be2-95f9-036736301c3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36296, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "父は来月の引っ越しの計画に、ずっと考えている。", "corrected_sentence": "父は来月の引っ越しの計画を、ずっと考えている。", "error_description": "「計画」は「考える」の対象（目的語）なので「を」が正しい。「に」は誤りで、対象を示す格助詞の選び方を誤っている。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1aff041-8e12-4be2-95f9-036736301c3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
